var e=JSON.parse(`[{"name":"Air Bubble","source":"AAG","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"You create a spectral globe around the head of a willing creature you can see within range. The globe is filled with fresh air that lasts until the spell ends. If the creature has more than one head, the globe of air appears around only one of its heads (which is all the creature needs to avoid suffocation, assuming that all its heads share the same respiratory system)."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 3rd level or higher, you can create two additional globes of fresh air for each slot level above 2nd."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":22},{"name":"Create Spelljamming Helm","source":"AAG","level":5,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a crystal rod worth at least 5,000 gp, which the spell consumes","cost":500000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Holding the rod used in the casting of the spell, you touch a Large or smaller chair that is unoccupied. The rod disappears, and the chair is transformed into a <b>spelljamming helm</b>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":22},{"name":"Distort Value","source":"AI","level":1,"school":"I","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"Do you need to squeeze a few more gold pieces out of a merchant as you try to sell that weird octopus statue you liberated from the chaos temple? Do you need to downplay the worth of some magical assets when the tax collector stops by? Distort value has you covered."},{"type":"text","content":"You cast this spell on an object no more than 1 foot on a side, doubling the object's perceived value by adding illusory flourishes or polish to it, or reducing its perceived value by half with the help of illusory scratches, dents, and other unsightly features. Anyone examining the object can ascertain its true value with a successful Intelligence (<i>Investigation</i>) check against your spell save DC."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 2nd level or higher, the maximum size of the object increases by 1 foot for each slot level above 1st."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":75},{"name":"Fast Friends","source":"AI","level":3,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"When you need to make sure something gets done, you can't rely on vague promises, sworn oaths, or binding contracts of employment. When you cast this spell, choose one humanoid within range that can see and hear you, and that can understand you. The creature must succeed on a Wisdom saving throw or become <i class=\\"text-dnd-gold\\">charmed</i> by you for the duration. While the creature is <i class=\\"text-dnd-gold\\">charmed</i> in this way, it undertakes to perform any services or activities you ask of it in a friendly manner, to the best of its ability."},{"type":"text","content":"You can set the creature new tasks when a previous task is completed, or if you decide to end its current task. If the service or activity might cause harm to the creature, or if it conflicts with the creature's normal activities and desires, the creature can make another Wisdom saving throw to try to end the effect. This save is made with advantage if you or your companions are fighting the creature. If the activity would result in certain death for the creature, the spell ends."},{"type":"text","content":"When the spell ends, the creature knows it was <i class=\\"text-dnd-gold\\">charmed</i> by you."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd."}]}],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":75},{"name":"Gift of Gab","source":"AI","level":2,"school":"E","time":[{"number":1,"unit":"reaction","condition":"which you take when you speak to another creature"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"r":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"{\\"type\\":\\"quote\\",\\"entries\\":[\\"When I met Jim Darkmagic, I wondered how he got anything done in that outfit. I have since learned that most of his talents involve standing and talking. His outfit is perfect for that.\\"],\\"by\\":\\"Môrgæn\\"}"},{"type":"text","content":"Jim Darkmagic is said to have invented this spell, originally calling it <i>I said what?!</i> Have you ever been talking to the local monarch and accidentally mentioned how their son looks like your favorite hog from when you were growing up on the family farm? We've all been there! But rather than being beheaded for an honest slip of the tongue, you can pretend it never happened—by ensuring that no one knows it happened."},{"type":"text","content":"When you cast this spell, you skillfully reshape the memories of listeners in your immediate area, so that each creature of your choice within 5 feet of you forgets everything you said within the last 6 seconds. Those creatures then remember that you actually said the words you speak as the verbal component of the spell."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"reaction","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":76},{"name":"Incite Greed","source":"AI","level":3,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":{"text":"a gem worth at least 50 gp","cost":5000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"When you cast this spell, you present the gem used as the material component and choose any number of creatures within range that can see you. Each target must succeed on a Wisdom saving throw or be <i class=\\"text-dnd-gold\\">charmed</i> by you until the spell ends, or until you or your companions do anything harmful to it. While <i class=\\"text-dnd-gold\\">charmed</i> in this way, a creature can do nothing but use its movement to approach you in a safe manner. While an affected creature is within 5 feet of you, it cannot move, but simply stares greedily at the gem you present."},{"type":"text","content":"At the end of each of its turns, an affected target can make a Wisdom saving throw. If it succeeds, this effect ends for that target."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":76},{"name":"Jim's Glowing Coin","source":"AI","level":2,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"s":true,"m":"a coin","r":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"Of the many tactics employed by master magician and renowned adventurer Jim Darkmagic, the old glowing coin trick is a time-honored classic. When you cast the spell, you hurl the coin that is the spell's material component to any spot within range. The coin lights up as if under the effect of a <a href=\\"/spells?search=light\\" class=\\"text-dnd-gold hover:underline\\">light</a> spell. Each creature of your choice that you can see within 30 feet of the coin must succeed on a Wisdom saving throw or be distracted for the duration. While distracted, a creature has disadvantage on Wisdom (<i>Perception</i>) checks and initiative rolls."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":76},{"name":"Jim's Magic Missile","source":"AI","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"r":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"{\\"type\\":\\"quote\\",\\"entries\\":[\\"Jim's magic missile is an ancient and powerful spell, as well as being the name of my band in Wizard Academy.\\"],\\"by\\":\\"Jim Darkmagic\\"}"},{"type":"text","content":"Any apprentice wizard can cast a boring old magic missile. Sure, it always strikes its target. Yawn. Do away with the drudgery of your grandfather's magic with this improved version of the spell, as used by Jim Darkmagic!"},{"type":"text","content":"You create three twisting, whistling, hypoallergenic, gluten-free darts of magical force. Each dart targets a creature of your choice that you can see within range. Make a ranged spell attack for each missile. On a hit, a missile deals <span class=\\"text-red-400 font-semibold\\">2d4</span> force damage to its target."},{"type":"text","content":"If the attack roll scores a critical hit, the target of that missile takes <span class=\\"text-red-400 font-semibold\\">5d4</span> force damage instead of you rolling damage twice for a critical hit. If the attack roll for any missile is a 1, all missiles miss their targets and blow up in your face, dealing 1 force damage per missile to you."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 2nd level or higher, the spell creates one more dart, and the royalty component increases by 1 gp, for each slot level above 1st."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":76},{"name":"Motivational Speech","source":"AI","level":3,"school":"E","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"{\\"type\\":\\"quote\\",\\"entries\\":[\\"I once heard a motivational speech by Jim and it was the worst ninety seconds of my life. What does Omin see in him, anyway?\\"],\\"by\\":\\"Walnut Dankgrass\\"}"},{"type":"text","content":"You address allies, staff, or innocent bystanders to exhort and inspire them to greatness, whether they have anything to get excited about or not. Choose up to five creatures within range that can hear you. For the duration, each affected creature gains 5 temporary hit points and has advantage on Wisdom saving throws. If an affected creature is hit by an attack, it has advantage on the next attack roll it makes. Once an affected creature loses the temporary hit points granted by this spell, the spell ends for that creature."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, the temporary hit points increase by 5 for each slot level above 3rd."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":77},{"name":"Linked Glyphs","source":"AitFR-AVT","level":3,"school":"A","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"incense and powdered diamond worth at least 300 gp, which the spell consumes","cost":30000,"consume":true}},"duration":[{"type":"permanent","ends":["dispel","trigger"]}],"entries":[{"type":"text","content":"When you cast this spell, you inscribe a detection glyph that later activates a magical effect at the site of a separate, linked glyph. You inscribe the detection glyph either on a surface (such as a table or a section of floor or wall) or within an object that can be closed (such as a book, a scroll, or a treasure chest) to conceal the glyph. The glyph can cover an area no larger than 10 feet in diameter. If the surface or object is moved more than 10 feet from where you cast this spell, the detection glyph is broken, and the spell ends without being triggered."},{"type":"text","content":"Both glyphs are nearly invisible, and finding either requires a successful Intelligence (<i>Investigation</i>) check against your spell save DC."},{"type":"text","content":"You decide what triggers the detection glyph when you cast this spell. For glyphs inscribed on a surface, the most typical triggers include touching or standing on the glyph, removing another object covering the glyph, approaching within a certain distance of the glyph, or manipulating the object on which the glyph is inscribed. For glyphs inscribed within an object, the most common triggers include opening that object, approaching within a certain distance of the object, or seeing or reading the glyph. Once a glyph is triggered, this spell ends."},{"type":"text","content":"You can further refine the trigger so the spell activates only under certain circumstances or according to physical characteristics (such as height or weight), creature kind (for example, the ward could be set to affect aberrations or drow), or alignment. You can also set conditions for creatures that don't trigger the glyph, such as those who say a certain password."},{"type":"text","content":"When you inscribe the detection glyph, choose an alarm glyph or spell glyph to link to it."},{"type":"section","name":"Alarm Glyph","entries":[{"type":"text","content":"You create and magically link two glyphs: a detection glyph and an effect glyph. Each of these two glyphs must stay within 100 miles of the other or the spell effect ends. When the detection glyph is triggered, the effect glyph reacts like an alarm spell, creating a mental ping in your mind if you are within 1 mile of the effect glyph. This ping awakens you if you are sleeping."}]},{"type":"section","name":"Spell Glyph","entries":[{"type":"text","content":"You create and magically link two glyphs: a detection glyph and an effect glyph. These two glyphs must be within 100 feet of each other. You can store a prepared spell of 4th level or lower in the effect glyph by casting it as part of creating the glyphs. The spell must target a single creature or an area. The spell being stored has no immediate effect when cast in this way. When the detection glyph is triggered, the spell stored in the effect glyph is cast. If the spell has a target, it targets the creature that triggered the glyph. If the spell affects an area, the area is centered on the effect glyph. If the spell summons hostile creatures or creates harmful objects or traps, they appear as close as possible to the effect glyph. If the spell requires <i>concentration</i>, it lasts until the end of its full duration."}]}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 5th level or higher to create a spell glyph, you can store any spell of up to the same level as the slot you use."}]}],"damageInflict":[],"conditionInflict":["invisible"],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":9},{"name":"Aura of Evasion","source":"AU","level":7,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"An aura of alacrity radiates from you in a 30-foot <i>Emanation [Area of Effect]</i> for the duration. While in the aura, you and your allies have <i>Advantage</i> on Dexterity saving throws. When an affected creature is subjected to an effect that allows it to make a Dexterity saving throw to take only half damage, it takes no damage if it succeeds on the save and only half damage if it fails. A creature with the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition doesn't gain any benefit from being in the aura."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":35},{"name":"Battle Familiar","source":"AU","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":{"text":"a diamond worth 25+ GP","cost":2500}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You conjure a familiar imbued with magical might. The familiar appears in an unoccupied space within range; resembles an animal of your choice but is a Celestial, Fey, or Fiend (your choice); and uses the <b>Battle Familiar</b> stat block. When you cast this spell, choose the Brute, Flyer, or Stalker form. The choice determines certain details in the stat block."},{"type":"section","name":"Combat","entries":[{"type":"text","content":"The familiar is an ally to you and your allies. It rolls its own <i>Initiative</i> and acts on its own turn."}]},{"type":"section","name":"Disappearance of the Familiar","entries":[{"type":"text","content":"The battle familiar disappears when the spell ends, if it drops to 0 <i>Hit Points</i>, or if you die. When it disappears, it leaves behind in its space anything it was wearing or carrying. If you cast this spell again, you decide whether you summon the familiar that disappeared or a different one."}]},{"type":"section","name":"One Familiar at a Time","entries":[{"type":"text","content":"You can't have more than one familiar at a time. If you cast this spell while you already have a familiar from this spell, that familiar is replaced by the new one."},{"type":"text","content":"If you have a familiar from the <a href=\\"/spells?search=Find Familiar\\" class=\\"text-dnd-gold hover:underline\\">Find Familiar</a> spell when you cast this spell, you empower your existing familiar rather than conjuring a new one. For the duration, your familiar can attack in addition to taking other actions as normal, and your familiar's game statistics are replaced by the Battle Familiar stat block, but it retains its creature type, alignment, <i>Hit Points</i>, <i>Hit Point Dice</i>, and any features granted by the <a href=\\"/spells?search=Find Familiar\\" class=\\"text-dnd-gold hover:underline\\">Find Familiar</a> spell. Your familiar gains a number of <i>Temporary Hit Points</i> equal to the <i>Hit Points</i> of the battle familiar. Battle Familiar ends early if the familiar has no more <i>Temporary Hit Points</i> left, and these <i>Temporary Hit Points</i> vanish if any remain when Battle Familiar ends. Your familiar reverts to its previous form when Battle Familiar ends."}]}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":35},{"name":"Catnap","source":"AU","level":3,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"s":true,"m":"a pinch of sand"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10}}],"entries":[{"type":"text","content":"You make a calming gesture, and up to three willing creatures of your choice that you can see within range have the <i class=\\"text-dnd-gold\\">Unconscious</i> condition for the spell's duration. The spell ends on a target if it takes damage or another creature takes an action to shake it awake. If a target has the <i class=\\"text-dnd-gold\\">Unconscious</i> condition from this spell for the full duration, that target gains the benefits of finishing a <i>Short Rest</i>, and it can't be affected by this spell again until it finishes a <i>Long Rest</i>."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional willing creature for each spell slot level above 3."}]}],"damageInflict":[],"conditionInflict":["unconscious"],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":37},{"name":"Detonate","source":"AU","level":9,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":500}},"components":{"v":true,"s":true,"m":"a piece of tinder"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You create a magical, explosive seed inside a creature you can see within range. The target makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">10d10</span> Fire damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"An explosion then originates from the target. Each creature in a 60-foot <i>Emanation [Area of Effect]</i> originating from the target (not including the target) makes a Dexterity saving throw, with <i>Disadvantage</i> if this spell reduced the target to 0 <i>Hit Points</i>. A creature takes <span class=\\"text-red-400 font-semibold\\">10d10</span> Fire damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"A nonmagical object that isn't being worn or carried also takes the damage if it's in the <i>Emanation [Area of Effect]</i>, and the object starts burning if it's flammable."}],"entriesHigherLevel":[],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["constitution","dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":38},{"name":"Disruptive Tune","source":"AU","level":2,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A distracting melody momentarily fills a 20-foot-radius <i>Sphere [Area of Effect]</i> centered on a point you choose within range. Each creature in the <i>Sphere [Area of Effect]</i> makes a Constitution saving throw. On a failed save, a target loses <i>Concentration</i>, and it has <i>Disadvantage</i> on Constitution saving throws to maintain <i>Concentration</i> for the spell's duration."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":38},{"name":"Distorted Distance","source":"AU","level":4,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You create an illusory spatial dilation that fills a 60-foot-radius <i>Sphere [Area of Effect]</i> centered on a point within range. For each creature you can see in the <i>Sphere [Area of Effect]</i>, you can choose one of the following effects for it:"},{"type":"list","items":[{"type":"item","name":"Dizzying Elongation","entry":"The creature makes an Intelligence saving throw. On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">2d10</span> Psychic damage, and the <i>Sphere [Area of Effect]</i> is <i>Difficult Terrain</i> for it until the end of its turn."},{"type":"item","name":"Shortened Space","entry":"The creature's <i>Speed</i> increases by 20 feet until the end of its next turn.\\nUntil the spell ends, whenever a creature enters the <i>Sphere [Area of Effect]</i> or ends its turn there, you can choose for it to receive one of these effects. A creature can be affected by this spell only once per turn."}]}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":38},{"name":"Dueling Ground","source":"AU","level":2,"school":"A","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a silk flag worth 100+ GP","cost":10000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You create a magical dueling ground bounded by a glowing, rune-scribed circle in a 15-foot-radius <i>Sphere [Area of Effect]</i> centered on a point on the ground you touch."},{"type":"text","content":"As part of creating the dueling ground, you designate two willing creatures within the <i>Sphere [Area of Effect]</i> as the targets. The spell ends early if a creature other than one of the targets enters the <i>Sphere [Area of Effect]</i>."},{"type":"text","content":"If a target drops to 0 <i>Hit Points</i> while in the dueling ground, the target is <i>Stable</i> and teleports to the nearest unoccupied space outside the dueling ground. If a target is subjected to an effect that would kill it instantly without dealing damage while in the dueling ground, the target doesn't die and instead has 0 <i>Hit Points</i> and the <i class=\\"text-dnd-gold\\">Unconscious</i> condition, is <i>Stable</i>, and teleports to the nearest unoccupied space outside the dueling ground."},{"type":"text","content":"When only one target remains in the dueling ground, runes matching those on the ground around the <i>Sphere [Area of Effect]</i> briefly flash around the remaining target's head like a crown."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional willing creature for each spell slot level above 2."}]}],"damageInflict":[],"conditionInflict":["unconscious"],"savingThrow":[],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":38},{"name":"Enervation","source":"AU","level":5,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A tendril of inky darkness reaches out from you to drain life from a creature you can see within range."},{"type":"text","content":"The target makes a Dexterity saving throw. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">6d8</span> Necrotic damage. On each of your subsequent turns, you can take a <i>Bonus Action</i> to deal <span class=\\"text-red-400 font-semibold\\">2d8</span> Necrotic damage to the target automatically. The spell ends if the target is ever outside the spell's range or it has <i>Cover</i> from you."},{"type":"text","content":"On a successful save, the target takes half the initial damage only, and the spell ends."},{"type":"text","content":"Whenever this spell deals damage to a target, you regain <i>Hit Points</i> equal to half the amount of Necrotic damage dealt."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The initial damage increases by <span class=\\"text-green-400 font-mono\\">1d8</span> for each spell slot level above 5."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":38},{"name":"Entrancing Mirrors","source":"AU","level":8,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":"a mirror shard"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create dozens of illusory mirrors to confuse up to three creatures of your choice that you can see within range."},{"type":"text","content":"Each target makes an Intelligence saving throw. On a failed save, a target takes <span class=\\"text-red-400 font-semibold\\">7d6</span> Psychic damage and has the <i class=\\"text-dnd-gold\\">Stunned</i> condition. While the target is <i class=\\"text-dnd-gold\\">Stunned</i>, its <i>Speed</i> is halved. On a successful save, a target takes half as much damage only."},{"type":"text","content":"A <i class=\\"text-dnd-gold\\">Stunned</i> target repeats the Intelligence saving throw at the end of each of its turns, ending the spell on itself on a success."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":["stunned"],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":39},{"name":"Festering Blast","source":"AU","level":4,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"line","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"A 60-foot-long, 10-foot-wide <i>Line [Area of Effect]</i> of miasma blasts from you in a direction you choose. Each creature in the <i>Line [Area of Effect]</i> must make a Constitution saving throw. On a failed save, a target takes <span class=\\"text-red-400 font-semibold\\">4d10</span> Necrotic damage and has the <i class=\\"text-dnd-gold\\">Poisoned</i> condition for the duration."},{"type":"text","content":"A creature <i class=\\"text-dnd-gold\\">Poisoned</i> by this spell takes <span class=\\"text-red-400 font-semibold\\">2d10</span> Poison damage at the start of each of its turns. At the end of each of its turns, a <i class=\\"text-dnd-gold\\">Poisoned</i> target repeats the save, ending the spell on itself on a success."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The initial damage increases by <span class=\\"text-green-400 font-mono\\">1d10</span> for each spell slot level above 4."}]}],"damageInflict":["necrotic","poison"],"conditionInflict":["poisoned"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":39},{"name":"Fractured Awareness","source":"AU","level":7,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You cause a creature to receive conflicting visions of multiple possible futures. Choose a creature you can see within range. The target makes an Intelligence saving throw. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">12d10</span> Psychic damage and has <i>Disadvantage</i> on <i>D20 Test</i> for the duration. On a successful save, the target takes half as much damage only, and the spell ends."},{"type":"text","content":"At the end of each of its turns, an affected target repeats the save, ending the spell on a success."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":40},{"name":"Grave Ground","source":"AU","level":5,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a handful of grave dirt"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Skeletal hands burst from an area on the ground within range. The area consists of up to four 10-foot squares, which you arrange as you like. Each square must be contiguous with at least one other square. That area is <i>Difficult Terrain</i> for your enemies."},{"type":"text","content":"Any enemy in that area when the skeletal hands appear makes a Strength saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">6d6</span> Necrotic damage, and until the end of its next turn, the creature subtracts <span class=\\"text-green-400 font-mono\\">1d6</span> from all its damage rolls. An enemy also makes this save if it enters the area or ends its turn there. A creature makes this save only once per turn."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-green-400 font-mono\\">1d6</span> for each spell slot level above 5."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":40},{"name":"Hindsight","source":"AU","level":9,"school":"D","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":500}},"components":{"v":true,"s":true,"m":{"text":"a tiny hourglass worth 500+ GP, which the spell consumes","cost":50000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You peer backward through the fabric of time. You see visions of events that occurred within range throughout the past 10 years, racing by at approximately 1 day per second. Throughout the spell's duration, you can freely slow down, pause, rewind, or fast-forward through these visions."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":40},{"name":"Illusory Dragon","source":"AU","level":8,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"By gathering threads of shadow material from the Shadowfell, you create a Huge shadowy dragon in an unoccupied space that you can see within range. The illusion lasts for the spell's duration and occupies its space as if it were a creature. The illusion is tangible because of the shadow material used to create it but has <i>Immunity</i> to all damage and conditions."},{"type":"text","content":"When the illusion appears, any enemy that can see it makes a Wisdom saving throw. On a failed save, the creature drops whatever it's holding and has the <i class=\\"text-dnd-gold\\">Frightened</i> condition for the duration. If a creature <i class=\\"text-dnd-gold\\">Frightened</i> in this way ends its turn in a space where it doesn't have line of sight to the illusion, the creature repeats the saving throw, ending the condition on itself on a success."},{"type":"text","content":"As a <i>Bonus Action</i>, you can move the illusion up to 60 feet. At any point during its movement, you can cause the shadowy dragon to exhale a blast of energy in a 60-foot <i>Cone [Area of Effect]</i>. Each creature in the <i>Cone [Area of Effect]</i> makes an Intelligence saving throw, taking <span class=\\"text-red-400 font-semibold\\">6d6</span> Acid, Cold, Fire, Lightning, Necrotic, or Poison damage (your choice when you create the dragon) on a failed save or half as much damage on a successful one."},{"type":"text","content":"A creature that takes a <b>Study</b> action to examine the dragon can determine that it is an illusion with a successful Intelligence (<i>Investigation</i>) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image and has <i>Advantage</i> on saving throws to end the <i class=\\"text-dnd-gold\\">Frightened</i> condition it caused and to resist its exhalation."}],"entriesHigherLevel":[],"damageInflict":["acid","cold","fire","lightning","necrotic","poison"],"conditionInflict":["frightened"],"savingThrow":["intelligence","wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":40},{"name":"Inflict Doubt","source":"AU","level":3,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You inflict self-doubt on a creature you can see within range. The target must succeed on a Wisdom saving throw or have <i>Disadvantage</i> on <i>D20 Test</i> for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":40},{"name":"Invulnerability","source":"AU","level":9,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"a piece of adamantine worth 500+ GP, which the spell consumes","cost":50000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You have <i>Immunity</i> to all damage until the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":41},{"name":"Iron Body","source":"AU","level":8,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"diamond dust worth 250+ GP, which the spell consumes","cost":25000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"One willing creature you touch transforms into living metal. Until the spell ends, the target's <i class=\\"text-dnd-gold\\">Exhaustion</i> level can't increase; the target has <i>Resistance</i> to Bludgeoning, Fire, Piercing, and Slashing damage; and it has <i>Immunity</i> to Poison damage and the <i class=\\"text-dnd-gold\\">Paralyzed</i>, <i class=\\"text-dnd-gold\\">Petrified</i>, and <i class=\\"text-dnd-gold\\">Poisoned</i> conditions. If the target is <i class=\\"text-dnd-gold\\">Paralyzed</i>, <i class=\\"text-dnd-gold\\">Petrified</i>, or <i class=\\"text-dnd-gold\\">Poisoned</i> when you cast the spell, those conditions immediately end for the target."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":41},{"name":"Lightning Ring","source":"AU","level":8,"school":"V","time":[{"number":1,"unit":"bonus"}],"range":{"type":"emanation","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":"a bit of fur and a glass ring"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"A ring of crackling electricity fills a 10-foot <i>Emanation [Area of Effect]</i> originating from you. Whenever the <i>Emanation [Area of Effect]</i> enters a creature's space and whenever a creature enters the <i>Emanation [Area of Effect]</i> or ends its turn there, you can force that creature to make a Constitution saving throw. On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">3d6</span> Lightning damage plus <span class=\\"text-red-400 font-semibold\\">3d6</span> Thunder damage, and it has the <i class=\\"text-dnd-gold\\">Deafened</i> condition for 1 minute. On a successful save, the creature takes half as much damage only."},{"type":"text","content":"As a <b>Magic</b> action while the spell is active, you can emit a 60-foot-long, 5-foot-wide <i>Line [Area of Effect]</i> out from you in a direction you choose. Each creature in the <i>Line [Area of Effect]</i> makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">6d6</span> Lightning damage on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[],"damageInflict":["lightning","thunder"],"conditionInflict":["deafened"],"savingThrow":["constitution","dexterity"],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":41},{"name":"Moment of Prescience","source":"AU","level":8,"school":"D","time":[{"number":1,"unit":"reaction","condition":"which you take when you fail a D20 Test or when a creature hits you with an attack roll"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You have a powerful sixth sense that guides you at just the right time. Turn the roll of your failed <i>D20 Test</i> into a 20, or turn the roll of the triggering attack roll into a 1."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"reaction","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":42},{"name":"Mordenkainen's Lucubration","source":"AU","level":5,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You recover up to two expended spell slots of level 2 or lower."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The maximum level of spell slots you can recover increases to level 3 (if cast with a level 6-7 spell slot) or level 4 (if cast with a level 8+ spell slot)."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":42},{"name":"Negative Energy Flood","source":"AU","level":5,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"m":"a broken bone and a square of black silk"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You send ribbons of negative energy at one creature you can see within range. If the target isn't Undead, it makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">3d10 + 25</span> Necrotic damage on a failed save or half as much damage on a successful one. A Humanoid killed by this spell rises at the start of your next turn as a <b>Zombie</b> that follows your verbal orders for 24 hours, after which it acts according to its nature."},{"type":"text","content":"If the target is Undead, it gains <span class=\\"text-green-400 font-mono\\">3d10</span> <i>Temporary Hit Points</i>."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-green-400 font-mono\\">1d10</span> for each spell slot level above 5."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":42},{"name":"Power Word Pain","source":"AU","level":7,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"You speak a word of power that causes waves of intense pain to assail one creature you can see within range. If the target has 100 <i>Hit Points</i> or fewer, it takes <span class=\\"text-red-400 font-semibold\\">6d8</span> Force damage and has the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration. Otherwise, it takes <span class=\\"text-red-400 font-semibold\\">6d8</span> Force damage only."},{"type":"text","content":"While the target is <i class=\\"text-dnd-gold\\">Charmed</i>, its <i>Speed</i> can be no more than 10 feet, and it has <i>Disadvantage</i> on <i>D20 Test</i> except Constitution saving throws. In addition, when the target tries to cast a spell, it must first succeed on a Constitution saving throw, or the spell dissipates with no effect, and the action, <i>Bonus Action</i>, or <i>Reaction</i> used to cast it is wasted. If that spell was cast with a spell slot, the slot isn't expended."},{"type":"text","content":"At the end of each of its turns, the <i class=\\"text-dnd-gold\\">Charmed</i> target makes a Constitution saving throw, ending the spell on itself on a successful save."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":["charmed"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":42},{"name":"Reweave Fate","source":"AU","level":7,"school":"D","time":[{"number":1,"unit":"reaction","condition":"which you take when a creature you can see within 60 feet of you fails a D20 Test"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You untangle a single thread of fate to encourage a different result. The creature that failed the <i>D20 Test</i> can reroll it with <i>Advantage</i>, and the creature must use the new roll. If the <i>D20 Test</i> is successful, the creature gains <span class=\\"text-green-400 font-mono\\">6d10</span> <i>Temporary Hit Points</i> from its strengthened fate."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"reaction","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":42},{"name":"Spirit Lantern","source":"AU","level":5,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a black lantern"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10}}],"entries":[{"type":"text","content":"You conjure a floating, ghostly black lantern that hovers above you and sheds <i>Dim Light</i> in a 60-foot radius. When an enemy dies within this <i>Dim Light</i>, a fragment of the creature's soul flies into the lantern. The lantern can hold a number of soul fragments equal to your spellcasting ability modifier, and those fragments dissipate when the spell ends."},{"type":"text","content":"As a <i>Bonus Action</i>, you can expend a soul fragment to create one of the following effects."},{"type":"section","name":"Drain Life","entries":[{"type":"text","content":"The soul fragment darts at a creature of your choice that you can see within 60 feet of yourself. The target makes a Constitution saving throw, taking Necrotic damage equal to <span class=\\"text-red-400 font-semibold\\">4d8</span> plus your spellcasting ability modifier on a failed save or half as much damage on a successful one."}]},{"type":"section","name":"Repair Undead","entries":[{"type":"text","content":"The soul fragment flies into an Undead creature of your choice that you can see within 60 feet of yourself. That creature regains <i>Hit Points</i> equal to <span class=\\"text-green-400 font-mono\\">4d8</span> plus your spellcasting ability modifier."}]},{"type":"section","name":"Ward Ally","entries":[{"type":"text","content":"The soul fragment darts around a creature of your choice that you can see within 60 feet of yourself. Other creatures have <i>Disadvantage</i> on attack rolls against the chosen creature until the start of your next turn."}]}],"entriesHigherLevel":[],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":43},{"name":"Summon Dinosaur","source":"AU","level":6,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"polished scale worth 600+ GP","cost":60000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth the spirit of a primeval dinosaur. It manifests in an unoccupied space that you can see within range and uses the <b>Dinosaur Spirit</b> stat block. When you cast the spell, choose Ankylosaur, <b>Triceratops</b>, or Tyrannosaur. The creature resembles a dinosaur of the chosen type, which determines certain details in its stat block. The creature disappears when it drops to 0 <i>Hit Points</i> or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your allies. In combat, the creature shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, the creature takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":43},{"name":"Summon Plant","source":"AU","level":5,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"herbs worth 500+ GP","cost":50000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth the spirit of an animated plant. It manifests in an unoccupied space that you can see within range and uses the <b>Plant Spirit</b> stat block. When you cast the spell, choose Fungus, Tree, or Vine. The creature resembles a plant of the chosen type, which determines certain details in its stat block. The creature disappears when it drops to 0 <i>Hit Points</i> or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your allies. In combat, the creature shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":44},{"name":"Transfix","source":"AU","level":7,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"For the duration, your appearance becomes otherworldly and alluring. One creature of your choice that you can see within 60 feet of you must succeed on a Charisma saving throw or have the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration."},{"type":"text","content":"While <i class=\\"text-dnd-gold\\">Charmed</i>, the target has the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition, and if the target is more than 5 feet away from you, it moves on its turn toward you by the most direct route, trying to get within 5 feet of you. If the <i class=\\"text-dnd-gold\\">Charmed</i> creature ends its turn within 5 feet of you, it takes <span class=\\"text-red-400 font-semibold\\">4d8</span> Psychic damage."},{"type":"text","content":"The target doesn't avoid <b>Opportunity Attack</b> when moving toward you, but before moving into damaging terrain (such as lava or a pit), the target repeats the save, ending the spell on itself on a success."},{"type":"text","content":"Until the spell ends, you can take a <b>Magic</b> action on subsequent turns to target another creature, but you can't target a creature again if it has succeeded on a save against this casting of the spell."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-green-400 font-mono\\">1d8</span> for each spell slot level above 7."}]}],"damageInflict":["psychic"],"conditionInflict":["charmed","incapacitated"],"savingThrow":["charisma"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":44},{"name":"Uncertain Footing","source":"AU","level":2,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a distorted lens"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create illusory obstacles such as rocks or spikes in an attempt to confuse up to three creatures you can see within range, affecting their ability to move. Each target makes an Intelligence saving throw. On a failed save, a target's <i>Speed</i> is halved, and it can't take the <b>Dash</b> action. A hampered target repeats the save at the end of each of its turns, ending the spell on itself on a success."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":44},{"name":"Vision of Elapsing Eons","source":"AU","level":9,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"You trick a creature you can see within range into believing it is watching itself and its surroundings crumble away, as if eons were passing in moments. The target must succeed on an Intelligence saving throw or take <span class=\\"text-red-400 font-semibold\\">10d12</span> Psychic damage and have the <i class=\\"text-dnd-gold\\">Paralyzed</i> condition for the duration."},{"type":"text","content":"While <i class=\\"text-dnd-gold\\">Paralyzed</i>, the target repeats the save at the end of each of its turns. On a failed save, it gains 1 <i class=\\"text-dnd-gold\\">Exhaustion</i> level. On a successful save, the spell ends. The spell ends early if someone within 5 feet of the target takes an action to shake it free from the illusion."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":["exhaustion","paralyzed"],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":45},{"name":"Wail of the Banshee","source":"AU","level":9,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You emit a terrible scream that can kill those who hear it. Choose up to ten creatures within range. Each target with 50 <i>Hit Points</i> or fewer dies. Targets with more than 50 <i>Hit Points</i> make a Constitution saving throw. On a failed save, a target takes <span class=\\"text-red-400 font-semibold\\">12d10</span> Psychic damage and has the <i class=\\"text-dnd-gold\\">Deafened</i> condition for 1 hour. On a successful save, a target takes half as much damage only. A target is unaffected by the spell if it can't hear you."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":["deafened"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":45},{"name":"Waves of Exhaustion","source":"AU","level":5,"school":"N","time":[{"number":1,"unit":"bonus"}],"range":{"type":"cone","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a piece of dried meat"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You evoke a nimbus of flickering gray light around your body. For the duration, you can take a <b>Magic</b> action to emit a wave of gray light in a 60-foot <i>Cone [Area of Effect]</i>. Creatures in that area must succeed on a Constitution saving throw or gain 1 <i class=\\"text-dnd-gold\\">Exhaustion</i> level. This spell can't increase a creature's <i class=\\"text-dnd-gold\\">Exhaustion</i> level above 4."},{"type":"text","content":"<i class=\\"text-dnd-gold\\">Exhaustion</i> levels gained from this spell are removed when the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["exhaustion"],"savingThrow":["constitution"],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":45},{"name":"Wither and Bloom","source":"AU","level":2,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a withered vine twisted into a loop"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You invoke both death and life in a 10-foot-radius <i>Sphere [Area of Effect]</i> centered on a point within range. Each creature of your choice in that area makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">3d6</span> Necrotic damage on a failed save or half as much damage on a successful one. Nonmagical plants in that area that aren't creatures, such as trees and shrubs, wither."},{"type":"text","content":"In addition, one creature of your choice in that area can roll one of its unexpended <i>Hit Point Dice</i> and regain a number of <i>Hit Points</i> equal to the roll plus your spellcasting ability modifier. That die is then expended."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-green-400 font-mono\\">1d6</span> for each spell slot level above 2. The number of <i>Hit Point Dice</i> that can be rolled and expended increases by one for each spell slot level above 2. You add your spellcasting modifier to the number of <i>Hit Points</i> regained by this spell only once, regardless of the number of <i>Hit Point Dice</i> rolled and expended."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":45},{"name":"Zone of Amicability","source":"AU","level":4,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10}}],"entries":[{"type":"text","content":"A magical zone of amicability radiates from you in a 60-foot <i>Emanation [Area of Effect]</i> for the duration. When you make an ability check to influence a creature in that area, you can treat a <span class=\\"text-green-400 font-mono\\">d20</span> roll of 9 or lower as a 10."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":45},{"name":"Antagonize","source":"BMT","level":3,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a playing card depicting a rogue"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You whisper magical words that antagonize one creature of your choice within range. The target must make a Wisdom saving throw. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">4d4</span> psychic damage and must immediately use its reaction to make a melee attack against another creature of your choice that you can see. If the target can't make this attack (for example, because there is no one within its reach or because its reaction is unavailable), the target instead has disadvantage on the next attack roll it makes before the start of your next turn. On a successful save, the target takes half as much damage only."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 4d4 for each slot level above 3rd."}]}],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":50},{"name":"Spirit of Death","source":"BMT","level":4,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"a gilded playing card worth at least 400 gp and depicting an avatar of death","cost":40000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth a spirit that embodies death. The spirit manifests in an unoccupied space you can see within range and uses the <b>reaper spirit</b> stat block. The spirit disappears when it is reduced to 0 hit points or when the spell ends."},{"type":"text","content":"The spirit is an ally to you and your companions. In combat, the spirit shares your initiative count and takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue the spirit any commands, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 5th level or higher, use the higher level wherever the spell's level appears in the reaper spirit stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":50},{"name":"Spray of Cards","source":"BMT","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"cone","distance":{"type":"feet","amount":15}},"components":{"v":true,"s":true,"m":"a deck of cards"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You spray a 15-foot cone of spectral cards. Each creature in that area must make a Dexterity saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">2d10</span> force damage and has the <i class=\\"text-dnd-gold\\">blinded</i> condition until the end of its next turn. On a successful save, a creature takes half as much damage only."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 2d10 for each slot level above 2nd."}]}],"damageInflict":["force"],"conditionInflict":["blinded"],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":50},{"name":"Homunculus Servant","source":"EFA","level":2,"school":"C","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":{"text":"a gem worth 100+ GP","cost":10000}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You summon a special homunculus in an unoccupied space within range. This creature uses the <b>Homunculus Servant</b> stat block. If you already have a homunculus from this spell, the homunculus is replaced by the new one. You determine the homunculus's appearance, such as a mechanical-looking bird, winged vial, or miniature animate cauldron."},{"type":"section","name":"Combat","entries":[{"type":"text","content":"The homunculus is an ally to you and your allies. In combat, it shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}]}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":true,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":21},{"name":"Dark Star","source":"EGW","level":8,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":{"text":"a shard of onyx and a drop of the caster's blood, both of which the spell consumes","consume":true}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"This spell creates a sphere centered on a point you choose within range. The sphere can have a radius of up to 40 feet. The area within this sphere is filled with magical darkness and crushing gravitational force."},{"type":"text","content":"For the duration, the spell's area is difficult terrain. A creature with <i>darkvision</i> can't see through the magical darkness, and nonmagical light can't illuminate it. No sound can be created within or pass through the area. Any creature or object entirely inside the sphere is immune to thunder damage, and creatures are <i class=\\"text-dnd-gold\\">deafened</i> while entirely inside it. Casting a spell that includes a verbal component is impossible there."},{"type":"text","content":"Any creature that enters the spell's area for the first time on a turn or starts its turn there must make a Constitution saving throw. The creature takes <span class=\\"text-red-400 font-semibold\\">8d10</span> force damage on a failed save, or half as much damage on a successful one. A creature reduced to 0 hit points by this damage is disintegrated. A disintegrated creature and everything it is wearing and carrying, except magic items, are reduced to a pile of fine gray dust."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":["deafened"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":186},{"name":"Fortune's Favor","source":"EGW","level":2,"school":"D","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"a white pearl worth at least 100 gp, which the spell consumes","cost":10000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You impart latent luck to yourself or one willing creature you can see within range. When the chosen creature makes an attack roll, an ability check, or a saving throw before the spell ends, it can dismiss this spell on itself to roll an additional <span class=\\"text-green-400 font-mono\\">d20</span> and choose which of the <span class=\\"text-green-400 font-mono\\">d20</span>s to use. Alternatively, when an attack roll is made against the chosen creature, it can dismiss this spell on itself to roll a <span class=\\"text-green-400 font-mono\\">d20</span> and choose which of the <span class=\\"text-green-400 font-mono\\">d20</span>s to use, the one it rolled or the one the attacker rolled."},{"type":"text","content":"If the original <span class=\\"text-green-400 font-mono\\">d20</span> roll has advantage or disadvantage, the creature rolls the additional <span class=\\"text-green-400 font-mono\\">d20</span> after advantage or disadvantage has been applied to the original roll."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":186},{"name":"Gift of Alacrity","source":"EGW","level":1,"school":"D","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You touch a willing creature. For the duration, the target can add <span class=\\"text-green-400 font-mono\\">1d8</span> to its initiative rolls."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":186},{"name":"Gravity Fissure","source":"EGW","level":6,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"line","distance":{"type":"feet","amount":100}},"components":{"v":true,"s":true,"m":"a fistful of iron filings"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You manifest a ravine of gravitational energy in a line originating from you that is 100 feet long and 5 feet wide. Each creature in that line must make a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">8d8</span> force damage on a failed save, or half as much damage on a successful one."},{"type":"text","content":"Each creature within 10 feet of the line but not in it must succeed on a Constitution saving throw or take <span class=\\"text-red-400 font-semibold\\">8d8</span> force damage and be pulled toward the line until the creature is in its area."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 7th level or higher, the damage increases by 8d8 for each slot level above 6th."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":187},{"name":"Gravity Sinkhole","source":"EGW","level":4,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a black marble"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A 20-foot-radius sphere of crushing force forms at a point you can see within range and tugs at the creatures there. Each creature in the sphere must make a Constitution saving throw. On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">5d10</span> force damage and is pulled in a straight line toward the center of the sphere, ending in an unoccupied space as close to the center as possible (even if that space is in the air). On a successful save, the creature takes half as much damage and isn't pulled."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 5th level or higher, the damage increases by 5d10 for each slot level above 4th."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":187},{"name":"Immovable Object","source":"EGW","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"gold dust worth at least 25 gp, which the spell consumes","cost":2500,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You touch an object that weighs no more than 10 pounds and cause it to become magically fixed in place. You and the creatures you designate when you cast this spell can move the object normally. You can also set a password that, when spoken within 5 feet of the object, suppresses this spell for 1 minute."},{"type":"text","content":"If the object is fixed in the air, it can hold up to 4,000 pounds of weight. More weight causes the object to fall. Otherwise, a creature can use an action to make a Strength check against your spell save DC. On a success, the creature can move the object up to 10 feet."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"If you cast this spell using a spell slot of 4th or 5th level, the DC to move the object increases by 5, it can carry up to 8,000 pounds of weight, and the duration increases to 24 hours. If you cast this spell using a spell slot of 6th level or higher, the DC to move the object increases by 10, it can carry up to 20,000 pounds of weight, and the effect is permanent until dispelled."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":187},{"name":"Magnify Gravity","source":"EGW","level":1,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"round","amount":1}}],"entries":[{"type":"text","content":"The gravity in a 10-foot-radius sphere centered on a point you can see within range increases for a moment. Each creature in the sphere on the turn when you cast the spell must make a Constitution saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">2d8</span> force damage, and its speed is halved until the end of its next turn. On a successful save, a creature takes half as much damage and suffers no reduction to its speed."},{"type":"text","content":"Until the start of your next turn, any object that isn't being worn or carried in the sphere requires a successful Strength check against your spell save DC to pick up or move."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 2d8 for each slot level above 1st."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":188},{"name":"Pulse Wave","source":"EGW","level":3,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"cone","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You create intense pressure, unleash it in a 30-foot cone, and decide whether the pressure pulls or pushes creatures and objects. Each creature in that cone must make a Constitution saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">6d6</span> force damage on a failed save, or half as much damage on a successful one. And every creature that fails the save is either pulled 15 feet toward you or pushed 15 feet away from you, depending on the choice you made for the spell."},{"type":"text","content":"In addition, unsecured objects that are completely within the cone are likewise pulled or pushed 15 feet."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 6d6 and the distance pulled or pushed increases by 5 feet for each slot level above 3rd."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":188},{"name":"Ravenous Void","source":"EGW","level":9,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":1000}},"components":{"v":true,"s":true,"m":"a small, nine-pointed star made of iron"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a 20-foot-radius sphere of destructive gravitational force centered on a point you can see within range. For the spell's duration, the sphere and any space within 100 feet of it are difficult terrain, and nonmagical objects fully inside the sphere are destroyed if they aren't being worn or carried."},{"type":"text","content":"When the sphere appears and at the start of each of your turns until the spell ends, unsecured objects within 100 feet of the sphere are pulled toward the sphere's center, ending in an unoccupied space as close to the center as possible."},{"type":"text","content":"A creature that starts its turn within 100 feet of the sphere must succeed on a Strength saving throw or be pulled straight toward the sphere's center, ending in an unoccupied space as close to the center as possible. A creature that enters the sphere for the first time on a turn or starts its turn there takes <span class=\\"text-red-400 font-semibold\\">5d10</span> force damage and is <i class=\\"text-dnd-gold\\">restrained</i> until it is no longer in the sphere. If the sphere is in the air, the <i class=\\"text-dnd-gold\\">restrained</i> creature hovers inside the sphere. A creature can use its action to make a Strength check against your spell save DC, ending this <i class=\\"text-dnd-gold\\">restrained</i> condition on itself or another creature in the sphere that it can reach. A creature reduced to 0 hit points by this spell is annihilated, along with any nonmagical items it is wearing or carrying."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":["restrained"],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":188},{"name":"Reality Break","source":"EGW","level":8,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a crystal prism"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You shatter the barriers between realities and timelines, thrusting a creature into turmoil and madness. The target must succeed on a Wisdom saving throw, or it can't take reactions until the spell ends. The affected target must also roll a <span class=\\"text-green-400 font-mono\\">d10</span> at the start of each of its turns; the number rolled determines what happens to the target, as shown on the Reality Break Effects table."},{"type":"text","content":"At the end of each of its turns, the affected target can repeat the Wisdom saving throw, ending the spell on itself on a success."},{"type":"table","caption":"Reality Break Effects","colLabels":["d10","Effect"],"rows":[["1-2","<b>Vision of the Far Realm.</b> The target takes <span class=\\"text-red-400 font-semibold\\">6d12</span> psychic damage, and it is <i class=\\"text-dnd-gold\\">stunned</i> until the end of the turn."],["3-5","<b>Rending Rift.</b> The target must make a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">8d12</span> force damage on a failed save, or half as much damage on a successful one."],["6-8","<b>Wormhole.</b> The target is teleported, along with everything it is wearing and carrying, up to 30 feet to an unoccupied space of your choice that you can see. The target also takes <span class=\\"text-red-400 font-semibold\\">10d12</span> force damage and is knocked <i class=\\"text-dnd-gold\\">prone</i>."],["9-10","<b>Chill of the Dark Void.</b> The target takes <span class=\\"text-red-400 font-semibold\\">10d12</span> cold damage, and it is <i class=\\"text-dnd-gold\\">blinded</i> until the end of the turn."]]}],"entriesHigherLevel":[],"damageInflict":["psychic","force","cold"],"conditionInflict":["stunned","prone","blinded"],"savingThrow":["wisdom","dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":189},{"name":"Sapping Sting","source":"EGW","level":0,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You sap the vitality of one creature you can see in range. The target must succeed on a Constitution saving throw or take <span class=\\"text-red-400 font-semibold\\">1d4</span> necrotic damage and fall <i class=\\"text-dnd-gold\\">prone</i>."},{"type":"text","content":"This spell's damage increases by <span class=\\"text-red-400 font-semibold\\">1d4</span> when you reach 5th level (<span class=\\"text-red-400 font-semibold\\">2d4</span>), 11th level (<span class=\\"text-red-400 font-semibold\\">3d4</span>), and 17th level (<span class=\\"text-red-400 font-semibold\\">4d4</span>)."}],"entriesHigherLevel":[],"damageInflict":["necrotic"],"conditionInflict":["prone"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":189},{"name":"Temporal Shunt","source":"EGW","level":5,"school":"T","time":[{"number":1,"unit":"reaction","condition":"taken when a creature you can see makes an attack roll or starts to cast a spell"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"round","amount":1}}],"entries":[{"type":"text","content":"You target the triggering creature, which must succeed on a Wisdom saving throw or vanish, being thrown to another point in time and causing the attack to miss or the spell to be wasted. At the start of its next turn, the target reappears where it was or in the closest unoccupied space. The target doesn't remember you casting the spell or being affected by it."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 6th level or higher, you can target one additional creature for each slot level above 5th. All targets must be within 30 feet of each other."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"reaction","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":189},{"name":"Tether Essence","source":"EGW","level":7,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"a spool of platinum cord worth at least 250 gp, which the spell consumes","cost":25000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Two creatures you can see within range must make a Constitution saving throw, with disadvantage if they are within 30 feet of each other. Either creature can willingly fail the save. If either save succeeds, the spell has no effect. If both saves fail, the creatures are magically linked for the duration, regardless of the distance between them. When damage is dealt to one of them, the same damage is dealt to the other one. If hit points are restored to one of them, the same number of hit points are restored to the other one. If either of the tethered creatures is reduced to 0 hit points, the spell ends on both. If the spell ends on one creature, it ends on both."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":189},{"name":"Time Ravage","source":"EGW","level":9,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"an hourglass filled with diamond dust worth at least 5,000 gp, which the spell consumes","cost":500000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You target a creature you can see within range, putting its physical form through the devastation of rapid aging. The target must make a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">10d12</span> necrotic damage on a failed save, or half as much damage on a successful one. If the save fails, the target also ages to the point where it has only 30 days left before it dies of old age. In this aged state, the target has disadvantage on attack rolls, ability checks, and saving throws, and its walking speed is halved. Only the <a href=\\"/spells?search=wish\\" class=\\"text-dnd-gold hover:underline\\">wish</a> spell or the <a href=\\"/spells?search=greater restoration\\" class=\\"text-dnd-gold hover:underline\\">greater restoration</a> cast with a 9th-level spell slot can end these effects and restore the target to its previous age."}],"entriesHigherLevel":[],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":189},{"name":"Wristpocket","source":"EGW","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You flick your wrist, causing one object in your hand to vanish. The object, which only you can be holding and can weigh no more than 5 pounds, is transported to an extradimensional space, where it remains for the duration."},{"type":"text","content":"Until the spell ends, you can use your action to summon the object to your free hand, and you can use your action to return the object to the extradimensional space. An object still in the pocket plane when the spell ends appears in your space, at your feet."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":190},{"name":"Ashardalon's Stride","source":"FTD","level":3,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"The billowing flames of a dragon blast from your feet, granting you explosive speed. For the duration, your speed increases by 20 feet and moving doesn't provoke opportunity attacks."},{"type":"text","content":"When you move within 5 feet of a creature or an object that isn't being worn or carried, it takes <span class=\\"text-red-400 font-semibold\\">1d6</span> fire damage from your trail of heat. A creature or object can take this damage only once during a turn."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, increase your speed by 5 feet for each spell slot level above 3rd. The spell deals an additional 1d6 fire damage for each slot level above 3rd."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":19},{"name":"Draconic Transformation","source":"FTD","level":7,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"a statuette of a dragon, worth at least 500 gp","cost":50000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"With a roar, you draw on the magic of dragons to transform yourself, taking on draconic features. You gain the following benefits until the spell ends:"},{"type":"list","items":[{"type":"item","name":"Blindsight","entry":"You have <i>blindsight</i> with a range of 30 feet. Within that range, you can effectively see anything that isn't behind Cover, even if you're <i class=\\"text-dnd-gold\\">blinded</i> or in darkness. Moreover, you can see an <i class=\\"text-dnd-gold\\">invisible</i> creature, unless the creature successfully hides from you."},{"type":"item","name":"Breath Weapon","entry":"When you cast this spell, and as a bonus action on subsequent turns for the duration, you can exhale shimmering energy in a 60-foot cone. Each creature in that area must make a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">6d8</span> force damage on a failed save, or half as much damage on a successful one."},{"type":"item","name":"Wings","entry":"Incorporeal wings sprout from your back, giving you a flying speed of 60 feet."}]}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":19},{"name":"Fizban's Platinum Shield","source":"FTD","level":6,"school":"A","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"a platinum-plated dragon scale, worth at least 500 gp","cost":50000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a field of silvery light that surrounds a creature of your choice within range (you can choose yourself). The field sheds dim light out to 5 feet. While surrounded by the field, a creature gains the following benefits:"},{"type":"list","items":[{"type":"item","name":"Cover","entry":"The creature has Cover."},{"type":"item","name":"Damage Resistance","entry":"The creature has resistance to acid, cold, fire, lightning, and poison damage."},{"type":"item","name":"Evasion","entry":"If the creature is subjected to an effect that allows it to make a Dexterity saving throw to take only half damage, the creature instead takes no damage if it succeeds on the saving throw, and only half damage if it fails."}]},{"type":"text","content":"As a bonus action on subsequent turns, you can move the field to another creature within 60 feet of the field."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":20},{"name":"Nathair's Mischief","source":"FTD","level":2,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"s":true,"m":"a piece of crust from an apple pie"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You fill a 20-foot cube you can see within range with fey and draconic magic. Roll on the Mischievous Surge table to determine the magical effect produced, and roll again at the start of each of your turns until the spell ends. You can move the cube up to 10 feet before you roll."},{"type":"table","caption":"Mischievous Surge","colLabels":["d4","Effect"],"rows":[["1","The smell of apple pie fills the air, and each creature in the cube must succeed on a Wisdom saving throw or become <i class=\\"text-dnd-gold\\">charmed</i> by you until the start of your next turn."],["2","Bouquets of flowers appear all around, and each creature in the cube must succeed on a Dexterity saving throw or be <i class=\\"text-dnd-gold\\">blinded</i> until the start of your next turn as the flowers spray water in their faces."],["3","Each creature in the cube must succeed on a Wisdom saving throw or begin giggling until the start of your next turn. A giggling creature is <i class=\\"text-dnd-gold\\">incapacitated</i> and uses all its movement to move in a random direction."],["4","Drops of molasses hover in the cube, making it difficult terrain until the start of your next turn."]]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["dexterity","wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":20},{"name":"Raulothim's Psychic Lance","source":"FTD","level":4,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You unleash a shimmering lance of psychic power from your forehead at a creature that you can see within range. Alternatively, you can utter a creature's name. If the named target is within range, it becomes the spell's target even if you can't see it. If the named target isn't within range, the lance dissipates without effect."},{"type":"text","content":"The target must make an Intelligence saving throw. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">7d6</span> psychic damage and is <i class=\\"text-dnd-gold\\">incapacitated</i> until the start of your next turn. On a successful save, the creature takes half as much damage and isn't <i class=\\"text-dnd-gold\\">incapacitated</i>."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 5th level or higher, the damage increases by 7d6 for each slot level above 4th."}]}],"damageInflict":["psychic"],"conditionInflict":["incapacitated"],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":21},{"name":"Rime's Binding Ice","source":"FTD","level":2,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"cone","distance":{"type":"feet","amount":30}},"components":{"s":true,"m":"a vial of meltwater"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A burst of cold energy emanates from you in a 30-foot cone. Each creature in that area must make a Constitution saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">3d8</span> cold damage and is hindered by ice formations for 1 minute, or until it or another creature within reach of it uses an action to break away the ice. A creature hindered by ice has its speed reduced to 0. On a successful save, a creature takes half as much damage and isn't hindered by ice."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 3rd level or higher, increase the cold damage by 3d8 for each slot level above 2nd."}]}],"damageInflict":["cold"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":21},{"name":"Summon Draconic Spirit","source":"FTD","level":5,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"an object with the image of a dragon engraved on it, worth at least 500 gp","cost":50000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth a <b>draconic spirit</b>. It manifests in an unoccupied space that you can see within range. This corporeal form uses the Draconic Spirit stat block. When you cast this spell, choose a family of dragon: chromatic, gem, or metallic. The creature resembles a dragon of the chosen family, which determines certain traits in its stat block. The creature disappears when it drops to 0 hit points or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your companions. In combat, the creature shares your initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its move to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 6th level or higher, use the higher level wherever the spell's level appears in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":["Summon Dragon|XPHB"],"page":21},{"name":"Alustriel's Mooncloak","source":"FRHoF","level":5,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":20}},"components":{"v":true,"s":true,"m":{"text":"a moonstone worth 50+ GP","cost":5000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"For the duration, moonlight fills a 20-foot <i>Emanation [Area of Effect]</i> originating from you with <i>Dim Light</i>. While in that area, you and your allies have <i>Cover</i> and <i>Resistance</i> to Cold, Lightning, and Radiant damage."},{"type":"text","content":"While the spell lasts, you can use one of the following options, ending the spell immediately:"},{"type":"list","items":[{"type":"item","name":"Liberation","entry":"When you fail a saving throw to avoid or end the <i class=\\"text-dnd-gold\\">Frightened</i>, <i class=\\"text-dnd-gold\\">Grappled</i>, or <i class=\\"text-dnd-gold\\">Restrained</i> condition, you can take a <i>Reaction</i> to succeed on the save instead."},{"type":"item","name":"Respite","entry":"As a <b>Magic</b> action, you or an ally within the area regains <i>Hit Points</i> equal to <span class=\\"text-green-400 font-mono\\">4d10</span> plus your spellcasting ability modifier."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":142},{"name":"Backlash","source":"FRHoF","level":4,"school":"A","time":[{"number":1,"unit":"reaction","condition":"which you take in response to taking damage"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You ward yourself against destructive energy, reducing the damage taken by <span class=\\"text-green-400 font-mono\\">4d6</span> plus your spellcasting ability modifier."},{"type":"text","content":"If the triggering damage was from a creature within range, you can force the creature to make a Constitution saving throw. The creature takes <span class=\\"text-red-400 font-semibold\\">4d6</span> Force damage on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage reduction and Force damage from this spell both increase by 4d6 for every spell slot level above 4."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"reaction","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":142},{"name":"Blade of Disaster","source":"FRHoF","level":9,"school":"C","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a 3-foot-long blade-shaped planar rift that lasts for the duration. The rift appears within range in a space of your choice, and you can immediately make up to two melee spell attacks, each one against a creature or object within 5 feet of the rift. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">10d6</span> Force damage. This attack scores a <i>Critical Hit</i> if the number on the <span class=\\"text-green-400 font-mono\\">d20</span> is 18 or higher."},{"type":"text","content":"As a <i>Bonus Action</i> on your later turns, you can move the rift up to 60 feet and repeat the two attacks against a creature or an object within 5 feet of it. You can direct the attacks at the same target or at different ones."},{"type":"text","content":"The blade can harmlessly pass through any barrier, including ones created by spells like <a href=\\"/spells?search=Wall of Force\\" class=\\"text-dnd-gold hover:underline\\">Wall of Force</a>."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":143},{"name":"Cacophonic Shield","source":"FRHoF","level":3,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Thunderous reverberations fill a 10-foot <i>Emanation [Area of Effect]</i> originating from you for the duration. Whenever the <i>Emanation [Area of Effect]</i> enters a creature's space and whenever a creature enters the <i>Emanation [Area of Effect]</i> or ends its turn there, the creature makes a Constitution saving throw. On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">3d6</span> Thunder damage and has the <i class=\\"text-dnd-gold\\">Deafened</i> condition until the start of your next turn. On a successful save, the creature takes half as much damage only. A creature makes this save only once per turn. When you cast this spell, you can designate creatures to be unaffected by it."},{"type":"text","content":"In addition, you have <i>Resistance</i> to Thunder damage, and ranged attack rolls against you are made with <i>Disadvantage</i>."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d6 for each spell slot level above 3."}]}],"damageInflict":["thunder"],"conditionInflict":["deafened"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":143},{"name":"Conjure Constructs","source":"FRHoF","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a brass cog"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You conjure a group of intangible, orderly spirits that appear as a Medium group of modrons or other Constructs in an unoccupied space you can see within range. The spirits last for the duration. When you cast this spell and as a <b>Magic</b> action on subsequent turns, you can command the spirits to target one creature or object you can see within 5 feet of the spirits and create one of the following effects:"},{"type":"list","items":[{"type":"item","name":"Clockwork Force","entry":"The target makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">3d6</span> Force damage on a failed save or half as much damage on a successful one."},{"type":"item","name":"Orderly Ward","entry":"The target gains <i>Temporary Hit Points</i> equal to <span class=\\"text-green-400 font-mono\\">1d6</span> plus your spellcasting ability modifier."}]},{"type":"text","content":"When you move on your turn, you can also move the spirits up to 30 feet to an unoccupied space you can see."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage and <i>Temporary Hit Points</i> both increase by 3d6 for each spell slot level above 3."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":143},{"name":"Death Armor","source":"FRHoF","level":2,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"an onyx worth 50+ GP, which the spell consumes","cost":5000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"For the duration, an inky aura surrounds one creature you touch. The target has <i>Advantage</i> on <i>Death Saving Throw</i>, and once per turn, when a creature within 5 feet of the target hits it with a melee attack roll, the attacker takes <span class=\\"text-red-400 font-semibold\\">2d4</span> Necrotic damage."}],"entriesHigherLevel":[],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":143},{"name":"Deryan's Helpful Homunculi","source":"FRHoF","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"powdered gemstones worth 100+ GP, which the spell consumes, and one set of Artisan's Tools with which you have proficiency","cost":10000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You summon a group of helpful spirits, which lasts for the duration. The spirits appear as homunculi or as another Construct of your choice but are intangible and invulnerable, and they are considered to have proficiency in the <i>Arcana</i> skill and with the set of <b>Artisan's Tools</b> used in the spell's casting."},{"type":"text","content":"If you are crafting an item, the spirits function as a single assistant for your crafting, halving the crafting time."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":143},{"name":"Dirge","source":"FRHoF","level":6,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Deathly power fills a 60-foot <i>Emanation [Area of Effect]</i> originating from you for the duration."},{"type":"text","content":"When you cast this spell, you can designate creatures to be unaffected by it. Any other creature can't regain <i>Hit Points</i> while in the <i>Emanation [Area of Effect]</i>. Whenever the <i>Emanation [Area of Effect]</i> enters a creature's space and whenever a creature enters the <i>Emanation [Area of Effect]</i> or ends its turn there, the creature makes a Constitution saving throw. On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">3d10</span> Necrotic damage and has the <i class=\\"text-dnd-gold\\">Prone</i> condition. On a successful save, the creature takes half as much damage and its <i>Speed</i> is halved. A creature makes this save only once per turn."},{"type":"section","name":"Casting as a Circle Spell","entries":[{"type":"text","content":"Casting this as a Circle spell requires a minimum of two secondary casters. If the spell is cast as a Circle spell, its duration becomes <i>Concentration</i>, up to 10 minutes."},{"type":"text","content":"A creature that fails its save against the spell's effect also gains 1 <i class=\\"text-dnd-gold\\">Exhaustion</i> level. While the creature has <i class=\\"text-dnd-gold\\">Exhaustion</i> levels, finishing a <i>Long Rest</i> neither restores lost <i>Hit Points</i> nor reduces the creature's <i class=\\"text-dnd-gold\\">Exhaustion</i> level."},{"type":"text","content":"When the spell is cast, each secondary caster must expend a level 4+ spell slot; otherwise, the spell fails."}]}],"entriesHigherLevel":[],"damageInflict":["necrotic"],"conditionInflict":["prone"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":144},{"name":"Doomtide","source":"FRHoF","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"soot and a dried eel"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a 20-foot-radius <i>Sphere [Area of Effect]</i> of inky fog within range. The fog is magical <i>Darkness</i> and lasts for the duration or until a strong wind (such as the one created by the <a href=\\"/spells?search=Gust of Wind\\" class=\\"text-dnd-gold hover:underline\\">Gust of Wind</a> spell) disperses it, ending the spell."},{"type":"text","content":"Each creature in the <i>Sphere [Area of Effect]</i> when it appears makes a Wisdom saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">5d6</span> Psychic damage and subtracts <span class=\\"text-green-400 font-mono\\">1d6</span> from its saving throws until the end of its next turn. On a successful save, a creature takes half as much damage only. A creature also makes this save when the <i>Sphere [Area of Effect]</i> moves into its space, when it enters the <i>Sphere [Area of Effect]</i>, or when it ends its turn inside the <i>Sphere [Area of Effect]</i>. A creature makes this save only once per turn."},{"type":"text","content":"The <i>Sphere [Area of Effect]</i> moves 10 feet away from you at the start of each of your turns."},{"type":"section","name":"Casting as a Circle Spell","entries":[{"type":"text","content":"Casting this as a Circle spell requires a minimum of five secondary casters. In addition to the spell's usual components, you must provide a special component (a string of three black pearls from Pandemonium), which the spell consumes. The spell's range increases to 1 mile, and its duration increases to until dispelled (no <i>Concentration</i> required). The spell ends early if any caster who participated in this casting contributes to another casting of <a href=\\"/spells?search=Doomtide\\" class=\\"text-dnd-gold hover:underline\\">Doomtide</a> as a Circle spell."},{"type":"text","content":"When the spell is cast, each secondary caster must expend a level 3+ spell slot; otherwise, the spell fails."}]}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":144},{"name":"Elminster's Effulgent Spheres","source":"FRHoF","level":6,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"an opal worth 1,000 GP+","cost":100000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"Six chromatic spheres orbit you for the duration."},{"type":"text","content":"While the spheres are present, you can expend spheres to create the following effects:"},{"type":"list","items":[{"type":"item","name":"Absorb Energy","entry":"When you take Acid, Cold, Fire, Lightning, or Thunder damage, you can take a <i>Reaction</i> to expend one sphere and give yourself <i>Resistance</i> to the triggering damage type until the start of your next turn."},{"type":"item","name":"Energy Blast","entry":"As a <i>Bonus Action</i>, you send one sphere hurtling toward a target within 120 feet of yourself. Make a ranged spell attack. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">3d6</span> Acid, Cold, Fire, Lightning, or Thunder damage (your choice). Regardless of whether you hit, the sphere is expended."}]},{"type":"text","content":"The spell ends early if you have no more spheres remaining."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The number of spheres increases by 1 for every spell slot level above 6."}]}],"damageInflict":["acid","cold","fire","lightning","thunder"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":144},{"name":"Elminster's Elusion","source":"FRHoF","level":2,"school":"A","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Arcane wards protect you against magic for the duration. You have <i>Advantage</i> on saving throws against spells and magical effects. Additionally, if you succeed on a saving throw against a spell or magical effect and would normally take half as much damage, you instead take no damage."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":144},{"name":"Holy Star of Mystra","source":"FRHoF","level":8,"school":"V","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a glowing mote of energy that hovers above you for the duration. The mote sheds <i>Bright Light</i> in a 5-foot radius and <i>Dim Light</i> for an additional 5 feet."},{"type":"text","content":"When you cast this spell and as a <i>Bonus Action</i> on later turns, you can unleash a shining bolt from the mote, targeting one creature within 120 feet of yourself. Make a ranged spell attack. On a hit, the target takes Force or Radiant damage (your choice) equal to <span class=\\"text-green-400 font-mono\\">4d10</span> plus your spellcasting ability modifier."},{"type":"text","content":"In addition, while the mote is present, you have <i>Cover</i>, and if you succeed on a saving throw against a spell of level 7 or lower that targeted only you and didn't create an area of effect, you can take a <i>Reaction</i> to deflect that spell back at the spell's caster; the caster makes a saving throw against that spell using that caster's own spell save DC."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":145},{"name":"Laeral's Silver Lance","source":"FRHoF","level":3,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"line","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":{"text":"a silver pin worth 250+ GP","cost":25000}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Silver energy bursts out from you in a 120-foot-long, 5-foot-wide <i>Line [Area of Effect]</i>. Each creature of your choice in the <i>Line [Area of Effect]</i> makes a Strength saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">3d10</span> Force damage and has the <i class=\\"text-dnd-gold\\">Prone</i> condition. On a successful save, a creature takes half as much damage only."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d10 for every spell slot level above 3."}]}],"damageInflict":["force"],"conditionInflict":["prone"],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":145},{"name":"Simbul's Synostodweomer","source":"FRHoF","level":7,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You imbue one creature you touch with magical healing energy for the duration. Whenever the target casts a spell using a spell slot, the target can immediately roll a number of unexpended <i>Hit Point Dice</i> equal to the spell slot's level and regain <i>Hit Points</i> equal to the roll's total plus your spellcasting ability modifier; those dice are then expended."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":145},{"name":"Songal's Elemental Suffusion","source":"FRHoF","level":5,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"a pearl worth 100+ GP","cost":10000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You imbue yourself with the elemental power of genies. You gain the following benefits until the spell ends:"},{"type":"list","items":[{"type":"item","name":"Elemental Immunity","entry":"When you cast this spell, choose one of the following damage types: Acid, Cold, Fire, Lightning, or Thunder. You have <i>Resistance</i> to the chosen damage type."},{"type":"item","name":"Elemental Pulse","entry":"When you cast this spell and at the start of each of your subsequent turns, you release a burst of elemental energy in a 15-foot <i>Emanation [Area of Effect]</i> originating from yourself. Each creature of your choice in that area makes a Dexterity saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">2d6</span> Acid, Cold, Fire, Lightning, or Thunder damage (your choice) and has the <i class=\\"text-dnd-gold\\">Prone</i> condition. On a successful save, a creature takes half as much damage only."},{"type":"item","name":"Flight","entry":"You gain a <i>Fly Speed</i> of 30 feet and can hover."}]},{"type":"section","name":"Casting as a Circle Spell","entries":[{"type":"text","content":"If the spell is cast as a Circle spell, its casting time increases to 1 minute, and its duration increases to <i>Concentration</i>, up to 10 minutes. For each secondary caster who participates in the casting, you can choose one additional creature, to a maximum of nine additional creatures. The chosen creatures also gain the benefits of the spell for its duration."},{"type":"text","content":"When the spell is cast, each secondary caster must expend a level 2+ spell slot; otherwise, the spell fails."}]}],"entriesHigherLevel":[],"damageInflict":["acid","cold","fire","lightning","thunder"],"conditionInflict":["prone"],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":145},{"name":"Spellfire Flare","source":"FRHoF","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You unleash a blast of brilliant fire. Make a ranged spell attack against a target within range; a target gains no benefit from <i>Cover</i> or <i>Cover</i> for this attack roll. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">2d10</span> Radiant damage."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You create an additional blast for each spell slot level above 1. You can direct the blasts at the same target or at different ones. Make a separate attack roll for each blast."}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":146},{"name":"Spellfire Storm","source":"FRHoF","level":4,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You conjure a pillar of spellfire in a 20-foot-radius, 20-foot-high <i>Cylinder [Area of Effect]</i> centered on a point within range. The area of the <i>Cylinder [Area of Effect]</i> is <i>Bright Light</i>, and each creature in it when it appears makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">4d10</span> Radiant damage on a failed save or half as much damage on a successful one. A creature also makes this save when it enters the spell's area for the first time on a turn or ends its turn there. A creature makes this save only once per turn."},{"type":"text","content":"In addition, whenever a creature in the <i>Cylinder [Area of Effect]</i> casts a spell, that creature makes a Constitution saving throw. On a failed save, the spell dissipates with no effect, and the action, <i>Bonus Action</i>, or <i>Reaction</i> used to cast it is wasted. If that spell was cast with a spell slot, the slot isn't expended."},{"type":"text","content":"When you cast this spell, you can designate creatures to be unaffected by it."},{"type":"section","name":"Casting as a Circle Spell","entries":[{"type":"text","content":"In addition to the spell's usual components, you must provide a special component (a blue star sapphire worth 25,000+ GP), which the spell consumes. The spell's range increases to 1 mile, and it no longer requires <i>Concentration</i>. When the spell is cast, each secondary caster must expend a level 3+ spell slot; otherwise, the spell fails."}]}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 4d10 for every spell slot level above 4."},{"type":"text","content":"The number of secondary casters determines the spell's area of effect and duration, as shown in the table below. The spell ends early if any caster who participated in this casting contributes to another casting of Spellfire Storm as a Circle spell."},{"type":"table","caption":"","colLabels":["Secondary Casters","Area of Effect","Duration"],"rows":[["1-3","40-foot-radius, 40-foot-high <i>Cylinder [Area of Effect]</i>","1 Hour"],["4-6","60-foot-radius, 60-foot-high <i>Cylinder [Area of Effect]</i>","8 Hours"],["7+","100-foot-radius, 100-foot-high <i>Cylinder [Area of Effect]</i>","24 Hours"]]}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":146},{"name":"Syluné's Viper","source":"FRHoF","level":3,"school":"C","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a snake fang"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"A shimmering, spectral snake encircles your body for the duration. You gain 15 <i>Temporary Hit Points</i>; the spell ends early if you have no <i>Temporary Hit Points</i> left."},{"type":"text","content":"While the spell is active, you gain the following benefits:"},{"type":"list","items":[{"type":"item","name":"Climbing","entry":"You gain a <i>Climb Speed</i> equal to your <i>Speed</i>."},{"type":"item","name":"Venomous Bite","entry":"As a <b>Magic</b> action, you can make a ranged spell attack using the snake against one creature within 50 feet. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">1d6</span> Force damage and has the <i class=\\"text-dnd-gold\\">Poisoned</i> condition until the start of your next turn. While <i class=\\"text-dnd-gold\\">Poisoned</i>, the target has the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition."}]}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"For each spell slot level above 3, the number of <i>Temporary Hit Points</i> you gain from this spell increases by 5, and the damage of Venomous Bite increases by 1d6."}]}],"damageInflict":["force"],"conditionInflict":["incapacitated","poisoned"],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":147},{"name":"Wardaway","source":"FRHoF","level":1,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a miniature clay hand"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You hurl a disorienting magical force toward one creature within range. The target makes a Constitution saving throw; Constructs and Undead automatically succeed on this save."},{"type":"text","content":"On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">2d4</span> Force damage, its <i>Speed</i> is halved until the start of your next turn, and on its next turn, it can take only an action or a <i>Bonus Action</i> (but not both). On a successful save, the target takes half as much damage only."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d4 for every spell slot level above 1."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":147},{"name":"Encode Thoughts","source":"GGR","level":0,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"Putting a finger to your head, you pull a memory, an idea, or a message from your mind and transform it into a tangible string of glowing energy called a thought strand, which persists for the duration or until you cast this spell again. The thought strand appears in an unoccupied space within 5 feet of you as a Tiny, weightless, semisolid object that can be held and carried like a ribbon. It is otherwise stationary."},{"type":"text","content":"If you cast this spell while <i>concentration</i> on a spell or an ability that allows you to read or manipulate the thoughts of others (such as <a href=\\"/spells?search=detect thoughts\\" class=\\"text-dnd-gold hover:underline\\">detect thoughts</a> or <a href=\\"/spells?search=modify memory\\" class=\\"text-dnd-gold hover:underline\\">modify memory</a>), you can transform the thoughts or memories you read, rather than your own, into a thought strand."},{"type":"text","content":"Casting this spell while holding a thought strand allows you to instantly receive whatever memory, idea, or message the thought strand contains. (Casting <a href=\\"/spells?search=detect thoughts\\" class=\\"text-dnd-gold hover:underline\\">detect thoughts</a> on the strand has the same effect.)"}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":47},{"name":"Create Magen","source":"IDRotF","level":7,"school":"T","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a vial of quicksilver worth 500 gp and a life-sized human doll, both of which the spell consumes, and an intricate crystal rod worth at least 1,500 gp that is not consumed","cost":50000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"While casting the spell, you place a vial of quicksilver in the chest of a life-sized human doll stuffed with ash or dust. You then stitch up the doll and drip your blood on it. At the end of the casting, you tap the doll with a crystal rod, transforming it into a <i>magen</i> clothed in whatever the doll was wearing. The type of magen is chosen by you during the casting of the spell. See appendix C for different kinds of magen and their statistics."},{"type":"text","content":"When the magen appears, your hit point maximum decreases by an amount equal to the magen's challenge rating (minimum reduction of 1). Only a <a href=\\"/spells?search=wish\\" class=\\"text-dnd-gold hover:underline\\">wish</a> spell can undo this reduction to your hit point maximum."},{"type":"text","content":"Any magen you create with this spell obeys your commands without question."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":318},{"name":"Frost Fingers","source":"IDRotF","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"cone","distance":{"type":"feet","amount":15}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Freezing cold blasts from your fingertips in a 15-foot cone. Each creature in that area must make a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">2d8</span> cold damage on a failed save, or half as much damage on a successful one."},{"type":"text","content":"The cold freezes nonmagical liquids in the area that aren't being worn or carried."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 2nd level or higher, the damage increases by <span class=\\"text-red-400 font-semibold\\">1d8</span> for each slot level above 1st."}]}],"damageInflict":["cold"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":318},{"name":"Flock of Familiars","source":"LLK","level":2,"school":"C","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You temporarily summon three familiars—spirits that take animal forms of your choice. Each familiar uses the same rules and options for a familiar conjured by the <a href=\\"/spells?search=find familiar\\" class=\\"text-dnd-gold hover:underline\\">find familiar</a> spell. All the familiars conjured by this spell must be the same type of creature (celestials, fey, or fiends; your choice). If you already have a familiar conjured by the <a href=\\"/spells?search=find familiar\\" class=\\"text-dnd-gold hover:underline\\">find familiar</a> spell or similar means, then one fewer familiars are conjured by this spell."},{"type":"text","content":"Familiars summoned by this spell can telepathically communicate with you and share their visual or auditory senses while they are within 1 mile of you."},{"type":"text","content":"When you cast a spell with a range of touch, one of the familiars conjured by this spell can deliver the spell, as normal. However, you can cast a touch spell through only one familiar per turn."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 3rd level or higher, you conjure an additional familiar for each slot level above 2nd."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":57},{"name":"Galder's Speedy Courier","source":"LLK","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":{"text":"25 gold pieces, or mineral goods of equivalent value, which the spell consumes","cost":2500,"consume":true}},"duration":[{"type":"timed","duration":{"type":"minute","amount":10}}],"entries":[{"type":"text","content":"You summon a Small air elemental to a spot within range. The air elemental is formless, nearly transparent, immune to all damage, and cannot interact with other creatures or objects. It carries an open, empty chest whose interior dimensions are 3 feet on each side. While the spell lasts, you can deposit as many items inside the chest as will fit. You can then name a living creature you have met and seen at least once before, or any creature for which you possess a body part, lock of hair, clipping from a nail, or similar portion of the creature's body."},{"type":"text","content":"As soon as the lid of the chest is closed, the elemental and the chest disappear, then reappear adjacent to the target creature. If the target creature is on another plane, or if it is proofed against magical detection or location, the contents of the chest reappear on the ground at your feet."},{"type":"text","content":"The target creature is made aware of the chest's contents before it chooses whether or not to open it, and knows how much of the spell's duration remains in which it can retrieve them. No other creature can open the chest and retrieve its contents. When the spell expires or when all the contents of the chest have been removed, the elemental and the chest disappear. The elemental also disappears if the target creature orders it to return the items to you. When the elemental disappears, any items not taken from the chest reappear on the ground at your feet."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using an 8th-level spell slot, you can send the chest to a creature on a different plane of existence from you."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":57},{"name":"Galder's Tower","source":"LLK","level":3,"school":"C","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a fragment of stone, wood, or other building material"},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"You conjure a two-story tower made of stone, wood, or similar suitably sturdy materials. The tower can be round or square in shape. Each level of the tower is 10 feet tall and has an area of up to 100 square feet. Access between levels consists of a simple ladder and hatch. Each level takes one of the following forms, chosen by you when you cast the spell:"},{"type":"list","items":["A bedroom with a bed, chairs, chest, and magical fireplace","A study with desks, books, bookshelves, parchments, ink, and ink pens","A dining space with a table, chairs, magical fireplace, containers, and cooking utensils","A lounge with couches, armchairs, side tables and footstools","A washroom with toilets, washtubs, a magical brazier, and sauna benches","An observatory with a telescope and maps of the night sky","An unfurnished, empty room"]},{"type":"text","content":"The interior of the tower is warm and dry, regardless of conditions outside. Any equipment or furnishings conjured with the tower dissipate into smoke if removed from it. At the end of the spell's duration, all creatures and objects within the tower that were not created by the spell appear safely outside on the ground, and all traces of the tower and its furnishings disappear."},{"type":"text","content":"You can cast this spell again while it is active to maintain the tower's existence for another 24 hours. You can create a permanent tower by casting this spell in the same location and with the same configuration every day for one year."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, the tower can have one additional story for each slot level beyond 3rd."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":57},{"name":"Acid Splash","source":"XPHB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You create an acidic bubble at a point within range, where it explodes in a 5-foot-radius <i>Sphere [Area of Effect]</i>. Each creature in that <i>Sphere [Area of Effect]</i> must succeed on a Dexterity saving throw or take <span class=\\"text-red-400 font-semibold\\">1d6</span> Acid damage."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d6</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d6</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d6</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d6</span>)."}]}],"damageInflict":["acid"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":239},{"name":"Aid","source":"XPHB","level":2,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a strip of white cloth"},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"Choose up to three creatures within range. Each target's <i>Hit Points</i> maximum and current <i>Hit Points</i> increase by 5 for the duration."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Each target's <i>Hit Points</i> increase by 5 for each spell slot level above 2."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":239},{"name":"Alarm","source":"XPHB","level":1,"school":"A","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a bell and silver wire"},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You set an alarm against intrusion. Choose a door, a window, or an area within range that is no larger than a 20-foot <i>Cube [Area of Effect]</i>. Until the spell ends, an alarm alerts you whenever a creature touches or enters the warded area. When you cast the spell, you can designate creatures that won't set off the alarm. You also choose whether the alarm is audible or mental:"},{"type":"list","items":[{"type":"item","name":"Audible Alarm","entry":"The alarm produces the sound of a handbell for 10 seconds within 60 feet of the warded area."},{"type":"item","name":"Mental Alarm","entry":"You are alerted by a mental ping if you are within 1 mile of the warded area. This ping awakens you if you're asleep."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":239},{"name":"Alter Self","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You alter your physical form. Choose one of the following options. Its effects last for the duration, during which you can take a <b>Magic</b> action to replace the option you chose with a different one."},{"type":"section","name":"Aquatic Adaptation","entries":[{"type":"text","content":"You sprout gills and grow webs between your fingers. You can breathe underwater and gain a <i>Swim Speed</i> equal to your <i>Speed</i>."}]},{"type":"section","name":"Change Appearance","entries":[{"type":"text","content":"You alter your appearance. You decide what you look like, including your height, weight, facial features, sound of your voice, hair length, coloration, and other distinguishing characteristics. You can make yourself appear as a member of another species, though none of your statistics change. You can't appear as a creature of a different size, and your basic shape stays the same; if you're bipedal, you can't use this spell to become quadrupedal, for instance. For the duration, you can take a <b>Magic</b> action to change your appearance in this way again."}]},{"type":"section","name":"Natural Weapons","entries":[{"type":"text","content":"You grow claws (Slashing), fangs (Piercing), horns (Piercing), or hooves (Bludgeoning). When you use your <i>Unarmed Strike</i> to deal damage with that new growth, it deals <span class=\\"text-red-400 font-semibold\\">1d6</span> damage of the type in parentheses instead of dealing the normal damage for your <i>Unarmed Strike</i>, and you use your spellcasting ability modifier for the attack and damage rolls rather than using Strength."}]}],"entriesHigherLevel":[],"damageInflict":["bludgeoning","piercing","slashing"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":239},{"name":"Animal Friendship","source":"XPHB","level":1,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a morsel of food"},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"Target a Beast that you can see within range. The target must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration. If you or one of your allies deals damage to the target, the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional Beast for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":239},{"name":"Animal Messenger","source":"XPHB","level":2,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a morsel of food"},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"A <i>Tiny Beast</i> of your choice that you can see within range must succeed on a Charisma saving throw, or it attempts to deliver a message for you (if the target's <i>Challenge Rating</i> isn't 0, it automatically succeeds). You specify a location you have visited and a recipient who matches a general description, such as \\"a person dressed in the uniform of the town guard\\" or \\"a red-haired dwarf wearing a pointed hat.\\" You also communicate a message of up to twenty-five words. The Beast travels for the duration toward the specified location, covering about 25 miles per 24 hours or 50 miles if the Beast can fly."},{"type":"text","content":"When the Beast arrives, it delivers your message to the creature that you described, mimicking your communication. If the Beast doesn't reach its destination before the spell ends, the message is lost, and the Beast returns to where you cast the spell."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The spell's duration increases by 48 hours for each spell slot level above 2."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":["charisma"],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":240},{"name":"Animal Shapes","source":"XPHB","level":8,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"Choose any number of willing creatures that you can see within range. Each target shape-shifts into a Large or smaller Beast of your choice that has a <i>Challenge Rating</i> of 4 or lower. You can choose a different form for each target. On later turns, you can take a <b>Magic</b> action to transform the targets again."},{"type":"text","content":"A target's game statistics are replaced by the chosen Beast's statistics, but the target retains its creature type; <i>Hit Points</i>; <i>Hit Point Dice</i>; alignment; ability to communicate; and Intelligence, Wisdom, and Charisma scores. The target's actions are limited by the Beast form's anatomy, and it can't cast spells. The target's equipment melds into the new form, and the target can't use any of that equipment while in that form."},{"type":"text","content":"The target gains a number of <i>Temporary Hit Points</i> equal to the <i>Hit Points</i> of the first form into which it shape-shifts. These <i>Temporary Hit Points</i> vanish if any remain when the spell ends. The transformation lasts for the duration or until the target ends it as a <i>Bonus Action</i>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":240},{"name":"Animate Dead","source":"XPHB","level":3,"school":"N","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":"a drop of blood, a piece of flesh, and a pinch of bone dust"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Choose a pile of bones or a corpse of a Medium or Small Humanoid within range. The target becomes an Undead creature: a <b>Skeleton</b> if you chose bones or a <b>Zombie</b> if you chose a corpse."},{"type":"text","content":"On each of your turns, you can take a <i>Bonus Action</i> to mentally command any creature you made with this spell if the creature is within 60 feet of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move on its next turn, or you can issue a general command, such as to guard a chamber or corridor. If you issue no commands, the creature takes the <b>Dodge</b> action and moves only to avoid harm. Once given an order, the creature continues to follow it until its task is complete."},{"type":"text","content":"The creature is under your control for 24 hours, after which it stops obeying any command you've given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature again before the current 24-hour period ends. This use of the spell reasserts your control over up to four creatures you have animated with this spell rather than animating a new creature."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You animate or reassert control over two additional Undead creatures for each spell slot level above 3. Each of the creatures must come from a different corpse or pile of bones."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":240},{"name":"Animate Objects","source":"XPHB","level":5,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Objects animate at your command. Choose a number of nonmagical objects within range that aren't being worn or carried, aren't fixed to a surface, and aren't Gargantuan. The maximum number of objects is equal to your spellcasting ability modifier; for this number, a Medium or smaller target counts as one object, a Large target counts as two, and a Huge target counts as three."},{"type":"text","content":"Each target animates, sprouts legs, and becomes a Construct that uses the <b>Animated Object</b> stat block; this creature is under your control until the spell ends or until it is reduced to 0 <i>Hit Points</i>. Each creature you make with this spell is an ally to you and your allies. In combat, it shares your <i>Initiative</i> count and takes its turn immediately after yours."},{"type":"text","content":"Until the spell ends, you can take a <i>Bonus Action</i> to mentally command any creature you made with this spell if the creature is within 500 feet of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to each one). If you issue no commands, the creature takes the <b>Dodge</b> action and moves only to avoid harm. When the creature drops to 0 <i>Hit Points</i>, it reverts to its object form, and any remaining damage carries over to that form."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The creature's Slam damage increases by <span class=\\"text-red-400 font-semibold\\">1d4</span> (Medium or smaller), <span class=\\"text-red-400 font-semibold\\">1d6</span> (Large), or <span class=\\"text-red-400 font-semibold\\">1d12</span> (Huge) for each spell slot level above 5."}]}],"damageInflict":["bludgeoning","piercing","slashing"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":240},{"name":"Antilife Shell","source":"XPHB","level":5,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"An aura extends from you in a 10-foot <i>Emanation [Area of Effect]</i> for the duration. The aura prevents creatures other than Constructs and Undead from passing or reaching through it. An affected creature can cast spells or make attacks with Ranged or Reach weapons through the barrier."},{"type":"text","content":"If you move so that an affected creature is forced to pass through the barrier, the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":241},{"name":"Antimagic Field","source":"XPHB","level":8,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":"iron filings"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"An aura of antimagic surrounds you in a 10-foot <i>Emanation [Area of Effect]</i>. No one can cast spells, take <b>Magic</b> actions, or create other magical effects inside the aura, and those things can't target or otherwise affect anything inside it. Magical properties of magic items don't work inside the aura or on anything inside it."},{"type":"text","content":"Areas of effect created by spells or other magic can't extend into the aura, and no one can teleport into or out of it or use planar travel there. Portals close temporarily while in the aura."},{"type":"text","content":"Ongoing spells, except those cast by an Artifact or a deity, are suppressed in the area. While an effect is suppressed, it doesn't function, but the time it spends suppressed counts against its duration."},{"type":"text","content":"<a href=\\"/spells?search=Dispel Magic\\" class=\\"text-dnd-gold hover:underline\\">Dispel Magic</a> has no effect on the aura, and the auras created by different <a href=\\"/spells?search=Antimagic Field\\" class=\\"text-dnd-gold hover:underline\\">Antimagic Field</a> spells don't nullify each other."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":241},{"name":"Antipathy/Sympathy","source":"XPHB","level":8,"school":"E","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a mix of vinegar and honey"},"duration":[{"type":"timed","duration":{"type":"day","amount":10}}],"entries":[{"type":"text","content":"As you cast the spell, choose whether it creates antipathy or sympathy, and target one creature or object that is Huge or smaller. Then specify a kind of creature, such as red dragons, goblins, or vampires. A creature of the chosen kind makes a Wisdom saving throw when it comes within 120 feet of the target. Your choice of antipathy or sympathy determines what happens to a creature when it fails that save:"},{"type":"list","items":[{"type":"item","name":"Antipathy","entry":"The creature has the <i class=\\"text-dnd-gold\\">Frightened</i> condition. The <i class=\\"text-dnd-gold\\">Frightened</i> creature must use its movement on its turns to get as far away as possible from the target, moving by the safest route."},{"type":"item","name":"Sympathy","entry":"The creature has the <i class=\\"text-dnd-gold\\">Charmed</i> condition. The <i class=\\"text-dnd-gold\\">Charmed</i> creature must use its movement on its turns to get as close as possible to the target, moving by the safest route. If the creature is within 5 feet of the target, the creature can't willingly move away. If the target damages the <i class=\\"text-dnd-gold\\">Charmed</i> creature, that creature can make a Wisdom saving throw to end the effect, as described below."}]},{"type":"section","name":"Ending the Effect","entries":[{"type":"text","content":"If the <i class=\\"text-dnd-gold\\">Frightened</i> or <i class=\\"text-dnd-gold\\">Charmed</i> creature ends its turn more than 120 feet away from the target, the creature makes a Wisdom saving throw. On a successful save, the creature is no longer affected by the target. A creature that successfully saves against this effect is immune to it for 1 minute, after which it can be affected again."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["frightened","charmed"],"savingThrow":["wisdom"],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":242},{"name":"Arcane Eye","source":"XPHB","level":4,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a bit of bat fur"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create an <i class=\\"text-dnd-gold\\">Invisible</i>, invulnerable eye within range that hovers for the duration. You mentally receive visual information from the eye, which can see in every direction. It also has <i>Darkvision</i> with a range of 30 feet."},{"type":"text","content":"As a <i>Bonus Action</i>, you can move the eye up to 30 feet in any direction. A solid barrier blocks the eye's movement, but the eye can pass through an opening as small as 1 inch in diameter."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":242},{"name":"Arcane Gate","source":"XPHB","level":6,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":500}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You create linked teleportation portals. Choose two Large, unoccupied spaces on the ground that you can see, one space within range and the other one within 10 feet of you. A circular portal opens in each of those spaces and remains for the duration."},{"type":"text","content":"The portals are two-dimensional glowing rings filled with mist that blocks sight. They hover inches from the ground and are perpendicular to it."},{"type":"text","content":"A portal is open on only one side (you choose which). Anything entering the open side of a portal exits from the open side of the other portal as if the two were adjacent to each other. As a <i>Bonus Action</i>, you can change the facing of the open sides."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":242},{"name":"Arcane Lock","source":"XPHB","level":2,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"gold dust worth 25+ GP, which the spell consumes","cost":2500,"consume":true}},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"You touch a closed door, window, gate, container, or hatch and magically lock it for the duration. This lock can't be unlocked by any nonmagical means. You and any creatures you designate when you cast the spell can open and close the object despite the lock. You can also set a password that, when spoken within 5 feet of the object, unlocks it for 1 minute."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":242},{"name":"Armor of Agathys","source":"XPHB","level":1,"school":"A","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a shard of blue glass"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"Protective magical frost surrounds you. You gain 5 <i>Temporary Hit Points</i>. If a creature hits you with a melee attack roll before the spell ends, the creature takes 5 Cold damage. The spell ends early if you have no <i>Temporary Hit Points</i>."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The <i>Temporary Hit Points</i> and the Cold damage both increase by 5 for each spell slot level above 1."}]}],"damageInflict":["cold"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":243},{"name":"Arms of Hadar","source":"XPHB","level":1,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Invoking Hadar, you cause tendrils to erupt from yourself. Each creature in a 10-foot <i>Emanation [Area of Effect]</i> originating from you makes a Strength saving throw. On a failed save, a target takes <span class=\\"text-red-400 font-semibold\\">2d6</span> Necrotic damage and can't take Reactions until the start of its next turn. On a successful save, a target takes half as much damage only."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d6 for each spell slot level above 1."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":243},{"name":"Astral Projection","source":"XPHB","level":9,"school":"N","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":{"text":"for each of the spell's targets, one jacinth worth 1,000+ GP and one silver bar worth 100+ GP, all of which the spell consumes","cost":100000,"consume":true}},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"You and up to eight willing creatures within range project your astral bodies into the Astral Plane (the spell ends instantly if you are already on that plane). Each target's body is left behind in a state of suspended animation; it has the <i class=\\"text-dnd-gold\\">Unconscious</i> condition, doesn't need food or air, and doesn't age."},{"type":"text","content":"A target's astral form resembles its body in almost every way, replicating its game statistics and possessions. The principal difference is the addition of a silvery cord that trails from between the shoulder blades of the astral form. The cord fades from view after 1 foot. If the cord is cut—which happens only when an effect states that it does so—the target's body and astral form both die."},{"type":"text","content":"A target's astral form can travel through the Astral Plane. The moment an astral form leaves that plane, the target's body and possessions travel along the silver cord, causing the target to re-enter its body on the new plane."},{"type":"text","content":"Any damage or other effects that apply to an astral form have no effect on the target's body and vice versa. If a target's body or astral form drops to 0 <i>Hit Points</i>, the spell ends for that target. The spell ends for all the targets if you take a <b>Magic</b> action to dismiss it."},{"type":"text","content":"When the spell ends for a target who isn't dead, the target reappears in its body and exits the state of suspended animation."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["unconscious"],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":243},{"name":"Augury","source":"XPHB","level":2,"school":"D","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"specially marked sticks, bones, cards, or other divinatory tokens worth 25+ GP","cost":2500}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You receive an omen from an otherworldly entity about the results of a course of action that you plan to take within the next 30 minutes. The DM chooses the omen from the Omens table."},{"type":"table","caption":"Omens","colLabels":["Omen","For Results That Will Be..."],"rows":[["Weal","Good"],["Woe","Bad"],["Weal and woe","Good and bad"],["Indifference","Neither good nor bad"]]},{"type":"text","content":"The spell doesn't account for circumstances, such as other spells, that might change the results."},{"type":"text","content":"If you cast the spell more than once before finishing a <i>Long Rest</i>, there is a cumulative 25% chance for each casting after the first that you get no answer."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":244},{"name":"Aura of Life","source":"XPHB","level":4,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"An aura radiates from you in a 30-foot <i>Emanation [Area of Effect]</i> for the duration. While in the aura, you and your allies have <i>Resistance</i> to Necrotic damage, and your <i>Hit Points</i> maximums can't be reduced. If an ally with 0 <i>Hit Points</i> starts its turn in the aura, that ally regains 1 <i>Hit Points</i>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":244},{"name":"Aura of Purity","source":"XPHB","level":4,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"An aura radiates from you in a 30-foot <i>Emanation [Area of Effect]</i> for the duration. While in the aura, you and your allies have <i>Resistance</i> to Poison damage and <i>Advantage</i> on saving throws to avoid or end effects that include the <i class=\\"text-dnd-gold\\">Blinded</i>, <i class=\\"text-dnd-gold\\">Charmed</i>, <i class=\\"text-dnd-gold\\">Deafened</i>, <i class=\\"text-dnd-gold\\">Frightened</i>, <i class=\\"text-dnd-gold\\">Paralyzed</i>, <i class=\\"text-dnd-gold\\">Poisoned</i>, or <i class=\\"text-dnd-gold\\">Stunned</i> condition."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":244},{"name":"Aura of Vitality","source":"XPHB","level":3,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"An aura radiates from you in a 30-foot <i>Emanation [Area of Effect]</i> for the duration. When you create the aura and at the start of each of your turns while it persists, you can restore <span class=\\"text-green-400 font-mono\\">2d6</span> <i>Hit Points</i> to one creature in it."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":244},{"name":"Awaken","source":"XPHB","level":5,"school":"T","time":[{"number":8,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"an agate worth 1,000+ GP, which the spell consumes","cost":100000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You spend the casting time tracing magical pathways within a precious gemstone, and then touch the target. The target must be either a <i>Beast</i> or <i>Plant</i> creature with an Intelligence of 3 or less or a natural plant that isn't a creature. The target gains an Intelligence of 10 and the ability to speak one language you know. If the target is a natural plant, it becomes a Plant creature and gains the ability to move its limbs, roots, vines, creepers, and so forth, and it gains senses similar to a human's. The DM chooses statistics appropriate for the awakened Plant, such as the statistics for the <b>Awakened Shrub</b> or <b>Awakened Tree</b> in the <i>Monster Manual</i>."},{"type":"text","content":"The awakened target has the <i class=\\"text-dnd-gold\\">Charmed</i> condition for 30 days or until you or your allies deal damage to it. When that condition ends, the awakened creature chooses its attitude toward you."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":244},{"name":"Bane","source":"XPHB","level":1,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a drop of blood"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Up to three creatures of your choice that you can see within range must each make a Charisma saving throw. Whenever a target that fails this save makes an attack roll or a saving throw before the spell ends, the target must subtract <span class=\\"text-green-400 font-mono\\">1d4</span> from the attack roll or save."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":["charisma"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":245},{"name":"Banishing Smite","source":"XPHB","level":5,"school":"C","time":[{"number":1,"unit":"bonus","condition":"which you take immediately after hitting a creature with a Melee weapon or an {@variantrule Unarmed Strike|XPHB}"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"The target hit by the attack roll takes an extra <span class=\\"text-red-400 font-semibold\\">5d10</span> Force damage from the attack. If the attack reduces the target to 50 <i>Hit Points</i> or fewer, the target must succeed on a Charisma saving throw or be transported to a harmless demiplane for the duration. While there, the target has the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition. When the spell ends, the target reappears in the space it left or in the nearest unoccupied space if that space is occupied."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":["incapacitated"],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":245},{"name":"Banishment","source":"XPHB","level":4,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a pentacle"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"One creature that you can see within range must succeed on a Charisma saving throw or be transported to a harmless demiplane for the duration. While there, the target has the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition. When the spell ends, the target reappears in the space it left or in the nearest unoccupied space if that space is occupied."},{"type":"text","content":"If the target is an Aberration, a Celestial, an Elemental, a Fey, or a Fiend, the target doesn't return if the spell lasts for 1 minute. The target is instead transported to a random location on a plane (DM's choice) associated with its creature type."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 4."}]}],"damageInflict":[],"conditionInflict":["incapacitated"],"savingThrow":["charisma"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":245},{"name":"Barkskin","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a handful of oak bark"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You touch a willing creature. Until the spell ends, the target's skin assumes a bark-like appearance, and the target has an <i>Armor Class</i> of 17 if its AC is lower than that."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":245},{"name":"Beacon of Hope","source":"XPHB","level":3,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Choose any number of creatures within range. For the duration, each target has <i>Advantage</i> on Wisdom saving throws and <i>Death Saving Throw</i> and regains the maximum number of <i>Hit Points</i> possible from any healing."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":245},{"name":"Beast Sense","source":"XPHB","level":2,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You touch a willing Beast. For the duration, you can perceive through the Beast's senses as well as your own. When perceiving through the Beast's senses, you benefit from any special senses it has."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":245},{"name":"Bestow Curse","source":"XPHB","level":3,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You touch a creature, which must succeed on a Wisdom saving throw or become cursed for the duration. Until the curse ends, the target suffers one of the following effects of your choice:"},{"type":"list","items":["Choose one ability. The target has <i>Disadvantage</i> on ability checks and saving throws made with that ability.","The target has <i>Disadvantage</i> on attack rolls against you.","In combat, the target must succeed on a Wisdom saving throw at the start of each of its turns or be forced to take the <b>Dodge</b> action on that turn.","If you deal damage to the target with an attack roll or a spell, the target takes an extra <span class=\\"text-red-400 font-semibold\\">1d8</span> Necrotic damage."]}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"If you cast this spell using a level 4 spell slot, you can maintain <i>Concentration</i> on it for up to 10 minutes. If you use a level 5+ spell slot, the spell doesn't require <i>Concentration</i>, and the duration becomes 8 hours (level 5-6 slot) or 24 hours (level 7-8 slot). If you use a level 9 spell slot, the spell lasts until dispelled."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":246},{"name":"Bigby's Hand","source":"XPHB","level":5,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"an eggshell and a glove"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a Large hand of shimmering magical energy in an unoccupied space that you can see within range. The hand lasts for the duration, and it moves at your command, mimicking the movements of your own hand."},{"type":"text","content":"The hand is an object that has AC 20 and <i>Hit Points</i> equal to your <i>Hit Points</i> maximum. If it drops to 0 <i>Hit Points</i>, the spell ends. The hand doesn't occupy its space."},{"type":"text","content":"When you cast the spell and as a <i>Bonus Action</i> on your later turns, you can move the hand up to 60 feet and then cause one of the following effects:"},{"type":"list","items":[{"type":"item","name":"Clenched Fist","entry":"The hand strikes a target within 5 feet of it. Make a melee spell attack. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">5d8</span> Force damage."},{"type":"item","name":"Forceful Hand","entry":"The hand attempts to push a Huge or smaller creature within 5 feet of it. The target must succeed on a Strength saving throw, or the hand pushes the target up to 5 feet plus a number of feet equal to five times your spellcasting ability modifier. The hand moves with the target, remaining within 5 feet of it."},{"type":"item","name":"Grasping Hand","entry":"The hand attempts to grapple a Huge or smaller creature within 5 feet of it. The target must succeed on a Dexterity saving throw, or the target has the <i class=\\"text-dnd-gold\\">Grappled</i> condition, with an escape DC equal to your spell save DC. While the hand grapples the target, you can take a <i>Bonus Action</i> to cause the hand to crush it, dealing Bludgeoning damage to the target equal to <span class=\\"text-red-400 font-semibold\\">4d6</span> plus your spellcasting ability modifier."},{"type":"item","name":"Interposing Hand","entry":"The hand grants you <i>Cover</i> against attacks and other effects that originate from its space or that pass through it. In addition, its space counts as <i>Difficult Terrain</i> for your enemies."}]}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage of the Clenched Fist increases by 5d8 and the damage of the Grasping Hand increases by 4d6 for each spell slot level above 5."}]}],"damageInflict":["bludgeoning","force"],"conditionInflict":["grappled"],"savingThrow":["dexterity","strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":246},{"name":"Blade Barrier","source":"XPHB","level":6,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You create a wall of whirling blades made of magical energy. The wall appears within range and lasts for the duration. You make a straight wall up to 100 feet long, 20 feet high, and 5 feet thick, or a ringed wall up to 60 feet in diameter, 20 feet high, and 5 feet thick. The wall provides Three-Quarters <i>Cover</i>, and its space is <i>Difficult Terrain</i>."},{"type":"text","content":"Any creature in the wall's space makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">6d10</span> Force damage on a failed save or half as much damage on a successful one. A creature also makes that save if it enters the wall's space or ends its turn there. A creature makes that save only once per turn."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":247},{"name":"Blade Ward","source":"XPHB","level":0,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Whenever a creature makes an attack roll against you before the spell ends, the attacker subtracts <span class=\\"text-green-400 font-mono\\">1d4</span> from the attack roll."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":247},{"name":"Bless","source":"XPHB","level":1,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":{"text":"a Holy Symbol worth 5+ GP","cost":500}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You bless up to three creatures within range. Whenever a target makes an attack roll or a saving throw before the spell ends, the target adds <span class=\\"text-green-400 font-mono\\">1d4</span> to the attack roll or save."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":247},{"name":"Blight","source":"XPHB","level":4,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A creature that you can see within range makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">8d8</span> Necrotic damage on a failed save or half as much damage on a successful one. A Plant creature automatically fails the save."},{"type":"text","content":"Alternatively, target a nonmagical plant that isn't a creature, such as a tree or shrub. It doesn't make a save; it simply withers and dies."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 8d8 for each spell slot level above 4."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":247},{"name":"Blinding Smite","source":"XPHB","level":3,"school":"V","time":[{"number":1,"unit":"bonus","condition":"which you take immediately after hitting a creature with a Melee weapon or an {@variantrule Unarmed Strike|XPHB}"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"The target hit by the strike takes an extra <span class=\\"text-red-400 font-semibold\\">3d8</span> Radiant damage from the attack, and the target has the <i class=\\"text-dnd-gold\\">Blinded</i> condition until the spell ends. At the end of each of its turns, the <i class=\\"text-dnd-gold\\">Blinded</i> target makes a Constitution saving throw, ending the spell on itself on a success."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The extra damage increases by 3d8 for each spell slot level above 3."}]}],"damageInflict":["radiant"],"conditionInflict":["blinded"],"savingThrow":["constitution"],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":247},{"name":"Blindness/Deafness","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"One creature that you can see within range must succeed on a Constitution saving throw, or it has the <i class=\\"text-dnd-gold\\">Blinded</i> or <i class=\\"text-dnd-gold\\">Deafened</i> condition (your choice) for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 2."}]}],"damageInflict":[],"conditionInflict":["blinded","deafened"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":248},{"name":"Blink","source":"XPHB","level":3,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"Roll <span class=\\"text-green-400 font-mono\\">1d6</span> at the end of each of your turns for the duration. On a roll of 4-6, you vanish from your current plane of existence and appear in the Ethereal Plane (the spell ends instantly if you are already on that plane). While on the Ethereal Plane, you can perceive the plane you left, which is cast in shades of gray, but you can't see anything there more than 60 feet away. You can affect and be affected only by other creatures on the Ethereal Plane, and creatures on the other plane can't perceive you unless they have a special ability that lets them perceive things on the Ethereal Plane."},{"type":"text","content":"You return to the other plane at the start of your next turn and when the spell ends if you are on the Ethereal Plane. You return to an unoccupied space of your choice that you can see within 10 feet of the space you left. If no unoccupied space is available within that range, you appear in the nearest unoccupied space."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":248},{"name":"Blur","source":"XPHB","level":2,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Your body becomes blurred. For the duration, any creature has <i>Disadvantage</i> on attack rolls against you. An attacker is immune to this effect if it perceives you with <i>Blindsight</i> or <i>Truesight</i>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":248},{"name":"Branding Smite","source":"PHB","level":2,"school":"V","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"The next time you hit a creature with a weapon attack before this spell ends, the weapon gleams with astral radiance as you strike. The attack deals an extra <span class=\\"text-red-400 font-semibold\\">2d6</span> radiant damage to the target, which becomes visible if it's <i class=\\"text-dnd-gold\\">invisible</i>, and the target sheds dim light in a 5-foot radius and can't become <i class=\\"text-dnd-gold\\">invisible</i> until the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 3rd level or higher, the extra damage increases by 2d6 for each slot level above 2nd."}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":true,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":["Shining Smite|XPHB"],"page":219},{"name":"Burning Hands","source":"XPHB","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"cone","distance":{"type":"feet","amount":15}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A thin sheet of flames shoots forth from you. Each creature in a 15-foot <i>Cone [Area of Effect]</i> makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">3d6</span> Fire damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"Flammable objects in the <i>Cone [Area of Effect]</i> that aren't being worn or carried start burning."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d6 for each spell slot level above 1."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":248},{"name":"Call Lightning","source":"XPHB","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"A storm cloud appears at a point within range that you can see above yourself. It takes the shape of a <i>Cylinder [Area of Effect]</i> that is 10 feet tall with a 60-foot radius."},{"type":"text","content":"When you cast the spell, choose a point you can see under the cloud. A lightning bolt shoots from the cloud to that point. Each creature within 5 feet of that point makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">3d10</span> Lightning damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"Until the spell ends, you can take a <b>Magic</b> action to call down lightning in that way again, targeting the same point or a different one."},{"type":"text","content":"If you're outdoors in a storm when you cast this spell, the spell gives you control over that storm instead of creating a new one. Under such conditions, the spell's damage increases by <span class=\\"text-red-400 font-semibold\\">1d10</span>."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d10 for each spell slot level above 3."}]}],"damageInflict":["lightning"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":248},{"name":"Calm Emotions","source":"XPHB","level":2,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Each Humanoid in a 20-foot-radius <i>Sphere [Area of Effect]</i> centered on a point you choose within range must succeed on a Charisma saving throw or be affected by one of the following effects (choose for each creature):"},{"type":"list","items":["The creature has <i>Immunity</i> to the <i class=\\"text-dnd-gold\\">Charmed</i> and <i class=\\"text-dnd-gold\\">Frightened</i> conditions until the spell ends. If the creature was already <i class=\\"text-dnd-gold\\">Charmed</i> or <i class=\\"text-dnd-gold\\">Frightened</i>, those conditions are suppressed for the duration.","The creature becomes <i>Indifferent [Attitude]</i> about creatures of your choice that it's <i>Hostile [Attitude]</i> toward. This indifference ends if the target takes damage or witnesses its allies taking damage. When the spell ends, the creature's attitude returns to normal."]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["charisma"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":249},{"name":"Chain Lightning","source":"XPHB","level":6,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":"three silver pins"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You launch a lightning bolt toward a target you can see within range. Three bolts then leap from that target to as many as three other targets of your choice, each of which must be within 30 feet of the first target. A target can be a creature or an object and can be targeted by only one of the bolts."},{"type":"text","content":"Each target makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">10d8</span> Lightning damage on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"One additional bolt leaps from the first target to another target for each spell slot level above 6."}]}],"damageInflict":["lightning"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":249},{"name":"Charm Person","source":"XPHB","level":1,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"One Humanoid you can see within range makes a Wisdom saving throw. It does so with <i>Advantage</i> if you or your allies are fighting it. On a failed save, the target has the <i class=\\"text-dnd-gold\\">Charmed</i> condition until the spell ends or until you or your allies damage it. The <i class=\\"text-dnd-gold\\">Charmed</i> creature is <i>Friendly [Attitude]</i> to you. When the spell ends, the target knows it was <i class=\\"text-dnd-gold\\">Charmed</i> by you."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":249},{"name":"Chill Touch","source":"XPHB","level":0,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Channeling the chill of the grave, make a melee spell attack against a target within reach. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">1d10</span> Necrotic damage, and it can't regain <i>Hit Points</i> until the end of your next turn."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d10</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d10</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d10</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d10</span>)."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":249},{"name":"Chromatic Orb","source":"XPHB","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"a diamond worth 50+ GP","cost":5000}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You hurl an orb of energy at a target within range. Choose Acid, Cold, Fire, Lightning, Poison, or Thunder for the type of orb you create, and then make a ranged spell attack against the target. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">3d8</span> damage of the chosen type."},{"type":"text","content":"If you roll the same number on two or more of the d8s, the orb leaps to a different target of your choice within 30 feet of the target. Make an attack roll against the new target, and make a new damage roll. The orb can't leap again unless you cast the spell with a level 2+ spell slot."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d8 for each spell slot level above 1. The orb can leap a maximum number of times equal to the level of the slot expended, and a creature can be targeted only once by each casting of this spell."}]}],"damageInflict":["acid","cold","fire","lightning","poison","thunder"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":249},{"name":"Circle of Death","source":"XPHB","level":6,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":{"text":"the powder of a crushed black pearl worth 500+ GP","cost":50000}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Negative energy ripples out in a 60-foot-radius <i>Sphere [Area of Effect]</i> from a point you choose within range. Each creature in that area makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">8d8</span> Necrotic damage on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 8d8 for each spell slot level above 6."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":250},{"name":"Circle of Power","source":"XPHB","level":5,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"An aura radiates from you in a 30-foot <i>Emanation [Area of Effect]</i> for the duration. While in the aura, you and your allies have <i>Advantage</i> on saving throws against spells and other magical effects. When an affected creature makes a saving throw against a spell or magical effect that allows a save to take only half damage, it takes no damage if it succeeds on the save."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":250},{"name":"Clairvoyance","source":"XPHB","level":3,"school":"D","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"miles","amount":1}},"components":{"v":true,"s":true,"m":{"text":"a focus worth 100+ GP, either a jeweled horn for hearing or a glass eye for seeing","cost":10000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You create an <i class=\\"text-dnd-gold\\">Invisible</i> sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The intangible, invulnerable sensor remains in place for the duration."},{"type":"text","content":"When you cast the spell, choose seeing or hearing. You can use the chosen sense through the sensor as if you were in its space. As a <i>Bonus Action</i>, you can switch between seeing and hearing."},{"type":"text","content":"A creature that sees the sensor (such as a creature benefiting from <a href=\\"/spells?search=See Invisibility\\" class=\\"text-dnd-gold hover:underline\\">See Invisibility</a> or <i>Truesight</i>) sees a luminous orb about the size of your fist."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":250},{"name":"Clone","source":"XPHB","level":8,"school":"N","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a diamond worth 1,000+ GP, which the spell consumes, and a sealable vessel worth 2,000+ GP that is large enough to hold the creature being cloned","cost":100000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You touch a creature or at least 1 cubic inch of its flesh. An inert duplicate of that creature forms inside the vessel used in the spell's casting and finishes growing after 120 days; you choose whether the finished clone is the same age as the creature or younger. The clone remains inert and endures indefinitely while its vessel remains undisturbed."},{"type":"text","content":"If the original creature dies after the clone finishes forming, the creature's soul transfers to the clone if the soul is free and willing to return. The clone is physically identical to the original and has the same personality, memories, and abilities, but none of the original's equipment. The creature's original remains, if any, become inert and can't be revived, since the creature's soul is elsewhere."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":251},{"name":"Cloud of Daggers","source":"XPHB","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a sliver of glass"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You conjure spinning daggers in a 5-foot <i>Cube [Area of Effect]</i> centered on a point within range. Each creature in that area takes <span class=\\"text-red-400 font-semibold\\">4d4</span> Slashing damage. A creature also takes this damage if it enters the <i>Cube [Area of Effect]</i> or ends its turn there or if the <i>Cube [Area of Effect]</i> moves into its space. A creature takes this damage only once per turn."},{"type":"text","content":"On your later turns, you can take a <b>Magic</b> action to teleport the <i>Cube [Area of Effect]</i> up to 30 feet."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 4d4 for each spell slot level above 2."}]}],"damageInflict":["slashing"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":251},{"name":"Cloudkill","source":"XPHB","level":5,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You create a 20-foot-radius <i>Sphere [Area of Effect]</i> of yellow-green fog centered on a point within range. The fog lasts for the duration or until strong wind (such as the one created by <a href=\\"/spells?search=Gust of Wind\\" class=\\"text-dnd-gold hover:underline\\">Gust of Wind</a>) disperses it, ending the spell. Its area is <i>Heavily Obscured</i>."},{"type":"text","content":"Each creature in the <i>Sphere [Area of Effect]</i> makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">5d8</span> Poison damage on a failed save or half as much damage on a successful one. A creature must also make this save when the <i>Sphere [Area of Effect]</i> moves into its space and when it enters the <i>Sphere [Area of Effect]</i> or ends its turn there. A creature makes this save only once per turn."},{"type":"text","content":"The <i>Sphere [Area of Effect]</i> moves 10 feet away from you at the start of each of your turns."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 5d8 for each spell slot level above 5."}]}],"damageInflict":["poison"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":251},{"name":"Color Spray","source":"XPHB","level":1,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"cone","distance":{"type":"feet","amount":15}},"components":{"v":true,"s":true,"m":"a pinch of colorful sand"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You launch a dazzling array of flashing, colorful light. Each creature in a 15-foot <i>Cone [Area of Effect]</i> originating from you must succeed on a Constitution saving throw or have the <i class=\\"text-dnd-gold\\">Blinded</i> condition until the end of your next turn."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["blinded"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":251},{"name":"Command","source":"XPHB","level":1,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You speak a one-word command to a creature you can see within range. The target must succeed on a Wisdom saving throw or follow the command on its next turn. Choose the command from these options:"},{"type":"list","items":[{"type":"item","name":"Approach","entry":"The target moves toward you by the shortest and most direct route, ending its turn if it moves within 5 feet of you."},{"type":"item","name":"Drop","entry":"The target drops whatever it is holding and then ends its turn."},{"type":"item","name":"Flee","entry":"The target spends its turn moving away from you by the fastest available means."},{"type":"item","name":"Grovel","entry":"The target has the <i class=\\"text-dnd-gold\\">Prone</i> condition and then ends its turn."},{"type":"item","name":"Halt","entry":"On its turn, the target doesn't move and takes no action or <i>Bonus Action</i>."}]}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can affect one additional creature for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":["prone"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":251},{"name":"Commune","source":"XPHB","level":5,"school":"D","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"incense"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"You contact a deity or a divine proxy and ask up to three questions that can be answered with yes or no. You must ask your questions before the spell ends. You receive a correct answer for each question."},{"type":"text","content":"Divine beings aren't necessarily omniscient, so you might receive \\"unclear\\" as an answer if a question pertains to information that lies beyond the deity's knowledge. In a case where a one-word answer could be misleading or contrary to the deity's interests, the DM might offer a short phrase as an answer instead."},{"type":"text","content":"If you cast the spell more than once before finishing a <i>Long Rest</i>, there is a cumulative 25% chance for each casting after the first that you get no answer."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":251},{"name":"Commune with Nature","source":"XPHB","level":5,"school":"D","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"You commune with nature spirits and gain knowledge of the surrounding area. In the outdoors, the spell gives you knowledge of the area within 3 miles of you. In caves and other natural underground settings, the radius is limited to 300 feet. The spell doesn't function where nature has been replaced by construction, such as in castles and settlements."},{"type":"text","content":"Choose three of the following facts; you learn those facts as they pertain to the spell's area:"},{"type":"list","items":["Locations of settlements","Locations of portals to other planes of existence","Location of one <i>Challenge Rating</i> 10+ creature (DM's choice) that is a Celestial, an Elemental, a Fey, a Fiend, or an Undead","The most prevalent kind of plant, mineral, or Beast (you choose which to learn)","Locations of bodies of water"]},{"type":"text","content":"For example, you could determine the location of a powerful monster in the area, the locations of bodies of water, and the locations of any towns."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":252},{"name":"Compelled Duel","source":"XPHB","level":1,"school":"E","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You try to compel a creature into a duel. One creature that you can see within range makes a Wisdom saving throw. On a failed save, the target has <i>Disadvantage</i> on attack rolls against creatures other than you, and it can't willingly move to a space that is more than 30 feet away from you."},{"type":"text","content":"The spell ends if you make an attack roll against a creature other than the target, if you cast a spell on an enemy other than the target, if an ally of yours damages the target, or if you end your turn more than 30 feet away from the target."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":252},{"name":"Comprehend Languages","source":"XPHB","level":1,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a pinch of soot and salt"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"For the duration, you understand the literal meaning of any language that you hear or see signed. You also understand any written language that you see, but you must be touching the surface on which the words are written. It takes about 1 minute to read one page of text. This spell doesn't decode symbols or secret messages."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":252},{"name":"Compulsion","source":"XPHB","level":4,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Each creature of your choice that you can see within range must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Charmed</i> condition until the spell ends."},{"type":"text","content":"For the duration, you can take a <i>Bonus Action</i> to designate a direction that is horizontal to you. Each <i class=\\"text-dnd-gold\\">Charmed</i> target must use as much of its movement as possible to move in that direction on its next turn, taking the safest route. After moving in this way, a target repeats the save, ending the spell on itself on a success."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":252},{"name":"Cone of Cold","source":"XPHB","level":5,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"cone","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a small crystal or glass cone"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You unleash a blast of cold air. Each creature in a 60-foot <i>Cone [Area of Effect]</i> originating from you makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">8d8</span> Cold damage on a failed save or half as much damage on a successful one. A creature killed by this spell becomes a frozen statue until it thaws."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 8d8 for each spell slot level above 5."}]}],"damageInflict":["cold"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":253},{"name":"Confusion","source":"XPHB","level":4,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":"three nut shells"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Each creature in a 10-foot-radius <i>Sphere [Area of Effect]</i> centered on a point you choose within range must succeed on a Wisdom saving throw, or that target can't take Bonus Actions or Reactions and must roll <span class=\\"text-green-400 font-mono\\">1d10</span> at the start of each of its turns to determine its behavior for that turn, consulting the table below."},{"type":"table","caption":"","colLabels":["1d10","Behavior for the Turn"],"rows":[["1","The target doesn't take an action, and it uses all its movement to move. Roll <span class=\\"text-green-400 font-mono\\">1d4</span> for the direction: <b>1</b>, north; <b>2</b>, east; <b>3</b>, south; or <b>4</b>, west."],["2-6","The target doesn't move or take actions."],["7-8","The target doesn't move, and it takes the <b>Attack</b> action to make one melee attack against a random creature within reach. If none are within reach, the target takes no action."],["9-10","The target chooses its behavior."]]},{"type":"text","content":"At the end of each of its turns, an affected target repeats the save, ending the spell on itself on a success."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The <i>Sphere [Area of Effect]</i>'s radius increases by 5 feet for each spell slot level above 4."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":253},{"name":"Conjure Animals","source":"XPHB","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You conjure nature spirits that appear as a Large pack of spectral, intangible animals in an unoccupied space you can see within range. The pack lasts for the duration, and you choose the spirits' animal form, such as wolves, serpents, or birds."},{"type":"text","content":"You have <i>Advantage</i> on Strength saving throws while you're within 5 feet of the pack, and when you move on your turn, you can also move the pack up to 30 feet to an unoccupied space you can see."},{"type":"text","content":"Whenever the pack moves within 10 feet of a creature you can see and whenever a creature you can see enters a space within 10 feet of the pack or ends its turn there, you can force that creature to make a Dexterity saving throw. On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">3d10</span> Slashing damage. A creature makes this save only once per turn."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d10 for each spell slot level above 3."}]}],"damageInflict":["slashing"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":254},{"name":"Conjure Barrage","source":"XPHB","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"cone","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"a Melee or Ranged weapon worth at least 1 CP","cost":1}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You brandish the weapon used to cast the spell and conjure similar spectral weapons (or ammunition appropriate to the weapon) that launch forward and then disappear. Each creature of your choice that you can see in a 60-foot <i>Cone [Area of Effect]</i> makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">5d8</span> Force damage on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 5d8 for each spell slot level above 3."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":254},{"name":"Conjure Celestial","source":"XPHB","level":7,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You conjure a spirit from the Upper Planes, which manifests as a pillar of light in a 10-foot-radius, 40-foot-high <i>Cylinder [Area of Effect]</i> centered on a point within range. For each creature you can see in the <i>Cylinder [Area of Effect]</i>, choose which of these lights shines on it:"},{"type":"list","items":[{"type":"item","name":"Healing Light","entry":"The target regains <i>Hit Points</i> equal to <span class=\\"text-green-400 font-mono\\">4d12</span> plus your spellcasting ability modifier."},{"type":"item","name":"Searing Light","entry":"The target makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">6d12</span> Radiant damage on a failed save or half as much damage on a successful one."}]},{"type":"text","content":"Until the spell ends, <i>Bright Light</i> fills the <i>Cylinder [Area of Effect]</i>, and when you move on your turn, you can also move the <i>Cylinder [Area of Effect]</i> up to 30 feet."},{"type":"text","content":"Whenever the <i>Cylinder [Area of Effect]</i> moves into the space of a creature you can see and whenever a creature you can see enters the <i>Cylinder [Area of Effect]</i> or ends its turn there, you can bathe it in one of the lights. A creature can be affected by this spell only once per turn."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The healing and damage increase by 6d12 for each spell slot level above 7."}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":254},{"name":"Conjure Elemental","source":"XPHB","level":5,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You conjure a Large, intangible spirit from the Elemental Planes that appears in an unoccupied space within range. Choose the spirit's element, which determines its damage type: air (Lightning), earth (Thunder), fire (Fire), or water (Cold). The spirit lasts for the duration."},{"type":"text","content":"Whenever a creature you can see enters the spirit's space or starts its turn within 5 feet of the spirit, you can force that creature to make a Dexterity saving throw if the spirit has no creature <i class=\\"text-dnd-gold\\">Restrained</i>. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">8d8</span> damage of the spirit's type, and the target has the <i class=\\"text-dnd-gold\\">Restrained</i> condition until the spell ends. At the start of each of its turns, the <i class=\\"text-dnd-gold\\">Restrained</i> target repeats the save. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">4d8</span> damage of the spirit's type. On a successful save, the target isn't <i class=\\"text-dnd-gold\\">Restrained</i> by the spirit."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 8d8;4d8 for each spell slot level above 5."}]}],"damageInflict":["lightning","thunder","fire","cold"],"conditionInflict":["restrained"],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":254},{"name":"Conjure Fey","source":"XPHB","level":6,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You conjure a Medium spirit from the Feywild in an unoccupied space you can see within range. The spirit lasts for the duration, and it looks like a Fey creature of your choice. When the spirit appears, you can make one melee spell attack against a creature within 5 feet of it. On a hit, the target takes Psychic damage equal to <span class=\\"text-red-400 font-semibold\\">3d12</span> plus your spellcasting ability modifier, and the target has the <i class=\\"text-dnd-gold\\">Frightened</i> condition until the start of your next turn, with both you and the spirit as the source of the fear."},{"type":"text","content":"As a <i>Bonus Action</i> on your later turns, you can teleport the spirit to an unoccupied space you can see within 30 feet of the space it left and make the attack against a creature within 5 feet of it."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d12 for each spell slot level above 6."}]}],"damageInflict":["psychic"],"conditionInflict":["frightened"],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":255},{"name":"Conjure Minor Elementals","source":"XPHB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":15}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You conjure spirits from the Elemental Planes that flit around you in a 15-foot <i>Emanation [Area of Effect]</i> for the duration. Until the spell ends, any attack you make deals an extra <span class=\\"text-red-400 font-semibold\\">2d8</span> damage when you hit a creature in the <i>Emanation [Area of Effect]</i>. This damage is Acid, Cold, Fire, or Lightning (your choice when you make the attack)."},{"type":"text","content":"In addition, the ground in the <i>Emanation [Area of Effect]</i> is <i>Difficult Terrain</i> for your enemies."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d8 for each spell slot level above 4."}]}],"damageInflict":["acid","cold","fire","lightning"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":255},{"name":"Conjure Volley","source":"XPHB","level":5,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":{"text":"a Melee or Ranged weapon worth at least 1 CP","cost":1}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You brandish the weapon used to cast the spell and choose a point within range. Hundreds of similar spectral weapons (or ammunition appropriate to the weapon) fall in a volley and then disappear. Each creature of your choice that you can see in a 40-foot-radius, 20-foot-high <i>Cylinder [Area of Effect]</i> centered on that point makes a Dexterity saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">8d8</span> Force damage on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":255},{"name":"Conjure Woodland Beings","source":"XPHB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You conjure nature spirits that flit around you in a 10-foot <i>Emanation [Area of Effect]</i> for the duration. Whenever the <i>Emanation [Area of Effect]</i> enters the space of a creature you can see and whenever a creature you can see enters the <i>Emanation [Area of Effect]</i> or ends its turn there, you can force that creature to make a Wisdom saving throw. The creature takes <span class=\\"text-red-400 font-semibold\\">5d8</span> Force damage on a failed save or half as much damage on a successful one. A creature makes this save only once per turn."},{"type":"text","content":"In addition, you can take the <b>Disengage</b> action as a <i>Bonus Action</i> for the spell's duration."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 5d8 for each spell slot level above 4."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":255},{"name":"Contact Other Plane","source":"XPHB","level":5,"school":"D","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"You mentally contact a demigod, the spirit of a long-dead sage, or some other knowledgeable entity from another plane. Contacting this otherworldly intelligence can break your mind. When you cast this spell, make a DC 15 Intelligence saving throw. On a successful save, you can ask the entity up to five questions. You must ask your questions before the spell ends. The DM answers each question with one word, such as \\"yes,\\" \\"no,\\" \\"maybe,\\" \\"never,\\" \\"irrelevant,\\" or \\"unclear\\" (if the entity doesn't know the answer to the question). If a one-word answer would be misleading, the DM might instead offer a short phrase as an answer."},{"type":"text","content":"On a failed save, you take <span class=\\"text-red-400 font-semibold\\">6d6</span> Psychic damage and have the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition until you finish a <i>Long Rest</i>. A <a href=\\"/spells?search=Greater Restoration\\" class=\\"text-dnd-gold hover:underline\\">Greater Restoration</a> spell cast on you ends this effect."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["intelligence"],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":255},{"name":"Contagion","source":"XPHB","level":5,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"day","amount":7}}],"entries":[{"type":"text","content":"Your touch inflicts a magical contagion. The target must succeed on a Constitution saving throw or take <span class=\\"text-red-400 font-semibold\\">11d8</span> Necrotic damage and have the <i class=\\"text-dnd-gold\\">Poisoned</i> condition. Also, choose one ability when you cast the spell. While <i class=\\"text-dnd-gold\\">Poisoned</i>, the target has <i>Disadvantage</i> on saving throws made with the chosen ability."},{"type":"text","content":"The target must repeat the saving throw at the end of each of its turns until it gets three successes or failures. If the target succeeds on three of these saves, the spell ends on the target. If the target fails three of the saves, the spell lasts for 7 days on it."},{"type":"text","content":"Whenever the <i class=\\"text-dnd-gold\\">Poisoned</i> target receives an effect that would end the <i class=\\"text-dnd-gold\\">Poisoned</i> condition, the target must succeed on a Constitution saving throw, or the <i class=\\"text-dnd-gold\\">Poisoned</i> condition doesn't end on it."}],"entriesHigherLevel":[],"damageInflict":["necrotic"],"conditionInflict":["poisoned"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":256},{"name":"Contingency","source":"XPHB","level":6,"school":"A","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"a gem-encrusted statuette of yourself worth 1,500+ GP","cost":150000}},"duration":[{"type":"timed","duration":{"type":"day","amount":10}}],"entries":[{"type":"text","content":"Choose a spell of level 5 or lower that you can cast, that has a casting time of an action, and that can target you. You cast that spell—called the contingent spell—as part of casting Contingency, expending spell slots for both, but the contingent spell doesn't come into effect. Instead, it takes effect when a certain trigger occurs. You describe that trigger when you cast the two spells. For example, a Contingency cast with <a href=\\"/spells?search=Water Breathing\\" class=\\"text-dnd-gold hover:underline\\">Water Breathing</a> might stipulate that Water Breathing comes into effect when you are engulfed in water or a similar liquid."},{"type":"text","content":"The contingent spell takes effect immediately after the trigger occurs for the first time, whether or not you want it to, and then Contingency ends."},{"type":"text","content":"The contingent spell takes effect only on you, even if it can normally target others. You can use only one Contingency spell at a time. If you cast this spell again, the effect of another Contingency spell on you ends. Also, Contingency ends on you if its material component is ever not on your person."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":256},{"name":"Continual Flame","source":"XPHB","level":2,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"ruby dust worth 50+ GP, which the spell consumes","cost":5000,"consume":true}},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"A flame springs from an object that you touch. The effect casts <i>Bright Light</i> in a 20-foot radius and <i>Dim Light</i> for an additional 20 feet. It looks like a regular flame, but it creates no heat and consumes no fuel. The flame can be covered or hidden but not smothered or quenched."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":256},{"name":"Control Water","source":"XPHB","level":4,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":300}},"components":{"v":true,"s":true,"m":"a mixture of water and dust"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Until the spell ends, you control any water inside an area you choose that is a <i>Cube [Area of Effect]</i> up to 100 feet on a side, using one of the following effects. As a <b>Magic</b> action on your later turns, you can repeat the same effect or choose a different one."},{"type":"section","name":"Flood","entries":[{"type":"text","content":"You cause the water level of all standing water in the area to rise by as much as 20 feet. If you choose an area in a large body of water, you instead create a 20-foot tall wave that travels from one side of the area to the other and then crashes. Any Huge or smaller vehicles in the wave's path are carried with it to the other side. Any Huge or smaller vehicles struck by the wave have a 25% chance of capsizing."},{"type":"text","content":"The water level remains elevated until the spell ends or you choose a different effect. If this effect produced a wave, the wave repeats on the start of your next turn while the flood effect lasts."}]},{"type":"section","name":"Part Water","entries":[{"type":"text","content":"You part water in the area and create a trench. The trench extends across the spell's area, and the separated water forms a wall to either side. The trench remains until the spell ends or you choose a different effect. The water then slowly fills in the trench over the course of the next round until the normal water level is restored."}]},{"type":"section","name":"Redirect Flow","entries":[{"type":"text","content":"You cause flowing water in the area to move in a direction you choose, even if the water has to flow over obstacles, up walls, or in other unlikely directions. The water in the area moves as you direct it, but once it moves beyond the spell's area, it resumes its flow based on the terrain. The water continues to move in the direction you chose until the spell ends or you choose a different effect."}]},{"type":"section","name":"Whirlpool","entries":[{"type":"text","content":"You cause a whirlpool to form in the center of the area, which must be at least 50 feet square and 25 feet deep. The whirlpool lasts until you choose a different effect or the spell ends. The whirlpool is 5 feet wide at the base, up to 50 feet wide at the top, and 25 feet tall. Any creature in the water and within 25 feet of the whirlpool is pulled 10 feet toward it. When a creature enters the whirlpool for the first time on a turn or ends its turn there, it makes a Strength saving throw. On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">2d8</span> Bludgeoning damage. On a successful save, the creature takes half as much damage. A creature can swim away from the whirlpool only if it first takes an action to pull away and succeeds on a Strength (<i>Athletics</i>) check against your spell save DC."}]}],"entriesHigherLevel":[],"damageInflict":["bludgeoning"],"conditionInflict":[],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":256},{"name":"Control Weather","source":"XPHB","level":8,"school":"T","time":[{"number":10,"unit":"minute"}],"range":{"type":"sphere","distance":{"type":"miles","amount":5}},"components":{"v":true,"s":true,"m":"burning incense"},"duration":[{"type":"timed","duration":{"type":"hour","amount":8},"concentration":true}],"entries":[{"type":"text","content":"You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell, and it ends early if you go indoors."},{"type":"text","content":"When you cast the spell, you change the current weather conditions, which are determined by the DM. You can change precipitation, temperature, and wind. It takes <span class=\\"text-green-400 font-mono\\">1d4 × 10</span> minutes for the new conditions to take effect. Once they do so, you can change the conditions again. When the spell ends, the weather gradually returns to normal."},{"type":"text","content":"When you change the weather conditions, find a current condition on the following tables and change its stage by one, up or down. When changing the wind, you can change its direction."},{"type":"table","caption":"Precipitation","colLabels":["Stage","Condition"],"rows":[["1","Clear"],["2","Light clouds"],["3","Overcast or ground fog"],["4","Rain, hail, or snow"],["5","Torrential rain, driving hail, or blizzard"]]},{"type":"table","caption":"Temperature","colLabels":["Stage","Condition"],"rows":[["1","Heat wave"],["2","Hot"],["3","Warm"],["4","Cool"],["5","Cold"],["6","Freezing"]]},{"type":"table","caption":"Wind","colLabels":["Stage","Condition"],"rows":[["1","Calm"],["2","Moderate wind"],["3","Strong wind"],["4","Gale"],["5","Storm"]]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":257},{"name":"Cordon of Arrows","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"four or more arrows or bolts"},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You touch up to four nonmagical Arrows or Bolts and plant them in the ground in your space. Until the spell ends, the ammunition can't be physically uprooted, and whenever a creature other than you enters a space within 30 feet of the ammunition for the first time on a turn or ends its turn there, one piece of ammunition flies up to strike it. The creature must succeed on a Dexterity saving throw or take <span class=\\"text-red-400 font-semibold\\">2d4</span> Piercing damage. The piece of ammunition is then destroyed. The spell ends when none of the ammunition remains planted in the ground."},{"type":"text","content":"When you cast this spell, you can designate any creatures you choose, and the spell ignores them."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The amount of ammunition that can be affected increases by two for each spell slot level above 2."}]}],"damageInflict":["piercing"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":258},{"name":"Counterspell","source":"XPHB","level":3,"school":"A","time":[{"number":1,"unit":"reaction","condition":"which you take when you see a creature within 60 feet of yourself casting a spell with Verbal, Somatic, or Material components"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You attempt to interrupt a creature in the process of casting a spell. The creature makes a Constitution saving throw. On a failed save, the spell dissipates with no effect, and the action, <i>Bonus Action</i>, or <i>Reaction</i> used to cast it is wasted. If that spell was cast with a spell slot, the slot isn't expended."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"reaction","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":258},{"name":"Create Food and Water","source":"XPHB","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You create 45 pounds of food and 30 gallons of fresh water on the ground or in containers within range—both useful in fending off the hazards of malnutrition and dehydration. The food is bland but nourishing and looks like a food of your choice, and the water is clean. The food spoils after 24 hours if uneaten."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":258},{"name":"Create or Destroy Water","source":"XPHB","level":1,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a mix of water and sand"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You do one of the following:"},{"type":"list","items":[{"type":"item","name":"Create Water","entry":"You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot <i>Cube [Area of Effect]</i> within range, extinguishing exposed flames there."},{"type":"item","name":"Destroy Water","entry":"You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot <i>Cube [Area of Effect]</i> within range."}]}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You create or destroy 10 additional gallons of water, or the size of the <i>Cube [Area of Effect]</i> increases by 5 feet, for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":258},{"name":"Create Undead","source":"XPHB","level":6,"school":"N","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":{"text":"one 150+ GP black onyx stone for each corpse","cost":15000}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You can cast this spell only at night. Choose up to three corpses of Medium or Small Humanoids within range. Each one becomes a <b>Ghoul</b> under your control (see the <i>Monster Manual</i> for its stat block)."},{"type":"text","content":"As a <i>Bonus Action</i> on each of your turns, you can mentally command any creature you animated with this spell if the creature is within 120 feet of you (if you control multiple creatures, you can command any of them at the same time, issuing the same command to them). You decide what action the creature will take and where it will move on its next turn, or you can issue a general command, such as to guard a particular place. If you issue no commands, the creature takes the <b>Dodge</b> action and moves only to avoid harm. Once given an order, the creature continues to follow the order until its task is complete."},{"type":"text","content":"The creature is under your control for 24 hours, after which it stops obeying any command you've given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature before the current 24-hour period ends. This use of the spell reasserts your control over up to three creatures you have animated with this spell rather than animating new ones."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"If you use a level 7 spell slot, you can animate or reassert control over four <b>Ghoul</b>. If you use a level 8 spell slot, you can animate or reassert control over five <b>Ghoul</b> or two <b>Ghast</b> or <b>Wight</b>. If you use a level 9 spell slot, you can animate or reassert control over six <b>Ghoul</b>, three <b>Ghast</b> or <b>Wight</b>, or two <b>Mummy</b>. See the <i>Monster Manual</i> for these stat blocks."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":258},{"name":"Creation","source":"XPHB","level":5,"school":"I","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a paintbrush"},"duration":[{"type":"special"}],"entries":[{"type":"text","content":"You pull wisps of shadow material from the Shadowfell to create an object within range. It is either an object of vegetable matter (soft goods, rope, wood, and the like) or mineral matter (stone, crystal, metal, and the like). The object must be no larger than a 5-foot <i>Cube [Area of Effect]</i>, and the object must be of a form and material that you have seen."},{"type":"text","content":"The spell's duration depends on the object's material, as shown in the Materials table. If the object is composed of multiple materials, use the shortest duration. Using any object created by this spell as another spell's Material component causes the other spell to fail."},{"type":"table","caption":"Materials","colLabels":["Material","Duration"],"rows":[["Vegetable matter","24 hours"],["Stone or crystal","12 hours"],["Precious metals","1 hour"],["Gems","10 minutes"],["Adamantine or mithral","1 minute"]]}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The <i>Cube [Area of Effect]</i> increases by 5 feet for each spell slot level above 5."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":259},{"name":"Crown of Madness","source":"XPHB","level":2,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"One creature that you can see within range must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration. The creature succeeds automatically if it isn't Humanoid."},{"type":"text","content":"A spectral crown appears on the <i class=\\"text-dnd-gold\\">Charmed</i> target's head, and it must use its action before moving on each of its turns to make a melee attack against a creature other than itself that you mentally choose. The target can act normally on its turn if you choose no creature or if no creature is within its reach. The target repeats the save at the end of each of its turns, ending the spell on itself on a success."},{"type":"text","content":"On your later turns, you must take the <b>Magic</b> action to maintain control of the target, or the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":259},{"name":"Crusader's Mantle","source":"XPHB","level":3,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You radiate a magical aura in a 30-foot <i>Emanation [Area of Effect]</i>. While in the aura, you and your allies each deal an extra <span class=\\"text-red-400 font-semibold\\">1d4</span> Radiant damage when hitting with a weapon or an <i>Unarmed Strike</i>."}],"entriesHigherLevel":[],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":259},{"name":"Cure Wounds","source":"XPHB","level":1,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A creature you touch regains a number of <i>Hit Points</i> equal to <span class=\\"text-green-400 font-mono\\">2d8</span> plus your spellcasting ability modifier."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The healing increases by 2d8 for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":259},{"name":"Dancing Lights","source":"XPHB","level":0,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a bit of phosphorus"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create up to four torch-size lights within range, making them appear as torches, lanterns, or glowing orbs that hover for the duration. Alternatively, you combine the four lights into one glowing Medium form that is vaguely humanlike. Whichever form you choose, each light sheds <i>Dim Light</i> in a 10-foot radius."},{"type":"text","content":"As a <i>Bonus Action</i>, you can move the lights up to 60 feet to a space within range. A light must be within 20 feet of another light created by this spell, and a light vanishes if it exceeds the spell's range."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":259},{"name":"Darkness","source":"XPHB","level":2,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"m":"bat fur and a piece of coal"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"For the duration, magical <i>Darkness</i> spreads from a point within range and fills a 15-foot-radius <i>Sphere [Area of Effect]</i>. <i>Darkvision</i> can't see through it, and nonmagical light can't illuminate it."},{"type":"text","content":"Alternatively, you cast the spell on an object that isn't being worn or carried, causing the <i>Darkness</i> to fill a 15-foot <i>Emanation [Area of Effect]</i> originating from that object. Covering that object with something opaque, such as a bowl or helm, blocks the <i>Darkness</i>."},{"type":"text","content":"If any of this spell's area overlaps with an area of <i>Bright Light</i> or <i>Dim Light</i> created by a spell of level 2 or lower, that other spell is dispelled."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":260},{"name":"Darkvision","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a dried carrot"},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"For the duration, a willing creature you touch has <i>Darkvision</i> with a range of 150 feet."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":260},{"name":"Daylight","source":"XPHB","level":3,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"For the duration, sunlight spreads from a point within range and fills a 60-foot-radius <i>Sphere [Area of Effect]</i>. The sunlight's area is <i>Bright Light</i> and sheds <i>Dim Light</i> for an additional 60 feet."},{"type":"text","content":"Alternatively, you cast the spell on an object that isn't being worn or carried, causing the sunlight to fill a 60-foot <i>Emanation [Area of Effect]</i> originating from that object. Covering that object with something opaque, such as a bowl or helm, blocks the sunlight."},{"type":"text","content":"If any of this spell's area overlaps with an area of <i>Darkness</i> created by a spell of level 3 or lower, that other spell is dispelled."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":260},{"name":"Death Ward","source":"XPHB","level":4,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You touch a creature and grant it a measure of protection from death. The first time the target would drop to 0 <i>Hit Points</i> before the spell ends, the target instead drops to 1 <i>Hit Points</i>, and the spell ends."},{"type":"text","content":"If the spell is still in effect when the target is subjected to an effect that would kill it instantly without dealing damage, that effect is negated against the target, and the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":261},{"name":"Delayed Blast Fireball","source":"XPHB","level":7,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":"a ball of bat guano and sulfur"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A beam of yellow light flashes from you, then condenses at a chosen point within range as a glowing bead for the duration. When the spell ends, the bead explodes, and each creature in a 20-foot-radius <i>Sphere [Area of Effect]</i> centered on that point makes a Dexterity saving throw. A creature takes Fire damage equal to the total accumulated damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"The spell's base damage is <span class=\\"text-red-400 font-semibold\\">12d6</span>, and the damage increases by <span class=\\"text-red-400 font-semibold\\">1d6</span> whenever your turn ends and the spell hasn't ended."},{"type":"text","content":"If a creature touches the glowing bead before the spell ends, that creature makes a Dexterity saving throw. On a failed save, the spell ends, causing the bead to explode. On a successful save, the creature can throw the bead up to 40 feet. If the thrown bead enters a creature's space or collides with a solid object, the spell ends, and the bead explodes."},{"type":"text","content":"When the bead explodes, flammable objects in the explosion that aren't being worn or carried start burning."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The base damage increases by 12d6 for each spell slot level above 7."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":261},{"name":"Demiplane","source":"XPHB","level":8,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You create a shadowy Medium door on a flat solid surface that you can see within range. This door can be opened and closed, and it leads to a demiplane that is an empty room 30 feet in each dimension, made of wood or stone (your choice)."},{"type":"text","content":"When the spell ends, the door vanishes, and any objects inside the demiplane remain there. Any creatures inside also remain unless they opt to be shunted through the door as it vanishes, landing with the <i class=\\"text-dnd-gold\\">Prone</i> condition in the unoccupied spaces closest to the door's former space."},{"type":"text","content":"Each time you cast this spell, you can create a new demiplane or connect the shadowy door to a demiplane you created with a previous casting of this spell. Additionally, if you know the nature and contents of a demiplane created by a casting of this spell by another creature, you can connect the shadowy door to that demiplane instead."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":261},{"name":"Destructive Wave","source":"XPHB","level":5,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Destructive energy ripples outward from you in a 30-foot <i>Emanation [Area of Effect]</i>. Each creature you choose in the <i>Emanation [Area of Effect]</i> makes a Constitution saving throw. On a failed save, a target takes <span class=\\"text-red-400 font-semibold\\">5d6</span> Thunder damage and <span class=\\"text-red-400 font-semibold\\">5d6</span> Radiant or Necrotic damage (your choice) and has the <i class=\\"text-dnd-gold\\">Prone</i> condition. On a successful save, a target takes half as much damage only."}],"entriesHigherLevel":[],"damageInflict":["necrotic","radiant","thunder"],"conditionInflict":["prone"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":261},{"name":"Detect Evil and Good","source":"XPHB","level":1,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"sphere","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"For the duration, you sense the location of any Aberration, Celestial, Elemental, Fey, Fiend, or Undead within 30 feet of yourself. You also sense whether the <a href=\\"/spells?search=Hallow\\" class=\\"text-dnd-gold hover:underline\\">Hallow</a> spell is active there and, if so, where."},{"type":"text","content":"The spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":261},{"name":"Detect Magic","source":"XPHB","level":1,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"sphere","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"For the duration, you sense the presence of magical effects within 30 feet of yourself. If you sense such effects, you can take the <b>Magic</b> action to see a faint aura around any visible creature or object in the area that bears the magic, and if an effect was created by a spell, you learn the spell's <i>school of magic</i>."},{"type":"text","content":"The spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":262},{"name":"Detect Poison and Disease","source":"XPHB","level":1,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"sphere","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a yew leaf"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"For the duration, you sense the location of poisons, poisonous or venomous creatures, and magical contagions within 30 feet of yourself. You sense the kind of poison, creature, or contagion in each case."},{"type":"text","content":"The spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":262},{"name":"Detect Thoughts","source":"XPHB","level":2,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"1 Copper Piece"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You activate one of the effects below. Until the spell ends, you can activate either effect as a <b>Magic</b> action on your later turns."},{"type":"section","name":"Sense Thoughts","entries":[{"type":"text","content":"You sense the presence of thoughts within 30 feet of yourself that belong to creatures that know languages or are telepathic. You don't read the thoughts, but you know that a thinking creature is present."},{"type":"text","content":"The spell is blocked by 1 foot of stone, dirt, or wood; 1 inch of metal; or a thin sheet of lead."}]},{"type":"section","name":"Read Thoughts","entries":[{"type":"text","content":"Target one creature you can see within 30 feet of yourself or one creature within 30 feet of yourself that you detected with the Sense Thoughts option. You learn what is most on the target's mind right now. If the target doesn't know any languages and isn't telepathic, you learn nothing."},{"type":"text","content":"As a <b>Magic</b> action on your next turn, you can try to probe deeper into the target's mind. If you probe deeper, the target makes a Wisdom saving throw. On a failed save, you discern the target's reasoning, emotions, and something that looms large in its mind (such as a worry, love, or hate). On a successful save, the spell ends. Either way, the target knows that you are probing into its mind, and until you shift your attention away from the target's mind, the target can take an action on its turn to make an Intelligence (<i>Arcana</i>) check against your spell save DC, ending the spell on a success."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":262},{"name":"Dimension Door","source":"XPHB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":500}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You teleport to a location within range. You arrive at exactly the spot desired. It can be a place you can see, one you can visualize, or one you can describe by stating distance and direction, such as \\"200 feet straight downward\\" or \\"300 feet upward to the northwest at a 45-degree angle.\\""},{"type":"text","content":"You can also teleport one willing creature. The creature must be within 5 feet of you when you teleport, and it teleports to a space within 5 feet of your destination space."},{"type":"text","content":"If you, the other creature, or both would arrive in a space occupied by a creature or completely filled by one or more objects, you and any creature traveling with you each take <span class=\\"text-red-400 font-semibold\\">4d6</span> Force damage, and the teleportation fails."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":262},{"name":"Disguise Self","source":"XPHB","level":1,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You make yourself—including your clothing, armor, weapons, and other belongings on your person—look different until the spell ends. You can seem 1 foot shorter or taller and can appear heavier or lighter. You must adopt a form that has the same basic arrangement of limbs as you have. Otherwise, the extent of the illusion is up to you."},{"type":"text","content":"The changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to your outfit, objects pass through the hat, and anyone who touches it would feel nothing."},{"type":"text","content":"To discern that you are disguised, a creature must take the <b>Study</b> action to inspect your appearance and succeed on an Intelligence (<i>Investigation</i>) check against your spell save DC."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":262},{"name":"Disintegrate","source":"XPHB","level":6,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a lodestone and dust"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You launch a green ray at a target you can see within range. The target can be a creature, a nonmagical object, or a creation of magical force, such as the wall created by <a href=\\"/spells?search=Wall of Force\\" class=\\"text-dnd-gold hover:underline\\">Wall of Force</a>."},{"type":"text","content":"A creature targeted by this spell makes a Dexterity saving throw. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">10d6 + 40</span> Force damage. If this damage reduces it to 0 <i>Hit Points</i>, it and everything nonmagical it is wearing and carrying are disintegrated into gray dust. The target can be revived only by a <a href=\\"/spells?search=True Resurrection\\" class=\\"text-dnd-gold hover:underline\\">True Resurrection</a> or a <a href=\\"/spells?search=Wish\\" class=\\"text-dnd-gold hover:underline\\">Wish</a> spell."},{"type":"text","content":"This spell automatically disintegrates a Large or smaller nonmagical object or a creation of magical force. If such a target is Huge or larger, this spell disintegrates a 10-foot-<i>Cube [Area of Effect]</i> portion of it."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 10d6 + 40 for each spell slot level above 6."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":263},{"name":"Dispel Evil and Good","source":"XPHB","level":5,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"powdered silver and iron"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"For the duration, Celestials, Elementals, Fey, Fiends, and Undead have <i>Disadvantage</i> on attack rolls against you. You can end the spell early by using either of the following special functions."},{"type":"section","name":"Break Enchantment","entries":[{"type":"text","content":"As a <b>Magic</b> action, you touch a creature that is possessed by or has the <i class=\\"text-dnd-gold\\">Charmed</i> or <i class=\\"text-dnd-gold\\">Frightened</i> condition from one or more creatures of the types above. The target is no longer possessed, <i class=\\"text-dnd-gold\\">Charmed</i>, or <i class=\\"text-dnd-gold\\">Frightened</i> by such creatures."}]},{"type":"section","name":"Dismissal","entries":[{"type":"text","content":"As a <b>Magic</b> action, you target one creature you can see within 5 feet of you that has one of the creature types above. The target must succeed on a Charisma saving throw or be sent back to its home plane if it isn't there already. If they aren't on their home plane, Undead are sent to the Shadowfell, and Fey are sent to the Feywild."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["charisma"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":263},{"name":"Dispel Magic","source":"XPHB","level":3,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Choose one creature, object, or magical effect within range. Any ongoing spell of level 3 or lower on the target ends. For each ongoing spell of level 4 or higher on the target, make an ability check using your spellcasting ability (DC 10 plus that spell's level). On a successful check, the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You automatically end a spell on the target if the spell's level is equal to or less than the level of the spell slot you use."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":264},{"name":"Dissonant Whispers","source":"XPHB","level":1,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"One creature of your choice that you can see within range hears a discordant melody in its mind. The target makes a Wisdom saving throw. On a failed save, it takes <span class=\\"text-red-400 font-semibold\\">3d6</span> Psychic damage and must immediately use its <i>Reaction</i>, if available, to move as far away from you as it can, using the safest route. On a successful save, the target takes half as much damage only."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d6 for each spell slot level above 1."}]}],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":264},{"name":"Divination","source":"XPHB","level":4,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"incense worth 25+ GP, which the spell consumes","cost":2500,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"This spell puts you in contact with a god or a god's servants. You ask one question about a specific goal, event, or activity to occur within 7 days. The DM offers a truthful reply, which might be a short phrase or cryptic rhyme. The spell doesn't account for circumstances that might change the answer, such as the casting of other spells."},{"type":"text","content":"If you cast the spell more than once before finishing a <i>Long Rest</i>, there is a cumulative 25% chance for each casting after the first that you get no answer."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":264},{"name":"Divine Favor","source":"XPHB","level":1,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"Until the spell ends, your attacks with weapons deal an extra <span class=\\"text-red-400 font-semibold\\">1d4</span> Radiant damage on a hit."}],"entriesHigherLevel":[],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":265},{"name":"Divine Word","source":"XPHB","level":7,"school":"V","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You utter a word imbued with power from the Upper Planes. Each creature of your choice in range makes a Charisma saving throw. On a failed save, a target that has 50 <i>Hit Points</i> or fewer suffers an effect based on its current <i>Hit Points</i>, as shown in the Divine Word Effects table. Regardless of its <i>Hit Points</i>, a Celestial, an Elemental, a Fey, or a Fiend target that fails its save is forced back to its plane of origin (if it isn't there already) and can't return to the current plane for 24 hours by any means short of a <a href=\\"/spells?search=Wish\\" class=\\"text-dnd-gold hover:underline\\">Wish</a> spell."},{"type":"table","caption":"Divine Word Effects","colLabels":["Hit Points","Effect"],"rows":[["0-20","The target dies."],["21-30","The target has the <i class=\\"text-dnd-gold\\">Blinded</i>, <i class=\\"text-dnd-gold\\">Deafened</i>, and <i class=\\"text-dnd-gold\\">Stunned</i> conditions for 1 hour."],["31-40","The target has the <i class=\\"text-dnd-gold\\">Blinded</i> and <i class=\\"text-dnd-gold\\">Deafened</i> conditions for 10 minutes."],["41-50","The target has the <i class=\\"text-dnd-gold\\">Deafened</i> condition for 1 minute."]]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["blinded","deafened","stunned"],"savingThrow":["charisma"],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":265},{"name":"Dominate Beast","source":"XPHB","level":4,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"One Beast you can see within range must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration. The target has <i>Advantage</i> on the save if you or your allies are fighting it. Whenever the target takes damage, it repeats the save, ending the spell on itself on a success."},{"type":"text","content":"You have a telepathic link with the <i class=\\"text-dnd-gold\\">Charmed</i> target while the two of you are on the same plane of existence. On your turn, you can use this link to issue commands to the target (no action required), such as \\"<b>Attack</b> that creature,\\" \\"Move over there,\\" or \\"Fetch that object.\\" The target does its best to obey on its turn. If it completes an order and doesn't receive further direction from you, it acts and moves as it likes, focusing on protecting itself."},{"type":"text","content":"You can command the target to take a <i>Reaction</i> but must take your own <i>Reaction</i> to do so."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Your <i>Concentration</i> can last longer with a spell slot of level 5 (up to 10 minutes), 6 (up to 1 hour), or 7+ (up to 8 hours)."}]}],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":265},{"name":"Dominate Monster","source":"XPHB","level":8,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"One creature you can see within range must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration. The target has <i>Advantage</i> on the save if you or your allies are fighting it. Whenever the target takes damage, it repeats the save, ending the spell on itself on a success."},{"type":"text","content":"You have a telepathic link with the <i class=\\"text-dnd-gold\\">Charmed</i> target while the two of you are on the same plane of existence. On your turn, you can use this link to issue commands to the target (no action required), such as \\"<b>Attack</b> that creature,\\" \\"Move over there,\\" or \\"Fetch that object.\\" The target does its best to obey on its turn. If it completes an order and doesn't receive further direction from you, it acts and moves as it likes, focusing on protecting itself."},{"type":"text","content":"You can command the target to take a <i>Reaction</i> but must take your own <i>Reaction</i> to do so."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Your <i>Concentration</i> can last longer with a level 9 spell slot (up to 8 hours)."}]}],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":265},{"name":"Dominate Person","source":"XPHB","level":5,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"One Humanoid you can see within range must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration. The target has <i>Advantage</i> on the save if you or your allies are fighting it. Whenever the target takes damage, it repeats the save, ending the spell on itself on a success."},{"type":"text","content":"You have a telepathic link with the <i class=\\"text-dnd-gold\\">Charmed</i> target while the two of you are on the same plane of existence. On your turn, you can use this link to issue commands to the target (no action required), such as \\"<b>Attack</b> that creature,\\" \\"Move over there,\\" or \\"Fetch that object.\\" The target does its best to obey on its turn. If it completes an order and doesn't receive further direction from you, it acts and moves as it likes, focusing on protecting itself."},{"type":"text","content":"You can command the target to take a <i>Reaction</i> but must take your own <i>Reaction</i> to do so."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Your <i>Concentration</i> can last longer with a spell slot of level 6 (up to 10 minutes), 7 (up to 1 hour), or 8+ (up to 8 hours)."}]}],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":266},{"name":"Drawmij's Instant Summons","source":"XPHB","level":6,"school":"C","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a sapphire worth 1,000+ GP","cost":100000}},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"You touch the sapphire used in the casting and an object weighing 10 pounds or less whose longest dimension is 6 feet or less. The spell leaves an <i class=\\"text-dnd-gold\\">Invisible</i> mark on that object and invisibly inscribes the object's name on the sapphire. Each time you cast this spell, you must use a different sapphire."},{"type":"text","content":"Thereafter, you can take a <b>Magic</b> action to speak the object's name and crush the sapphire. The object instantly appears in your hand regardless of physical or planar distances, and the spell ends."},{"type":"text","content":"If another creature is holding or carrying the object, crushing the sapphire doesn't transport it, but instead you learn who that creature is and where that creature is currently located."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":266},{"name":"Dream","source":"XPHB","level":5,"school":"I","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a handful of sand"},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You target a creature you know on the same plane of existence. You or a willing creature you touch enters a trance state to act as a dream messenger. While in the trance, the messenger is <i class=\\"text-dnd-gold\\">Incapacitated</i> and has a <i>Speed</i> of 0."},{"type":"text","content":"If the target is asleep, the messenger appears in the target's dreams and can converse with the target as long as it remains asleep, through the spell's duration. The messenger can also shape the dream's environment, creating landscapes, objects, and other images. The messenger can emerge from the trance at any time, ending the spell. The target recalls the dream perfectly upon waking."},{"type":"text","content":"If the target is awake when you cast the spell, the messenger knows it and can either end the trance (and the spell) or wait for the target to sleep, at which point the messenger enters its dreams."},{"type":"text","content":"You can make the messenger terrifying to the target. If you do so, the messenger can deliver a message of no more than ten words, and then the target makes a Wisdom saving throw. On a failed save, the target gains no benefit from its rest, and it takes <span class=\\"text-red-400 font-semibold\\">3d6</span> Psychic damage when it wakes up."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":266},{"name":"Druidcraft","source":"XPHB","level":0,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Whispering to the spirits of nature, you create one of the following effects within range."},{"type":"section","name":"Weather Sensor","entries":[{"type":"text","content":"You create a Tiny, harmless sensory effect that predicts what the weather will be at your location for the next 24 hours. The effect might manifest as a golden orb for clear skies, a cloud for rain, falling snowflakes for snow, and so on. This effect persists for 1 round."}]},{"type":"section","name":"Bloom","entries":[{"type":"text","content":"You instantly make a flower blossom, a seed pod open, or a leaf bud bloom."}]},{"type":"section","name":"Sensory Effect","entries":[{"type":"text","content":"You create a harmless sensory effect, such as falling leaves, spectral dancing fairies, a gentle breeze, the sound of an animal, or the faint odor of skunk. The effect must fit in a 5-foot <i>Cube [Area of Effect]</i>."}]},{"type":"section","name":"Fire Play","entries":[{"type":"text","content":"You light or snuff out a candle, a torch, or a campfire."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":266},{"name":"Earthquake","source":"XPHB","level":8,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":500}},"components":{"v":true,"s":true,"m":"a fractured rock"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Choose a point on the ground that you can see within range. For the duration, an intense tremor rips through the ground in a 100-foot-radius circle centered on that point. The ground there is <i>Difficult Terrain</i>."},{"type":"text","content":"When you cast this spell and at the end of each of your turns for the duration, each creature on the ground in the area makes a Dexterity saving throw. On a failed save, a creature has the <i class=\\"text-dnd-gold\\">Prone</i> condition, and its <i>Concentration</i> is broken."},{"type":"text","content":"You can also cause the effects below."},{"type":"section","name":"Fissures","entries":[{"type":"text","content":"A total of <span class=\\"text-green-400 font-mono\\">1d6</span> fissures open in the spell's area at the end of the turn you cast it. You choose the fissures' locations, which can't be under structures. Each fissure is <span class=\\"text-green-400 font-mono\\">1d10 × 10</span> feet deep and 10 feet wide, and it extends from one edge of the spell's area to another edge. A creature in the same space as a fissure must succeed on a Dexterity saving throw or fall in. A creature that successfully saves moves with the fissure's edge as it opens."}]},{"type":"section","name":"Structures","entries":[{"type":"text","content":"The tremor deals 50 Bludgeoning damage to any structure in contact with the ground in the area when you cast the spell and at the end of each of your turns until the spell ends. If a structure drops to 0 <i>Hit Points</i>, it collapses."},{"type":"text","content":"A creature within a distance from a collapsing structure equal to half the structure's height makes a Dexterity saving throw. On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">12d6</span> Bludgeoning damage, has the <i class=\\"text-dnd-gold\\">Prone</i> condition, and is buried in the rubble, requiring a DC 20 Strength (<i>Athletics</i>) check as an action to escape. On a successful save, the creature takes half as much damage only."}]}],"entriesHigherLevel":[],"damageInflict":["bludgeoning"],"conditionInflict":["prone"],"savingThrow":["constitution","dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":267},{"name":"Eldritch Blast","source":"XPHB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You hurl a beam of crackling energy. Make a ranged spell attack against one creature or object in range. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">1d10</span> Force damage."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The spell creates two beams at level 5, three beams at level 11, and four beams at level 17. You can direct the beams at the same target or at different ones. Make a separate attack roll for each beam."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":267},{"name":"Elemental Weapon","source":"XPHB","level":3,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A nonmagical weapon you touch becomes a magic weapon. Choose one of the following damage types: Acid, Cold, Fire, Lightning, or Thunder. For the duration, the weapon has a +1 bonus to attack rolls and deals an extra <span class=\\"text-red-400 font-semibold\\">1d4</span> damage of the chosen type when it hits."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"If you use a level 5-6 spell slot, the bonus to attack rolls increases to +2, and the extra damage increases to <span class=\\"text-red-400 font-semibold\\">2d4</span>. If you use a level 7+ spell slot, the bonus increases to +3, and the extra damage increases to <span class=\\"text-red-400 font-semibold\\">3d4</span>."}]}],"damageInflict":["acid","cold","fire","lightning","thunder"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":267},{"name":"Enhance Ability","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"fur or a feather"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You touch a creature and choose Strength, Dexterity, Intelligence, Wisdom, or Charisma. For the duration, the target has <i>Advantage</i> on ability checks using the chosen ability."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 2. You can choose a different ability for each target."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":268},{"name":"Enlarge/Reduce","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a pinch of powdered iron"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"For the duration, the spell enlarges or reduces a creature or an object you can see within range (see the chosen effect below). A targeted object must be neither worn nor carried. If the target is an unwilling creature, it can make a Constitution saving throw. On a successful save, the spell has no effect."},{"type":"text","content":"Everything that a targeted creature is wearing and carrying changes size with it. Any item it drops returns to normal size at once. A thrown weapon or piece of ammunition returns to normal size immediately after it hits or misses a target."},{"type":"section","name":"Enlarge","entries":[{"type":"text","content":"The target's size increases by one category—from Medium to Large, for example. The target also has <i>Advantage</i> on Strength checks and Strength saving throws. The target's attacks with its enlarged weapons or Unarmed Strikes deal an extra <span class=\\"text-red-400 font-semibold\\">1d4</span> damage on a hit."}]},{"type":"section","name":"Reduce","entries":[{"type":"text","content":"The target's size decreases by one category—from Medium to Small, for example. The target also has <i>Disadvantage</i> on Strength checks and Strength saving throws. The target's attacks with its reduced weapons or Unarmed Strikes deal <span class=\\"text-red-400 font-semibold\\">1d4</span> less damage on a hit (this can't reduce the damage below 1)."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":268},{"name":"Ensnaring Strike","source":"XPHB","level":1,"school":"C","time":[{"number":1,"unit":"bonus","condition":"which you take immediately after hitting a creature with a weapon"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"As you hit the target, grasping vines appear on it, and it makes a Strength saving throw. A Large or larger creature has <i>Advantage</i> on this save. On a failed save, the target has the <i class=\\"text-dnd-gold\\">Restrained</i> condition until the spell ends. On a successful save, the vines shrivel away, and the spell ends."},{"type":"text","content":"While <i class=\\"text-dnd-gold\\">Restrained</i>, the target takes <span class=\\"text-red-400 font-semibold\\">1d6</span> Piercing damage at the start of each of its turns. The target or a creature within reach of it can take an action to make a Strength (<i>Athletics</i>) check against your spell save DC. On a success, the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 1d6 for each spell slot level above 1."}]}],"damageInflict":["piercing"],"conditionInflict":["restrained"],"savingThrow":["strength"],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":268},{"name":"Entangle","source":"XPHB","level":1,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Grasping plants sprout from the ground in a 20-foot square within range. For the duration, these plants turn the ground in the area into <i>Difficult Terrain</i>. They disappear when the spell ends."},{"type":"text","content":"Each creature (other than you) in the area when you cast the spell must succeed on a Strength saving throw or have the <i class=\\"text-dnd-gold\\">Restrained</i> condition until the spell ends. A <i class=\\"text-dnd-gold\\">Restrained</i> creature can take an action to make a Strength (<i>Athletics</i>) check against your spell save DC. On a success, it frees itself from the grasping plants and is no longer <i class=\\"text-dnd-gold\\">Restrained</i> by them."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["restrained"],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":268},{"name":"Enthrall","source":"XPHB","level":2,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You weave a distracting string of words, causing creatures of your choice that you can see within range to make a Wisdom saving throw. Any creature you or your companions are fighting automatically succeeds on this save. On a failed save, a target has a -10 penalty to Wisdom (<i>Perception</i>) checks and Passive <i>Perception</i> until the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":269},{"name":"Etherealness","source":"XPHB","level":7,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You step into the border regions of the Ethereal Plane, where it overlaps with your current plane. You remain in the Border Ethereal for the duration. During this time, you can move in any direction. If you move up or down, every foot of movement costs an extra foot. You can perceive the plane you left, which looks gray, and you can't see anything there more than 60 feet away."},{"type":"text","content":"While on the Ethereal Plane, you can affect and be affected only by creatures, objects, and effects on that plane. Creatures that aren't on the Ethereal Plane can't perceive or interact with you unless a feature gives them the ability to do so."},{"type":"text","content":"When the spell ends, you return to the plane you left in the spot that corresponds to your space in the Border Ethereal. If you appear in an occupied space, you are shunted to the nearest unoccupied space and take Force damage equal to twice the number of feet you are moved."},{"type":"text","content":"This spell ends instantly if you cast it while you are on the Ethereal Plane or a plane that doesn't border it, such as one of the Outer Planes."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target up to three willing creatures (including yourself) for each spell slot level above 7. The creatures must be within 10 feet of you when you cast the spell."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":269},{"name":"Evard's Black Tentacles","source":"XPHB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":"a tentacle"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Squirming, ebony tentacles fill a 20-foot square on ground that you can see within range. For the duration, these tentacles turn the ground in that area into <i>Difficult Terrain</i>."},{"type":"text","content":"Each creature in that area makes a Strength saving throw. On a failed save, it takes <span class=\\"text-red-400 font-semibold\\">3d6</span> Bludgeoning damage, and it has the <i class=\\"text-dnd-gold\\">Restrained</i> condition until the spell ends. A creature also makes that save if it enters the area or ends its turn there. A creature makes that save only once per turn."},{"type":"text","content":"A <i class=\\"text-dnd-gold\\">Restrained</i> creature can take an action to make a Strength (<i>Athletics</i>) check against your spell save DC, ending the condition on itself on a success."}],"entriesHigherLevel":[],"damageInflict":["bludgeoning"],"conditionInflict":["restrained"],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":270},{"name":"Expeditious Retreat","source":"XPHB","level":1,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You take the <b>Dash</b> action, and until the spell ends, you can take that action again as a <i>Bonus Action</i>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":270},{"name":"Eyebite","source":"XPHB","level":6,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"For the duration, your eyes become an inky void. One creature of your choice within 60 feet of you that you can see must succeed on a Wisdom saving throw or be affected by one of the following effects of your choice for the duration."},{"type":"text","content":"On each of your turns until the spell ends, you can take a <b>Magic</b> action to target another creature but can't target a creature again if it has succeeded on a save against this casting of the spell."},{"type":"section","name":"Asleep","entries":[{"type":"text","content":"The target has the <i class=\\"text-dnd-gold\\">Unconscious</i> condition. It wakes up if it takes any damage or if another creature takes an action to shake it awake."}]},{"type":"section","name":"Panicked","entries":[{"type":"text","content":"The target has the <i class=\\"text-dnd-gold\\">Frightened</i> condition. On each of its turns, the <i class=\\"text-dnd-gold\\">Frightened</i> target must take the <b>Dash</b> action and move away from you by the safest and shortest route available. If the target moves to a space at least 60 feet away from you where it can't see you, this effect ends."}]},{"type":"section","name":"Sickened","entries":[{"type":"text","content":"The target has the <i class=\\"text-dnd-gold\\">Poisoned</i> condition."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["frightened","unconscious"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":270},{"name":"Fabricate","source":"XPHB","level":4,"school":"T","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You convert raw materials into products of the same material. For example, you can fabricate a wooden bridge from a clump of trees, a rope from a patch of hemp, or clothes from flax or wool."},{"type":"text","content":"Choose raw materials that you can see within range. You can fabricate a Large or smaller object (contained within a 10-foot <i>Cube [Area of Effect]</i> or eight connected 5-foot Cubes) given a sufficient quantity of material. If you're working with metal, stone, or another mineral substance, however, the fabricated object can be no larger than Medium (contained within a 5-foot <i>Cube [Area of Effect]</i>). The quality of any fabricated objects is based on the quality of the raw materials."},{"type":"text","content":"Creatures and magic items can't be created by this spell. You also can't use it to create items that require a high degree of skill—such as weapons and armor—unless you have proficiency with the type of <b>Artisan's Tools</b> used to craft such objects."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":271},{"name":"Faerie Fire","source":"XPHB","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Objects in a 20-foot <i>Cube [Area of Effect]</i> within range are outlined in blue, green, or violet light (your choice). Each creature in the <i>Cube [Area of Effect]</i> is also outlined if it fails a Dexterity saving throw. For the duration, objects and affected creatures shed <i>Dim Light</i> in a 10-foot radius and can't benefit from the <i class=\\"text-dnd-gold\\">Invisible</i> condition."},{"type":"text","content":"<b>Attack</b> rolls against an affected creature or object have <i>Advantage</i> if the attacker can see it."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":271},{"name":"False Life","source":"XPHB","level":1,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a drop of alcohol"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You gain <span class=\\"text-green-400 font-mono\\">2d4 + 4</span> <i>Temporary Hit Points</i>."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You gain 5 additional <i>Temporary Hit Points</i> for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":271},{"name":"Fear","source":"XPHB","level":3,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"cone","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a white feather"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Each creature in a 30-foot <i>Cone [Area of Effect]</i> must succeed on a Wisdom saving throw or drop whatever it is holding and have the <i class=\\"text-dnd-gold\\">Frightened</i> condition for the duration."},{"type":"text","content":"A <i class=\\"text-dnd-gold\\">Frightened</i> creature takes the <b>Dash</b> action and moves away from you by the safest route on each of its turns unless there is nowhere to move. If the creature ends its turn in a space where it doesn't have line of sight to you, the creature makes a Wisdom saving throw. On a successful save, the spell ends on that creature."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["frightened"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":271},{"name":"Feather Fall","source":"XPHB","level":1,"school":"T","time":[{"number":1,"unit":"reaction","condition":"which you take when you or a creature you can see within 60 feet of you falls"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"m":"a small feather or piece of down"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"Choose up to five falling creatures within range. A falling creature's rate of descent slows to 60 feet per round until the spell ends. If a creature lands before the spell ends, the creature takes no damage from the fall, and the spell ends for that creature."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"reaction","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":271},{"name":"Feeblemind","source":"PHB","level":8,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":"a handful of clay, crystal, glass, or mineral spheres"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You blast the mind of a creature that you can see within range, attempting to shatter its intellect and personality. The target takes <span class=\\"text-red-400 font-semibold\\">4d6</span> psychic damage and must make an Intelligence saving throw."},{"type":"text","content":"On a failed save, the creature's Intelligence and Charisma scores become 1. The creature can't cast spells, activate magic items, understand language, or communicate in any intelligible way. The creature can, however, identify its friends, follow them, and even protect them."},{"type":"text","content":"At the end of every 30 days, the creature can repeat its saving throw against this spell. If it succeeds on its saving throw, the spell ends."},{"type":"text","content":"The spell can also be ended by <a href=\\"/spells?search=greater restoration\\" class=\\"text-dnd-gold hover:underline\\">greater restoration</a>, <a href=\\"/spells?search=heal\\" class=\\"text-dnd-gold hover:underline\\">heal</a>, or <a href=\\"/spells?search=wish\\" class=\\"text-dnd-gold hover:underline\\">wish</a>."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":false,"srd":true,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":["Befuddlement|XPHB"],"page":239},{"name":"Feign Death","source":"XPHB","level":3,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a pinch of graveyard dirt"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You touch a willing creature and put it into a cataleptic state that is indistinguishable from death."},{"type":"text","content":"For the duration, the target appears dead to outward inspection and to spells used to determine the target's status. The target has the <i class=\\"text-dnd-gold\\">Blinded</i> and <i class=\\"text-dnd-gold\\">Incapacitated</i> conditions, and its <i>Speed</i> is 0."},{"type":"text","content":"The target also has <i>Resistance</i> to all damage except Psychic damage, and it has <i>Immunity</i> to the <i class=\\"text-dnd-gold\\">Poisoned</i> condition."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["blinded","incapacitated"],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":271},{"name":"Find Familiar","source":"XPHB","level":1,"school":"C","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":{"text":"burning incense worth 10+ GP, which the spell consumes","cost":1000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You gain the service of a familiar, a spirit that takes an animal form you choose: <b>Bat</b>, <b>Cat</b>, <b>Frog</b>, <b>Hawk</b>, <b>Lizard</b>, <b>Octopus</b>, <b>Owl</b>, <b>Rat</b>, <b>Raven</b>, <b>Spider</b>, <b>Weasel</b>, or another Beast that has a <i>Challenge Rating of 0</i>. Appearing in an unoccupied space within range, the familiar has the statistics of the chosen form, though it is a Celestial, Fey, or Fiend (your choice) instead of a Beast. Your familiar acts independently of you, but it obeys your commands."},{"type":"section","name":"Telepathic Connection","entries":[{"type":"text","content":"While your familiar is within 100 feet of you, you can communicate with it telepathically. Additionally, as a <i>Bonus Action</i>, you can see through the familiar's eyes and hear what it hears until the start of your next turn, gaining the benefits of any special senses it has."},{"type":"text","content":"Finally, when you cast a spell with a range of touch, your familiar can deliver the touch. Your familiar must be within 100 feet of you, and it must take a <i>Reaction</i> to deliver the touch when you cast the spell."}]},{"type":"section","name":"Combat","entries":[{"type":"text","content":"The familiar is an ally to you and your allies. It rolls its own <i>Initiative</i> and acts on its own turn. A familiar can't attack, but it can take other actions as normal."}]},{"type":"section","name":"Disappearance of the Familiar","entries":[{"type":"text","content":"When the familiar drops to 0 <i>Hit Points</i>, it disappears. It reappears after you cast this spell again. As a <b>Magic</b> action, you can temporarily dismiss the familiar to a pocket dimension. Alternatively, you can dismiss it forever. As a <b>Magic</b> action while it is temporarily dismissed, you can cause it to reappear in an unoccupied space within 30 feet of you. Whenever the familiar drops to 0 <i>Hit Points</i> or disappears into the pocket dimension, it leaves behind in its space anything it was wearing or carrying."}]},{"type":"section","name":"One Familiar Only","entries":[{"type":"text","content":"You can't have more than one familiar at a time. If you cast this spell while you have a familiar, you instead cause it to adopt a new eligible form."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":272},{"name":"Find Steed","source":"XPHB","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You summon an otherworldly being that appears as a loyal steed in an unoccupied space of your choice within range. This creature uses the <b>Otherworldly Steed</b> stat block. If you already have a steed from this spell, the steed is replaced by the new one."},{"type":"text","content":"The steed resembles a Large, rideable animal of your choice, such as a horse, a camel, a dire wolf, or an elk. Whenever you cast the spell, choose the steed's creature type—Celestial, Fey, or Fiend—which determines certain traits in the stat block."},{"type":"section","name":"Combat","entries":[{"type":"text","content":"The steed is an ally to you and your allies. In combat, it shares your <i>Initiative</i> count, and it functions as a controlled mount while you ride it (as defined in the rules on <i>mounted combat</i>). If you have the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition, the steed takes its turn immediately after yours and acts independently, focusing on protecting you."}]},{"type":"section","name":"Disappearance of the Steed","entries":[{"type":"text","content":"The steed disappears if it drops to 0 <i>Hit Points</i> or if you die. When it disappears, it leaves behind anything it was wearing or carrying. If you cast this spell again, you decide whether you summon the steed that disappeared or a different one."}]}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":272},{"name":"Find the Path","source":"XPHB","level":6,"school":"D","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"a set of divination tools—such as cards or runes—worth 100+ GP","cost":10000}},"duration":[{"type":"timed","duration":{"type":"day","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You magically sense the most direct physical route to a location you name. You must be familiar with the location, and the spell fails if you name a destination on another plane of existence, a moving destination (such as a mobile fortress), or an unspecific destination (such as \\"a green dragon's lair\\")."},{"type":"text","content":"For the duration, as long as you are on the same plane of existence as the destination, you know how far it is and in what direction it lies. Whenever you face a choice of paths along the way there, you know which path is the most direct."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":273},{"name":"Find Traps","source":"XPHB","level":2,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You sense any trap within range that is within line of sight. A trap, for the purpose of this spell, includes any object or mechanism that was created to cause damage or other danger. Thus, the spell would sense the <a href=\\"/spells?search=Alarm\\" class=\\"text-dnd-gold hover:underline\\">Alarm</a> or <a href=\\"/spells?search=Glyph of Warding\\" class=\\"text-dnd-gold hover:underline\\">Glyph of Warding</a> spell or a mechanical pit trap, but it wouldn't reveal a natural weakness in the floor, an unstable ceiling, or a hidden sinkhole."},{"type":"text","content":"This spell reveals that a trap is present but not its location. You do learn the general nature of the danger posed by a trap you sense."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":273},{"name":"Finger of Death","source":"XPHB","level":7,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You unleash negative energy toward a creature you can see within range. The target makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">7d8 + 30</span> Necrotic damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"A Humanoid killed by this spell rises at the start of your next turn as a <b>Zombie</b> that follows your verbal orders."}],"entriesHigherLevel":[],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":273},{"name":"Fire Bolt","source":"XPHB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You hurl a mote of fire at a creature or an object within range. Make a ranged spell attack against the target. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">1d10</span> Fire damage. A flammable object hit by this spell starts burning if it isn't being worn or carried."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d10</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d10</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d10</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d10</span>)."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":274},{"name":"Fire Shield","source":"XPHB","level":4,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a bit of phosphorus or a firefly"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10}}],"entries":[{"type":"text","content":"Wispy flames wreathe your body for the duration, shedding <i>Bright Light</i> in a 10-foot radius and <i>Dim Light</i> for an additional 10 feet."},{"type":"text","content":"The flames provide you with a warm shield or a chill shield, as you choose. The warm shield grants you <i>Resistance</i> to Cold damage, and the chill shield grants you <i>Resistance</i> to Fire damage."},{"type":"text","content":"In addition, whenever a creature within 5 feet of you hits you with a melee attack roll, the shield erupts with flame. The attacker takes <span class=\\"text-red-400 font-semibold\\">2d8</span> Fire damage from a warm shield or <span class=\\"text-red-400 font-semibold\\">2d8</span> Cold damage from a chill shield."}],"entriesHigherLevel":[],"damageInflict":["cold","fire"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":274},{"name":"Fire Storm","source":"XPHB","level":7,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A storm of fire appears within range. The area of the storm consists of up to ten 10-foot Cubes, which you arrange as you like. Each <i>Cube [Area of Effect]</i> must be contiguous with at least one other <i>Cube [Area of Effect]</i>. Each creature in the area makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">7d10</span> Fire damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"Flammable objects in the area that aren't being worn or carried start burning."}],"entriesHigherLevel":[],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":275},{"name":"Fireball","source":"XPHB","level":3,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":"a ball of bat guano and sulfur"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A bright streak flashes from you to a point you choose within range and then blossoms with a low roar into a fiery explosion. Each creature in a 20-foot-radius <i>Sphere [Area of Effect]</i> centered on that point makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">8d6</span> Fire damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"Flammable objects in the area that aren't being worn or carried start burning."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 8d6 for each spell slot level above 3."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":274},{"name":"Flame Blade","source":"XPHB","level":2,"school":"V","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a sumac leaf"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You evoke a fiery blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke it again as a <i>Bonus Action</i>."},{"type":"text","content":"As a <b>Magic</b> action, you can make a melee spell attack with the fiery blade. On a hit, the target takes Fire damage equal to <span class=\\"text-red-400 font-semibold\\">3d6</span> plus your spellcasting ability modifier."},{"type":"text","content":"The flaming blade sheds <i>Bright Light</i> in a 10-foot radius and <i>Dim Light</i> for an additional 10 feet."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d6 for each spell slot level above 2."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":275},{"name":"Flame Strike","source":"XPHB","level":5,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a pinch of sulfur"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A vertical column of brilliant fire roars down from above. Each creature in a 10-foot-radius, 40-foot-high <i>Cylinder [Area of Effect]</i> centered on a point within range makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">5d6</span> Fire damage and <span class=\\"text-red-400 font-semibold\\">5d6</span> Radiant damage on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The Fire damage and the Radiant damage increase by 5d6 for each spell slot level above 5."}]}],"damageInflict":["fire","radiant"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":275},{"name":"Flaming Sphere","source":"XPHB","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a ball of wax"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a 5-foot-diameter sphere of fire in an unoccupied space on the ground within range. It lasts for the duration. Any creature that ends its turn within 5 feet of the sphere makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">2d6</span> Fire damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"As a <i>Bonus Action</i>, you can move the sphere up to 30 feet, rolling it along the ground. If you move the sphere into a creature's space, that creature makes the save against the sphere, and the sphere stops moving for the turn."},{"type":"text","content":"When you move the sphere, you can direct it over barriers up to 5 feet tall and jump it across pits up to 10 feet wide. Flammable objects that aren't being worn or carried start burning if touched by the sphere, and it sheds <i>Bright Light</i> in a 20-foot radius and <i>Dim Light</i> for an additional 20 feet."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d6 for each spell slot level above 2."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":275},{"name":"Flesh to Stone","source":"XPHB","level":6,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a cockatrice feather"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You attempt to turn one creature that you can see within range into stone. The target makes a Constitution saving throw. On a failed save, it has the <i class=\\"text-dnd-gold\\">Restrained</i> condition for the duration. On a successful save, its <i>Speed</i> is 0 until the start of your next turn. Constructs automatically succeed on the save."},{"type":"text","content":"A <i class=\\"text-dnd-gold\\">Restrained</i> target makes another Constitution saving throw at the end of each of its turns. If it successfully saves against this spell three times, the spell ends. If it fails its saves three times, it is turned to stone and has the <i class=\\"text-dnd-gold\\">Petrified</i> condition for the duration. The successes and failures needn't be consecutive; keep track of both until the target collects three of a kind."},{"type":"text","content":"If you maintain your <i>Concentration</i> on this spell for the entire possible duration, the target is <i class=\\"text-dnd-gold\\">Petrified</i> until the condition is ended by <a href=\\"/spells?search=Greater Restoration\\" class=\\"text-dnd-gold hover:underline\\">Greater Restoration</a> or similar magic."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["petrified","restrained"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":275},{"name":"Fly","source":"XPHB","level":3,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a feather"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You touch a willing creature. For the duration, the target gains a <i>Fly Speed</i> of 60 feet and can hover. When the spell ends, the target falls if it is still aloft unless it can stop the fall."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 3."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":276},{"name":"Fog Cloud","source":"XPHB","level":1,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a 20-foot-radius <i>Sphere [Area of Effect]</i> of fog centered on a point within range. The <i>Sphere [Area of Effect]</i> is <i>Heavily Obscured</i>. It lasts for the duration or until a strong wind (such as one created by <a href=\\"/spells?search=Gust of Wind\\" class=\\"text-dnd-gold hover:underline\\">Gust of Wind</a>) disperses it."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The fog's radius increases by 20 feet for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":276},{"name":"Forbiddance","source":"XPHB","level":6,"school":"A","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"ruby dust worth 1,000+ GP","cost":100000}},"duration":[{"type":"timed","duration":{"type":"day","amount":1}}],"entries":[{"type":"text","content":"You create a ward against magical travel that protects up to 40,000 square feet of floor space to a height of 30 feet above the floor. For the duration, creatures can't teleport into the area or use portals, such as those created by the <a href=\\"/spells?search=Gate\\" class=\\"text-dnd-gold hover:underline\\">Gate</a> spell, to enter the area. The spell proofs the area against planar travel, and therefore prevents creatures from accessing the area by way of the Astral Plane, the Ethereal Plane, the Feywild, the Shadowfell, or the <a href=\\"/spells?search=Plane Shift\\" class=\\"text-dnd-gold hover:underline\\">Plane Shift</a> spell."},{"type":"text","content":"In addition, the spell damages types of creatures that you choose when you cast it. Choose one or more of the following: Aberrations, Celestials, Elementals, Fey, Fiends, and Undead. When a creature of a chosen type enters the spell's area for the first time on a turn or ends its turn there, the creature takes <span class=\\"text-red-400 font-semibold\\">5d10</span> Radiant or Necrotic damage (your choice when you cast this spell)."},{"type":"text","content":"You can designate a password when you cast the spell. A creature that speaks the password as it enters the area takes no damage from the spell."},{"type":"text","content":"The spell's area can't overlap with the area of another Forbiddance spell. If you cast <a href=\\"/spells?search=Forbiddance\\" class=\\"text-dnd-gold hover:underline\\">Forbiddance</a> every day for 30 days in the same location, the spell lasts until it is dispelled, and the Material components are consumed on the last casting."}],"entriesHigherLevel":[],"damageInflict":["necrotic","radiant"],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":276},{"name":"Forcecage","source":"XPHB","level":7,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":100}},"components":{"v":true,"s":true,"m":{"text":"ruby dust worth 1,500+ GP, which the spell consumes","cost":150000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"An immobile, <i class=\\"text-dnd-gold\\">Invisible</i>, <i>Cube [Area of Effect]</i>-shaped prison composed of magical force springs into existence around an area you choose within range. The prison can be a cage or a solid box, as you choose."},{"type":"text","content":"A prison in the shape of a cage can be up to 20 feet on a side and is made from 1/2-inch diameter bars spaced 1/2 inch apart. A prison in the shape of a box can be up to 10 feet on a side, creating a solid barrier that prevents any matter from passing through it and blocking any spells cast into or out from the area."},{"type":"text","content":"When you cast the spell, any creature that is completely inside the cage's area is trapped. Creatures only partially within the area, or those too large to fit inside it, are pushed away from the center of the area until they are completely outside it."},{"type":"text","content":"A creature inside the cage can't leave it by nonmagical means. If the creature tries to use teleportation or interplanar travel to leave, it must first make a Charisma saving throw. On a successful save, the creature can use that magic to exit the cage. On a failed save, the creature doesn't exit the cage and wastes the spell or effect. The cage also extends into the Ethereal Plane, blocking ethereal travel."},{"type":"text","content":"This spell can't be dispelled by <a href=\\"/spells?search=Dispel Magic\\" class=\\"text-dnd-gold hover:underline\\">Dispel Magic</a>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["charisma"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":276},{"name":"Foresight","source":"XPHB","level":9,"school":"D","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a hummingbird feather"},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You touch a willing creature and bestow a limited ability to see into the immediate future. For the duration, the target has <i>Advantage</i> on <i>D20 Test</i>, and other creatures have <i>Disadvantage</i> on attack rolls against it. The spell ends early if you cast it again."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":276},{"name":"Freedom of Movement","source":"XPHB","level":4,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a leather strap"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You touch a willing creature. For the duration, the target's movement is unaffected by <i>Difficult Terrain</i>, and spells and other magical effects can neither reduce the target's <i>Speed</i> nor cause the target to have the <i class=\\"text-dnd-gold\\">Paralyzed</i> or <i class=\\"text-dnd-gold\\">Restrained</i> conditions. The target also has a <i>Swim Speed</i> equal to its <i>Speed</i>."},{"type":"text","content":"In addition, the target can spend 5 feet of movement to automatically escape from nonmagical restraints, such as manacles or a creature imposing the <i class=\\"text-dnd-gold\\">Grappled</i> condition on it."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 4."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":277},{"name":"Friends","source":"XPHB","level":0,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"s":true,"m":"some makeup"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You magically emanate a sense of friendship toward one creature you can see within range. The target must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration. The target succeeds automatically if it isn't a Humanoid, if you're fighting it, or if you have cast this spell on it within the past 24 hours."},{"type":"text","content":"The spell ends early if the target takes damage or if you make an attack roll, deal damage, or force anyone to make a saving throw. When the spell ends, the target knows it was <i class=\\"text-dnd-gold\\">Charmed</i> by you."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":277},{"name":"Gaseous Form","source":"XPHB","level":3,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a bit of gauze"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A willing creature you touch shape-shifts, along with everything it's wearing and carrying, into a misty cloud for the duration. The spell ends on the target if it drops to 0 <i>Hit Points</i> or if it takes a <b>Magic</b> action to end the spell on itself."},{"type":"text","content":"While in this form, the target's only method of movement is a <i>Fly Speed</i> of 10 feet, and it can hover. The target can enter and occupy the space of another creature. The target has <i>Resistance</i> to Bludgeoning, Piercing, and Slashing damage; it has <i>Immunity</i> to the <i class=\\"text-dnd-gold\\">Prone</i> condition; and it has <i>Advantage</i> on Strength, Dexterity, and Constitution saving throws. The target can pass through narrow openings, but it treats liquids as though they were solid surfaces."},{"type":"text","content":"The target can't talk or manipulate objects, and any objects it was carrying or holding can't be dropped, used, or otherwise interacted with. Finally, the target can't attack or cast spells."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 3."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":277},{"name":"Gate","source":"XPHB","level":9,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"a diamond worth 5,000+ GP","cost":500000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You conjure a portal linking an unoccupied space you can see within range to a precise location on a different plane of existence. The portal is a circular opening, which you can make 5 to 20 feet in diameter. You can orient the portal in any direction you choose. The portal lasts for the duration, and the portal's destination is visible through it."},{"type":"text","content":"The portal has a front and a back on each plane where it appears. Travel through the portal is possible only by moving through its front. Anything that does so is instantly transported to the other plane, appearing in the unoccupied space nearest to the portal."},{"type":"text","content":"Deities and other planar rulers can prevent portals created by this spell from opening in their presence or anywhere within their domains."},{"type":"text","content":"When you cast this spell, you can speak the name of a specific creature (a pseudonym, title, or nickname doesn't work). If that creature is on a plane other than the one you are on, the portal opens next to the named creature and transports it to the nearest unoccupied space on your side of the portal. You gain no special power over the creature, and it is free to act as the DM deems appropriate. It might leave, attack you, or help you."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":277},{"name":"Geas","source":"XPHB","level":5,"school":"E","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"day","amount":30}}],"entries":[{"type":"text","content":"You give a verbal command to a creature that you can see within range, ordering it to carry out some service or refrain from an action or a course of activity as you decide. The target must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration. The target automatically succeeds if it can't understand your command."},{"type":"text","content":"While <i class=\\"text-dnd-gold\\">Charmed</i>, the creature takes <span class=\\"text-red-400 font-semibold\\">5d10</span> Psychic damage if it acts in a manner directly counter to your command. It takes this damage no more than once each day."},{"type":"text","content":"You can issue any command you choose, short of an activity that would result in certain death. Should you issue a suicidal command, the spell ends."},{"type":"text","content":"A <a href=\\"/spells?search=Remove Curse\\" class=\\"text-dnd-gold hover:underline\\">Remove Curse</a>, <a href=\\"/spells?search=Greater Restoration\\" class=\\"text-dnd-gold hover:underline\\">Greater Restoration</a>, or <a href=\\"/spells?search=Wish\\" class=\\"text-dnd-gold hover:underline\\">Wish</a> spell ends this spell."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"If you use a level 7 or 8 spell slot, the duration is 365 days. If you use a level 9 spell slot, the spell lasts until it is ended by one of the spells mentioned above."}]}],"damageInflict":["psychic"],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":278},{"name":"Gentle Repose","source":"XPHB","level":2,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"2 Copper Pieces, which the spell consumes","consume":true}},"duration":[{"type":"timed","duration":{"type":"day","amount":10}}],"entries":[{"type":"text","content":"You touch a corpse or other remains. For the duration, the target is protected from decay and can't become Undead."},{"type":"text","content":"The spell also effectively extends the time limit on raising the target from the dead, since days spent under the influence of this spell don't count against the time limit of spells such as <a href=\\"/spells?search=Raise Dead\\" class=\\"text-dnd-gold hover:underline\\">Raise Dead</a>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":278},{"name":"Giant Insect","source":"XPHB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You summon a giant centipede, spider, or wasp (chosen when you cast the spell). It manifests in an unoccupied space you can see within range and uses the <b>Giant Insect</b> stat block. The form you choose determines certain details in its stat block. The creature disappears when it drops to 0 <i>Hit Points</i> or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your allies. In combat, the creature shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":279},{"name":"Glibness","source":"XPHB","level":8,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"Until the spell ends, when you make a Charisma check, you can replace the number you roll with a 15. Additionally, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":279},{"name":"Globe of Invulnerability","source":"XPHB","level":6,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":"a glass bead"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"An immobile, shimmering barrier appears in a 10-foot <i>Emanation [Area of Effect]</i> around you and remains for the duration."},{"type":"text","content":"Any spell of level 5 or lower cast from outside the barrier can't affect anything within it. Such a spell can target creatures and objects within the barrier, but the spell has no effect on them. Similarly, the area within the barrier is excluded from areas of effect created by such spells."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The barrier blocks spells of 1 level higher for each spell slot level above 6."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":279},{"name":"Glyph of Warding","source":"XPHB","level":3,"school":"A","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"powdered diamond worth 200+ GP, which the spell consumes","cost":20000,"consume":true}},"duration":[{"type":"permanent","ends":["dispel","trigger"]}],"entries":[{"type":"text","content":"You inscribe a glyph that later unleashes a magical effect. You inscribe it either on a surface (such as a table or a section of floor) or within an object that can be closed (such as a book or chest) to conceal the glyph. The glyph can cover an area no larger than 10 feet in diameter. If the surface or object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered."},{"type":"text","content":"The glyph is nearly imperceptible and requires a successful Wisdom (<i>Perception</i>) check against your spell save DC to notice."},{"type":"text","content":"When you inscribe the glyph, you set its trigger and choose whether it's an explosive rune or a spell glyph, as explained below."},{"type":"section","name":"Set the Trigger","entries":[{"type":"text","content":"You decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, common triggers include touching or stepping on the glyph, removing another object covering it, or approaching within a certain distance of it. For glyphs inscribed within an object, common triggers include opening that object or seeing the glyph. Once a glyph is triggered, this spell ends."},{"type":"text","content":"You can refine the trigger so that only creatures of certain types activate it (for example, the glyph could be set to affect Aberrations). You can also set conditions for creatures that don't trigger the glyph, such as those who say a certain password."}]},{"type":"section","name":"Explosive Rune","entries":[{"type":"text","content":"When triggered, the glyph erupts with magical energy in a 20-foot-radius <i>Sphere [Area of Effect]</i> centered on the glyph. Each creature in the area makes a Dexterity saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">5d8</span> Acid, Cold, Fire, Lightning, or Thunder damage (your choice when you create the glyph) on a failed save or half as much damage on a successful one."}]},{"type":"section","name":"Spell Glyph","entries":[{"type":"text","content":"You can store a prepared spell of level 3 or lower in the glyph by casting it as part of creating the glyph. The spell must target a single creature or an area. The spell being stored has no immediate effect when cast in this way."},{"type":"text","content":"When the glyph is triggered, the stored spell takes effect. If the spell has a target, it targets the creature that triggered the glyph. If the spell affects an area, the area is centered on that creature. If the spell summons <i>Hostile [Attitude]</i> creatures or creates harmful objects or traps, they appear as close as possible to the intruder and attack it. If the spell requires <i>Concentration</i>, it lasts until the end of its full duration."}]}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage of an explosive rune increases by 5d8 for each spell slot level above 3. If you create a spell glyph, you can store any spell of up to the same level as the spell slot you use for the Glyph of Warding."}]}],"damageInflict":["acid","cold","fire","lightning","thunder"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":279},{"name":"Goodberry","source":"XPHB","level":1,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a sprig of mistletoe"},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"Ten berries appear in your hand and are infused with magic for the duration. A creature can take a <i>Bonus Action</i> to eat one berry. Eating a berry restores 1 <i>Hit Points</i>, and the berry provides enough nourishment to sustain a creature for one day."},{"type":"text","content":"Uneaten berries disappear when the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":280},{"name":"Grasping Vine","source":"XPHB","level":4,"school":"C","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You conjure a vine that sprouts from a surface in an unoccupied space that you can see within range. The vine lasts for the duration."},{"type":"text","content":"Make a melee spell attack against a creature within 30 feet of the vine. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">4d8</span> Bludgeoning damage and is pulled up to 30 feet toward the vine; if the target is Huge or smaller, it has the <i class=\\"text-dnd-gold\\">Grappled</i> condition (escape DC equal to your spell save DC). The vine can grapple only one creature at a time, and you can cause the vine to release a <i class=\\"text-dnd-gold\\">Grappled</i> creature (no action required)."},{"type":"text","content":"As a <i>Bonus Action</i> on your later turns, you can repeat the attack against a creature within 30 feet of the vine."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The number of creatures the vine can grapple increases by one for each spell slot level above 4."}]}],"damageInflict":["bludgeoning"],"conditionInflict":["grappled"],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":280},{"name":"Grease","source":"XPHB","level":1,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a bit of pork rind or butter"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"Nonflammable grease covers the ground in a 10-foot square centered on a point within range and turns it into <i>Difficult Terrain</i> for the duration."},{"type":"text","content":"When the grease appears, each creature standing in its area must succeed on a Dexterity saving throw or have the <i class=\\"text-dnd-gold\\">Prone</i> condition. A creature that enters the area or ends its turn there must also succeed on that save or fall <i class=\\"text-dnd-gold\\">Prone</i>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["prone"],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":280},{"name":"Greater Invisibility","source":"XPHB","level":4,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A creature you touch has the <i class=\\"text-dnd-gold\\">Invisible</i> condition until the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["invisible"],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":281},{"name":"Greater Restoration","source":"XPHB","level":5,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"diamond dust worth 100+ GP, which the spell consumes","cost":10000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You touch a creature and magically remove one of the following effects from it:"},{"type":"list","items":["1 <i class=\\"text-dnd-gold\\">Exhaustion</i> level","The <i class=\\"text-dnd-gold\\">Charmed</i> or <i class=\\"text-dnd-gold\\">Petrified</i> condition","A curse, including the target's <i>Attunement</i> to a cursed magic item","Any reduction to one of the target's ability scores","Any reduction to the target's <i>Hit Points</i> maximum"]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":281},{"name":"Guardian of Faith","source":"XPHB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"A Large spectral guardian appears and hovers for the duration in an unoccupied space that you can see within range. The guardian occupies that space and is invulnerable, and it appears in a form appropriate for your deity or pantheon."},{"type":"text","content":"Any enemy that moves to a space within 10 feet of the guardian for the first time on a turn or starts its turn there makes a Dexterity saving throw, taking 20 Radiant damage on a failed save or half as much damage on a successful one. The guardian vanishes when it has dealt a total of 60 damage."}],"entriesHigherLevel":[],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":281},{"name":"Guards and Wards","source":"XPHB","level":6,"school":"A","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a silver rod worth 10+ GP","cost":1000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"You create a ward that protects up to 2,500 square feet of floor space. The warded area can be up to 20 feet tall, and you shape it as one 50-foot square, one hundred 5-foot squares that are contiguous, or twenty-five 10-foot squares that are contiguous."},{"type":"text","content":"When you cast this spell, you can specify individuals that are unaffected by the spell's effects. You can also specify a password that, when spoken aloud within 5 feet of the warded area, makes the speaker immune to its effects."},{"type":"text","content":"The spell creates the effects below within the warded area. <a href=\\"/spells?search=Dispel Magic\\" class=\\"text-dnd-gold hover:underline\\">Dispel Magic</a> has no effect on Guards and Wards itself, but each of the following effects can be dispelled. If all four are dispelled, Guards and Wards ends. If you cast the spell every day for 365 days on the same area, the spell thereafter lasts until all its effects are dispelled."},{"type":"section","name":"Corridors","entries":[{"type":"text","content":"Fog fills all the warded corridors, making them <i>Heavily Obscured</i>. In addition, at each intersection or branching passage offering a choice of direction, there is a 50% chance that a creature other than you believes it is going in the opposite direction from the one it chooses."}]},{"type":"section","name":"Doors","entries":[{"type":"text","content":"All doors in the warded area are magically locked, as if sealed by the <a href=\\"/spells?search=Arcane Lock\\" class=\\"text-dnd-gold hover:underline\\">Arcane Lock</a> spell. In addition, you can cover up to ten doors with an illusion to make them appear as plain sections of wall."}]},{"type":"section","name":"Stairs","entries":[{"type":"text","content":"Webs fill all stairs in the warded area from top to bottom, as in the <a href=\\"/spells?search=Web\\" class=\\"text-dnd-gold hover:underline\\">Web</a> spell. These strands regrow in 10 minutes if they are destroyed while Guards and Wards lasts."}]},{"type":"section","name":"Other Spell Effect","entries":[{"type":"text","content":"Place one of the following magical effects within the warded area:"},{"type":"list","items":["<a href=\\"/spells?search=Dancing Lights\\" class=\\"text-dnd-gold hover:underline\\">Dancing Lights</a> in four corridors, with a simple program that the lights repeat as long as Guards and Wards lasts","<a href=\\"/spells?search=Magic Mouth\\" class=\\"text-dnd-gold hover:underline\\">Magic Mouth</a> in two locations","<a href=\\"/spells?search=Stinking Cloud\\" class=\\"text-dnd-gold hover:underline\\">Stinking Cloud</a> in two locations (the vapors return within 10 minutes if dispersed while Guards and Wards lasts)","<a href=\\"/spells?search=Gust of Wind\\" class=\\"text-dnd-gold hover:underline\\">Gust of Wind</a> in one corridor or room (the wind blows continuously while the spell lasts)","<a href=\\"/spells?search=Suggestion\\" class=\\"text-dnd-gold hover:underline\\">Suggestion</a> in one 5-foot square; any creature that enters that square receives the suggestion mentally"]}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":282},{"name":"Guidance","source":"XPHB","level":0,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You touch a willing creature and choose a skill. Until the spell ends, the creature adds <span class=\\"text-green-400 font-mono\\">1d4</span> to any ability check using the chosen skill."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":282},{"name":"Guiding Bolt","source":"XPHB","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"round","amount":1}}],"entries":[{"type":"text","content":"You hurl a bolt of light toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes <span class=\\"text-red-400 font-semibold\\">4d6</span> Radiant damage, and the next attack roll made against it before the end of your next turn has <i>Advantage</i>."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 4d6 for each spell slot level above 1."}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":282},{"name":"Gust of Wind","source":"XPHB","level":2,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a legume seed"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A <i>Line [Area of Effect]</i> of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose for the duration. Each creature in the <i>Line [Area of Effect]</i> must succeed on a Strength saving throw or be pushed 15 feet away from you in a direction following the <i>Line [Area of Effect]</i>. A creature that ends its turn in the <i>Line [Area of Effect]</i> must make the same save."},{"type":"text","content":"Any creature in the <i>Line [Area of Effect]</i> must spend 2 feet of movement for every 1 foot it moves when moving closer to you."},{"type":"text","content":"The gust disperses gas or vapor, and it extinguishes candles and similar unprotected flames in the area. It causes protected flames, such as those of lanterns, to dance wildly and has a 50% chance to extinguish them."},{"type":"text","content":"As a <i>Bonus Action</i> on your later turns, you can change the direction in which the <i>Line [Area of Effect]</i> blasts from you."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":282},{"name":"Hail of Thorns","source":"XPHB","level":1,"school":"C","time":[{"number":1,"unit":"bonus","condition":"which you take immediately after hitting a creature with a Ranged weapon"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"As you hit the creature, this spell creates a rain of thorns that sprouts from your Ranged weapon or ammunition. The target of the attack and each creature within 5 feet of it make a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">1d10</span> Piercing damage on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 1d10 for each spell slot level above 1."}]}],"damageInflict":["piercing"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":283},{"name":"Hallow","source":"XPHB","level":5,"school":"A","time":[{"number":24,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"incense worth 1,000+ GP, which the spell consumes","cost":100000,"consume":true}},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"You touch a point and infuse an area around it with holy or unholy power. The area can have a radius up to 60 feet, and the spell fails if the radius includes an area already under the effect of Hallow. The affected area has the following effects."},{"type":"section","name":"Hallowed Ward","entries":[{"type":"text","content":"Choose any of these creature types: Aberration, Celestial, Elemental, Fey, Fiend, or Undead. Creatures of the chosen types can't willingly enter the area, and any creature that is possessed by or that has the <i class=\\"text-dnd-gold\\">Charmed</i> or <i class=\\"text-dnd-gold\\">Frightened</i> condition from such creatures isn't possessed, <i class=\\"text-dnd-gold\\">Charmed</i>, or <i class=\\"text-dnd-gold\\">Frightened</i> by them while in the area."}]},{"type":"section","name":"Extra Effect","entries":[{"type":"text","content":"You bind an extra effect to the area from the list below:"},{"type":"list","items":[{"type":"item","name":"Courage","entry":"Creatures of any types you choose can't gain the <i class=\\"text-dnd-gold\\">Frightened</i> condition while in the area."},{"type":"item","name":"Darkness","entry":"<i>Darkness</i> fills the area. Normal light, as well as magical light created by spells of a level lower than this spell, can't illuminate the area."},{"type":"item","name":"Daylight","entry":"Bright light fills the area. Magical <i>Darkness</i> created by spells of a level lower than this spell can't extinguish the light."},{"type":"item","name":"Peaceful Rest","entry":"<i>Dead</i> bodies interred in the area can't be turned into Undead."},{"type":"item","name":"Extradimensional Interference","entry":"Creatures of any types you choose can't enter or exit the area using teleportation or interplanar travel."},{"type":"item","name":"Fear","entry":"Creatures of any types you choose have the <i class=\\"text-dnd-gold\\">Frightened</i> condition while in the area."},{"type":"item","name":"Resistance","entry":"Creatures of any types you choose have <i>Resistance</i> to one damage type of your choice while in the area."},{"type":"item","name":"Silence","entry":"No sound can emanate from within the area, and no sound can reach into it."},{"type":"item","name":"Tongues","entry":"Creatures of any types you choose can communicate with any other creature in the area even if they don't share a common language."},{"type":"item","name":"Vulnerability","entry":"Creatures of any types you choose have <i>Vulnerability</i> to one damage type of your choice while in the area."}]}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":283},{"name":"Hallucinatory Terrain","source":"XPHB","level":4,"school":"I","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":300}},"components":{"v":true,"s":true,"m":"a mushroom"},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"You make natural terrain in a 150-foot <i>Cube [Area of Effect]</i> in range look, sound, and smell like another sort of natural terrain. Thus, open fields or a road can be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road. Manufactured structures, equipment, and creatures within the area aren't changed."},{"type":"text","content":"The tactile characteristics of the terrain are unchanged, so creatures entering the area are likely to notice the illusion. If the difference isn't obvious by touch, a creature examining the illusion can take the <b>Study</b> action to make an Intelligence (<i>Investigation</i>) check against your spell save DC to disbelieve it. If a creature discerns that the terrain is illusory, the creature sees a vague image superimposed on the real terrain."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":283},{"name":"Harm","source":"XPHB","level":6,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You unleash virulent magic on a creature you can see within range. The target makes a Constitution saving throw. On a failed save, it takes <span class=\\"text-red-400 font-semibold\\">14d6</span> Necrotic damage, and its <i>Hit Points</i> maximum is reduced by an amount equal to the Necrotic damage it took. On a successful save, it takes half as much damage only. This spell can't reduce a target's <i>Hit Points</i> maximum below 1."}],"entriesHigherLevel":[],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":283},{"name":"Haste","source":"XPHB","level":3,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a shaving of licorice root"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Choose a willing creature that you can see within range. Until the spell ends, the target's <i>Speed</i> is doubled, it gains a +2 bonus to <i>Armor Class</i>, it has <i>Advantage</i> on Dexterity saving throws, and it gains an additional action on each of its turns. That action can be used to take only the <b>Attack</b> (one attack only), <b>Dash</b>, <b>Disengage</b>, <b>Hide</b>, or <b>Utilize</b> action."},{"type":"text","content":"When the spell ends, the target is <i class=\\"text-dnd-gold\\">Incapacitated</i> and has a <i>Speed</i> of 0 until the end of its next turn, as a wave of lethargy washes over it."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["incapacitated"],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":284},{"name":"Heal","source":"XPHB","level":6,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Choose a creature that you can see within range. Positive energy washes through the target, restoring 70 <i>Hit Points</i>. This spell also ends the <i class=\\"text-dnd-gold\\">Blinded</i>, <i class=\\"text-dnd-gold\\">Deafened</i>, and <i class=\\"text-dnd-gold\\">Poisoned</i> conditions on the target."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The healing increases by 70 for each spell slot level above 6."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":284},{"name":"Healing Word","source":"XPHB","level":1,"school":"A","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A creature of your choice that you can see within range regains <i>Hit Points</i> equal to <span class=\\"text-green-400 font-mono\\">2d4</span> plus your spellcasting ability modifier."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The healing increases by 2d4 for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":284},{"name":"Heat Metal","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a piece of iron and a flame"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Choose a manufactured metal object, such as a metal weapon or a suit of Heavy or Medium metal armor, that you can see within range. You cause the object to glow red-hot. Any creature in physical contact with the object takes <span class=\\"text-red-400 font-semibold\\">2d8</span> Fire damage when you cast the spell. Until the spell ends, you can take a <i>Bonus Action</i> on each of your later turns to deal this damage again if the object is within range."},{"type":"text","content":"If a creature is holding or wearing the object and takes the damage from it, the creature must succeed on a Constitution saving throw or drop the object if it can. If it doesn't drop the object, it has <i>Disadvantage</i> on attack rolls and ability checks until the start of your next turn."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d8 for each spell slot level above 2."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":284},{"name":"Hellish Rebuke","source":"XPHB","level":1,"school":"V","time":[{"number":1,"unit":"reaction","condition":"which you take in response to taking damage from a creature that you can see within 60 feet of yourself"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"The creature that damaged you is momentarily surrounded by green flames. It makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">2d10</span> Fire damage on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d10 for each spell slot level above 1."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"reaction","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":284},{"name":"Heroes' Feast","source":"XPHB","level":6,"school":"C","time":[{"number":10,"unit":"minute"}],"range":{"type":"cube","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":{"text":"a gem-encrusted bowl worth 1,000+ GP, which the spell consumes","cost":100000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You conjure a feast that appears on a surface in an unoccupied 10-foot <i>Cube [Area of Effect]</i> next to you. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don't set in until this hour is over. Up to twelve creatures can partake of the feast."},{"type":"text","content":"A creature that partakes gains several benefits, which last for 24 hours. The creature has <i>Resistance</i> to Poison damage, and it has <i>Immunity</i> to the <i class=\\"text-dnd-gold\\">Frightened</i> and <i class=\\"text-dnd-gold\\">Poisoned</i> conditions. Its <i>Hit Points</i> maximum also increases by <span class=\\"text-green-400 font-mono\\">2d10</span>, and it gains the same number of <i>Hit Points</i>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":284},{"name":"Heroism","source":"XPHB","level":1,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to the <i class=\\"text-dnd-gold\\">Frightened</i> condition and gains <i>Temporary Hit Points</i> equal to your spellcasting ability modifier at the start of each of its turns."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":285},{"name":"Hex","source":"XPHB","level":1,"school":"E","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":"the petrified eye of a newt"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You place a curse on a creature that you can see within range. Until the spell ends, you deal an extra <span class=\\"text-red-400 font-semibold\\">1d6</span> Necrotic damage to the target whenever you hit it with an attack roll. Also, choose one ability when you cast the spell. The target has <i>Disadvantage</i> on ability checks made with the chosen ability."},{"type":"text","content":"If the target drops to 0 <i>Hit Points</i> before this spell ends, you can take a <i>Bonus Action</i> on a later turn to curse a new creature."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Your <i>Concentration</i> can last longer with a spell slot of level 2 (up to 4 hours), 3-4 (up to 8 hours), or 5+ (24 hours)."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":285},{"name":"Hold Monster","source":"XPHB","level":5,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":"a straight piece of iron"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Choose a creature that you can see within range. The target must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Paralyzed</i> condition for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 5."}]}],"damageInflict":[],"conditionInflict":["paralyzed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":285},{"name":"Hold Person","source":"XPHB","level":2,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a straight piece of iron"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Choose a Humanoid that you can see within range. The target must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Paralyzed</i> condition for the duration. At the end of each of its turns, the target repeats the save, ending the spell on itself on a success."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional Humanoid for each spell slot level above 2."}]}],"damageInflict":[],"conditionInflict":["paralyzed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":286},{"name":"Holy Aura","source":"XPHB","level":8,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":{"text":"a reliquary worth 1,000+ GP","cost":100000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"For the duration, you emit an aura in a 30-foot <i>Emanation [Area of Effect]</i>. While in the aura, creatures of your choice have <i>Advantage</i> on all saving throws, and other creatures have <i>Disadvantage</i> on attack rolls against them. In addition, when a Fiend or an Undead hits an affected creature with a melee attack roll, the attacker must succeed on a Constitution saving throw or have the <i class=\\"text-dnd-gold\\">Blinded</i> condition until the end of its next turn."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["blinded"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":286},{"name":"Hunger of Hadar","source":"XPHB","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":"a pickled tentacle"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You open a gateway to the Far Realm, a region infested with unspeakable horrors. A 20-foot-radius <i>Sphere [Area of Effect]</i> of <i>Darkness</i> appears, centered on a point within range and lasting for the duration. The <i>Sphere [Area of Effect]</i> is <i>Difficult Terrain</i>, and it is filled with strange whispers and slurping noises, which can be heard up to 30 feet away. No light, magical or otherwise, can illuminate the area, and creatures fully within it have the <i class=\\"text-dnd-gold\\">Blinded</i> condition."},{"type":"text","content":"Any creature that starts its turn in the area takes <span class=\\"text-red-400 font-semibold\\">2d6</span> Cold damage. Any creature that ends its turn there must succeed on a Dexterity saving throw or take <span class=\\"text-red-400 font-semibold\\">2d6</span> Acid damage from otherworldly tentacles."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The Cold or Acid damage (your choice) increases by 2d6 for each spell slot level above 3."}]}],"damageInflict":["acid","cold"],"conditionInflict":["blinded"],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":286},{"name":"Hunter's Mark","source":"XPHB","level":1,"school":"D","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You magically mark one creature you can see within range as your quarry. Until the spell ends, you deal an extra <span class=\\"text-red-400 font-semibold\\">1d6</span> Force damage to the target whenever you hit it with an attack roll. You also have <i>Advantage</i> on any Wisdom (<i>Perception</i> or <i>Survival</i>) check you make to find it."},{"type":"text","content":"If the target drops to 0 <i>Hit Points</i> before this spell ends, you can take a <i>Bonus Action</i> to move the mark to a new creature you can see within range."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Your <i>Concentration</i> can last longer with a spell slot of level 3-4 (up to 8 hours) or 5+ (up to 24 hours)."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":287},{"name":"Hypnotic Pattern","source":"XPHB","level":3,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"s":true,"m":"a pinch of confetti"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a twisting pattern of colors in a 30-foot <i>Cube [Area of Effect]</i> within range. The pattern appears for a moment and vanishes. Each creature in the area who can see the pattern must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration. While <i class=\\"text-dnd-gold\\">Charmed</i>, the creature has the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition and a <i>Speed</i> of 0."},{"type":"text","content":"The spell ends for an affected creature if it takes any damage or if someone else uses an action to shake the creature out of its stupor."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["charmed","incapacitated"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":287},{"name":"Ice Storm","source":"XPHB","level":4,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":300}},"components":{"v":true,"s":true,"m":"a mitten"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Hail falls in a 20-foot-radius, 40-foot-high <i>Cylinder [Area of Effect]</i> centered on a point within range. Each creature in the <i>Cylinder [Area of Effect]</i> makes a Dexterity saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">2d10</span> Bludgeoning damage and <span class=\\"text-red-400 font-semibold\\">4d6</span> Cold damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"Hailstones turn ground in the <i>Cylinder [Area of Effect]</i> into <i>Difficult Terrain</i> until the end of your next turn."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The Bludgeoning damage increases by 2d8 for each spell slot level above 4."}]}],"damageInflict":["bludgeoning","cold"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":287},{"name":"Identify","source":"XPHB","level":1,"school":"D","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a pearl worth 100+ GP","cost":10000}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You touch an object throughout the spell's casting. If the object is a magic item or some other magical object, you learn its properties and how to use them, whether it requires <i>Attunement</i>, and how many charges it has, if any. You learn whether any ongoing spells are affecting the item and what they are. If the item was created by a spell, you learn that spell's name."},{"type":"text","content":"If you instead touch a creature throughout the casting, you learn which ongoing spells, if any, are currently affecting it."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":287},{"name":"Illusory Script","source":"XPHB","level":1,"school":"I","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"s":true,"m":{"text":"ink worth 10+ GP, which the spell consumes","cost":1000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"day","amount":10}}],"entries":[{"type":"text","content":"You write on parchment, paper, or another suitable material and imbue it with an illusion that lasts for the duration. To you and any creatures you designate when you cast the spell, the writing appears normal, seems to be written in your hand, and conveys whatever meaning you intended when you wrote the text. To all others, the writing appears as if it were written in an unknown or magical script that is unintelligible. Alternatively, the illusion can alter the meaning, handwriting, and language of the text, though the language must be one you know."},{"type":"text","content":"If the spell is dispelled, the original script and the illusion both disappear."},{"type":"text","content":"A creature that has <i>Truesight</i> can read the hidden message."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":288},{"name":"Imprisonment","source":"XPHB","level":9,"school":"A","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":{"text":"a statuette of the target worth 5,000+ GP","cost":500000}},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"You create a magical restraint to hold a creature that you can see within range. The target must make a Wisdom saving throw. On a successful save, the target is unaffected, and it is immune to this spell for the next 24 hours. On a failed save, the target is imprisoned. While imprisoned, the target doesn't need to breathe, eat, or drink, and it doesn't age. Divination spells can't locate or perceive the imprisoned target, and the target can't teleport."},{"type":"text","content":"Until the spell ends, the target is also affected by one of the following effects of your choice:"},{"type":"list","items":[{"type":"item","name":"Burial","entry":"The target is entombed beneath the earth in a hollow globe of magical force that is just large enough to contain the target. Nothing can pass into or out of the globe."},{"type":"item","name":"Chaining","entry":"Chains firmly rooted in the ground hold the target in place. The target has the <i class=\\"text-dnd-gold\\">Restrained</i> condition and can't be moved by any means."},{"type":"item","name":"Hedged Prison","entry":"The target is trapped in a demiplane that is warded against teleportation and planar travel. The demiplane is your choice of a labyrinth, a cage, a tower, or the like."},{"type":"item","name":"Minimus Containment","entry":"The target becomes 1 inch tall and is trapped inside an indestructible gemstone or a similar object. Light can pass through the gemstone (allowing the target to see out and other creatures to see in), but nothing else can pass through by any means."},{"type":"item","name":"Slumber","entry":"The target has the <i class=\\"text-dnd-gold\\">Unconscious</i> condition and can't be awoken."}]},{"type":"section","name":"Ending the Spell","entries":[{"type":"text","content":"When you cast the spell, specify a trigger that will end it. The trigger can be as simple or as elaborate as you choose, but the DM must agree that it has a high likelihood of happening within the next decade. The trigger must be an observable action, such as someone making a particular offering at the temple of your god, saving your true love, or defeating a specific monster."},{"type":"text","content":"A <a href=\\"/spells?search=Dispel Magic\\" class=\\"text-dnd-gold hover:underline\\">Dispel Magic</a> spell can end the spell only if it is cast with a level 9 spell slot, targeting either the prison or the component used to create it."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["restrained","unconscious"],"savingThrow":["wisdom"],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":288},{"name":"Incendiary Cloud","source":"XPHB","level":8,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A swirling cloud of embers and smoke fills a 20-foot-radius <i>Sphere [Area of Effect]</i> centered on a point within range. The cloud's area is <i>Heavily Obscured</i>. It lasts for the duration or until a strong wind (like that created by <a href=\\"/spells?search=Gust of Wind\\" class=\\"text-dnd-gold hover:underline\\">Gust of Wind</a>) disperses it."},{"type":"text","content":"When the cloud appears, each creature in it makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">10d8</span> Fire damage on a failed save or half as much damage on a successful one. A creature must also make this save when the <i>Sphere [Area of Effect]</i> moves into its space and when it enters the <i>Sphere [Area of Effect]</i> or ends its turn there. A creature makes this save only once per turn."},{"type":"text","content":"The cloud moves 10 feet away from you in a direction you choose at the start of each of your turns."}],"entriesHigherLevel":[],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":288},{"name":"Inflict Wounds","source":"XPHB","level":1,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A creature you touch makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">2d10</span> Necrotic damage on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d10 for each spell slot level above 1."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":288},{"name":"Insect Plague","source":"XPHB","level":5,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":300}},"components":{"v":true,"s":true,"m":"a locust"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Swarming locusts fill a 20-foot-radius <i>Sphere [Area of Effect]</i> centered on a point you choose within range. The <i>Sphere [Area of Effect]</i> remains for the duration, and its area is <i>Lightly Obscured</i> and <i>Difficult Terrain</i>."},{"type":"text","content":"When the swarm appears, each creature in it makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">4d10</span> Piercing damage on a failed save or half as much damage on a successful one. A creature also makes this save when it enters the spell's area for the first time on a turn or ends its turn there. A creature makes this save only once per turn."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 4d10 for each spell slot level above 5."}]}],"damageInflict":["piercing"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":289},{"name":"Invisibility","source":"XPHB","level":2,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"an eyelash in gum arabic"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A creature you touch has the <i class=\\"text-dnd-gold\\">Invisible</i> condition until the spell ends. The spell ends early immediately after the target makes an attack roll, deals damage, or casts a spell."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 2."}]}],"damageInflict":[],"conditionInflict":["invisible"],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":289},{"name":"Jump","source":"XPHB","level":1,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a grasshopper's hind leg"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"You touch a willing creature. Once on each of its turns until the spell ends, that creature can jump up to 30 feet by spending 10 feet of movement."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":290},{"name":"Knock","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Choose an object that you can see within range. The object can be a door, a box, a chest, a set of manacles, a padlock, or another object that contains a mundane or magical means that prevents access."},{"type":"text","content":"A target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, only one of them is unlocked."},{"type":"text","content":"If the target is held shut by <a href=\\"/spells?search=Arcane Lock\\" class=\\"text-dnd-gold hover:underline\\">Arcane Lock</a>, that spell is suppressed for 10 minutes, during which time the target can be opened and closed."},{"type":"text","content":"When you cast the spell, a loud knock, audible up to 300 feet away, emanates from the target."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":290},{"name":"Legend Lore","source":"XPHB","level":5,"school":"D","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"incense worth 250+ GP, which the spell consumes, and four ivory strips worth 50+ GP each","cost":25000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Name or describe a famous person, place, or object. The spell brings to your mind a brief summary of the significant lore about that famous thing, as described by the DM."},{"type":"text","content":"The lore might consist of important details, amusing revelations, or even secret lore that has never been widely known. The more information you already know about the thing, the more precise and detailed the information you receive is. That information is accurate but might be couched in figurative language or poetry, as determined by the DM."},{"type":"text","content":"If the famous thing you chose isn't actually famous, you hear sad musical notes played on a trombone, and the spell fails."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":290},{"name":"Leomund's Secret Chest","source":"XPHB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a chest, 3 feet by 2 feet by 2 feet, constructed from rare materials worth 5,000+ GP, and a Tiny replica of the chest made from the same materials worth 50+ GP","cost":500000}},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"You hide a chest and all its contents on the Ethereal Plane. You must touch the chest and the miniature replica that serve as Material components for the spell. The chest can contain up to 12 cubic feet of nonliving material (3 feet by 2 feet by 2 feet)."},{"type":"text","content":"While the chest remains on the Ethereal Plane, you can take a <b>Magic</b> action and touch the replica to recall the chest. It appears in an unoccupied space on the ground within 5 feet of you. You can send the chest back to the Ethereal Plane by taking a <b>Magic</b> action to touch the chest and the replica."},{"type":"text","content":"After 60 days, there is a cumulative 5% chance at the end of each day that the spell ends. The spell also ends if you cast this spell again or if the Tiny replica chest is destroyed. If the spell ends and the larger chest is on the Ethereal Plane, the chest remains there for you or someone else to find."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":290},{"name":"Leomund's Tiny Hut","source":"XPHB","level":3,"school":"V","time":[{"number":1,"unit":"minute"}],"range":{"type":"emanation","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":"a crystal bead"},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"A 10-foot <i>Emanation [Area of Effect]</i> springs into existence around you and remains stationary for the duration. The spell fails when you cast it if the <i>Emanation [Area of Effect]</i> isn't big enough to fully encapsulate all creatures in its area."},{"type":"text","content":"Creatures and objects within the <i>Emanation [Area of Effect]</i> when you cast the spell can move through it freely. All other creatures and objects are barred from passing through it. Spells of level 3 or lower can't be cast through it, and the effects of such spells can't extend into it."},{"type":"text","content":"The atmosphere inside the <i>Emanation [Area of Effect]</i> is comfortable and dry, regardless of the weather outside. Until the spell ends, you can command the interior to have <i>Dim Light</i> or <i>Darkness</i> (no action required). The <i>Emanation [Area of Effect]</i> is opaque from the outside and of any color you choose, but it's transparent from the inside."},{"type":"text","content":"The spell ends early if you leave the <i>Emanation [Area of Effect]</i> or if you cast it again."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":291},{"name":"Lesser Restoration","source":"XPHB","level":2,"school":"A","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You touch a creature and end one condition on it: <i class=\\"text-dnd-gold\\">Blinded</i>, <i class=\\"text-dnd-gold\\">Deafened</i>, <i class=\\"text-dnd-gold\\">Paralyzed</i>, or <i class=\\"text-dnd-gold\\">Poisoned</i>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":291},{"name":"Levitate","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a metal spring"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"One creature or loose object of your choice that you can see within range rises vertically up to 20 feet and remains suspended there for the duration. The spell can levitate an object that weighs up to 500 pounds. An unwilling creature that succeeds on a Constitution saving throw is unaffected."},{"type":"text","content":"The target can move only by pushing or pulling against a fixed object or surface within reach (such as a wall or a ceiling), which allows it to move as if it were climbing. You can change the target's altitude by up to 20 feet in either direction on your turn. If you are the target, you can move up or down as part of your move. Otherwise, you can take a <b>Magic</b> action to move the target, which must remain within the spell's range."},{"type":"text","content":"When the spell ends, the target floats gently to the ground if it is still aloft."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":291},{"name":"Light","source":"XPHB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"m":"a firefly or phosphorescent moss"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You touch one Large or smaller object that isn't being worn or carried by someone else. Until the spell ends, the object sheds <i>Bright Light</i> in a 20-foot radius and <i>Dim Light</i> for an additional 20 feet. The light can be colored as you like."},{"type":"text","content":"Covering the object with something opaque blocks the light. The spell ends if you cast it again."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":292},{"name":"Lightning Arrow","source":"XPHB","level":3,"school":"T","time":[{"number":1,"unit":"bonus","condition":"which you take immediately after hitting or missing a target with a ranged attack using a weapon"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"As your attack hits or misses the target, the weapon or ammunition you're using transforms into a lightning bolt. Instead of taking any damage or other effects from the attack, the target takes <span class=\\"text-red-400 font-semibold\\">4d8</span> Lightning damage on a hit or half as much damage on a miss. Each creature within 10 feet of the target then makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">2d8</span> Lightning damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"The weapon or ammunition then returns to its normal form."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage for both effects of the spell increases by 4d8;2d8 for each spell slot level above 3."}]}],"damageInflict":["lightning"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":292},{"name":"Lightning Bolt","source":"XPHB","level":3,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"line","distance":{"type":"feet","amount":100}},"components":{"v":true,"s":true,"m":"a bit of fur and a crystal rod"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A stroke of lightning forming a 100-foot-long, 5-foot-wide <i>Line [Area of Effect]</i> blasts out from you in a direction you choose. Each creature in the <i>Line [Area of Effect]</i> makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">8d6</span> Lightning damage on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 8d6 for each spell slot level above 3."}]}],"damageInflict":["lightning"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":292},{"name":"Locate Animals or Plants","source":"XPHB","level":2,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"fur from a bloodhound"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Describe or name a specific kind of Beast, Plant creature, or nonmagical plant. You learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":292},{"name":"Locate Creature","source":"XPHB","level":4,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"fur from a bloodhound"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Describe or name a creature that is familiar to you. You sense the direction to the creature's location if that creature is within 1,000 feet of you. If the creature is moving, you know the direction of its movement."},{"type":"text","content":"The spell can locate a specific creature known to you or the nearest creature of a specific kind (such as a human or a unicorn) if you have seen such a creature up close—within 30 feet—at least once. If the creature you described or named is in a different form, such as under the effects of a <a href=\\"/spells?search=Flesh to Stone\\" class=\\"text-dnd-gold hover:underline\\">Flesh to Stone</a> or <a href=\\"/spells?search=Polymorph\\" class=\\"text-dnd-gold hover:underline\\">Polymorph</a> spell, this spell doesn't locate the creature."},{"type":"text","content":"This spell can't locate a creature if any thickness of lead blocks a direct path between you and the creature."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":292},{"name":"Locate Object","source":"XPHB","level":2,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a forked twig"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Describe or name an object that is familiar to you. You sense the direction to the object's location if that object is within 1,000 feet of you. If the object is in motion, you know the direction of its movement."},{"type":"text","content":"The spell can locate a specific object known to you if you have seen it up close—within 30 feet—at least once. Alternatively, the spell can locate the nearest object of a particular kind, such as a certain kind of apparel, jewelry, furniture, tool, or weapon."},{"type":"text","content":"This spell can't locate an object if any thickness of lead blocks a direct path between you and the object."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":293},{"name":"Longstrider","source":"XPHB","level":1,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a pinch of dirt"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You touch a creature. The target's <i>Speed</i> increases by 10 feet until the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":293},{"name":"Mage Armor","source":"XPHB","level":1,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a piece of cured leather"},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You touch a willing creature who isn't wearing armor. Until the spell ends, the target's base AC becomes 13 plus its Dexterity modifier. The spell ends early if the target dons armor."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":293},{"name":"Mage Hand","source":"XPHB","level":0,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"A spectral, floating hand appears at a point you choose within range. The hand lasts for the duration. The hand vanishes if it is ever more than 30 feet away from you or if you cast this spell again."},{"type":"text","content":"When you cast the spell, you can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial."},{"type":"text","content":"As a <b>Magic</b> action on your later turns, you can control the hand thus again. As part of that action, you can move the hand up to 30 feet."},{"type":"text","content":"The hand can't attack, activate magic items, or carry more than 10 pounds."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":293},{"name":"Magic Circle","source":"XPHB","level":3,"school":"A","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":{"text":"salt and powdered silver worth 100+ GP, which the spell consumes","cost":10000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You create a 10-foot-radius, 20-foot-tall <i>Cylinder [Area of Effect]</i> of magical energy centered on a point on the ground that you can see within range. Glowing runes appear wherever the <i>Cylinder [Area of Effect]</i> intersects with the floor or other surface."},{"type":"text","content":"Choose one or more of the following types of creatures: Celestials, Elementals, Fey, Fiends, or Undead. The circle affects a creature of the chosen type in the following ways:"},{"type":"list","items":["The creature can't willingly enter the <i>Cylinder [Area of Effect]</i> by nonmagical means. If the creature tries to use teleportation or interplanar travel to do so, it must first succeed on a Charisma saving throw.","The creature has <i>Disadvantage</i> on attack rolls against targets within the <i>Cylinder [Area of Effect]</i>.","Targets within the <i>Cylinder [Area of Effect]</i> can't be possessed by or gain the <i class=\\"text-dnd-gold\\">Charmed</i> or <i class=\\"text-dnd-gold\\">Frightened</i> condition from the creature."]},{"type":"text","content":"Each time you cast this spell, you can cause its magic to operate in the reverse direction, preventing a creature of the specified type from leaving the <i>Cylinder [Area of Effect]</i> and protecting targets outside it."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The duration increases by 1 hour for each spell slot level above 3."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":["charisma"],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":293},{"name":"Magic Jar","source":"XPHB","level":6,"school":"N","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"a gem, crystal, or reliquary worth 500+ GP","cost":50000}},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"Your body falls into a catatonic state as your soul leaves it and enters the container you used for the spell's Material component. While your soul inhabits the container, you are aware of your surroundings as if you were in the container's space. You can't move or take Reactions. The only action you can take is to project your soul up to 100 feet out of the container, either returning to your living body (and ending the spell) or attempting to possess a Humanoid's body."},{"type":"text","content":"You can attempt to possess any Humanoid within 100 feet of you that you can see (creatures warded by a <a href=\\"/spells?search=Protection from Evil and Good\\" class=\\"text-dnd-gold hover:underline\\">Protection from Evil and Good</a> or <a href=\\"/spells?search=Magic Circle\\" class=\\"text-dnd-gold hover:underline\\">Magic Circle</a> spell can't be possessed). The target makes a Charisma saving throw. On a failed save, your soul enters the target's body, and the target's soul becomes trapped in the container. On a successful save, the target resists your efforts to possess it, and you can't attempt to possess it again for 24 hours."},{"type":"text","content":"Once you possess a creature's body, you control it. Your <i>Hit Points</i>, <i>Hit Point Dice</i>, Strength, Dexterity, Constitution, <i>Speed</i>, and senses are replaced by the creature's. You otherwise keep your game statistics."},{"type":"text","content":"Meanwhile, the possessed creature's soul can perceive from the container using its own senses, but it can't move and it is <i class=\\"text-dnd-gold\\">Incapacitated</i>."},{"type":"text","content":"While possessing a body, you can take a <b>Magic</b> action to return from the host body to the container if it is within 100 feet of you, returning the host creature's soul to its body. If the host body dies while you're in it, the creature dies, and you make a Charisma saving throw against your own spellcasting DC. On a success, you return to the container if it is within 100 feet of you. Otherwise, you die."},{"type":"text","content":"If the container is destroyed or the spell ends, your soul returns to your body. If your body is more than 100 feet away from you or if your body is dead, you die. If another creature's soul is in the container when it is destroyed, the creature's soul returns to its body if the body is alive and within 100 feet. Otherwise, that creature dies."},{"type":"text","content":"When the spell ends, the container is destroyed."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["charisma"],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":294},{"name":"Magic Missile","source":"XPHB","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You create three glowing darts of magical force. Each dart strikes a creature of your choice that you can see within range. A dart deals <span class=\\"text-red-400 font-semibold\\">1d4 + 1</span> Force damage to its target. The darts all strike simultaneously, and you can direct them to hit one creature or several."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The spell creates one more dart for each spell slot level above 1."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":295},{"name":"Magic Mouth","source":"XPHB","level":2,"school":"I","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":{"text":"jade dust worth 10+ GP, which the spell consumes","cost":1000,"consume":true}},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"You implant a message within an object in range—a message that is uttered when a trigger condition is met. Choose an object that you can see and that isn't being worn or carried by another creature. Then speak the message, which must be 25 words or fewer, though it can be delivered over as long as 10 minutes. Finally, determine the circumstance that will trigger the spell to deliver your message."},{"type":"text","content":"When that trigger occurs, a magical mouth appears on the object and recites the message in your voice and at the same volume you spoke. If the object you chose has a mouth or something that looks like a mouth (for example, the mouth of a statue), the magical mouth appears there, so the words appear to come from the object's mouth. When you cast this spell, you can have the spell end after it delivers its message, or it can remain and repeat its message whenever the trigger occurs."},{"type":"text","content":"The trigger can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the object. For example, you could instruct the mouth to speak when any creature moves within 30 feet of the object or when a silver bell rings within 30 feet of it."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":295},{"name":"Magic Weapon","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You touch a nonmagical weapon. Until the spell ends, that weapon becomes a magic weapon with a +1 bonus to attack rolls and damage rolls. The spell ends early if you cast it again."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The bonus increases to +2 with a level 3-5 spell slot. The bonus increases to +3 with a level 6+ spell slot."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":295},{"name":"Major Image","source":"XPHB","level":3,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a bit of fleece"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-foot <i>Cube [Area of Effect]</i>. The image appears at a spot that you can see within range and lasts for the duration. It seems real, including sounds, smells, and temperature appropriate to the thing depicted, but it can't deal damage or cause conditions."},{"type":"text","content":"If you are within range of the illusion, you can take a <b>Magic</b> action to cause the image to move to any other spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking. Similarly, you can cause the illusion to make different sounds at different times, even making it carry on a conversation, for example."},{"type":"text","content":"Physical interaction with the image reveals it to be an illusion, for things can pass through it. A creature that takes a <b>Study</b> action to examine the image can determine that it is an illusion with a successful Intelligence (<i>Investigation</i>) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and its other sensory qualities become faint to the creature."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The spell lasts until dispelled, without requiring <i>Concentration</i>, if cast with a level 4+ spell slot."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":295},{"name":"Mass Cure Wounds","source":"XPHB","level":5,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A wave of healing energy washes out from a point you can see within range. Choose up to six creatures in a 30-foot-radius <i>Sphere [Area of Effect]</i> centered on that point. Each target regains <i>Hit Points</i> equal to <span class=\\"text-green-400 font-mono\\">5d8</span> plus your spellcasting ability modifier."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The healing increases by 5d8 for each spell slot level above 5."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":296},{"name":"Mass Heal","source":"XPHB","level":9,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A flood of healing energy flows from you into creatures around you. You restore up to 700 <i>Hit Points</i>, divided as you choose among any number of creatures that you can see within range. Creatures healed by this spell also have the <i class=\\"text-dnd-gold\\">Blinded</i>, <i class=\\"text-dnd-gold\\">Deafened</i>, and <i class=\\"text-dnd-gold\\">Poisoned</i> conditions removed from them."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":296},{"name":"Mass Healing Word","source":"XPHB","level":3,"school":"A","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Up to six creatures of your choice that you can see within range regain <i>Hit Points</i> equal to <span class=\\"text-green-400 font-mono\\">2d4</span> plus your spellcasting ability modifier."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The healing increases by 2d4 for each spell slot level above 3."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":296},{"name":"Mass Suggestion","source":"XPHB","level":6,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"m":"a snake's tongue"},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"You suggest a course of activity—described in no more than 25 words—to twelve or fewer creatures you can see within range that can hear and understand you. The suggestion must sound achievable and not involve anything that would obviously deal damage to any of the targets or their allies. For example, you could say, \\"Walk to the village down that road, and help the villagers there harvest crops until sunset.\\" Or you could say, \\"Now is not the time for violence. Drop your weapons, and dance! Stop in an hour.\\""},{"type":"text","content":"Each target must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration or until you or your allies deal damage to the target. Each <i class=\\"text-dnd-gold\\">Charmed</i> target pursues the suggestion to the best of its ability. The suggested activity can continue for the entire duration, but if the suggested activity can be completed in a shorter time, the spell ends for a target upon completing it."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The duration is longer with a spell slot of level 7 (10 days), 8 (30 days), or 9 (366 days)."}]}],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":296},{"name":"Maze","source":"XPHB","level":8,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You banish a creature that you can see within range into a labyrinthine demiplane. The target remains there for the duration or until it escapes the maze."},{"type":"text","content":"The target can take a <b>Study</b> action to try to escape. When it does so, it makes a DC 20 Intelligence (<i>Investigation</i>) check. If it succeeds, it escapes, and the spell ends."},{"type":"text","content":"When the spell ends, the target reappears in the space it left or, if that space is occupied, in the nearest unoccupied space."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":296},{"name":"Meld into Stone","source":"XPHB","level":3,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You step into a stone object or surface large enough to fully contain your body, merging yourself and your equipment with the stone for the duration. You must touch the stone to do so. Nothing of your presence remains visible or otherwise detectable by nonmagical senses."},{"type":"text","content":"While merged with the stone, you can't see what occurs outside it, and any Wisdom (<i>Perception</i>) checks you make to hear sounds outside it are made with <i>Disadvantage</i>. You remain aware of the passage of time and can cast spells on yourself while merged in the stone. You can use 5 feet of movement to leave the stone where you entered it, which ends the spell. You otherwise can't move."},{"type":"text","content":"Minor physical damage to the stone doesn't harm you, but its partial destruction or a change in its shape (to the extent that you no longer fit within it) expels you and deals <span class=\\"text-red-400 font-semibold\\">6d6</span> Force damage to you. The stone's complete destruction (or transmutation into a different substance) expels you and deals 50 Force damage to you. If expelled, you move into an unoccupied space closest to where you first entered and have the <i class=\\"text-dnd-gold\\">Prone</i> condition."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":["prone"],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":296},{"name":"Melf's Acid Arrow","source":"XPHB","level":2,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":"powdered rhubarb leaf"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A shimmering green arrow streaks toward a target within range and bursts in a spray of acid. Make a ranged spell attack against the target. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">4d4</span> Acid damage and <span class=\\"text-red-400 font-semibold\\">2d4</span> Acid damage at the end of its next turn. On a miss, the arrow splashes the target with acid for half as much of the initial damage only."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage (both initial and later) increases by 4d4;2d4 for each spell slot level above 2."}]}],"damageInflict":["acid"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":297},{"name":"Mending","source":"XPHB","level":0,"school":"T","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"two lodestones"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"This spell repairs a single break or tear in an object you touch, such as a broken chain link, two halves of a broken key, a torn cloak, or a leaking wineskin. As long as the break or tear is no larger than 1 foot in any dimension, you mend it, leaving no trace of the former damage."},{"type":"text","content":"This spell can physically repair a magic item, but it can't restore magic to such an object."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":297},{"name":"Message","source":"XPHB","level":0,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"s":true,"m":"a copper wire"},"duration":[{"type":"timed","duration":{"type":"round","amount":1}}],"entries":[{"type":"text","content":"You point toward a creature within range and whisper a message. The target (and only the target) hears the message and can reply in a whisper that only you can hear."},{"type":"text","content":"You can cast this spell through solid objects if you are familiar with the target and know it is beyond the barrier. Magical silence; 1 foot of stone, metal, or wood; or a thin sheet of lead blocks the spell."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":298},{"name":"Meteor Swarm","source":"XPHB","level":9,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"miles","amount":1}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Blazing orbs of fire plummet to the ground at four different points you can see within range. Each creature in a 40-foot-radius <i>Sphere [Area of Effect]</i> centered on each of those points makes a Dexterity saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">20d6</span> Fire damage and <span class=\\"text-red-400 font-semibold\\">20d6</span> Bludgeoning damage on a failed save or half as much damage on a successful one. A creature in the area of more than one fiery <i>Sphere [Area of Effect]</i> is affected only once."},{"type":"text","content":"A nonmagical object that isn't being worn or carried also takes the damage if it's in the spell's area, and the object starts burning if it's flammable."}],"entriesHigherLevel":[],"damageInflict":["bludgeoning","fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":298},{"name":"Mind Blank","source":"XPHB","level":8,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"Until the spell ends, one willing creature you touch has <i>Immunity</i> to Psychic damage and the <i class=\\"text-dnd-gold\\">Charmed</i> condition. The target is also unaffected by anything that would sense its emotions or alignment, read its thoughts, or magically detect its location, and no spell—not even <a href=\\"/spells?search=Wish\\" class=\\"text-dnd-gold hover:underline\\">Wish</a>—can gather information about the target, observe it remotely, or control its mind."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":298},{"name":"Minor Illusion","source":"XPHB","level":0,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"s":true,"m":"a bit of fleece"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"You create a sound or an image of an object within range that lasts for the duration. See the descriptions below for the effects of each. The illusion ends if you cast this spell again."},{"type":"text","content":"If a creature takes a <b>Study</b> action to examine the sound or image, the creature can determine that it is an illusion with a successful Intelligence (<i>Investigation</i>) check against your spell save DC. If a creature discerns the illusion for what it is, the illusion becomes faint to the creature."},{"type":"section","name":"Sound","entries":[{"type":"text","content":"If you create a sound, its volume can range from a whisper to a scream. It can be your voice, someone else's voice, a lion's roar, a beating of drums, or any other sound you choose. The sound continues unabated throughout the duration, or you can make discrete sounds at different times before the spell ends."}]},{"type":"section","name":"Image","entries":[{"type":"text","content":"If you create an image of an object—such as a chair, muddy footprints, or a small chest—it must be no larger than a 5-foot <i>Cube [Area of Effect]</i>. The image can't create sound, light, smell, or any other sensory effect. Physical interaction with the image reveals it to be an illusion, since things can pass through it."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":298},{"name":"Mirage Arcane","source":"XPHB","level":7,"school":"I","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"sight"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"day","amount":10}}],"entries":[{"type":"text","content":"You make terrain in an area up to 1 mile square look, sound, smell, and even feel like some other sort of terrain. Open fields or a road could be made to resemble a swamp, hill, crevasse, or some other rough or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road."},{"type":"text","content":"Similarly, you can alter the appearance of structures or add them where none are present. The spell doesn't disguise, conceal, or add creatures."},{"type":"text","content":"The illusion includes audible, visual, tactile, and olfactory elements, so it can turn clear ground into <i>Difficult Terrain</i> (or vice versa) or otherwise impede movement through the area. Any piece of the illusory terrain (such as a rock or stick) that is removed from the spell's area disappears immediately."},{"type":"text","content":"Creatures with <i>Truesight</i> can see through the illusion to the terrain's true form; however, all other elements of the illusion remain, so while the creature is aware of the illusion's presence, the creature can still physically interact with the illusion."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":299},{"name":"Mirror Image","source":"XPHB","level":2,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions, shifting position so it's impossible to track which image is real."},{"type":"text","content":"Each time a creature hits you with an attack roll during the spell's duration, roll a <span class=\\"text-green-400 font-mono\\">d6</span> for each of your remaining duplicates. If any of the d6s rolls a 3 or higher, one of the duplicates is hit instead of you, and the duplicate is destroyed. The duplicates otherwise ignore all other damage and effects. The spell ends when all three duplicates are destroyed."},{"type":"text","content":"A creature is unaffected by this spell if it has the <i class=\\"text-dnd-gold\\">Blinded</i> condition, <i>Blindsight</i>, or <i>Truesight</i>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":299},{"name":"Mislead","source":"XPHB","level":5,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You gain the <i class=\\"text-dnd-gold\\">Invisible</i> condition at the same time that an illusory double of you appears where you are standing. The double lasts for the duration, but the invisibility ends immediately after you make an attack roll, deal damage, or cast a spell."},{"type":"text","content":"As a <b>Magic</b> action, you can move the illusory double up to twice your <i>Speed</i> and make it gesture, speak, and behave in whatever way you choose. It is intangible and invulnerable."},{"type":"text","content":"You can see through its eyes and hear through its ears as if you were located where it is."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["invisible"],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":299},{"name":"Misty Step","source":"XPHB","level":2,"school":"C","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space you can see."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":299},{"name":"Modify Memory","source":"XPHB","level":5,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You attempt to reshape another creature's memories. One creature that you can see within range makes a Wisdom saving throw. If you are fighting the creature, it has <i>Advantage</i> on the save. On a failed save, the target has the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration. While <i class=\\"text-dnd-gold\\">Charmed</i> in this way, the target also has the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition and is unaware of its surroundings, though it can hear you. If it takes any damage or is targeted by another spell, this spell ends, and no memories are modified."},{"type":"text","content":"While this charm lasts, you can affect the target's memory of an event that it experienced within the last 24 hours and that lasted no more than 10 minutes. You can permanently eliminate all memory of the event, allow the target to recall the event with perfect clarity, change its memory of the event's details, or create a memory of some other event."},{"type":"text","content":"You must speak to the target to describe how its memories are affected, and it must be able to understand your language for the modified memories to take root. Its mind fills in any gaps in the details of your description. If the spell ends before you finish describing the modified memories, the creature's memory isn't altered. Otherwise, the modified memories take hold when the spell ends."},{"type":"text","content":"A modified memory doesn't necessarily affect how a creature behaves, particularly if the memory contradicts the creature's natural inclinations, alignment, or beliefs. An illogical modified memory, such as a false memory of how much the creature enjoyed swimming in acid, is dismissed as a bad dream. The DM might deem a modified memory too nonsensical to affect a creature."},{"type":"text","content":"A <a href=\\"/spells?search=Remove Curse\\" class=\\"text-dnd-gold hover:underline\\">Remove Curse</a> or <a href=\\"/spells?search=Greater Restoration\\" class=\\"text-dnd-gold hover:underline\\">Greater Restoration</a> spell cast on the target restores the creature's true memory."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can alter the target's memories of an event that took place up to 7 days ago (level 6 spell slot), 30 days ago (level 7 spell slot), 365 days ago (level 8 spell slot), or any time in the creature's past (level 9 spell slot)."}]}],"damageInflict":[],"conditionInflict":["charmed","incapacitated"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":299},{"name":"Moonbeam","source":"XPHB","level":2,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a moonseed leaf"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A silvery beam of pale light shines down in a 5-foot-radius, 40-foot-high <i>Cylinder [Area of Effect]</i> centered on a point within range. Until the spell ends, <i>Dim Light</i> fills the <i>Cylinder [Area of Effect]</i>, and you can take a <b>Magic</b> action on later turns to move the <i>Cylinder [Area of Effect]</i> up to 60 feet."},{"type":"text","content":"When the <i>Cylinder [Area of Effect]</i> appears, each creature in it makes a Constitution saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">2d10</span> Radiant damage, and if the creature is shape-shifted (as a result of the <a href=\\"/spells?search=Polymorph\\" class=\\"text-dnd-gold hover:underline\\">Polymorph</a> spell, for example), it reverts to its true form and can't shape-shift until it leaves the <i>Cylinder [Area of Effect]</i>. On a successful save, a creature takes half as much damage only. A creature also makes this save when the spell's area moves into its space and when it enters the spell's area or ends its turn there. A creature makes this save only once per turn."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d10 for each spell slot level above 2."}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":300},{"name":"Mordenkainen's Faithful Hound","source":"XPHB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a silver whistle"},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You conjure a phantom watchdog in an unoccupied space that you can see within range. The hound remains for the duration or until the two of you are more than 300 feet apart from each other."},{"type":"text","content":"No one but you can see the hound, and it is intangible and invulnerable. When a Small or larger creature comes within 30 feet of it without first speaking the password that you specify when you cast this spell, the hound starts barking loudly. The hound has <i>Truesight</i> with a range of 30 feet."},{"type":"text","content":"At the start of each of your turns, the hound attempts to bite one enemy within 5 feet of it. That enemy must succeed on a Dexterity saving throw or take <span class=\\"text-red-400 font-semibold\\">4d8</span> Force damage."},{"type":"text","content":"On your later turns, you can take a <b>Magic</b> action to move the hound up to 30 feet."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":300},{"name":"Mordenkainen's Magnificent Mansion","source":"XPHB","level":7,"school":"C","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":300}},"components":{"v":true,"s":true,"m":{"text":"a miniature door worth 15+ GP","cost":1500}},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"You conjure a shimmering door in range that lasts for the duration. The door leads to an extradimensional dwelling and is 5 feet wide and 10 feet tall. You and any creature you designate when you cast the spell can enter the extradimensional dwelling as long as the door remains open. You can open or close it (no action required) if you are within 30 feet of it. While closed, the door is imperceptible."},{"type":"text","content":"Beyond the door is a magnificent foyer with numerous chambers beyond. The dwelling's atmosphere is clean, fresh, and warm."},{"type":"text","content":"You can create any floor plan you like for the dwelling, but it can't exceed 50 contiguous 10-foot Cubes. The place is furnished and decorated as you choose. It contains sufficient food to serve a nine-course banquet for up to 100 people. Furnishings and other objects created by this spell dissipate into smoke if removed from it."},{"type":"text","content":"A staff of 100 near-transparent servants attends all who enter. You determine the appearance of these servants and their attire. They are invulnerable and obey your commands. Each servant can perform tasks that a human could perform, but they can't attack or take any action that would directly harm another creature. Thus the servants can fetch things, clean, mend, fold clothes, light fires, serve food, pour wine, and so on. The servants can't leave the dwelling."},{"type":"text","content":"When the spell ends, any creatures or objects left inside the extradimensional space are expelled into the unoccupied spaces nearest to the entrance."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":300},{"name":"Mordenkainen's Private Sanctum","source":"XPHB","level":4,"school":"A","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a thin sheet of lead"},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"You make an area within range magically secure. The area is a <i>Cube [Area of Effect]</i> that can be as small as 5 feet to as large as 100 feet on each side. The spell lasts for the duration."},{"type":"text","content":"When you cast the spell, you decide what sort of security the spell provides, choosing any of the following properties:"},{"type":"list","items":["Sound can't pass through the barrier at the edge of the warded area.","The barrier of the warded area appears dark and foggy, preventing vision (including <i>Darkvision</i>) through it.","Sensors created by Divination spells can't appear inside the protected area or pass through the barrier at its perimeter.","Creatures in the area can't be targeted by Divination spells.","Nothing can teleport into or out of the warded area.","Planar travel is blocked within the warded area."]},{"type":"text","content":"Casting this spell on the same spot every day for 365 days makes the spell last until dispelled."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can increase the size of the <i>Cube [Area of Effect]</i> by 100 feet for each spell slot level above 4."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":301},{"name":"Mordenkainen's Sword","source":"XPHB","level":7,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"a miniature sword worth 250+ GP","cost":25000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a spectral sword that hovers within range. It lasts for the duration."},{"type":"text","content":"When the sword appears, you make a melee spell attack against a target within 5 feet of the sword. On a hit, the target takes Force damage equal to <span class=\\"text-red-400 font-semibold\\">4d12</span> plus your spellcasting ability modifier."},{"type":"text","content":"On your later turns, you can take a <i>Bonus Action</i> to move the sword up to 30 feet to a spot you can see and repeat the attack against the same target or a different one."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":302},{"name":"Move Earth","source":"XPHB","level":6,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a miniature shovel"},"duration":[{"type":"timed","duration":{"type":"hour","amount":2},"concentration":true}],"entries":[{"type":"text","content":"Choose an area of terrain no larger than 40 feet on a side within range. You can reshape dirt, sand, or clay in the area in any manner you choose for the duration. You can raise or lower the area's elevation, create or fill in a trench, erect or flatten a wall, or form a pillar. The extent of any such changes can't exceed half the area's largest dimension. For example, if you affect a 40-foot square, you can create a pillar up to 20 feet high, raise or lower the square's elevation by up to 20 feet, dig a trench up to 20 feet deep, and so on. It takes 10 minutes for these changes to complete. Because the terrain's transformation occurs slowly, creatures in the area can't usually be trapped or injured by the ground's movement."},{"type":"text","content":"At the end of every 10 minutes you spend <i>Concentration</i> on the spell, you can choose a new area of terrain to affect within range."},{"type":"text","content":"This spell can't manipulate natural stone or stone construction. Rocks and structures shift to accommodate the new terrain. If the way you shape the terrain would make a structure unstable, it might collapse."},{"type":"text","content":"Similarly, this spell doesn't directly affect plant growth. The moved earth carries any plants along with it."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":302},{"name":"Nondetection","source":"XPHB","level":3,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a pinch of diamond dust worth 25+ GP, which the spell consumes","cost":2500,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"For the duration, you hide a target that you touch from Divination spells. The target can be a willing creature, or it can be a place or an object no larger than 10 feet in any dimension. The target can't be targeted by any Divination spell or perceived through magical scrying sensors."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":302},{"name":"Nystul's Magic Aura","source":"XPHB","level":2,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a small square of silk"},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"With a touch, you place an illusion on a willing creature or an object that isn't being worn or carried. A creature gains the Mask effect below, and an object gains the False Aura effect below. The effect lasts for the duration. If you cast the spell on the same target every day for 30 days, the illusion lasts until dispelled."},{"type":"section","name":"Mask (Creature)","entries":[{"type":"text","content":"Choose a creature type other than the target's actual type. Spells and other magical effects treat the target as if it were a creature of the chosen type."}]},{"type":"section","name":"False Aura (Object)","entries":[{"type":"text","content":"You change the way the target appears to spells and magical effects that detect magical auras, such as <a href=\\"/spells?search=Detect Magic\\" class=\\"text-dnd-gold hover:underline\\">Detect Magic</a>. You can make a nonmagical object appear magical, make a magic item appear nonmagical, or change the object's aura so that it appears to belong to a school of magic you choose."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":302},{"name":"Otiluke's Freezing Sphere","source":"XPHB","level":6,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":300}},"components":{"v":true,"s":true,"m":"a miniature crystal sphere"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A frigid globe streaks from you to a point of your choice within range, where it explodes in a 60-foot-radius <i>Sphere [Area of Effect]</i>. Each creature in that area makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">10d6</span> Cold damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"If the globe strikes a body of water, it freezes the water to a depth of 6 inches over an area 30 feet square. This ice lasts for 1 minute. Creatures that were swimming on the surface of frozen water are trapped in the ice and have the <i class=\\"text-dnd-gold\\">Restrained</i> condition. A trapped creature can take an action to make a Strength (<i>Athletics</i>) check against your spell save DC to break free."},{"type":"text","content":"You can refrain from firing the globe after completing the spell's casting. If you do so, a globe about the size of a sling bullet, cool to the touch, appears in your hand. At any time, you or a creature you give the globe to can throw the globe (to a range of 40 feet) or hurl it with a sling (to the sling's normal range). It shatters on impact, with the same effect as a normal casting of the spell. You can also set the globe down without shattering it. After 1 minute, if the globe hasn't already shattered, it explodes."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 10d6 for each spell slot level above 6."}]}],"damageInflict":["cold"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":302},{"name":"Otiluke's Resilient Sphere","source":"XPHB","level":4,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a glass sphere"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A shimmering sphere encloses a Large or smaller creature or object within range. An unwilling creature must succeed on a Dexterity saving throw or be enclosed for the duration."},{"type":"text","content":"Nothing—not physical objects, energy, or other spell effects—can pass through the barrier, in or out, though a creature in the sphere can breathe there. The sphere is immune to all damage, and a creature or object inside can't be damaged by attacks or effects originating from outside, nor can a creature inside the sphere damage anything outside it."},{"type":"text","content":"The sphere is weightless and just large enough to contain the creature or object inside. An enclosed creature can take an action to push against the sphere's walls and thus roll the sphere at up to half the creature's <i>Speed</i>. Similarly, the globe can be picked up and moved by other creatures."},{"type":"text","content":"A <a href=\\"/spells?search=Disintegrate\\" class=\\"text-dnd-gold hover:underline\\">Disintegrate</a> spell targeting the globe destroys it without harming anything inside."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":303},{"name":"Otto's Irresistible Dance","source":"XPHB","level":6,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"One creature that you can see within range must make a Wisdom saving throw. On a successful save, the target dances comically until the end of its next turn, during which it must spend all its movement to dance in place."},{"type":"text","content":"On a failed save, the target has the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration. While <i class=\\"text-dnd-gold\\">Charmed</i>, the target dances comically, must use all its movement to dance in place, and has <i>Disadvantage</i> on Dexterity saving throws and attack rolls, and other creatures have <i>Advantage</i> on attack rolls against it. On each of its turns, the target can take an action to collect itself and repeat the save, ending the spell on itself on a success."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":303},{"name":"Pass without Trace","source":"XPHB","level":2,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"ashes from burned mistletoe"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You radiate a concealing aura in a 30-foot <i>Emanation [Area of Effect]</i> for the duration. While in the aura, you and each creature you choose have a +10 bonus to Dexterity (<i>Stealth</i>) checks and leave no tracks."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":303},{"name":"Passwall","source":"XPHB","level":5,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a pinch of sesame seeds"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"A passage appears at a point that you can see on a wooden, plaster, or stone surface (such as a wall, ceiling, or floor) within range and lasts for the duration. You choose the opening's dimensions: up to 5 feet wide, 8 feet tall, and 20 feet deep. The passage creates no instability in a structure surrounding it."},{"type":"text","content":"When the opening disappears, any creatures or objects still in the passage created by the spell are safely ejected to an unoccupied space nearest to the surface on which you cast the spell."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":304},{"name":"Phantasmal Force","source":"XPHB","level":2,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a bit of fleece"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You attempt to craft an illusion in the mind of a creature you can see within range. The target makes an Intelligence saving throw. On a failed save, you create a phantasmal object, creature, or other phenomenon that is no larger than a 10-foot <i>Cube [Area of Effect]</i> and that is perceivable only to the target for the duration. The phantasm includes sound, temperature, and other stimuli."},{"type":"text","content":"The target can take a <b>Study</b> action to examine the phantasm with an Intelligence (<i>Investigation</i>) check against your spell save DC. If the check succeeds, the target realizes that the phantasm is an illusion, and the spell ends."},{"type":"text","content":"While affected by the spell, the target treats the phantasm as if it were real and rationalizes any illogical outcomes from interacting with it. For example, if the target steps through a phantasmal bridge and survives the fall, it believes the bridge exists and something else caused it to fall."},{"type":"text","content":"An affected target can even take damage from the illusion if the phantasm represents a dangerous creature or hazard. On each of your turns, such a phantasm can deal <span class=\\"text-red-400 font-semibold\\">2d8</span> Psychic damage to the target if it is in the phantasm's area or within 5 feet of the phantasm. The target perceives the damage as a type appropriate to the illusion."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":304},{"name":"Phantasmal Killer","source":"XPHB","level":4,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You tap into the nightmares of a creature you can see within range and create an illusion of its deepest fears, visible only to that creature. The target makes a Wisdom saving throw. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">4d10</span> Psychic damage and has <i>Disadvantage</i> on ability checks and attack rolls for the duration. On a successful save, the target takes half as much damage, and the spell ends."},{"type":"text","content":"For the duration, the target makes a Wisdom saving throw at the end of each of its turns. On a failed save, it takes the Psychic damage again. On a successful save, the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 4d10 for each spell slot level above 4."}]}],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":304},{"name":"Phantom Steed","source":"XPHB","level":3,"school":"I","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"A Large, quasi-real, horselike creature appears on the ground in an unoccupied space of your choice within range. You decide the creature's appearance, and it is equipped with a saddle, bit, and bridle. Any of the equipment created by the spell vanishes in a puff of smoke if it is carried more than 10 feet away from the steed."},{"type":"text","content":"For the duration, you or a creature you choose can ride the steed. The steed uses the <b>Riding Horse</b> stat block, except it has a <i>Speed</i> of 100 feet and can travel 13 miles in an hour. When the spell ends, the steed gradually fades, giving the rider 1 minute to dismount. The spell ends early if the steed takes any damage."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":304},{"name":"Planar Ally","source":"XPHB","level":6,"school":"C","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You beseech an otherworldly entity for aid. The being must be known to you: a god, a demon prince, or some other being of cosmic power. That entity sends a <i>Celestial</i>, an <i>Elemental</i>, or a <i>Fiend</i> loyal to it to aid you, making the creature appear in an unoccupied space within range. If you know a specific creature's name, you can speak that name when you cast this spell to request that creature, though you might get a different creature anyway (DM's choice)."},{"type":"text","content":"When the creature appears, it is under no compulsion to behave a particular way. You can ask it to perform a service in exchange for payment, but it isn't obliged to do so. The requested task could range from simple (fly us across the chasm, or help us fight a battle) to complex (spy on our enemies, or protect us during our foray into the dungeon). You must be able to communicate with the creature to bargain for its services."},{"type":"text","content":"Payment can take a variety of forms. A Celestial might require a sizable donation of gold or magic items to an allied temple, while a Fiend might demand a living sacrifice or a gift of treasure. Some creatures might exchange their service for a quest undertaken by you."},{"type":"text","content":"A task that can be measured in minutes requires a payment worth 100 GP per minute. A task measured in hours requires 1,000 GP per hour. And a task measured in days (up to 10 days) requires 10,000 GP per day. The DM can adjust these payments based on the circumstances under which you cast the spell. If the task is aligned with the creature's ethos, the payment might be halved or even waived. Nonhazardous tasks typically require only half the suggested payment, while especially dangerous tasks might require a greater gift. Creatures rarely accept tasks that seem suicidal."},{"type":"text","content":"After the creature completes the task, or when the agreed-upon duration of service expires, the creature returns to its home plane after reporting back to you if possible. If you are unable to agree on a price for the creature's service, the creature immediately returns to its home plane."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":304},{"name":"Planar Binding","source":"XPHB","level":5,"school":"A","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"a jewel worth 1,000+ GP, which the spell consumes","cost":100000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"You attempt to bind a Celestial, an Elemental, a Fey, or a Fiend to your service. The creature must be within range for the entire casting of the spell. (Typically, the creature is first summoned into the center of the inverted version of the <a href=\\"/spells?search=Magic Circle\\" class=\\"text-dnd-gold hover:underline\\">Magic Circle</a> spell to trap it while this spell is cast.) At the completion of the casting, the target must succeed on a Charisma saving throw or be bound to serve you for the duration. If the creature was summoned or created by another spell, that spell's duration is extended to match the duration of this spell."},{"type":"text","content":"A bound creature must follow your commands to the best of its ability. You might command the creature to accompany you on an adventure, to guard a location, or to deliver a message. If the creature is <i>Hostile [Attitude]</i>, it strives to twist your commands to achieve its own objectives. If the creature carries out your commands completely before the spell ends, it travels to you to report this fact if you are on the same plane of existence. If you are on a different plane, it returns to the place where you bound it and remains there until the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The duration increases with a spell slot of level 6 (10 days), 7 (30 days), 8 (180 days), and 9 (366 days)."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":["charisma"],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":305},{"name":"Plane Shift","source":"XPHB","level":7,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a forked, metal rod worth 250+ GP and attuned to a plane of existence","cost":25000}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You and up to eight willing creatures who link hands in a circle are transported to a different plane of existence. You can specify a target destination in general terms, such as the City of Brass on the Elemental Plane of Fire or the palace of Dispater on the second level of the Nine Hells, and you appear in or near that destination, as determined by the DM."},{"type":"text","content":"Alternatively, if you know the sigil sequence of a teleportation circle on another plane of existence, this spell can take you to that circle. If the teleportation circle is too small to hold all the creatures you transported, they appear in the closest unoccupied spaces next to the circle."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":305},{"name":"Plant Growth","source":"XPHB","level":3,"school":"T","time":[{"number":1,"unit":"action","note":"Overgrowth"},{"number":8,"unit":"hour","note":"Enrichment"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"This spell channels vitality into plants. The casting time you use determines whether the spell has the Overgrowth or the Enrichment effect below."},{"type":"section","name":"Overgrowth","entries":[{"type":"text","content":"Choose a point within range. All normal plants in a 100-foot-radius <i>Sphere [Area of Effect]</i> centered on that point become thick and overgrown. A creature moving through that area must spend 4 feet of movement for every 1 foot it moves. You can exclude one or more areas of any size within the spell's area from being affected."}]},{"type":"section","name":"Enrichment","entries":[{"type":"text","content":"All plants in a half-mile radius centered on a point within range become enriched for 365 days. The plants yield twice the normal amount of food when harvested. They can benefit from only one Plant Growth per year."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":305},{"name":"Poison Spray","source":"XPHB","level":0,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You spray toxic mist at a creature within range. Make a ranged spell attack against the target. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">1d12</span> Poison damage."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d12</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d12</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d12</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d12</span>)."}]}],"damageInflict":["poison"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":306},{"name":"Polymorph","source":"XPHB","level":4,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a caterpillar cocoon"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You attempt to transform a creature that you can see within range into a Beast. The target must succeed on a Wisdom saving throw or shape-shift into Beast form for the duration. That form can be any <i>Beast</i> you choose that has a <i>Challenge Rating</i> equal to or less than the target's (or the target's level if it doesn't have a <i>Challenge Rating</i>). The target's game statistics are replaced by the stat block of the chosen Beast, but the target retains its alignment, personality, creature type, <i>Hit Points</i>, and <i>Hit Point Dice</i>."},{"type":"text","content":"The target gains a number of <i>Temporary Hit Points</i> equal to the <i>Hit Points</i> of the Beast form. These <i>Temporary Hit Points</i> vanish if any remain when the spell ends. The spell ends early on the target if it has no <i>Temporary Hit Points</i> left."},{"type":"text","content":"The target is limited in the actions it can perform by the anatomy of its new form, and it can't speak or cast spells."},{"type":"text","content":"The target's gear melds into the new form. The creature can't use or otherwise benefit from any of that equipment."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":306},{"name":"Power Word Heal","source":"XPHB","level":9,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A wave of healing energy washes over one creature you can see within range. The target regains all its <i>Hit Points</i>. If the creature has the <i class=\\"text-dnd-gold\\">Charmed</i>, <i class=\\"text-dnd-gold\\">Frightened</i>, <i class=\\"text-dnd-gold\\">Paralyzed</i>, <i class=\\"text-dnd-gold\\">Poisoned</i>, or <i class=\\"text-dnd-gold\\">Stunned</i> condition, the condition ends. If the creature has the <i class=\\"text-dnd-gold\\">Prone</i> condition, it can use its <i>Reaction</i> to stand up."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":306},{"name":"Power Word Kill","source":"XPHB","level":9,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You compel one creature you can see within range to die. If the target has 100 <i>Hit Points</i> or fewer, it dies. Otherwise, it takes <span class=\\"text-red-400 font-semibold\\">12d12</span> Psychic damage."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":306},{"name":"Power Word Stun","source":"XPHB","level":8,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You overwhelm the mind of one creature you can see within range. If the target has 150 <i>Hit Points</i> or fewer, it has the <i class=\\"text-dnd-gold\\">Stunned</i> condition. Otherwise, its <i>Speed</i> is 0 until the start of your next turn."},{"type":"text","content":"The <i class=\\"text-dnd-gold\\">Stunned</i> target makes a Constitution saving throw at the end of each of its turns, ending the condition on itself on a success."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["stunned"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":306},{"name":"Prayer of Healing","source":"XPHB","level":2,"school":"A","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Up to five creatures of your choice who remain within range for the spell's entire casting gain the benefits of a <i>Short Rest</i> and also regain <span class=\\"text-green-400 font-mono\\">2d8</span> <i>Hit Points</i>. A creature can't be affected by this spell again until that creature finishes a <i>Long Rest</i>."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The healing increases by 2d8 for each spell slot level above 2."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":307},{"name":"Prestidigitation","source":"XPHB","level":0,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You create a magical effect within range. Choose the effect from the options below. If you cast this spell multiple times, you can have up to three of its non-instantaneous effects active at a time."},{"type":"section","name":"Sensory Effect","entries":[{"type":"text","content":"You create an instantaneous, harmless sensory effect, such as a shower of sparks, a puff of wind, faint musical notes, or an odd odor."}]},{"type":"section","name":"Fire Play","entries":[{"type":"text","content":"You instantaneously light or snuff out a candle, a torch, or a small campfire."}]},{"type":"section","name":"Clean or Soil","entries":[{"type":"text","content":"You instantaneously clean or soil an object no larger than 1 cubic foot."}]},{"type":"section","name":"Minor Sensation","entries":[{"type":"text","content":"You chill, warm, or flavor up to 1 cubic foot of nonliving material for 1 hour."}]},{"type":"section","name":"Magic Mark","entries":[{"type":"text","content":"You make a color, a small mark, or a symbol appear on an object or a surface for 1 hour."}]},{"type":"section","name":"Minor Creation","entries":[{"type":"text","content":"You create a nonmagical trinket or an illusory image that can fit in your hand. It lasts until the end of your next turn. A trinket can deal no damage and has no monetary worth."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":307},{"name":"Prismatic Spray","source":"XPHB","level":7,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"cone","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Eight rays of light flash from you in a 60-foot <i>Cone [Area of Effect]</i>. Each creature in the <i>Cone [Area of Effect]</i> makes a Dexterity saving throw. For each target, roll <span class=\\"text-green-400 font-mono\\">1d8</span> to determine which color ray affects it, consulting the Prismatic Rays table."},{"type":"table","caption":"Prismatic Rays","colLabels":["1d8","Ray"],"rows":[["1","<b>Red.</b> <i>Failed Save:</i> <span class=\\"text-red-400 font-semibold\\">12d6</span> Fire damage. <i>Successful Save:</i> Half as much damage."],["2","<b>Orange.</b> <i>Failed Save:</i> <span class=\\"text-red-400 font-semibold\\">12d6</span> Acid damage. <i>Successful Save:</i> Half as much damage."],["3","<b>Yellow.</b> <i>Failed Save:</i> <span class=\\"text-red-400 font-semibold\\">12d6</span> Lightning damage. <i>Successful Save:</i> Half as much damage."],["4","<b>Green.</b> <i>Failed Save:</i> <span class=\\"text-red-400 font-semibold\\">12d6</span> Poison damage. <i>Successful Save:</i> Half as much damage."],["5","<b>Blue.</b> <i>Failed Save:</i> <span class=\\"text-red-400 font-semibold\\">12d6</span> Cold damage. <i>Successful Save:</i> Half as much damage."],["6","<b>Indigo.</b> <i>Failed Save:</i> The target has the <i class=\\"text-dnd-gold\\">Restrained</i> condition and makes a Constitution saving throw at the end of each of its turns. If it successfully saves three times, the condition ends. If it fails three times, it has the <i class=\\"text-dnd-gold\\">Petrified</i> condition until it is freed by an effect like the <a href=\\"/spells?search=Greater Restoration\\" class=\\"text-dnd-gold hover:underline\\">Greater Restoration</a> spell. The successes and failures needn't be consecutive; keep track of both until the target collects three of a kind."],["7","<b>Violet.</b> <i>Failed Save:</i> The target has the <i class=\\"text-dnd-gold\\">Blinded</i> condition and makes a Wisdom saving throw at the start of your next turn. On a successful save, the condition ends. On a failed save, the condition ends, and the creature teleports to another plane of existence (DM's choice)."],["8","<b>Special.</b> The target is struck by two rays. Roll twice, rerolling any 8."]]}],"entriesHigherLevel":[],"damageInflict":["acid","cold","fire","lightning","poison"],"conditionInflict":["blinded","petrified","restrained"],"savingThrow":["dexterity","constitution","wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":307},{"name":"Prismatic Wall","source":"XPHB","level":9,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10}}],"entries":[{"type":"text","content":"A shimmering, multicolored plane of light forms a vertical opaque wall—up to 90 feet long, 30 feet high, and 1 inch thick—centered on a point within range. Alternatively, you shape the wall into a globe up to 30 feet in diameter centered on a point within range. The wall lasts for the duration. If you position the wall in a space occupied by a creature, the spell ends instantly without effect."},{"type":"text","content":"The wall sheds <i>Bright Light</i> within 100 feet and <i>Dim Light</i> for an additional 100 feet. You and creatures you designate when you cast the spell can pass through and be near the wall without harm. If another creature that can see the wall moves within 20 feet of it or starts its turn there, the creature must succeed on a Constitution saving throw or have the <i class=\\"text-dnd-gold\\">Blinded</i> condition for 1 minute."},{"type":"text","content":"The wall consists of seven layers, each with a different color. When a creature reaches into or passes through the wall, it does so one layer at a time through all the layers. Each layer forces the creature to make a Dexterity saving throw or be affected by that layer's properties as described in the Prismatic Layers table."},{"type":"text","content":"The wall, which has AC 10, can be destroyed one layer at a time, in order from red to violet, by means specific to each layer. If a layer is destroyed, it is gone for the duration. <a href=\\"/spells?search=Antimagic Field\\" class=\\"text-dnd-gold hover:underline\\">Antimagic Field</a> has no effect on the wall, and <a href=\\"/spells?search=Dispel Magic\\" class=\\"text-dnd-gold hover:underline\\">Dispel Magic</a> can affect only the violet layer."},{"type":"table","caption":"Prismatic Layers","colLabels":["Order","Effects"],"rows":[["1","<b>Red.</b> <i>Failed Save:</i> <span class=\\"text-red-400 font-semibold\\">12d6</span> Fire damage. <i>Successful Save:</i> Half as much damage. <i>Additional Effects</i>: Nonmagical ranged attacks can't pass through this layer, which is destroyed if it takes at least 25 Cold damage."],["2","<b>Orange.</b> <i>Failed Save:</i> <span class=\\"text-red-400 font-semibold\\">12d6</span> Acid damage. <i>Successful Save:</i> Half as much damage. <i>Additional Effects:</i> Magical ranged attacks can't pass through this layer, which is destroyed by a strong wind (such as the one created by <a href=\\"/spells?search=Gust of Wind\\" class=\\"text-dnd-gold hover:underline\\">Gust of Wind</a>)."],["3","<b>Yellow.</b> <i>Failed Save:</i> <span class=\\"text-red-400 font-semibold\\">12d6</span> Lightning damage. <i>Successful Save:</i> Half as much damage. <i>Additional Effects:</i> The layer is destroyed if it takes at least 60 Force damage."],["4","<b>Green.</b> <i>Failed Save:</i> <span class=\\"text-red-400 font-semibold\\">12d6</span> Poison damage. <i>Successful Save:</i> Half as much damage. <i>Additional Effects:</i> A <a href=\\"/spells?search=Passwall\\" class=\\"text-dnd-gold hover:underline\\">Passwall</a> spell, or another spell of equal or greater level that can open a portal on a solid surface, destroys this layer."],["5","<b>Blue.</b> <i>Failed Save:</i> <span class=\\"text-red-400 font-semibold\\">12d6</span> Cold damage. <i>Successful Save:</i> Half as much damage. <i>Additional Effects:</i> The layer is destroyed if it takes at least 25 Fire damage."],["6","<b>Indigo.</b> <i>Failed Save:</i> The target has the <i class=\\"text-dnd-gold\\">Restrained</i> condition and makes a Constitution saving throw at the end of each of its turns. If it successfully saves three times, the condition ends. If it fails three times, it has the <i class=\\"text-dnd-gold\\">Petrified</i> condition until it is freed by an effect like the <a href=\\"/spells?search=Greater Restoration\\" class=\\"text-dnd-gold hover:underline\\">Greater Restoration</a> spell. The successes and failures needn't be consecutive; keep track of both until the target collects three of a kind. <i>Additional Effects:</i> Spells can't be cast through this layer, which is destroyed by <i>Bright Light</i> shed by the <a href=\\"/spells?search=Daylight\\" class=\\"text-dnd-gold hover:underline\\">Daylight</a> spell."],["7","<b>Violet.</b> <i>Failed Save:</i> The target has the <i class=\\"text-dnd-gold\\">Blinded</i> condition and makes a Wisdom saving throw at the start of your next turn. On a successful save, the condition ends. On a failed save, the condition ends, and the creature teleports to another plane of existence (DM's choice). <i>Additional Effects:</i> This layer is destroyed by <a href=\\"/spells?search=Dispel Magic\\" class=\\"text-dnd-gold hover:underline\\">Dispel Magic</a>."]]}],"entriesHigherLevel":[],"damageInflict":["acid","cold","fire","force","lightning","poison"],"conditionInflict":["blinded","petrified","restrained"],"savingThrow":["constitution","dexterity","wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":308},{"name":"Produce Flame","source":"XPHB","level":0,"school":"C","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10}}],"entries":[{"type":"text","content":"A flickering flame appears in your hand and remains there for the duration. While there, the flame emits no heat and ignites nothing, and it sheds <i>Bright Light</i> in a 20-foot radius and <i>Dim Light</i> for an additional 20 feet. The spell ends if you cast it again."},{"type":"text","content":"Until the spell ends, you can take a <b>Magic</b> action to hurl fire at a creature or an object within 60 feet of you. Make a ranged spell attack. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">1d8</span> Fire damage."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d8</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d8</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d8</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d8</span>)."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":308},{"name":"Programmed Illusion","source":"XPHB","level":6,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":{"text":"jade dust worth 25+ GP","cost":2500}},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"You create an illusion of an object, a creature, or some other visible phenomenon within range that activates when a specific trigger occurs. The illusion is imperceptible until then. It must be no larger than a 30-foot <i>Cube [Area of Effect]</i>, and you decide when you cast the spell how the illusion behaves and what sounds it makes. This scripted performance can last up to 5 minutes."},{"type":"text","content":"When the trigger you specify occurs, the illusion springs into existence and performs in the manner you described. Once the illusion finishes performing, it disappears and remains dormant for 10 minutes, after which the illusion can be activated again."},{"type":"text","content":"The trigger can be as general or as detailed as you like, though it must be based on visual or audible phenomena that occur within 30 feet of the area. For example, you could create an illusion of yourself to appear and warn off others who attempt to open a trapped door."},{"type":"text","content":"Physical interaction with the image reveals it to be illusory, since things can pass through it. A creature that takes the <b>Study</b> action to examine the image can determine that it is an illusion with a successful Intelligence (<i>Investigation</i>) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":309},{"name":"Project Image","source":"XPHB","level":7,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"miles","amount":500}},"components":{"v":true,"s":true,"m":{"text":"a statuette of yourself worth 5+ GP","cost":500}},"duration":[{"type":"timed","duration":{"type":"day","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create an illusory copy of yourself that lasts for the duration. The copy can appear at any location within range that you have seen before, regardless of intervening obstacles. The illusion looks and sounds like you, but it is intangible. If the illusion takes any damage, it disappears, and the spell ends."},{"type":"text","content":"You can see through the illusion's eyes and hear through its ears as if you were in its space. As a <b>Magic</b> action, you can move it up to 60 feet and make it gesture, speak, and behave in whatever way you choose. It mimics your mannerisms perfectly."},{"type":"text","content":"Physical interaction with the image reveals it to be illusory, since things can pass through it. A creature that takes the <b>Study</b> action to examine the image can determine that it is an illusion with a successful Intelligence (<i>Investigation</i>) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":309},{"name":"Protection from Energy","source":"XPHB","level":3,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"For the duration, the willing creature you touch has <i>Resistance</i> to one damage type of your choice: Acid, Cold, Fire, Lightning, or Thunder."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":309},{"name":"Protection from Evil and Good","source":"XPHB","level":1,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a flask of Holy Water worth 25+ GP, which the spell consumes","cost":2500,"consume":true}},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Until the spell ends, one willing creature you touch is protected against creatures that are Aberrations, Celestials, Elementals, Fey, Fiends, or Undead. The protection grants several benefits. Creatures of those types have <i>Disadvantage</i> on attack rolls against the target. The target also can't be possessed by or gain the <i class=\\"text-dnd-gold\\">Charmed</i> or <i class=\\"text-dnd-gold\\">Frightened</i> conditions from them. If the target is already possessed, <i class=\\"text-dnd-gold\\">Charmed</i>, or <i class=\\"text-dnd-gold\\">Frightened</i> by such a creature, the target has <i>Advantage</i> on any new saving throw against the relevant effect."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":309},{"name":"Protection from Poison","source":"XPHB","level":2,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You touch a creature and end the <i class=\\"text-dnd-gold\\">Poisoned</i> condition on it. For the duration, the target has <i>Advantage</i> on saving throws to avoid or end the <i class=\\"text-dnd-gold\\">Poisoned</i> condition, and it has <i>Resistance</i> to Poison damage."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":310},{"name":"Purify Food and Drink","source":"XPHB","level":1,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You remove poison and rot from nonmagical food and drink in a 5-foot-radius <i>Sphere [Area of Effect]</i> centered on a point within range."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":310},{"name":"Raise Dead","source":"XPHB","level":5,"school":"N","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a diamond worth 500+ GP, which the spell consumes","cost":50000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"With a touch, you revive a dead creature if it has been dead no longer than 10 days and it wasn't Undead when it died."},{"type":"text","content":"The creature returns to life with 1 <i>Hit Points</i>. This spell also neutralizes any poisons that affected the creature at the time of death."},{"type":"text","content":"This spell closes all mortal wounds, but it doesn't restore missing body parts. If the creature is lacking body parts or organs integral for its survival—its head, for instance—the spell automatically fails."},{"type":"text","content":"Coming back from the dead is an ordeal. The target takes a -4 penalty to <i>D20 Test</i>. Every time the target finishes a <i>Long Rest</i>, the penalty is reduced by 1 until it becomes 0."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":310},{"name":"Rary's Telepathic Bond","source":"XPHB","level":5,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"two eggs"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You forge a telepathic link among up to eight willing creatures of your choice within range, psychically linking each creature to all the others for the duration. Creatures that can't communicate in any languages aren't affected by this spell."},{"type":"text","content":"Until the spell ends, the targets can communicate telepathically through the bond whether or not they share a language. The communication is possible over any distance, though it can't extend to other planes of existence."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":311},{"name":"Ray of Enfeeblement","source":"XPHB","level":2,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A beam of enervating energy shoots from you toward a creature within range. The target must make a Constitution saving throw. On a successful save, the target has <i>Disadvantage</i> on the next attack roll it makes until the start of your next turn."},{"type":"text","content":"On a failed save, the target has <i>Disadvantage</i> on Strength-based <i>D20 Test</i> for the duration. During that time, it also subtracts <span class=\\"text-green-400 font-mono\\">1d8</span> from all its damage rolls. The target repeats the save at the end of each of its turns, ending the spell on a success."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":311},{"name":"Ray of Frost","source":"XPHB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A frigid beam of blue-white light streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes <span class=\\"text-red-400 font-semibold\\">1d8</span> Cold damage, and its <i>Speed</i> is reduced by 10 feet until the start of your next turn."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d8</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d8</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d8</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d8</span>)."}]}],"damageInflict":["cold"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":311},{"name":"Ray of Sickness","source":"XPHB","level":1,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You shoot a greenish ray at a creature within range. Make a ranged spell attack against the target. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">2d8</span> Poison damage and has the <i class=\\"text-dnd-gold\\">Poisoned</i> condition until the end of your next turn."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d8 for each spell slot level above 1."}]}],"damageInflict":["poison"],"conditionInflict":["poisoned"],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":311},{"name":"Regenerate","source":"XPHB","level":7,"school":"T","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a prayer wheel"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"A creature you touch regains <span class=\\"text-green-400 font-mono\\">4d8 + 15</span> <i>Hit Points</i>. For the duration, the target regains 1 <i>Hit Points</i> at the start of each of its turns, and any severed body parts regrow after 2 minutes."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":311},{"name":"Reincarnate","source":"XPHB","level":5,"school":"N","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"rare oils worth 1,000+ GP, which the spell consumes","cost":100000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You touch a dead Humanoid or a piece of one. If the creature has been dead no longer than 10 days, the spell forms a new body for it and calls the soul to enter that body. Roll <span class=\\"text-green-400 font-mono\\">1d10</span> and consult the table below to determine the body's species, or the DM chooses another playable species."},{"type":"table","caption":"","colLabels":["1d10","Species"],"rows":[["1","<b>Aasimar</b>"],["2","<b>Dragonborn</b>"],["3","<b>Dwarf</b>"],["4","<b>Elf</b>"],["5","<b>Gnome</b>"],["6","<b>Goliath</b>"],["7","<b>Halfling</b>"],["8","<b>Human</b>"],["9","<b>Orc</b>"],["10","<b>Tiefling</b>"]]},{"type":"text","content":"The reincarnated creature makes any choices that a species' description offers, and the creature recalls its former life. It retains the capabilities it had in its original form, except it loses the traits of its previous species and gains the traits of its new one."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":311},{"name":"Remove Curse","source":"XPHB","level":3,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains, but the spell breaks its owner's <i>Attunement</i> to the object so it can be removed or discarded."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":312},{"name":"Resistance","source":"XPHB","level":0,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You touch a willing creature and choose a damage type: Acid, Bludgeoning, Cold, Fire, Lightning, Necrotic, Piercing, Poison, Radiant, Slashing, or Thunder. When the creature takes damage of the chosen type before the spell ends, the creature reduces the total damage taken by <span class=\\"text-green-400 font-mono\\">1d4</span>. A creature can benefit from this spell only once per turn."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":312},{"name":"Resurrection","source":"XPHB","level":7,"school":"N","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a diamond worth 1,000+ GP, which the spell consumes","cost":100000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"With a touch, you revive a dead creature that has been dead for no more than a century, didn't die of old age, and wasn't Undead when it died."},{"type":"text","content":"The creature returns to life with all its <i>Hit Points</i>. This spell also neutralizes any poisons that affected the creature at the time of death. This spell closes all mortal wounds and restores any missing body parts."},{"type":"text","content":"Coming back from the dead is an ordeal. The target takes a -4 penalty to <i>D20 Test</i>. Every time the target finishes a <i>Long Rest</i>, the penalty is reduced by 1 until it becomes 0."},{"type":"text","content":"Casting this spell to revive a creature that has been dead for 365 days or longer taxes you. Until you finish a <i>Long Rest</i>, you can't cast spells again, and you have <i>Disadvantage</i> on <i>D20 Test</i>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":312},{"name":"Reverse Gravity","source":"XPHB","level":7,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":100}},"components":{"v":true,"s":true,"m":"a lodestone and iron filings"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"This spell reverses gravity in a 50-foot-radius, 100-foot high <i>Cylinder [Area of Effect]</i> centered on a point within range. All creatures and objects in that area that aren't anchored to the ground fall upward and reach the top of the <i>Cylinder [Area of Effect]</i>. A creature can make a Dexterity saving throw to grab a fixed object it can reach, thus avoiding the fall upward."},{"type":"text","content":"If a ceiling or an anchored object is encountered in this upward fall, creatures and objects strike it just as they would during a downward fall. If an affected creature or object reaches the <i>Cylinder [Area of Effect]</i>'s top without striking anything, it hovers there for the duration. When the spell ends, affected objects and creatures fall downward."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":312},{"name":"Revivify","source":"XPHB","level":3,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a diamond worth 300+ GP, which the spell consumes","cost":30000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You touch a creature that has died within the last minute. That creature revives with 1 <i>Hit Points</i>. This spell can't revive a creature that has died of old age, nor does it restore any missing body parts."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":312},{"name":"Rope Trick","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a segment of rope"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You touch a rope. One end of it hovers upward until the rope hangs perpendicular to the ground or the rope reaches a ceiling. At the rope's upper end, an <i class=\\"text-dnd-gold\\">Invisible</i> 3-foot-by-5-foot portal opens to an extradimensional space that lasts until the spell ends. That space can be reached by climbing the rope, which can be pulled into or dropped out of it."},{"type":"text","content":"The space can hold up to eight Medium or smaller creatures. Attacks, spells, and other effects can't pass into or out of the space, but creatures inside it can see through the portal. Anything inside the space drops out when the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":312},{"name":"Sacred Flame","source":"XPHB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Flame-like radiance descends on a creature that you can see within range. The target must succeed on a Dexterity saving throw or take <span class=\\"text-red-400 font-semibold\\">1d8</span> Radiant damage. The target gains no benefit from <i>Cover</i> or Three-Quarters <i>Cover</i> for this save."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d8</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d8</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d8</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d8</span>)."}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":313},{"name":"Sanctuary","source":"XPHB","level":1,"school":"A","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a shard of glass from a mirror"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"You ward a creature within range. Until the spell ends, any creature who targets the warded creature with an attack roll or a damaging spell must succeed on a Wisdom saving throw or either choose a new target or lose the attack or spell. This spell doesn't protect the warded creature from areas of effect."},{"type":"text","content":"The spell ends if the warded creature makes an attack roll, casts a spell, or deals damage."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":313},{"name":"Scorching Ray","source":"XPHB","level":2,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You hurl three fiery rays. You can hurl them at one target within range or at several. Make a ranged spell attack for each ray. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">2d6</span> Fire damage."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You create one additional ray for each spell slot level above 2."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":313},{"name":"Scrying","source":"XPHB","level":5,"school":"D","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"a focus worth 1,000+ GP, such as a crystal ball, mirror, or water-filled font","cost":100000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You can see and hear a creature you choose that is on the same plane of existence as you. The target makes a Wisdom saving throw, which is modified (see the tables below) by how well you know the target and the sort of physical connection you have to it. The target doesn't know what it is making the save against, only that it feels uneasy."},{"type":"table","caption":"","colLabels":["Your Knowledge of the Target Is...","Save Modifier"],"rows":[["Secondhand (heard of the target)","+5"],["Firsthand (met the target)","+0"],["Extensive (know the target well)","-5"]]},{"type":"table","caption":"","colLabels":["You Have the Target's...","Save Modifier"],"rows":[["Picture or other likeness","-2"],["Garment or other possession","-4"],["Body part, lock of hair, or bit of nail","-10"]]},{"type":"text","content":"On a successful save, the target isn't affected, and you can't use this spell on it again for 24 hours."},{"type":"text","content":"On a failed save, the spell creates an <i class=\\"text-dnd-gold\\">Invisible</i>, intangible sensor within 10 feet of the target. You can see and hear through the sensor as if you were there. The sensor moves with the target, remaining within 10 feet of it for the duration. If something can see the sensor, it appears as a luminous orb about the size of your fist."},{"type":"text","content":"Instead of targeting a creature, you can target a location you have seen. When you do so, the sensor appears at that location and doesn't move."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"minute","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":313},{"name":"Searing Smite","source":"XPHB","level":1,"school":"V","time":[{"number":1,"unit":"bonus","condition":"which you take immediately after hitting a target with a Melee weapon or an {@variantrule Unarmed Strike|XPHB}"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"As you hit the target, it takes an extra <span class=\\"text-red-400 font-semibold\\">1d6</span> Fire damage from the attack. At the start of each of its turns until the spell ends, the target takes <span class=\\"text-red-400 font-semibold\\">1d6</span> Fire damage and then makes a Constitution saving throw. On a failed save, the spell continues. On a successful save, the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"All the damage increases by 1d6 for each spell slot level above 1."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":314},{"name":"See Invisibility","source":"XPHB","level":2,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a pinch of talc"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"For the duration, you see creatures and objects that have the <i class=\\"text-dnd-gold\\">Invisible</i> condition as if they were visible, and you can see into the Ethereal Plane. Creatures and objects there appear ghostly."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":314},{"name":"Seeming","source":"XPHB","level":5,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You give an illusory appearance to each creature of your choice that you can see within range. An unwilling target can make a Charisma saving throw, and if it succeeds, it is unaffected by this spell."},{"type":"text","content":"You can give the same appearance or different ones to the targets. The spell can change the appearance of the targets' bodies and equipment. You can make each creature seem 1 foot shorter or taller and appear heavier or lighter. A target's new appearance must have the same basic arrangement of limbs as the target, but the extent of the illusion is otherwise up to you. The spell lasts for the duration."},{"type":"text","content":"The changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to a creature's outfit, objects pass through the hat."},{"type":"text","content":"A creature that takes the <b>Study</b> action to examine a target can make an Intelligence (<i>Investigation</i>) check against your spell save DC. If it succeeds, it becomes aware that the target is disguised."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["charisma"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":314},{"name":"Sending","source":"XPHB","level":3,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"unlimited"}},"components":{"v":true,"s":true,"m":"a copper wire"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You send a short message of 25 words or fewer to a creature you have met or a creature described to you by someone who has met it. The target hears the message in its mind, recognizes you as the sender if it knows you, and can answer in a like manner immediately. The spell enables targets to understand the meaning of your message."},{"type":"text","content":"You can send the message across any distance and even to other planes of existence, but if the target is on a different plane than you, there is a 5% chance that the message doesn't arrive. You know if the delivery fails."},{"type":"text","content":"Upon receiving your message, a creature can block your ability to reach it again with this spell for 8 hours. If you try to send another message during that time, you learn that you are blocked, and the spell fails."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":314},{"name":"Sequester","source":"XPHB","level":7,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"gem dust worth 5,000+ GP, which the spell consumes","cost":500000,"consume":true}},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"With a touch, you magically sequester an object or a willing creature. For the duration, the target has the <i class=\\"text-dnd-gold\\">Invisible</i> condition and can't be targeted by Divination spells, detected by magic, or viewed remotely with magic."},{"type":"text","content":"If the target is a creature, it enters a state of suspended animation; it has the <i class=\\"text-dnd-gold\\">Unconscious</i> condition, doesn't age, and doesn't need food, water, or air."},{"type":"text","content":"You can set a condition for the spell to end early. The condition can be anything you choose, but it must occur or be visible within 1 mile of the target. Examples include \\"after 1,000 years\\" or \\"when the tarrasque awakens.\\" This spell also ends if the target takes any damage."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["invisible","unconscious"],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":315},{"name":"Shapechange","source":"XPHB","level":9,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"a jade circlet worth 1,500+ GP","cost":150000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You shape-shift into another creature for the duration or until you take a <b>Magic</b> action to shape-shift into a different eligible form. The new form must be of a creature that has a <i>Challenge Rating</i> no higher than your level or <i>Challenge Rating</i>. You must have seen the sort of creature before, and it can't be a Construct or an Undead."},{"type":"text","content":"When you cast the spell, you gain a number of <i>Temporary Hit Points</i> equal to the <i>Hit Points</i> of the first form into which you shape-shift. These <i>Temporary Hit Points</i> vanish if any remain when the spell ends."},{"type":"text","content":"Your game statistics are replaced by the stat block of the chosen form, but you retain your creature type; alignment; personality; Intelligence, Wisdom, and Charisma scores; <i>Hit Points</i>; <i>Hit Point Dice</i>; proficiencies; and ability to communicate. If you have the Spellcasting feature, you retain it too."},{"type":"text","content":"Upon shape-shifting, you determine whether your equipment drops to the ground or changes in size and shape to fit the new form while you're in it."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":315},{"name":"Shatter","source":"XPHB","level":2,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a chip of mica"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A loud noise erupts from a point of your choice within range. Each creature in a 10-foot-radius <i>Sphere [Area of Effect]</i> centered there makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">3d8</span> Thunder damage on a failed save or half as much damage on a successful one. A Construct has <i>Disadvantage</i> on the save."},{"type":"text","content":"A nonmagical object that isn't being worn or carried also takes the damage if it's in the spell's area."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d8 for each spell slot level above 2."}]}],"damageInflict":["thunder"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":316},{"name":"Shield","source":"XPHB","level":1,"school":"A","time":[{"number":1,"unit":"reaction","condition":"which you take when you are hit by an attack roll or targeted by the Magic Missile spell"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"round","amount":1}}],"entries":[{"type":"text","content":"An imperceptible barrier of magical force protects you. Until the start of your next turn, you have a +5 bonus to AC, including against the triggering attack, and you take no damage from <a href=\\"/spells?search=Magic Missile\\" class=\\"text-dnd-gold hover:underline\\">Magic Missile</a>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"reaction","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":316},{"name":"Shield of Faith","source":"XPHB","level":1,"school":"A","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a prayer scroll"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"A shimmering field surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":316},{"name":"Shillelagh","source":"XPHB","level":0,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"mistletoe"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"A Club or Quarterstaff you are holding is imbued with nature's power. For the duration, you can use your spellcasting ability instead of Strength for the attack and damage rolls of melee attacks using that weapon, and the weapon's damage die becomes a <span class=\\"text-green-400 font-mono\\">d8</span>. If the attack deals damage, it can be Force damage or the weapon's normal damage type (your choice)."},{"type":"text","content":"The spell ends early if you cast it again or if you let go of the weapon."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage die changes when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">d10</span>), 11 (<span class=\\"text-red-400 font-semibold\\">d12</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">2d6</span>)."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":316},{"name":"Shocking Grasp","source":"XPHB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Lightning springs from you to a creature that you try to touch. Make a melee spell attack against the target. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">1d8</span> Lightning damage, and it can't make <b>Opportunity Attack</b> until the start of its next turn."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d8</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d8</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d8</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d8</span>)."}]}],"damageInflict":["lightning"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":316},{"name":"Silence","source":"XPHB","level":2,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"For the duration, no sound can be created within or pass through a 20-foot-radius <i>Sphere [Area of Effect]</i> centered on a point you choose within range. Any creature or object entirely inside the <i>Sphere [Area of Effect]</i> has <i>Immunity</i> to Thunder damage, and creatures have the <i class=\\"text-dnd-gold\\">Deafened</i> condition while entirely inside it. Casting a spell that includes a Verbal component is impossible there."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["deafened"],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":316},{"name":"Silent Image","source":"XPHB","level":1,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a bit of fleece"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 15-foot <i>Cube [Area of Effect]</i>. The image appears at a spot within range and lasts for the duration. The image is purely visual; it isn't accompanied by sound, smell, or other sensory effects."},{"type":"text","content":"As a <b>Magic</b> action, you can cause the image to move to any spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking."},{"type":"text","content":"Physical interaction with the image reveals it to be an illusion, since things can pass through it. A creature that takes a <b>Study</b> action to examine the image can determine that it is an illusion with a successful Intelligence (<i>Investigation</i>) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":317},{"name":"Simulacrum","source":"XPHB","level":7,"school":"I","time":[{"number":12,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"powdered ruby worth 1,500+ GP, which the spell consumes","cost":150000,"consume":true}},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"You create a simulacrum of one Beast or Humanoid that is within 10 feet of you for the entire casting of the spell. You finish the casting by touching both the creature and a pile of ice or snow that is the same size as that creature, and the pile turns into the simulacrum, which is a creature. It uses the game statistics of the original creature at the time of casting, except it is a Construct, its <i>Hit Points</i> maximum is half as much, and it can't cast this spell."},{"type":"text","content":"The simulacrum is <i>Friendly [Attitude]</i> to you and creatures you designate. It obeys your commands and acts on your turn in combat. The simulacrum can't gain levels, and it can't take Short or Long Rests."},{"type":"text","content":"If the simulacrum takes damage, the only way to restore its <i>Hit Points</i> is to repair it as you take a <i>Long Rest</i>, during which you expend components worth 100 GP per <i>Hit Points</i> restored. The simulacrum must stay within 5 feet of you for the repair."},{"type":"text","content":"The simulacrum lasts until it drops to 0 <i>Hit Points</i>, at which point it reverts to snow and melts away. If you cast this spell again, any simulacrum you created with this spell is instantly destroyed."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":317},{"name":"Sleep","source":"XPHB","level":1,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a pinch of sand or rose petals"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Each creature of your choice in a 5-foot-radius <i>Sphere [Area of Effect]</i> centered on a point within range must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition until the end of its next turn, at which point it must repeat the save. If the target fails the second save, the target has the <i class=\\"text-dnd-gold\\">Unconscious</i> condition for the duration. The spell ends on a target if it takes damage or someone within 5 feet of it takes an action to shake it out of the spell's effect."},{"type":"text","content":"Creatures that don't sleep, such as elves, or that have <i>Immunity</i> to the <i class=\\"text-dnd-gold\\">Exhaustion</i> condition automatically succeed on saves against this spell."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["incapacitated","unconscious"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":317},{"name":"Sleet Storm","source":"XPHB","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":"a miniature umbrella"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Until the spell ends, sleet falls in a 40-foot-tall, 20-foot-radius <i>Cylinder [Area of Effect]</i> centered on a point you choose within range. The area is <i>Heavily Obscured</i>, and exposed flames in the area are doused."},{"type":"text","content":"Ground in the <i>Cylinder [Area of Effect]</i> is <i>Difficult Terrain</i>. When a creature enters the <i>Cylinder [Area of Effect]</i> for the first time on a turn or starts its turn there, it must succeed on a Dexterity saving throw or have the <i class=\\"text-dnd-gold\\">Prone</i> condition and lose <i>Concentration</i>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["prone"],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":317},{"name":"Slow","source":"XPHB","level":3,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a drop of molasses"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You alter time around up to six creatures of your choice in a 40-foot <i>Cube [Area of Effect]</i> within range. Each target must succeed on a Wisdom saving throw or be affected by this spell for the duration."},{"type":"text","content":"An affected target's <i>Speed</i> is halved, it takes a -2 penalty to AC and Dexterity saving throws, and it can't take Reactions. On its turns, it can take either an action or a <i>Bonus Action</i>, not both, and it can make only one attack if it takes the <b>Attack</b> action. If it casts a spell with a Somatic component, there is a 25% chance the spell fails as a result of the target making the spell's gestures too slowly."},{"type":"text","content":"An affected target repeats the save at the end of each of its turns, ending the spell on itself on a success."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":318},{"name":"Spare the Dying","source":"XPHB","level":0,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":15}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Choose a creature within range that has 0 <i>Hit Points</i> and isn't dead. The creature becomes <i>Stable</i>."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The range doubles when you reach levels 5 (30 feet), 11 (60 feet), and 17 (120 feet)."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":318},{"name":"Speak with Animals","source":"XPHB","level":1,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10}}],"entries":[{"type":"text","content":"For the duration, you can comprehend and verbally communicate with Beasts, and you can use any of the <b>Influence</b> action's skill options with them."},{"type":"text","content":"Most Beasts have little to say about topics that don't pertain to survival or companionship, but at minimum, a Beast can give you information about nearby locations and monsters, including whatever it has perceived within the past day."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":318},{"name":"Speak with Dead","source":"XPHB","level":3,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":"burning incense"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10}}],"entries":[{"type":"text","content":"You grant the semblance of life to a corpse of your choice within range, allowing it to answer questions you pose. The corpse must have a mouth, and this spell fails if the deceased creature was Undead when it died. The spell also fails if the corpse was the target of this spell within the past 10 days."},{"type":"text","content":"Until the spell ends, you can ask the corpse up to five questions. The corpse knows only what it knew in life, including the languages it knew. Answers are usually brief, cryptic, or repetitive, and the corpse is under no compulsion to offer a truthful answer if you are antagonistic toward it or it recognizes you as an enemy. This spell doesn't return the creature's soul to its body, only its animating spirit. Thus, the corpse can't learn new information, doesn't comprehend anything that has happened since it died, and can't speculate about future events."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":318},{"name":"Speak with Plants","source":"XPHB","level":3,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10}}],"entries":[{"type":"text","content":"You imbue plants in an immobile 30-foot <i>Emanation [Area of Effect]</i> with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell's area within the past day, gaining information about creatures that have passed, weather, and other circumstances."},{"type":"text","content":"You can also turn <i>Difficult Terrain</i> caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration. Or you can turn ordinary terrain where plants are present into <i>Difficult Terrain</i> that lasts for the duration."},{"type":"text","content":"The spell doesn't enable plants to uproot themselves and move about, but they can move their branches, tendrils, and stalks for you."},{"type":"text","content":"If a Plant creature is in the area, you can communicate with it as if you shared a common language."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":319},{"name":"Spider Climb","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a drop of bitumen and a spider"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and along ceilings, while leaving its hands free. The target also gains a <i>Climb Speed</i> equal to its <i>Speed</i>."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 2."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":319},{"name":"Spike Growth","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":"seven thorns"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"The ground in a 20-foot-radius <i>Sphere [Area of Effect]</i> centered on a point within range sprouts hard spikes and thorns. The area becomes <i>Difficult Terrain</i> for the duration. When a creature moves into or within the area, it takes <span class=\\"text-red-400 font-semibold\\">2d4</span> Piercing damage for every 5 feet it travels."},{"type":"text","content":"The transformation of the ground is camouflaged to look natural. Any creature that can't see the area when the spell is cast must take a <b>Search</b> action and succeed on a Wisdom (<i>Perception</i> or <i>Survival</i>) check against your spell save DC to recognize the terrain as hazardous before entering it."}],"entriesHigherLevel":[],"damageInflict":["piercing"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":319},{"name":"Spirit Guardians","source":"XPHB","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":15}},"components":{"v":true,"s":true,"m":"a prayer scroll"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Protective spirits flit around you in a 15-foot <i>Emanation [Area of Effect]</i> for the duration. If you are good or neutral, their spectral form appears angelic or fey (your choice). If you are evil, they appear fiendish."},{"type":"text","content":"When you cast this spell, you can designate creatures to be unaffected by it. Any other creature's <i>Speed</i> is halved in the <i>Emanation [Area of Effect]</i>, and whenever the <i>Emanation [Area of Effect]</i> enters a creature's space and whenever a creature enters the <i>Emanation [Area of Effect]</i> or ends its turn there, the creature must make a Wisdom saving throw. On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">3d8</span> Radiant damage (if you are good or neutral) or <span class=\\"text-red-400 font-semibold\\">3d8</span> Necrotic damage (if you are evil). On a successful save, the creature takes half as much damage. A creature makes this save only once per turn."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d8 for each spell slot level above 3."}]}],"damageInflict":["necrotic","radiant"],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":319},{"name":"Spiritual Weapon","source":"XPHB","level":2,"school":"V","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a floating, spectral force that resembles a weapon of your choice and lasts for the duration. The force appears within range in a space of your choice, and you can immediately make one melee spell attack against one creature within 5 feet of the force. On a hit, the target takes Force damage equal to <span class=\\"text-red-400 font-semibold\\">1d8</span> plus your spellcasting ability modifier."},{"type":"text","content":"As a <i>Bonus Action</i> on your later turns, you can move the force up to 20 feet and repeat the attack against a creature within 5 feet of it."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 1d8 for every slot level above 2."}]}],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":319},{"name":"Staggering Smite","source":"XPHB","level":4,"school":"E","time":[{"number":1,"unit":"bonus","condition":"which you take immediately after hitting a creature with a Melee weapon or an {@variantrule Unarmed Strike|XPHB}"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"The target takes an extra <span class=\\"text-red-400 font-semibold\\">4d6</span> Psychic damage from the attack, and the target must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Stunned</i> condition until the end of your next turn."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The extra damage increases by 4d6 for each spell slot level above 4."}]}],"damageInflict":["psychic"],"conditionInflict":["stunned"],"savingThrow":["wisdom"],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":320},{"name":"Stinking Cloud","source":"XPHB","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":"a rotten egg"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a 20-foot-radius <i>Sphere [Area of Effect]</i> of yellow, nauseating gas centered on a point within range. The cloud is <i>Heavily Obscured</i>. The cloud lingers in the air for the duration or until a strong wind (such as the one created by <a href=\\"/spells?search=Gust of Wind\\" class=\\"text-dnd-gold hover:underline\\">Gust of Wind</a>) disperses it."},{"type":"text","content":"Each creature that starts its turn in the <i>Sphere [Area of Effect]</i> must succeed on a Constitution saving throw or have the <i class=\\"text-dnd-gold\\">Poisoned</i> condition until the end of the current turn. While <i class=\\"text-dnd-gold\\">Poisoned</i> in this way, the creature can't take an action or a <i>Bonus Action</i>."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["poisoned"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":321},{"name":"Stone Shape","source":"XPHB","level":4,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"soft clay"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You touch a stone object of Medium size or smaller or a section of stone no more than 5 feet in any dimension and form it into any shape you like. For example, you could shape a large rock into a weapon, statue, or coffer, or you could make a small passage through a wall that is 5 feet thick. You could also shape a stone door or its frame to seal the door shut. The object you create can have up to two hinges and a latch, but finer mechanical detail isn't possible."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":321},{"name":"Stoneskin","source":"XPHB","level":4,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"diamond dust worth 100+ GP, which the spell consumes","cost":10000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Until the spell ends, one willing creature you touch has <i>Resistance</i> to Bludgeoning, Piercing, and Slashing damage."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":321},{"name":"Storm of Vengeance","source":"XPHB","level":9,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"miles","amount":1}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A churning storm cloud forms for the duration, centered on a point within range and spreading to a radius of 300 feet. Each creature under the cloud when it appears must succeed on a Constitution saving throw or take <span class=\\"text-red-400 font-semibold\\">2d6</span> Thunder damage and have the <i class=\\"text-dnd-gold\\">Deafened</i> condition for the duration."},{"type":"text","content":"At the start of each of your later turns, the storm produces different effects, as detailed below."},{"type":"section","name":"Turn 2","entries":[{"type":"text","content":"Acidic rain falls. Each creature and object under the cloud takes <span class=\\"text-red-400 font-semibold\\">4d6</span> Acid damage."}]},{"type":"section","name":"Turn 3","entries":[{"type":"text","content":"You call six bolts of lightning from the cloud to strike six different creatures or objects beneath it. Each target makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">10d6</span> Lightning damage on a failed save or half as much damage on a successful one."}]},{"type":"section","name":"Turn 4","entries":[{"type":"text","content":"Hailstones rain down. Each creature under the cloud takes <span class=\\"text-red-400 font-semibold\\">2d6</span> Bludgeoning damage."}]},{"type":"section","name":"Turns 5-10","entries":[{"type":"text","content":"Gusts and freezing rain assail the area under the cloud. Each creature there takes <span class=\\"text-red-400 font-semibold\\">1d6</span> Cold damage. Until the spell ends, the area is <i>Difficult Terrain</i> and <i>Heavily Obscured</i>, ranged attacks with weapons are impossible there, and strong wind blows through the area."}]}],"entriesHigherLevel":[],"damageInflict":["acid","bludgeoning","cold","lightning","thunder"],"conditionInflict":["deafened"],"savingThrow":["constitution","dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":321},{"name":"Suggestion","source":"XPHB","level":2,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"m":"a drop of honey"},"duration":[{"type":"timed","duration":{"type":"hour","amount":8},"concentration":true}],"entries":[{"type":"text","content":"You suggest a course of activity—described in no more than 25 words—to one creature you can see within range that can hear and understand you. The suggestion must sound achievable and not involve anything that would obviously deal damage to the target or its allies. For example, you could say, \\"Fetch the key to the cult's treasure vault, and give the key to me.\\" Or you could say, \\"Stop fighting, leave this library peacefully, and don't return.\\""},{"type":"text","content":"The target must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Charmed</i> condition for the duration or until you or your allies deal damage to the target. The <i class=\\"text-dnd-gold\\">Charmed</i> target pursues the suggestion to the best of its ability. The suggested activity can continue for the entire duration, but if the suggested activity can be completed in a shorter time, the spell ends for the target upon completing it."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":321},{"name":"Sunbeam","source":"XPHB","level":6,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"line","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a magnifying glass"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You launch a sunbeam in a 5-foot-wide, 60-foot-long <i>Line [Area of Effect]</i>. Each creature in the <i>Line [Area of Effect]</i> makes a Constitution saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">6d8</span> Radiant damage and has the <i class=\\"text-dnd-gold\\">Blinded</i> condition until the start of your next turn. On a successful save, it takes half as much damage only."},{"type":"text","content":"Until the spell ends, you can take a <b>Magic</b> action to create a new <i>Line [Area of Effect]</i> of radiance."},{"type":"text","content":"For the duration, a mote of brilliant radiance shines above you. It sheds <i>Bright Light</i> in a 30-foot radius and <i>Dim Light</i> for an additional 30 feet. This light is sunlight."}],"entriesHigherLevel":[],"damageInflict":["radiant"],"conditionInflict":["blinded"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":329},{"name":"Sunburst","source":"XPHB","level":8,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":"a piece of sunstone"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Brilliant sunlight flashes in a 60-foot-radius <i>Sphere [Area of Effect]</i> centered on a point you choose within range. Each creature in the <i>Sphere [Area of Effect]</i> makes a Constitution saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">12d6</span> Radiant damage and has the <i class=\\"text-dnd-gold\\">Blinded</i> condition for 1 minute. On a successful save, it takes half as much damage only."},{"type":"text","content":"A creature <i class=\\"text-dnd-gold\\">Blinded</i> by this spell makes another Constitution saving throw at the end of each of its turns, ending the effect on itself on a success."},{"type":"text","content":"This spell dispels <i>Darkness</i> in its area that was created by any spell."}],"entriesHigherLevel":[],"damageInflict":["radiant"],"conditionInflict":["blinded"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":329},{"name":"Swift Quiver","source":"XPHB","level":5,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"a Quiver worth 1+ GP","cost":100}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"When you cast the spell and as a <i>Bonus Action</i> until it ends, you can make two attacks with a weapon that fires Arrows or Bolts, such as a Longbow or a Light Crossbow. The spell magically creates the ammunition needed for each attack. Each Arrow or Bolt created by the spell deals damage like a nonmagical piece of ammunition of its kind and disintegrates immediately after it hits or misses."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":329},{"name":"Symbol","source":"XPHB","level":7,"school":"A","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"powdered diamond worth 1,000+ GP, which the spell consumes","cost":100000,"consume":true}},"duration":[{"type":"permanent","ends":["dispel","trigger"]}],"entries":[{"type":"text","content":"You inscribe a harmful glyph either on a surface (such as a section of floor or wall) or within an object that can be closed (such as a book or chest). The glyph can cover an area no larger than 10 feet in diameter. If you choose an object, it must remain in place; if it is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered."},{"type":"text","content":"The glyph is nearly imperceptible and requires a successful Wisdom (<i>Perception</i>) check against your spell save DC to notice."},{"type":"text","content":"When you inscribe the glyph, you set its trigger and choose which effect the symbol bears: Death, Discord, Fear, Pain, Sleep, or Stunning. Each one is explained below."},{"type":"section","name":"Set the Trigger","entries":[{"type":"text","content":"You decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, common triggers include touching or stepping on the glyph, removing another object covering it, or approaching within a certain distance of it. For glyphs inscribed within an object, common triggers include opening that object or seeing the glyph."},{"type":"text","content":"You can refine the trigger so that only creatures of certain types activate it (for example, the glyph could be set to affect Aberrations). You can also set conditions for creatures that don't trigger the glyph, such as those who say a certain password."},{"type":"text","content":"Once triggered, the glyph glows, filling a 60-foot-radius <i>Sphere [Area of Effect]</i> with <i>Dim Light</i> for 10 minutes, after which time the spell ends. Each creature in the <i>Sphere [Area of Effect]</i> when the glyph activates is targeted by its effect, as is a creature that enters the <i>Sphere [Area of Effect]</i> for the first time on a turn or ends its turn there. A creature is targeted only once per turn."}]},{"type":"section","name":"Death","entries":[{"type":"text","content":"Each target makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">10d10</span> Necrotic damage on a failed save or half as much damage on a successful save."}]},{"type":"section","name":"Discord","entries":[{"type":"text","content":"Each target makes a Wisdom saving throw. On a failed save, a target argues with other creatures for 1 minute. During this time, it is incapable of meaningful communication and has <i>Disadvantage</i> on attack rolls and ability checks."}]},{"type":"section","name":"Fear","entries":[{"type":"text","content":"Each target must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Frightened</i> condition for 1 minute. While <i class=\\"text-dnd-gold\\">Frightened</i>, the target must move at least 30 feet away from the glyph on each of its turns, if able."}]},{"type":"section","name":"Pain","entries":[{"type":"text","content":"Each target must succeed on a Constitution saving throw or have the <i class=\\"text-dnd-gold\\">Incapacitated</i> condition for 1 minute."}]},{"type":"section","name":"Sleep","entries":[{"type":"text","content":"Each target must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Unconscious</i> condition for 10 minutes. A creature awakens if it takes damage or if someone takes an action to shake it awake."}]},{"type":"section","name":"Stunning","entries":[{"type":"text","content":"Each target must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Stunned</i> condition for 1 minute."}]}],"entriesHigherLevel":[],"damageInflict":["necrotic"],"conditionInflict":["frightened","incapacitated","stunned","unconscious"],"savingThrow":["constitution","wisdom","intelligence"],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":329},{"name":"Tasha's Hideous Laughter","source":"XPHB","level":1,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a tart and a feather"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"One creature of your choice that you can see within range makes a Wisdom saving throw. On a failed save, it has the <i class=\\"text-dnd-gold\\">Prone</i> and <i class=\\"text-dnd-gold\\">Incapacitated</i> conditions for the duration. During that time, it laughs uncontrollably if it's capable of laughter, and it can't end the <i class=\\"text-dnd-gold\\">Prone</i> condition on itself."},{"type":"text","content":"At the end of each of its turns and each time it takes damage, it makes another Wisdom saving throw. The target has <i>Advantage</i> on the save if the save is triggered by damage. On a successful save, the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 1."}]}],"damageInflict":[],"conditionInflict":["incapacitated","prone"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":331},{"name":"Telekinesis","source":"XPHB","level":5,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You gain the ability to move or manipulate creatures or objects by thought. When you cast the spell and as a <b>Magic</b> action on your later turns before the spell ends, you can exert your will on one creature or object that you can see within range, causing the appropriate effect below. You can affect the same target round after round or choose a new one at any time. If you switch targets, the prior target is no longer affected by the spell."},{"type":"section","name":"Creature","entries":[{"type":"text","content":"You can try to move a Huge or smaller creature. The target must succeed on a Strength saving throw, or you move it up to 30 feet in any direction within the spell's range. Until the end of your next turn, the creature has the <i class=\\"text-dnd-gold\\">Restrained</i> condition, and if you lift it into the air, it is suspended there. It falls at the end of your next turn unless you use this option on it again and it fails the save."}]},{"type":"section","name":"Object","entries":[{"type":"text","content":"You can try to move a Huge or smaller object. If the object isn't being worn or carried, you automatically move it up to 30 feet in any direction within the spell's range."},{"type":"text","content":"If the object is worn or carried by a creature, that creature must succeed on a Strength saving throw, or you pull the object away and move it up to 30 feet in any direction within the spell's range."},{"type":"text","content":"You can exert fine control on objects with your telekinetic grip, such as manipulating a simple tool, opening a door or a container, stowing or retrieving an item from an open container, or pouring the contents from a vial."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["restrained"],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":331},{"name":"Telepathy","source":"XPHB","level":8,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"unlimited"}},"components":{"v":true,"s":true,"m":"a pair of linked silver rings"},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"You create a telepathic link between yourself and a willing creature with which you are familiar. The creature can be anywhere on the same plane of existence as you. The spell ends if you or the target are no longer on the same plane."},{"type":"text","content":"Until the spell ends, you and the target can instantly share words, images, sounds, and other sensory messages with each other through the link, and the target recognizes you as the creature it is communicating with. The spell enables a creature to understand the meaning of your words and any sensory messages you send to it."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":331},{"name":"Teleport","source":"XPHB","level":7,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"This spell instantly transports you and up to eight willing creatures that you can see within range, or a single object that you can see within range, to a destination you select. If you target an object, it must be Large or smaller, and it can't be held or carried by an unwilling creature."},{"type":"text","content":"The destination you choose must be known to you, and it must be on the same plane of existence as you. Your familiarity with the destination determines whether you arrive there successfully. The DM rolls <span class=\\"text-green-400 font-mono\\">1d100</span> and consults the Teleportation Outcome table and the explanations after it."},{"type":"table","caption":"Teleportation Outcome","colLabels":["Familiarity","Mishap","Similar Area","Off Target","On Target"],"rows":[["Permanent circle","—","—","—","01-00"],["Linked object","—","—","—","01-00"],["Very familiar","01-05","06-13","14-24","25-00"],["Seen casually","01-33","34-43","44-53","54-00"],["Viewed once or described","01-43","44-53","54-73","74-00"],["False destination","01-50","51-00","—","—"]]},{"type":"section","name":"Familiarity","entries":[{"type":"text","content":"Here are the meanings of the terms in the table's Familiarity column:"},{"type":"list","items":["\\"Permanent circle\\" means a permanent teleportation circle whose sigil sequence you know.","\\"Linked object\\" means you possess an object taken from the desired destination within the last six months, such as a book from a wizard's library.","\\"Very familiar\\" is a place you have visited often, a place you have carefully studied, or a place you can see when you cast the spell.","\\"Seen casually\\" is a place you have seen more than once but with which you aren't very familiar.","\\"Viewed once or described\\" is a place you have seen once, possibly using magic, or a place you know through someone else's description, perhaps from a map.","\\"False destination\\" is a place that doesn't exist. Perhaps you tried to scry an enemy's sanctum but instead viewed an illusion, or you are attempting to teleport to a location that no longer exists."]}]},{"type":"section","name":"Mishap","entries":[{"type":"text","content":"The spell's unpredictable magic results in a difficult journey. Each teleporting creature (or the target object) takes <span class=\\"text-red-400 font-semibold\\">3d10</span> Force damage, and the DM rerolls on the table to see where you wind up (multiple mishaps can occur, dealing damage each time)."}]},{"type":"section","name":"Similar Area","entries":[{"type":"text","content":"You and your group (or the target object) appear in a different area that's visually or thematically similar to the target area. You appear in the closest similar place. If you are heading for your home laboratory, for example, you might appear in another person's laboratory in the same city."}]},{"type":"section","name":"Off Target","entries":[{"type":"text","content":"You and your group (or the target object) appear <span class=\\"text-green-400 font-mono\\">2d12</span> miles away from the destination in a random direction. Roll <span class=\\"text-green-400 font-mono\\">1d8</span> for the direction: 1, east; 2, southeast; 3, south; 4, southwest; 5, west; 6, northwest; 7, north; or 8, northeast."}]},{"type":"section","name":"On Target","entries":[{"type":"text","content":"You and your group (or the target object) appear where you intended."}]}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":331},{"name":"Teleportation Circle","source":"XPHB","level":5,"school":"C","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"m":{"text":"rare inks worth 50+ GP, which the spell consumes","cost":5000,"consume":true}},"duration":[{"type":"timed","duration":{"type":"round","amount":1}}],"entries":[{"type":"text","content":"As you cast the spell, you draw a 5-foot-radius circle on the ground inscribed with sigils that link your location to a permanent teleportation circle of your choice whose sigil sequence you know and that is on the same plane of existence as you. A shimmering portal opens within the circle you drew and remains open until the end of your next turn. Any creature that enters the portal instantly appears within 5 feet of the destination circle or in the nearest unoccupied space if that space is occupied."},{"type":"text","content":"Many major temples, guildhalls, and other important places have permanent teleportation circles. Each circle includes a unique sigil sequence—a string of runes arranged in a particular pattern."},{"type":"text","content":"When you first gain the ability to cast this spell, you learn the sigil sequences for two destinations on the Material Plane, determined by the DM. You might learn additional sigil sequences during your adventures. You can commit a new sigil sequence to memory after studying it for 1 minute."},{"type":"text","content":"You can create a permanent teleportation circle by casting this spell in the same location every day for 365 days."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":332},{"name":"Tenser's Floating Disk","source":"XPHB","level":1,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a drop of mercury"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"This spell creates a circular, horizontal plane of force, 3 feet in diameter and 1 inch thick, that floats 3 feet above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration and can hold up to 500 pounds. If more weight is placed on it, the spell ends, and everything on the disk falls to the ground."},{"type":"text","content":"The disk is immobile while you are within 20 feet of it. If you move more than 20 feet away from it, the disk follows you so that it remains within 20 feet of you. It can move across uneven terrain, up or down stairs, slopes and the like, but it can't cross an elevation change of 10 feet or more. For example, the disk can't move across a 10-foot-deep pit, nor could it leave such a pit if it was created at the bottom."},{"type":"text","content":"If you move more than 100 feet from the disk (typically because it can't move around an obstacle to follow you), the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":332},{"name":"Thaumaturgy","source":"XPHB","level":0,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"You manifest a minor wonder within range. You create one of the effects below within range. If you cast this spell multiple times, you can have up to three of its 1-minute effects active at a time."},{"type":"section","name":"Altered Eyes","entries":[{"type":"text","content":"You alter the appearance of your eyes for 1 minute."}]},{"type":"section","name":"Booming Voice","entries":[{"type":"text","content":"Your voice booms up to three times as loud as normal for 1 minute. For the duration, you have <i>Advantage</i> on Charisma (<i>Intimidation</i>) checks."}]},{"type":"section","name":"Fire Play","entries":[{"type":"text","content":"You cause flames to flicker, brighten, dim, or change color for 1 minute."}]},{"type":"section","name":"Invisible Hand","entries":[{"type":"text","content":"You instantaneously cause an unlocked door or window to fly open or slam shut."}]},{"type":"section","name":"Phantom Sound","entries":[{"type":"text","content":"You create an instantaneous sound that originates from a point of your choice within range, such as a rumble of thunder, the cry of a raven, or ominous whispers."}]},{"type":"section","name":"Tremors","entries":[{"type":"text","content":"You cause harmless tremors in the ground for 1 minute."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":333},{"name":"Thorn Whip","source":"XPHB","level":0,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"the stem of a plant with thorns"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You create a vine-like whip covered in thorns that lashes out at your command toward a creature in range. Make a melee spell attack against the target. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">1d6</span> Piercing damage, and if it is Large or smaller, you can pull it up to 10 feet closer to you."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d6</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d6</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d6</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d6</span>)."}]}],"damageInflict":["piercing"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":333},{"name":"Thunderous Smite","source":"XPHB","level":1,"school":"V","time":[{"number":1,"unit":"bonus","condition":"which you take immediately after hitting a target with a Melee weapon or an {@variantrule Unarmed Strike|XPHB}"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Your strike rings with thunder that is audible within 300 feet of you, and the target takes an extra <span class=\\"text-red-400 font-semibold\\">2d6</span> Thunder damage from the attack. Additionally, if the target is a creature, it must succeed on a Strength saving throw or be pushed 10 feet away from you and have the <i class=\\"text-dnd-gold\\">Prone</i> condition."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d6 for each spell slot level above 1."}]}],"damageInflict":["thunder"],"conditionInflict":["prone"],"savingThrow":["strength"],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":334},{"name":"Thunderwave","source":"XPHB","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"cube","distance":{"type":"feet","amount":15}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You unleash a wave of thunderous energy. Each creature in a 15-foot <i>Cube [Area of Effect]</i> originating from you makes a Constitution saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">2d8</span> Thunder damage and is pushed 10 feet away from you. On a successful save, a creature takes half as much damage only."},{"type":"text","content":"In addition, unsecured objects that are entirely within the <i>Cube [Area of Effect]</i> are pushed 10 feet away from you, and a thunderous boom is audible within 300 feet."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d8 for each spell slot level above 1."}]}],"damageInflict":["thunder"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":334},{"name":"Time Stop","source":"XPHB","level":9,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You briefly stop the flow of time for everyone but yourself. No time passes for other creatures, while you take <span class=\\"text-green-400 font-mono\\">1d4 + 1</span> turns in a row, during which you can use actions and move as normal."},{"type":"text","content":"This spell ends if one of the actions you use during this period, or any effects that you create during it, affects a creature other than you or an object being worn or carried by someone other than you. In addition, the spell ends if you move to a place more than 1,000 feet from the location where you cast it."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":334},{"name":"Tongues","source":"XPHB","level":3,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"m":"a miniature ziggurat"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"This spell grants the creature you touch the ability to understand any spoken or signed language that it hears or sees. Moreover, when the target communicates by speaking or signing, any creature that knows at least one language can understand it if that creature can hear the speech or see the signing."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":334},{"name":"Transport via Plants","source":"XPHB","level":6,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"This spell creates a magical link between a Large or larger inanimate plant within range and another plant, at any distance, on the same plane of existence. You must have seen or touched the destination plant at least once before. For the duration, any creature can step into the target plant and exit from the destination plant by using 5 feet of movement."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":334},{"name":"Tree Stride","source":"XPHB","level":5,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You gain the ability to enter a tree and move from inside it to inside another tree of the same kind within 500 feet. Both trees must be living and at least the same size as you. You must use 5 feet of movement to enter a tree. You instantly know the location of all other trees of the same kind within 500 feet and, as part of the move used to enter the tree, can either pass into one of those trees or step out of the tree you're in. You appear in a spot of your choice within 5 feet of the destination tree, using another 5 feet of movement. If you have no movement left, you appear within 5 feet of the tree you entered."},{"type":"text","content":"You can use this transportation ability only once on each of your turns. You must end each turn outside a tree."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":335},{"name":"True Polymorph","source":"XPHB","level":9,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a drop of mercury, a dollop of gum arabic, and a wisp of smoke"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Choose one creature or nonmagical object that you can see within range. The creature shape-shifts into a different creature or a nonmagical object, or the object shape-shifts into a creature (the object must be neither worn nor carried). The transformation lasts for the duration or until the target dies or is destroyed, but if you maintain <i>Concentration</i> on this spell for the full duration, the spell lasts until dispelled."},{"type":"text","content":"An unwilling creature can make a Wisdom saving throw, and if it succeeds, it isn't affected by this spell."},{"type":"section","name":"Creature into Creature","entries":[{"type":"text","content":"If you turn a creature into another kind of creature, the new form can be any kind you choose that has a <i>Challenge Rating</i> equal to or less than the target's <i>Challenge Rating</i> or level. The target's game statistics are replaced by the stat block of the new form, but it retains its <i>Hit Points</i>, <i>Hit Point Dice</i>, alignment, and personality."},{"type":"text","content":"The target gains a number of <i>Temporary Hit Points</i> equal to the <i>Hit Points</i> of the new form. These <i>Temporary Hit Points</i> vanish if any remain when the spell ends."},{"type":"text","content":"The target is limited in the actions it can perform by the anatomy of its new form, and it can't speak or cast spells."},{"type":"text","content":"The target's gear melds into the new form. The creature can't use or otherwise benefit from any of that equipment."}]},{"type":"section","name":"Object into Creature","entries":[{"type":"text","content":"You can turn an object into any kind of creature, as long as the creature's size is no larger than the object's size and the creature has a <i>Challenge Rating</i> of 9 or lower. The creature is <i>Friendly [Attitude]</i> to you and your allies. In combat, it takes its turns immediately after yours, and it obeys your commands."},{"type":"text","content":"If the spell lasts more than an hour, you no longer control the creature. It might remain <i>Friendly [Attitude]</i> to you, depending on how you have treated it."}]},{"type":"section","name":"Creature into Object","entries":[{"type":"text","content":"If you turn a creature into an object, it transforms along with whatever it is wearing and carrying into that form, as long as the object's size is no larger than the creature's size. The creature's statistics become those of the object, and the creature has no memory of time spent in this form after the spell ends and it returns to normal."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":335},{"name":"True Resurrection","source":"XPHB","level":9,"school":"N","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"diamonds worth 25,000+ GP, which the spell consumes","cost":2500000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You touch a creature that has been dead for no longer than 200 years and that died for any reason except old age. The creature is revived with all its <i>Hit Points</i>."},{"type":"text","content":"This spell closes all wounds, neutralizes any poison, cures all magical contagions, and lifts any curses affecting the creature when it died. The spell replaces damaged or missing organs and limbs. If the creature was Undead, it is restored to its non-Undead form."},{"type":"text","content":"The spell can provide a new body if the original no longer exists, in which case you must speak the creature's name. The creature then appears in an unoccupied space you choose within 10 feet of you."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":336},{"name":"True Seeing","source":"XPHB","level":6,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"mushroom powder worth 25+ GP, which the spell consumes","cost":2500,"consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"For the duration, the willing creature you touch has <i>Truesight</i> with a range of 120 feet."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":336},{"name":"True Strike","source":"XPHB","level":0,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"s":true,"m":{"text":"a weapon with which you have proficiency and that is worth 1+ CP","cost":1}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Guided by a flash of magical insight, you make one attack with the weapon used in the spell's casting. The attack uses your spellcasting ability for the attack and damage rolls instead of using Strength or Dexterity. If the attack deals damage, it can be Radiant damage or the weapon's normal damage type (your choice)."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"Whether you deal Radiant damage or the weapon's normal damage type, the attack deals extra Radiant damage when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">1d6</span>), 11 (<span class=\\"text-red-400 font-semibold\\">2d6</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">3d6</span>)."}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":336},{"name":"Tsunami","source":"XPHB","level":8,"school":"C","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"miles","amount":1}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"round","amount":6},"concentration":true}],"entries":[{"type":"text","content":"A wall of water springs into existence at a point you choose within range. You can make the wall up to 300 feet long, 300 feet high, and 50 feet thick. The wall lasts for the duration."},{"type":"text","content":"When the wall appears, each creature in its area makes a Strength saving throw, taking <span class=\\"text-red-400 font-semibold\\">6d10</span> Bludgeoning damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"At the start of each of your turns after the wall appears, the wall, along with any creatures in it, moves 50 feet away from you. Any Huge or smaller creature inside the wall or whose space the wall enters when it moves must succeed on a Strength saving throw or take <span class=\\"text-red-400 font-semibold\\">5d10</span> Bludgeoning damage. A creature can take this damage only once per round. At the end of the turn, the wall's height is reduced by 50 feet, and the damage the wall deals on later rounds is reduced by <span class=\\"text-green-400 font-mono\\">1d10</span>. When the wall reaches 0 feet in height, the spell ends."},{"type":"text","content":"A creature caught in the wall can move by swimming. Because of the wave's force, though, the creature must succeed on a Strength (<i>Athletics</i>) check against your spell save DC to move at all. If it fails the check, it can't move. A creature that moves out of the wall falls to the ground."}],"entriesHigherLevel":[],"damageInflict":["bludgeoning"],"conditionInflict":[],"savingThrow":["strength"],"castingTime":"minute","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":336},{"name":"Unseen Servant","source":"XPHB","level":1,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a bit of string and of wood"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"This spell creates an <i class=\\"text-dnd-gold\\">Invisible</i>, mindless, shapeless, Medium force that performs simple tasks at your command until the spell ends. The servant springs into existence in an unoccupied space on the ground within range. It has AC 10, 1 <i>Hit Points</i>, and a Strength of 2, and it can't attack. If it drops to 0 <i>Hit Points</i>, the spell ends."},{"type":"text","content":"Once on each of your turns as a <i>Bonus Action</i>, you can mentally command the servant to move up to 15 feet and interact with an object. The servant can perform simple tasks that a human could do, such as fetching things, cleaning, mending, folding clothes, lighting fires, serving food, and pouring drinks. Once you give the command, the servant performs the task to the best of its ability until it completes the task, then waits for your next command."},{"type":"text","content":"If you command the servant to perform a task that would move it more than 60 feet away from you, the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":336},{"name":"Vampiric Touch","source":"XPHB","level":3,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"The touch of your shadow-wreathed hand can siphon life force from others to heal your wounds. Make a melee spell attack against one creature within reach. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">3d6</span> Necrotic damage, and you regain <i>Hit Points</i> equal to half the amount of Necrotic damage dealt."},{"type":"text","content":"Until the spell ends, you can make the attack again on each of your turns as a <b>Magic</b> action, targeting the same creature or a different one."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d6 for each spell slot level above 3."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":337},{"name":"Vicious Mockery","source":"XPHB","level":0,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You unleash a string of insults laced with subtle enchantments at one creature you can see or hear within range. The target must succeed on a Wisdom saving throw or take <span class=\\"text-red-400 font-semibold\\">1d6</span> Psychic damage and have <i>Disadvantage</i> on the next attack roll it makes before the end of its next turn."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d6</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d6</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d6</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d6</span>)."}]}],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":337},{"name":"Wall of Fire","source":"XPHB","level":4,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a piece of charcoal"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a wall of fire on a solid surface within range. You can make the wall up to 60 feet long, 20 feet high, and 1 foot thick, or a ringed wall up to 20 feet in diameter, 20 feet high, and 1 foot thick. The wall is opaque and lasts for the duration."},{"type":"text","content":"When the wall appears, each creature in its area makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">5d8</span> Fire damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"One side of the wall, selected by you when you cast this spell, deals <span class=\\"text-red-400 font-semibold\\">5d8</span> Fire damage to each creature that ends its turn within 10 feet of that side or inside the wall. A creature takes the same damage when it enters the wall for the first time on a turn or ends its turn there. The other side of the wall deals no damage."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 5d8 for each spell slot level above 4."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":338},{"name":"Wall of Force","source":"XPHB","level":5,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a shard of glass"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"An <i class=\\"text-dnd-gold\\">Invisible</i> wall of force springs into existence at a point you choose within range. The wall appears in any orientation you choose, as a horizontal or vertical barrier or at an angle. It can be free floating or resting on a solid surface. You can form it into a hemispherical dome or a globe with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-by-10-foot panels. Each panel must be contiguous with another panel. In any form, the wall is 1/4 inch thick and lasts for the duration. If the wall cuts through a creature's space when it appears, the creature is pushed to one side of the wall (you choose which side)."},{"type":"text","content":"Nothing can physically pass through the wall. It is immune to all damage and can't be dispelled by <a href=\\"/spells?search=Dispel Magic\\" class=\\"text-dnd-gold hover:underline\\">Dispel Magic</a>. A <a href=\\"/spells?search=Disintegrate\\" class=\\"text-dnd-gold hover:underline\\">Disintegrate</a> spell destroys the wall instantly, however. The wall also extends into the Ethereal Plane and blocks ethereal travel through the wall."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":338},{"name":"Wall of Ice","source":"XPHB","level":6,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a piece of quartz"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You create a wall of ice on a solid surface within range. You can form it into a hemispherical dome or a globe with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-square panels. Each panel must be contiguous with another panel. In any form, the wall is 1 foot thick and lasts for the duration."},{"type":"text","content":"If the wall cuts through a creature's space when it appears, the creature is pushed to one side of the wall (you choose which side) and makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">10d6</span> Cold damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"The wall is an object that can be damaged and thus breached. It has AC 12 and 30 <i>Hit Points</i> per 10-foot section, and it has <i>Immunity</i> to Cold, Poison, and Psychic damage and <i>Vulnerability</i> to Fire damage. Reducing a 10-foot section of wall to 0 <i>Hit Points</i> destroys it and leaves behind a sheet of frigid air in the space the wall occupied."},{"type":"text","content":"A creature moving through the sheet of frigid air for the first time on a turn makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">5d6</span> Cold damage on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage the wall deals when it appears increases by 10d6 and the damage from passing through the sheet of frigid air increases by 5d6 for each spell slot level above 6."}]}],"damageInflict":["cold"],"conditionInflict":[],"savingThrow":["dexterity","constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":339},{"name":"Wall of Stone","source":"XPHB","level":5,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a cube of granite"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"A nonmagical wall of solid stone springs into existence at a point you choose within range. The wall is 6 inches thick and is composed of ten 10-foot-by-10-foot panels. Each panel must be contiguous with another panel. Alternatively, you can create 10-foot-by-20-foot panels that are only 3 inches thick."},{"type":"text","content":"If the wall cuts through a creature's space when it appears, the creature is pushed to one side of the wall (you choose which side). If a creature would be surrounded on all sides by the wall (or the wall and another solid surface), that creature can make a Dexterity saving throw. On a success, it can use its <i>Reaction</i> to move up to its <i>Speed</i> so that it is no longer enclosed by the wall."},{"type":"text","content":"The wall can have any shape you desire, though it can't occupy the same space as a creature or object. The wall doesn't need to be vertical or rest on a firm foundation. It must, however, merge with and be solidly supported by existing stone. Thus, you can use this spell to bridge a chasm or create a ramp."},{"type":"text","content":"If you create a span greater than 20 feet in length, you must halve the size of each panel to create supports. You can crudely shape the wall to create battlements and the like."},{"type":"text","content":"The wall is an object made of stone that can be damaged and thus breached. Each panel has AC 15 and 30 <i>Hit Points</i> per inch of thickness, and it has <i>Immunity</i> to Poison and Psychic damage. Reducing a panel to 0 <i>Hit Points</i> destroys it and might cause connected panels to collapse at the DM's discretion."},{"type":"text","content":"If you maintain your <i>Concentration</i> on this spell for its full duration, the wall becomes permanent and can't be dispelled. Otherwise, the wall disappears when the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":339},{"name":"Wall of Thorns","source":"XPHB","level":6,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a handful of thorns"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You create a wall of tangled brush bristling with needle-sharp thorns. The wall appears within range on a solid surface and lasts for the duration. You choose to make the wall up to 60 feet long, 10 feet high, and 5 feet thick or a circle that has a 20-foot diameter and is up to 20 feet high and 5 feet thick. The wall blocks line of sight."},{"type":"text","content":"When the wall appears, each creature in its area makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">7d8</span> Piercing damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"A creature can move through the wall, albeit slowly and painfully. For every 1 foot a creature moves through the wall, it must spend 4 feet of movement. Furthermore, the first time a creature enters a space in the wall on a turn or ends its turn there, the creature makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">7d8</span> Slashing damage on a failed save or half as much damage on a successful one. A creature makes this save only once per turn."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Both types of damage increase by 7d8 for each spell slot level above 6."}]}],"damageInflict":["piercing","slashing"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":339},{"name":"Warding Bond","source":"XPHB","level":2,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"a pair of platinum rings worth 50+ GP each, which you and the target must wear for the duration","cost":5000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You touch another creature that is willing and create a mystic connection between you and the target until the spell ends. While the target is within 60 feet of you, it gains a +1 bonus to AC and saving throws, and it has <i>Resistance</i> to all damage. Also, each time it takes damage, you take the same amount of damage."},{"type":"text","content":"The spell ends if you drop to 0 <i>Hit Points</i> or if you and the target become separated by more than 60 feet. It also ends if the spell is cast again on either of the connected creatures."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":340},{"name":"Water Breathing","source":"XPHB","level":3,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a short reed"},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"This spell grants up to ten willing creatures of your choice within range the ability to breathe underwater until the spell ends. Affected creatures also retain their normal mode of respiration."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":340},{"name":"Water Walk","source":"XPHB","level":3,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a piece of cork"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"This spell grants the ability to move across any liquid surface—such as water, acid, mud, snow, quicksand, or lava—as if it were harmless solid ground (creatures crossing molten lava can still take damage from the heat). Up to ten willing creatures of your choice within range gain this ability for the duration."},{"type":"text","content":"An affected target must take a <i>Bonus Action</i> to pass from the liquid's surface into the liquid itself and vice versa, but if the target falls into the liquid, the target passes through the surface into the liquid below."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":340},{"name":"Web","source":"XPHB","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a bit of spiderweb"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You conjure a mass of sticky webbing at a point within range. The webs fill a 20-foot <i>Cube [Area of Effect]</i> there for the duration. The webs are <i>Difficult Terrain</i>, and the area within them is <i>Lightly Obscured</i>."},{"type":"text","content":"If the webs aren't anchored between two solid masses (such as walls or trees) or layered across a floor, wall, or ceiling, the web collapses on itself, and the spell ends at the start of your next turn. Webs layered over a flat surface have a depth of 5 feet."},{"type":"text","content":"The first time a creature enters the webs on a turn or starts its turn there, it must succeed on a Dexterity saving throw or have the <i class=\\"text-dnd-gold\\">Restrained</i> condition while in the webs or until it breaks free."},{"type":"text","content":"A creature <i class=\\"text-dnd-gold\\">Restrained</i> by the webs can take an action to make a Strength (<i>Athletics</i>) check against your spell save DC. If it succeeds, it is no longer <i class=\\"text-dnd-gold\\">Restrained</i>."},{"type":"text","content":"The webs are flammable. Any 5-foot <i>Cube [Area of Effect]</i> of webs exposed to fire burns away in 1 round, dealing <span class=\\"text-red-400 font-semibold\\">2d4</span> Fire damage to any creature that starts its turn in the fire."}],"entriesHigherLevel":[],"damageInflict":["fire"],"conditionInflict":["restrained"],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":340},{"name":"Weird","source":"XPHB","level":9,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You try to create illusory terrors in others' minds. Each creature of your choice in a 30-foot-radius <i>Sphere [Area of Effect]</i> centered on a point within range makes a Wisdom saving throw. On a failed save, a target takes <span class=\\"text-red-400 font-semibold\\">10d10</span> Psychic damage and has the <i class=\\"text-dnd-gold\\">Frightened</i> condition for the duration. On a successful save, a target takes half as much damage only."},{"type":"text","content":"A <i class=\\"text-dnd-gold\\">Frightened</i> target makes a Wisdom saving throw at the end of each of its turns. On a failed save, it takes <span class=\\"text-red-400 font-semibold\\">5d10</span> Psychic damage. On a successful save, the spell ends on that target."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":["frightened"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":341},{"name":"Wind Walk","source":"XPHB","level":6,"school":"T","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a candle"},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You and up to ten willing creatures of your choice within range assume gaseous forms for the duration, appearing as wisps of cloud. While in this cloud form, a target has a <i>Fly Speed</i> of 300 feet and can hover; it has <i>Immunity</i> to the <i class=\\"text-dnd-gold\\">Prone</i> condition; and it has <i>Resistance</i> to Bludgeoning, Piercing, and Slashing damage. The only actions a target can take in this form are the <b>Dash</b> action or a <b>Magic</b> action to begin reverting to its normal form. Reverting takes 1 minute, during which the target has the <i class=\\"text-dnd-gold\\">Stunned</i> condition. Until the spell ends, the target can revert to cloud form, which also requires a <b>Magic</b> action followed by a 1-minute transformation."},{"type":"text","content":"If a target is in cloud form and flying when the effect ends, the target descends 60 feet per round for 1 minute until it lands, which it does safely. If it can't land after 1 minute, it falls the remaining distance."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["stunned"],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":341},{"name":"Wind Wall","source":"XPHB","level":3,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a fan and a feather"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A wall of strong wind rises from the ground at a point you choose within range. You can make the wall up to 50 feet long, 15 feet high, and 1 foot thick. You can shape the wall in any way you choose so long as it makes one continuous path along the ground. The wall lasts for the duration."},{"type":"text","content":"When the wall appears, each creature in its area makes a Strength saving throw, taking <span class=\\"text-red-400 font-semibold\\">4d8</span> Bludgeoning damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"The strong wind keeps fog, smoke, and other gases at bay. Small or smaller flying creatures or objects can't pass through the wall. Loose, lightweight materials brought into the wall fly upward. Arrows, bolts, and other ordinary projectiles launched at targets behind the wall are deflected upward and miss automatically. Boulders hurled by Giants or siege engines, and similar projectiles, are unaffected. Creatures in <a href=\\"/spells?search=gaseous form\\" class=\\"text-dnd-gold hover:underline\\">gaseous form</a> can't pass through it."}],"entriesHigherLevel":[],"damageInflict":["bludgeoning"],"conditionInflict":[],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":341},{"name":"Wish","source":"XPHB","level":9,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Wish is the mightiest spell a mortal can cast. By simply speaking aloud, you can alter reality itself."},{"type":"text","content":"The basic use of this spell is to duplicate any other spell of level 8 or lower. If you use it this way, you don't need to meet any requirements to cast that spell, including costly components. The spell simply takes effect."},{"type":"text","content":"Alternatively, you can create one of the following effects of your choice:"},{"type":"list","items":[{"type":"item","name":"Object Creation","entry":"You create one object of up to 25,000 GP in value that isn't a magic item. The object can be no more than 300 feet in any dimension, and it appears in an unoccupied space that you can see on the ground."},{"type":"item","name":"Instant Health","entry":"You allow yourself and up to twenty creatures that you can see to regain all <i>Hit Points</i>, and you end all effects on them listed in the <a href=\\"/spells?search=Greater Restoration\\" class=\\"text-dnd-gold hover:underline\\">Greater Restoration</a> spell."},{"type":"item","name":"Resistance","entry":"You grant up to ten creatures that you can see <i>Resistance</i> to one damage type that you choose. This <i>Resistance</i> is permanent."},{"type":"item","name":"Spell Immunity","entry":"You grant up to ten creatures you can see immunity to a single spell or other magical effect for 8 hours."},{"type":"item","name":"Sudden Learning","entry":"You replace one of your feats with another feat for which you are eligible. You lose all the benefits of the old feat and gain the benefits of the new one. You can't replace a feat that is a prerequisite for any of your other feats or features."},{"type":"item","name":"Roll Redo","entry":"You undo a single recent event by forcing a reroll of any die roll made within the last round (including your last turn). Reality reshapes itself to accommodate the new result. For example, a Wish spell could undo an ally's failed saving throw or a foe's <i>Critical Hit</i>. You can force the reroll to be made with <i>Advantage</i> or <i>Disadvantage</i>, and you choose whether to use the reroll or the original roll."},{"type":"item","name":"Reshape Reality","entry":"You may wish for something not included in any of the other effects. To do so, state your wish to the DM as precisely as possible. The DM has great latitude in ruling what occurs in such an instance; the greater the wish, the greater the likelihood that something goes wrong. This spell might simply fail, the effect you desire might be achieved only in part, or you might suffer an unforeseen consequence as a result of how you worded the wish. For example, wishing that a villain were dead might propel you forward in time to a period when that villain is no longer alive, effectively removing you from the game. Similarly, wishing for a Legendary magic item or an Artifact might instantly transport you to the presence of the item's current owner. If your wish is granted and its effects have consequences for a whole community, region, or world, you are likely to attract powerful foes. If your wish would affect a god, the god's divine servants might instantly intervene to prevent it or to encourage you to craft the wish in a particular way. If your wish would undo the multiverse itself, threaten the City of Sigil, or affect the Lady of Pain in any way, you see an image of her in your mind for a moment; she shakes her head, and your wish fails."}]},{"type":"text","content":"The stress of casting Wish to produce any effect other than duplicating another spell weakens you. After enduring that stress, each time you cast a spell until you finish a <i>Long Rest</i>, you take <span class=\\"text-red-400 font-semibold\\">1d10</span> Necrotic damage per level of that spell. This damage can't be reduced or prevented in any way. In addition, your Strength score becomes 3 for <span class=\\"text-green-400 font-mono\\">2d4</span> days. For each of those days that you spend resting and doing nothing more than light activity, your remaining recovery time decreases by 2 days. Finally, there is a 33% chance that you are unable to cast <a href=\\"/spells?search=Wish\\" class=\\"text-dnd-gold hover:underline\\">Wish</a> ever again if you suffer this stress."}],"entriesHigherLevel":[],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":341},{"name":"Witch Bolt","source":"XPHB","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a twig struck by lightning"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A beam of crackling energy lances toward a creature within range, forming a sustained arc of lightning between you and the target. Make a ranged spell attack against it. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">2d12</span> Lightning damage."},{"type":"text","content":"On each of your subsequent turns, you can take a <i>Bonus Action</i> to deal <span class=\\"text-red-400 font-semibold\\">1d12</span> Lightning damage to the target automatically, even if the first attack missed."},{"type":"text","content":"The spell ends if the target is ever outside the spell's range or if it has Total <i>Cover</i> from you."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The initial damage increases by 2d12 for each spell slot level above 1."}]}],"damageInflict":["lightning"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":343},{"name":"Word of Recall","source":"XPHB","level":6,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":5}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You and up to five willing creatures within 5 feet of you instantly teleport to a previously designated sanctuary. You and any creatures that teleport with you appear in the nearest unoccupied space to the spot you designated when you prepared your sanctuary (see below). If you cast this spell without first preparing a sanctuary, the spell has no effect."},{"type":"text","content":"You must designate a location, such as a temple, as a sanctuary by casting this spell there."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":343},{"name":"Wrathful Smite","source":"XPHB","level":1,"school":"N","time":[{"number":1,"unit":"bonus","condition":"which you take immediately after hitting a creature with a Melee weapon or an {@variantrule Unarmed Strike|XPHB}"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"The target takes an extra <span class=\\"text-red-400 font-semibold\\">1d6</span> Necrotic damage from the attack, and it must succeed on a Wisdom saving throw or have the <i class=\\"text-dnd-gold\\">Frightened</i> condition until the spell ends. At the end of each of its turns, the <i class=\\"text-dnd-gold\\">Frightened</i> target repeats the save, ending the spell on itself on a success."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 1d6 for each spell slot level above 1."}]}],"damageInflict":["necrotic"],"conditionInflict":["frightened"],"savingThrow":["wisdom"],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":343},{"name":"Zone of Truth","source":"XPHB","level":2,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10}}],"entries":[{"type":"text","content":"You create a magical zone that guards against deception in a 15-foot-radius <i>Sphere [Area of Effect]</i> centered on a point within range. Until the spell ends, a creature that enters the spell's area for the first time on a turn or starts its turn there makes a Charisma saving throw. On a failed save, a creature can't speak a deliberate lie while in the radius. You know whether a creature succeeds or fails on this save."},{"type":"text","content":"An affected creature is aware of the spell and can avoid answering questions to which it would normally respond with a lie. Such a creature can be evasive yet must be truthful."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["charisma"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":343},{"name":"Gate Seal","source":"SatO","level":4,"school":"A","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"a broken portal key, which the spell consumes","consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"You fortify the fabric of the planes in a 30-foot cube you can see within range. Within that area, portals close and can't be opened for the duration. Spells and other effects that allow planar travel or open portals, such as <a href=\\"/spells?search=gate\\" class=\\"text-dnd-gold hover:underline\\">gate</a> or <a href=\\"/spells?search=plane shift\\" class=\\"text-dnd-gold hover:underline\\">plane shift</a>, fail if used to enter or leave the area. The cube is stationary."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 6th level or higher, the spell lasts until dispelled."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":12},{"name":"Warp Sense","source":"SatO","level":2,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a razorvine leaf"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"For the duration, you sense the presence of portals, even inactive ones, within 30 feet of yourself."},{"type":"text","content":"If you detect a portal in this way, you can use your action to study it. Make a DC 15 ability check using your spellcasting ability. On a successful check, you learn the destination plane of the portal and what portal key it requires, then the spell ends. On a failed check, you learn nothing and can't study that portal again using this spell until you cast it again."},{"type":"text","content":"The spell can penetrate most barriers but is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":12},{"name":"Borrowed Knowledge","source":"SCC","level":2,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"a book worth at least 25 gp","cost":2500}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You draw on knowledge from spirits of the past. Choose one skill in which you lack proficiency. For the spell's duration, you have proficiency in the chosen skill. The spell ends early if you cast it again."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":37},{"name":"Kinetic Jaunt","source":"SCC","level":2,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You magically empower your movement with dance-like steps, giving yourself the following benefits for the duration."},{"type":"list","items":["Your walking speed increases by 10 feet.","You don't provoke opportunity attacks.","You can move through the space of another creature, and it doesn't count as difficult terrain. If you end your turn in another creature's space, you are shunted to the last unoccupied space you occupied, and you take <span class=\\"text-red-400 font-semibold\\">1d8</span> force damage."]}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":37},{"name":"Silvery Barbs","source":"SCC","level":1,"school":"E","time":[{"number":1,"unit":"reaction","condition":"which you take when a creature you can see within 60 feet of yourself succeeds on an attack roll, an ability check, or a saving throw"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You magically distract the triggering creature and turn its momentary uncertainty into encouragement for another creature. The triggering creature must reroll the <span class=\\"text-green-400 font-mono\\">d20</span> and use the lower roll."},{"type":"text","content":"You can then choose a different creature you can see within range (you can choose yourself). The chosen creature has advantage on the next attack roll, ability check, or saving throw it makes within 1 minute. A creature can be empowered by only one use of this spell at a time."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"reaction","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":38},{"name":"Vortex Warp","source":"SCC","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You magically twist space around another creature you can see within range. The target must succeed on a Constitution saving throw (the target can choose to fail), or the target is teleported to an unoccupied space of your choice that you can see within range. The chosen space must be on a surface or in a liquid that can support the target without the target having to squeeze."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 3rd level or higher, the range of the spell increases by 30 feet for each slot level above 2nd."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":38},{"name":"Booming Blade","source":"TCE","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"radius","distance":{"type":"feet","amount":5}},"components":{"s":true,"m":{"text":"a melee weapon worth at least 1 sp","cost":10}},"duration":[{"type":"timed","duration":{"type":"round","amount":1}}],"entries":[{"type":"text","content":"You brandish the weapon used in the spell's casting and make a melee attack with it against one creature within 5 feet of you. On a hit, the target suffers the weapon attack's normal effects and then becomes sheathed in booming energy until the start of your next turn. If the target willingly moves 5 feet or more before then, the target takes <span class=\\"text-red-400 font-semibold\\">1d8</span> thunder damage, and the spell ends."},{"type":"text","content":"This spell's damage increases when you reach certain levels. At 5th level, the melee attack deals an extra <span class=\\"text-red-400 font-semibold\\">1d8</span> thunder damage to the target on a hit, and the damage the target takes for moving increases to <span class=\\"text-red-400 font-semibold\\">2d8</span>. Both damage rolls increase by 1d8 at 11th level (<span class=\\"text-red-400 font-semibold\\">2d8</span> and <span class=\\"text-red-400 font-semibold\\">3d8</span>) and again at 17th level (<span class=\\"text-red-400 font-semibold\\">3d8</span> and <span class=\\"text-red-400 font-semibold\\">4d8</span>)."}],"entriesHigherLevel":[],"damageInflict":["thunder"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":106},{"name":"Dream of the Blue Veil","source":"TCE","level":7,"school":"C","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":20}},"components":{"v":true,"s":true,"m":"a magic item or a willing creature from the destination world"},"duration":[{"type":"timed","duration":{"type":"hour","amount":6}}],"entries":[{"type":"text","content":"You and up to eight willing creatures within range fall <i class=\\"text-dnd-gold\\">unconscious</i> for the spell's duration and experience visions of another world on the Material Plane, such as Oerth, Toril, Krynn, or Eberron. If the spell reaches its full duration, the visions conclude with each of you encountering and pulling back a mysterious blue curtain. The spell then ends with you mentally and physically transported to the world that was in the visions."},{"type":"text","content":"To cast this spell, you must have a magic item that originated on the world you wish to reach, and you must be aware of the world's existence, even if you don't know the world's name. Your destination in the other world is a safe location within 1 mile of where the magic item was created. Alternatively, you can cast the spell if one of the affected creatures was born on the other world, which causes your destination to be a safe location within 1 mile of where that creature was born."},{"type":"text","content":"The spell ends early on a creature if that creature takes any damage, and the creature isn't transported. If you take any damage, the spell ends for you and all the other creatures, with none of you being transported."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["unconscious"],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":106},{"name":"Green-Flame Blade","source":"TCE","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"radius","distance":{"type":"feet","amount":5}},"components":{"s":true,"m":{"text":"a melee weapon worth at least 1 sp","cost":10}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You brandish the weapon used in the spell's casting and make a melee attack with it against one creature within 5 feet of you. On a hit, the target suffers the weapon attack's normal effects, and you can cause green fire to leap from the target to a different creature of your choice that you can see within 5 feet of it. The second creature takes fire damage equal to your spellcasting ability modifier."},{"type":"text","content":"This spell's damage increases when you reach certain levels. At 5th level, the melee attack deals an extra <span class=\\"text-red-400 font-semibold\\">1d8</span> fire damage to the target on a hit, and the fire damage to the second creature increases to <span class=\\"text-red-400 font-semibold\\">1d8</span> + your spellcasting ability modifier. Both damage rolls increase by <span class=\\"text-red-400 font-semibold\\">1d8</span> at 11th level (<span class=\\"text-red-400 font-semibold\\">2d8</span> and <span class=\\"text-red-400 font-semibold\\">2d8</span>) and 17th level (<span class=\\"text-red-400 font-semibold\\">3d8</span> and <span class=\\"text-red-400 font-semibold\\">3d8</span>)."}],"entriesHigherLevel":[],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":107},{"name":"Intellect Fortress","source":"TCE","level":3,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"For the duration, you or one willing creature you can see within range has resistance to psychic damage, as well as advantage on Intelligence, Wisdom, and Charisma saving throws."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd. The creatures must be within 30 feet of each other when you target them."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":107},{"name":"Lightning Lure","source":"TCE","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"radius","distance":{"type":"feet","amount":15}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You create a lash of lightning energy that strikes at one creature of your choice that you can see within 15 feet of you. The target must succeed on a Strength saving throw or be pulled up to 10 feet in a straight line toward you and then take <span class=\\"text-red-400 font-semibold\\">1d8</span> lightning damage if it is within 5 feet of you."},{"type":"text","content":"This spell's damage increases by <span class=\\"text-red-400 font-semibold\\">1d8</span> when you reach 5th level (<span class=\\"text-red-400 font-semibold\\">2d8</span>), 11th level (<span class=\\"text-red-400 font-semibold\\">3d8</span>), and 17th level (<span class=\\"text-red-400 font-semibold\\">4d8</span>)."}],"entriesHigherLevel":[],"damageInflict":["lightning"],"conditionInflict":[],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":107},{"name":"Mind Sliver","source":"XPHB","level":0,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You try to temporarily sliver the mind of one creature you can see within range. The target must succeed on an Intelligence saving throw or take <span class=\\"text-red-400 font-semibold\\">1d6</span> Psychic damage and subtract <span class=\\"text-green-400 font-mono\\">1d4</span> from the next saving throw it makes before the end of your next turn."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d6</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d6</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d6</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d6</span>)."}]}],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":298},{"name":"Spirit Shroud","source":"TCE","level":3,"school":"N","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth spirits of the dead, which flit around you for the spell's duration. The spirits are intangible and invulnerable."},{"type":"text","content":"Until the spell ends, any attack you make deals <span class=\\"text-red-400 font-semibold\\">1d8</span> extra damage when you hit a creature within 10 feet of you. This damage is radiant, necrotic, or cold (your choice when you cast the spell). Any creature that takes this damage can't regain hit points until the start of your next turn."},{"type":"text","content":"In addition, any creature of your choice that you can see that starts its turn within 10 feet of you has its speed reduced by 10 feet until the start of your next turn."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for every two slot levels above 3rd."}]}],"damageInflict":["radiant","necrotic","cold"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":108},{"name":"Summon Aberration","source":"XPHB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"a pickled tentacle and an eyeball in a platinum-inlaid vial worth 400+ GP","cost":40000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth an aberrant spirit. It manifests in an unoccupied space that you can see within range and uses the <b>Aberrant Spirit</b> stat block. When you cast the spell, choose Beholderkin, Mind Flayer, or Slaad. The creature resembles an Aberration of that kind, which determines certain details in its stat block. The creature disappears when it drops to 0 <i>Hit Points</i> or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your allies. In combat, it shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":322},{"name":"Summon Beast","source":"XPHB","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"a feather, tuft of fur, and fish tail inside a gilded acorn worth 200+ GP","cost":20000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth a bestial spirit. It manifests in an unoccupied space that you can see within range and uses the <b>Bestial Spirit</b> stat block. When you cast the spell, choose an environment: Air, Land, or Water. The creature resembles an animal of your choice that is native to the chosen environment, which determines certain details in its stat block. The creature disappears when it drops to 0 <i>Hit Points</i> or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your allies. In combat, the creature shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":322},{"name":"Summon Celestial","source":"XPHB","level":5,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"a reliquary worth 500+ GP","cost":50000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth a Celestial spirit. It manifests in an angelic form in an unoccupied space that you can see within range and uses the <b>Celestial Spirit</b> stat block. When you cast the spell, choose Avenger or Defender. Your choice determines certain details in its stat block. The creature disappears when it drops to 0 <i>Hit Points</i> or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your allies. In combat, the creature shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":323},{"name":"Summon Construct","source":"XPHB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"a lockbox worth 400+ GP","cost":40000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth the spirit of a Construct. It manifests in an unoccupied space that you can see within range and uses the <b>Construct Spirit</b> stat block. When you cast the spell, choose a material: Clay, Metal, or Stone. The creature resembles an animate statue (you determine the appearance) made of the chosen material, which determines certain details in its stat block. The creature disappears when it drops to 0 <i>Hit Points</i> or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your allies. In combat, the creature shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":324},{"name":"Summon Elemental","source":"XPHB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"air, a pebble, ash, and water inside a gold-inlaid vial worth 400+ GP","cost":40000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth an Elemental spirit. It manifests in an unoccupied space that you can see within range and uses the <b>Elemental Spirit</b> stat block. When you cast the spell, choose an element: Air, Earth, Fire, or Water. The creature resembles a bipedal form wreathed in the chosen element, which determines certain details in its stat block. The creature disappears when it drops to 0 <i>Hit Points</i> or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your allies. In combat, the creature shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":325},{"name":"Summon Fey","source":"XPHB","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"a gilded flower worth 300+ GP","cost":30000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth a Fey spirit. It manifests in an unoccupied space that you can see within range and uses the <b>Fey Spirit</b> stat block. When you cast the spell, choose a mood: Fuming, Mirthful, or Tricksy. The creature resembles a Fey creature of your choice marked by the chosen mood, which determines certain details in its stat block. The creature disappears when it drops to 0 <i>Hit Points</i> or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your allies. In combat, the creature shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":326},{"name":"Summon Fiend","source":"XPHB","level":6,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"a bloody vial worth 600+ GP","cost":60000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth a fiendish spirit. It manifests in an unoccupied space that you can see within range and uses the <b>Fiendish Spirit</b> stat block. When you cast the spell, choose Demon, Devil, or Yugoloth. The creature resembles a Fiend of the chosen type, which determines certain details in its stat block. The creature disappears when it drops to 0 <i>Hit Points</i> or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your allies. In combat, the creature shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":326},{"name":"Summon Shadowspawn","source":"TCE","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"tears inside a gem worth at least 300 gp","cost":30000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth a shadowy spirit. It manifests in an unoccupied space that you can see within range. This corporeal form uses the <b>Shadow Spirit</b> stat block. When you cast the spell, choose an emotion: Fury, Despair, or Fear. The creature resembles a misshapen biped marked by the chosen emotion, which determines certain traits in its stat block. The creature disappears when it drops to 0 hit points or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your companions. In combat, the creature shares your initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its move to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, use the higher level wherever the spell's level appears in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":113},{"name":"Summon Undead","source":"XPHB","level":3,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"a gilded skull worth 300+ GP","cost":30000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth an Undead spirit. It manifests in an unoccupied space that you can see within range and uses the <b>Undead Spirit</b> stat block. When you cast the spell, choose the creature's form: Ghostly, Putrid, or Skeletal. The spirit resembles an Undead creature with the chosen form, which determines certain details in its stat block. The creature disappears when it drops to 0 <i>Hit Points</i> or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your allies. In combat, the creature shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":328},{"name":"Sword Burst","source":"TCE","level":0,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"radius","distance":{"type":"feet","amount":5}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You create a momentary circle of spectral blades that sweep around you. All other creatures within 5 feet of you must succeed on a Dexterity saving throw or take <span class=\\"text-red-400 font-semibold\\">1d6</span> force damage."},{"type":"text","content":"This spell's damage increases by <span class=\\"text-red-400 font-semibold\\">1d6</span> when you reach 5th level (<span class=\\"text-red-400 font-semibold\\">2d6</span>), 11th level (<span class=\\"text-red-400 font-semibold\\">3d6</span>), and 17th level (<span class=\\"text-red-400 font-semibold\\">4d6</span>)."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":115},{"name":"Tasha's Caustic Brew","source":"TCE","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"line","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a bit of rotten food"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A stream of acid emanates from you in a line 30 feet long and 5 feet wide in a direction you choose. Each creature in the line must succeed on a Dexterity saving throw or be covered in acid for the spell's duration or until a creature uses its action to scrape or wash the acid off itself or another creature. A creature covered in the acid takes <span class=\\"text-red-400 font-semibold\\">2d4</span> acid damage at start of each of its turns."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 2d4 for each slot level above 1st."}]}],"damageInflict":["acid"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":115},{"name":"Tasha's Mind Whip","source":"TCE","level":2,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"round","amount":1}}],"entries":[{"type":"text","content":"You psychically lash out at one creature you can see within range. The target must make an Intelligence saving throw. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">3d6</span> psychic damage, and it can't take a reaction until the end of its next turn. Moreover, on its next turn, it must choose whether it gets a move, an action, or a bonus action; it gets only one of the three. On a successful save, the target takes half as much damage and suffers none of the spell's other effects."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd. The creatures must be within 30 feet of each other when you target them."}]}],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":115},{"name":"Tasha's Otherworldly Guise","source":"TCE","level":6,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"an object engraved with a symbol of the Outer Planes, worth at least 500 gp","cost":50000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Uttering an incantation, you draw on the magic of the Lower Planes or Upper Planes (your choice) to transform yourself. You gain the following benefits until the spell ends:"},{"type":"list","items":["You are immune to fire and poison damage (Lower Planes) or radiant and necrotic damage (Upper Planes).","You are immune to the <i class=\\"text-dnd-gold\\">poisoned</i> condition (Lower Planes) or the <i class=\\"text-dnd-gold\\">charmed</i> condition (Upper Planes).","Spectral wings appear on your back, giving you a flying speed of 40 feet.","You have a +2 bonus to AC.","All your weapon attacks are magical, and when you make a weapon attack, you can use your spellcasting ability modifier, instead of Strength or Dexterity, for the attack and damage rolls.","You can attack twice, instead of once, when you take the <b>Attack</b> action on your turn. You ignore this benefit if you already have a feature, like Extra Attack, that lets you attack more than once when you take the Attack action on your turn."]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":116},{"name":"Abi-Dalzim's Horrid Wilting","source":"XGE","level":8,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":"a bit of sponge"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You draw the moisture from every creature in a 30-foot cube centered on a point you choose within range. Each creature in that area must make a Constitution saving throw. Constructs and undead aren't affected, and plants and water elementals make this saving throw with disadvantage. A creature takes <span class=\\"text-red-400 font-semibold\\">12d8</span> necrotic damage on a failed save, or half as much damage on a successful one."},{"type":"text","content":"Nonmagical plants in the area that aren't creatures, such as trees and shrubs, wither and die instantly."}],"entriesHigherLevel":[],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":150},{"name":"Absorb Elements","source":"XGE","level":1,"school":"A","time":[{"number":1,"unit":"reaction","condition":"which you take when you take acid, cold, fire, lightning, or thunder damage"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"s":true},"duration":[{"type":"timed","duration":{"type":"round","amount":1}}],"entries":[{"type":"text","content":"The spell captures some of the incoming energy, lessening its effect on you and storing it for your next melee attack. You have resistance to the triggering damage type until the start of your next turn. Also, the first time you hit with a melee attack on your next turn, the target takes an extra <span class=\\"text-red-400 font-semibold\\">1d6</span> damage of the triggering type, and the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 2nd level or higher, the extra damage increases by 1d6 for each slot level above 1st."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"reaction","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":150},{"name":"Aganazzar's Scorcher","source":"XGE","level":2,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a red dragon's scale"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A line of roaring flame 30 feet long and 5 feet wide emanates from you in a direction you choose. Each creature in the line must make a Dexterity saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">3d8</span> fire damage on a failed save, or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 3d8 for each slot level above 2nd."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":150},{"name":"Beast Bond","source":"XGE","level":1,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a bit of fur wrapped in a cloth"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You establish a telepathic link with one beast you touch that is friendly to you or <i class=\\"text-dnd-gold\\">charmed</i> by you. The spell fails if the beast's Intelligence score is 4 or higher. Until the spell ends, the link is active while you and the beast are within line of sight of each other. Through the link, the beast can understand your telepathic messages to it, and it can telepathically communicate simple emotions and concepts back to you. While the link is active, the beast gains advantage on attack rolls against any creature within 5 feet of you that you can see."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":150},{"name":"Bones of the Earth","source":"XGE","level":6,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You cause up to six pillars of stone to burst from places on the ground that you can see within range. Each pillar is a cylinder that has a diameter of 5 feet and a height of up to 30 feet. The ground where a pillar appears must be wide enough for its diameter, and you can target the ground under a creature if that creature is Medium or smaller. Each pillar has AC 5 and 30 hit points. When reduced to 0 hit points, a pillar crumbles into rubble, which creates an area of difficult terrain with a 10-foot radius that lasts until the rubble is cleared. Each 5-foot-diameter portion of the area requires at least 1 minute to clear by hand."},{"type":"text","content":"If a pillar is created under a creature, that creature must succeed on a Dexterity saving throw or be lifted by the pillar. A creature can choose to fail the save."},{"type":"text","content":"If a pillar is prevented from reaching its full height because of a ceiling or other obstacle, a creature on the pillar takes <span class=\\"text-red-400 font-semibold\\">6d6</span> bludgeoning damage and is <i class=\\"text-dnd-gold\\">restrained</i>, pinched between the pillar and the obstacle. The <i class=\\"text-dnd-gold\\">restrained</i> creature can use an action to make a Strength or Dexterity check (the creature's choice) against the spell's save DC. On a success, the creature is no longer <i class=\\"text-dnd-gold\\">restrained</i> and must either move off the pillar or fall off it."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 7th level or higher, you can create two additional pillars for each slot level above 6th."}]}],"damageInflict":["bludgeoning"],"conditionInflict":["restrained"],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":150},{"name":"Catapult","source":"XGE","level":1,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Choose one object weighing 1 to 5 pounds within range that isn't being worn or carried. The object flies in a straight line up to 90 feet in a direction you choose before falling to the ground, stopping early if it impacts against a solid surface. If the object would strike a creature, that creature must make a Dexterity saving throw. On a failed save, the object strikes the target and stops moving. When the object strikes something, the object and what it strikes each take <span class=\\"text-red-400 font-semibold\\">3d8</span> bludgeoning damage."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 2nd level or higher, the maximum weight of objects that you can target with this spell increases by 5 pounds, and the damage increases by 3d8, for each slot level above 1st."}]}],"damageInflict":["bludgeoning"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":150},{"name":"Cause Fear","source":"XGE","level":1,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You awaken the sense of mortality in one creature you can see within range. A construct or an undead is immune to this effect. The target must succeed on a Wisdom saving throw or become <i class=\\"text-dnd-gold\\">frightened</i> of you until the spell ends. The <i class=\\"text-dnd-gold\\">frightened</i> target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them."}]}],"damageInflict":[],"conditionInflict":["frightened"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":151},{"name":"Ceremony","source":"XGE","level":1,"school":"A","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"25 gp worth of powdered silver, which the spell consumes","cost":2500,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You perform a special religious ceremony that is infused with magic. When you cast the spell, choose one of the following rites, the target of which must be within 10 feet of you throughout the casting."},{"type":"section","name":"Atonement","entries":[{"type":"text","content":"You touch one willing creature whose alignment has changed, and you make a DC 20 Wisdom (<i>Insight</i>) check. On a successful check, you restore the target to its original alignment."}]},{"type":"section","name":"Bless Water","entries":[{"type":"text","content":"You touch one <b>vial</b> of water and cause it to become <b>Holy Water (flask)</b>."}]},{"type":"section","name":"Coming of Age","entries":[{"type":"text","content":"You touch one humanoid who is a young adult. For the next 24 hours, whenever the target makes an ability check, it can roll a <span class=\\"text-green-400 font-mono\\">d4</span> and add the number rolled to the ability check. A creature can benefit from this rite only once."}]},{"type":"section","name":"Dedication","entries":[{"type":"text","content":"You touch one humanoid who wishes to be dedicated to your god's service. For the next 24 hours, whenever the target makes a saving throw, it can roll a <span class=\\"text-green-400 font-mono\\">d4</span> and add the number rolled to the save. A creature can benefit from this rite only once."}]},{"type":"section","name":"Funeral Rite","entries":[{"type":"text","content":"You touch one corpse, and for the next 7 days, the target can't become undead by any means short of a <a href=\\"/spells?search=wish\\" class=\\"text-dnd-gold hover:underline\\">wish</a> spell."}]},{"type":"section","name":"Wedding","entries":[{"type":"text","content":"You touch adult humanoids willing to be bonded together in marriage. For the next 7 days, each target gains a +2 bonus to AC while they are within 30 feet of each other. A creature can benefit from this rite again only if widowed."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":true,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":151},{"name":"Chaos Bolt","source":"XGE","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You hurl an undulating, warbling mass of chaotic energy at one creature in range. Make a ranged spell attack against the target. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">2d8 + 1d6</span> damage. Choose one of the <span class=\\"text-green-400 font-mono\\">d8</span>s. The number rolled on that die determines the attack's damage type, as shown below."},{"type":"table","caption":"Chaos Bolt","colLabels":["{@dice d8}","Damage Type"],"rows":[["[object Object]","Acid"],["[object Object]","Cold"],["[object Object]","Fire"],["[object Object]","Force"],["[object Object]","Lightning"],["[object Object]","Poison"],["[object Object]","Psychic"],["[object Object]","Thunder"]]},{"type":"text","content":"If you roll the same number on both <span class=\\"text-green-400 font-mono\\">d8</span>s, the chaotic energy leaps from the target to a different creature of your choice within 30 feet of it. Make a new attack roll against the new target, and make a new damage roll, which could cause the chaotic energy to leap again."},{"type":"text","content":"A creature can be targeted only once by each casting of this spell."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 2nd level or higher, each target takes 2d8 + 1d6 extra damage of the type rolled for each slot level above 1st."}]}],"damageInflict":["acid","cold","fire","force","lightning","poison","psychic","thunder"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":151},{"name":"Charm Monster","source":"XPHB","level":4,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"One creature you can see within range makes a Wisdom saving throw. It does so with <i>Advantage</i> if you or your allies are fighting it. On a failed save, the target has the <i class=\\"text-dnd-gold\\">Charmed</i> condition until the spell ends or until you or your allies damage it. The <i class=\\"text-dnd-gold\\">Charmed</i> creature is <i>Friendly [Attitude]</i> to you. When the spell ends, the target knows it was <i class=\\"text-dnd-gold\\">Charmed</i> by you."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"You can target one additional creature for each spell slot level above 4."}]}],"damageInflict":[],"conditionInflict":["charmed"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":249},{"name":"Control Flames","source":"XGE","level":0,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"s":true},"duration":[{"type":"instant"},{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You choose nonmagical flame that you can see within range and that fits within a 5-foot cube. You affect it in one of the following ways:"},{"type":"list","items":["You instantaneously expand the flame 5 feet in one direction, provided that wood or other fuel is present in the new location.","You instantaneously extinguish the flames within the cube.","You double or halve the area of bright light and dim light cast by the flame, change its color, or both. The change lasts for 1 hour.","You cause simple shapes—such as the vague form of a creature, an inanimate object, or a location—to appear within the flames and animate as you like. The shapes last for 1 hour."]},{"type":"text","content":"If you cast this spell multiple times, you can have up to three non-instantaneous effects created by it active at a time, and you can dismiss such an effect as an action."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":152},{"name":"Control Winds","source":"XGE","level":5,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":300}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You take control of the air in a 100-foot cube that you can see within range. Choose one of the following effects when you cast the spell. The effect lasts for the spell's duration, unless you use your action on a later turn to switch to a different effect. You can also use your action to temporarily halt the effect or to restart one you've halted."},{"type":"section","name":"Gusts","entries":[{"type":"text","content":"A wind picks up within the cube, continually blowing in a horizontal direction you designate. You choose the intensity of the wind: calm, moderate, or strong. If the wind is moderate or strong, ranged weapon attacks that pass through it or that are made against targets within the cube have disadvantage on their attack rolls. If the wind is strong, any creature moving against the wind must spend 1 extra foot of movement for each foot moved."}]},{"type":"section","name":"Downdraft","entries":[{"type":"text","content":"You cause a sustained blast of strong wind to blow downward from the top of the cube. Ranged weapon attacks that pass through the cube or that are made against targets within it have disadvantage on their attack rolls. A creature must make a Strength saving throw if it flies into the cube for the first time on a turn or starts its turn there flying. On a failed save, the creature is knocked <i class=\\"text-dnd-gold\\">prone</i>."}]},{"type":"section","name":"Updraft","entries":[{"type":"text","content":"You cause a sustained updraft within the cube, rising upward from the cube's bottom side. Creatures that end a fall within the cube take only half damage from the fall. When a creature in the cube makes a vertical jump, the creature can jump up to 10 feet higher than normal."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["prone"],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":152},{"name":"Create Bonfire","source":"XGE","level":0,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You create a bonfire on ground that you can see within range. Until the spell ends, the magic bonfire fills a 5-foot cube. Any creature in the bonfire's space when you cast the spell must succeed on a Dexterity saving throw or take <span class=\\"text-red-400 font-semibold\\">1d8</span> fire damage. A creature must also make the saving throw when it moves into the bonfire's space for the first time on a turn or ends its turn there."},{"type":"text","content":"The bonfire ignites flammable objects in its area that aren't being worn or carried."},{"type":"text","content":"The spell's damage increases by <span class=\\"text-red-400 font-semibold\\">1d8</span> when you reach 5th level (<span class=\\"text-red-400 font-semibold\\">2d8</span>), 11th level (<span class=\\"text-red-400 font-semibold\\">3d8</span>), and 17th level (<span class=\\"text-red-400 font-semibold\\">4d8</span>)."}],"entriesHigherLevel":[],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":152},{"name":"Create Homunculus","source":"XGE","level":6,"school":"T","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"clay, ash, and mandrake root, all of which the spell consumes, and a jewel-encrusted dagger worth at least 1,000 gp","cost":100000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"While speaking an intricate incantation, you cut yourself with a jewel-encrusted dagger, taking <span class=\\"text-red-400 font-semibold\\">2d4</span> piercing damage that can't be reduced in any way. You then drip your blood on the spell's other components and touch them, transforming them into a special construct called a <b>homunculus</b>."},{"type":"text","content":"The statistics of the <b>homunculus</b> are in the Monster Manual. It is your faithful companion, and it dies if you die. Whenever you finish a long rest, you can spend up to half your Hit Dice if the homunculus is on the same plane of existence as you. When you do so, roll each die and add your Constitution modifier to it. Your hit point maximum is reduced by the total, and the homunculus's hit point maximum and current hit points are both increased by it. This process can reduce you to no lower than 1 hit point, and the change to your and the homunculus's hit points ends when you finish your next long rest. The reduction to your hit point maximum can't be removed by any means before then, except by the homunculus's death."},{"type":"text","content":"You can have only one homunculus at a time. If you cast this spell while your homunculus lives, the spell fails."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":152},{"name":"Crown of Stars","source":"XGE","level":7,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"Seven star-like motes of light appear and orbit your head until the spell ends. You can use a bonus action to send one of the motes streaking toward one creature or object within 120 feet of you. When you do so, make a ranged spell attack. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">4d12</span> radiant damage. Whether you hit or miss, the mote is expended. The spell ends early if you expend the last mote."},{"type":"text","content":"If you have four or more motes remaining, they shed bright light in a 30-foot radius and dim light for an additional 30 feet. If you have one to three motes remaining, they shed dim light in a 30-foot radius."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 8th level or higher, the number of motes created increases by two for each slot level above 7th."}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":152},{"name":"Danse Macabre","source":"XGE","level":5,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Threads of dark power leap from your fingers to pierce up to five Small or Medium corpses you can see within range. Each corpse immediately stands up and becomes undead. You decide whether it is a <b>zombie</b> or a <b>skeleton</b> (the statistics for <b>zombie</b> and <b>skeleton</b> are in the Monster Manual), and it gains a bonus to its attack and damage rolls equal to your spellcasting ability modifier."},{"type":"text","content":"You can use a bonus action to mentally command the creatures you make with this spell, issuing the same command to all of them. To receive the command, a creature must be within 60 feet of you. You decide what action the creatures will take and where they will move during their next turn, or you can issue a general command, such as to guard a chamber or passageway against your foes. If you issue no commands, the creatures do nothing except defend themselves against hostile creatures. Once given an order, the creatures continue to follow it until their task is complete."},{"type":"text","content":"The creatures are under your control until the spell ends, after which they become inanimate once more."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 6th level or higher, you animate up to two additional corpses for each slot level above 5th."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":153},{"name":"Dawn","source":"XGE","level":5,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"a sunburst pendant worth at least 100 gp","cost":10000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"The light of dawn shines down on a location you specify within range. Until the spell ends, a 30-foot-radius, 40-foot-high cylinder of bright light glimmers there. This light is sunlight."},{"type":"text","content":"When the cylinder appears, each creature in it must make a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">4d10</span> radiant damage on a failed save, or half as much damage on a successful one. A creature must also make this saving throw whenever it ends its turn in the cylinder."},{"type":"text","content":"If you're within 60 feet of the cylinder, you can move it up to 60 feet as a bonus action on your turn."}],"entriesHigherLevel":[],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":153},{"name":"Dragon's Breath","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":"a hot pepper"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You touch one willing creature, and choose Acid, Cold, Fire, Lightning, or Poison. Until the spell ends, the target can take a <b>Magic</b> action to exhale a 15-foot <i>Cone [Area of Effect]</i>. Each creature in that area makes a Dexterity saving throw, taking <span class=\\"text-red-400 font-semibold\\">3d6</span> damage of the chosen type on a failed save or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d6 for each spell slot level above 2."}]}],"damageInflict":["acid","cold","fire","lightning","poison"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":266},{"name":"Druid Grove","source":"XGE","level":6,"school":"A","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true,"m":{"text":"mistletoe, which the spell consumes, that was harvested with a golden sickle under the light of a full moon","consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"You invoke the spirits of nature to protect an area outdoors or underground. The area can be as small as a 30-foot cube or as large as a 90-foot cube. Buildings and other structures are excluded from the affected area. If you cast this spell in the same area every day for a year, the spell lasts until dispelled."},{"type":"text","content":"The spell creates the following effects within the area. When you cast this spell, you can specify creatures as friends who are immune to the effects. You can also specify a password that, when spoken aloud, makes the speaker immune to these effects."},{"type":"text","content":"The entire warded area radiates magic. A <a href=\\"/spells?search=dispel magic\\" class=\\"text-dnd-gold hover:underline\\">dispel magic</a> cast on the area, if successful, removes only one of the following effects, not the entire area. That spell's caster chooses which effect to end. Only when all its effects are gone is this spell dispelled."},{"type":"section","name":"Solid Fog","entries":[{"type":"text","content":"You can fill any number of 5-foot squares on the ground with thick fog, making them heavily obscured. The fog reaches 10 feet high. In addition, every foot of movement through the fog costs 2 extra feet. To a creature immune to this effect, the fog obscures nothing and looks like soft mist, with motes of green light floating in the air."}]},{"type":"section","name":"Grasping Undergrowth","entries":[{"type":"text","content":"You can fill any number of 5-foot squares on the ground that aren't filled with fog with grasping weeds and vines, as if they were affected by an <a href=\\"/spells?search=entangle\\" class=\\"text-dnd-gold hover:underline\\">entangle</a> spell. To a creature immune to this effect, the weeds and vines feel soft and reshape themselves to serve as temporary seats or beds."}]},{"type":"section","name":"Grove Guardians","entries":[{"type":"text","content":"You can animate up to four trees in the area, causing them to uproot themselves from the ground. These trees have the same statistics as an <b>awakened tree</b>, which appears in the Monster Manual, except they can't speak, and their bark is covered with druidic symbols. If any creature not immune to this effect enters the warded area, the grove guardians fight until they have driven off or slain the intruders. The grove guardians also obey your spoken commands (no action required by you) that you issue while in the area. If you don't give them commands and no intruders are present, the grove guardians do nothing. The grove guardians can't leave the warded area. When the spell ends, the magic animating them disappears, and the trees take root again if possible."}]},{"type":"section","name":"Additional Spell Effect","entries":[{"type":"text","content":"You can place your choice of one of the following magical effects within the warded area:"}]},{"type":"list","items":["A constant <a href=\\"/spells?search=gust of wind\\" class=\\"text-dnd-gold hover:underline\\">gust of wind</a> in two locations of your choice","<a href=\\"/spells?search=Spike growth\\" class=\\"text-dnd-gold hover:underline\\">Spike growth</a> in one location of your choice","<a href=\\"/spells?search=Wind wall\\" class=\\"text-dnd-gold hover:underline\\">Wind wall</a> in two locations of your choice"]},{"type":"text","content":"To a creature immune to this effect, the winds are a fragrant, gentle breeze, and the area of <a href=\\"/spells?search=spike growth\\" class=\\"text-dnd-gold hover:underline\\">spike growth</a> is harmless."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":154},{"name":"Dust Devil","source":"XGE","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a pinch of dust"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Choose an unoccupied 5-foot cube of air that you can see within range. An elemental force that resembles a dust devil appears in the cube and lasts for the spell's duration."},{"type":"text","content":"Any creature that ends its turn within 5 feet of the dust devil must make a Strength saving throw. On a failed save, the creature takes <span class=\\"text-red-400 font-semibold\\">1d8</span> bludgeoning damage and is pushed 10 feet away from the dust devil. On a successful save, the creature takes half as much damage and isn't pushed."},{"type":"text","content":"As a bonus action, you can move the dust devil up to 30 feet in any direction. If the dust devil moves over sand, dust, loose dirt, or light gravel, it sucks up the material and forms a 10-foot-radius cloud of debris around itself that lasts until the start of your next turn. The cloud heavily obscures its area."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd."}]}],"damageInflict":["bludgeoning"],"conditionInflict":[],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":154},{"name":"Earth Tremor","source":"XGE","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You cause a tremor in the ground within range. Each creature other than you in that area must make a Dexterity saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">1d6</span> bludgeoning damage and is knocked <i class=\\"text-dnd-gold\\">prone</i>. If the ground in that area is loose earth or stone, it becomes difficult terrain until cleared, with each 5-foot-diameter portion requiring at least 1 minute to clear by hand."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st."}]}],"damageInflict":["bludgeoning"],"conditionInflict":["prone"],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":155},{"name":"Earthbind","source":"XGE","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":300}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Choose one creature you can see within range. Yellow strips of magical energy loop around the creature. The target must succeed on a Strength saving throw, or its flying speed (if any) is reduced to 0 feet for the spell's duration. An airborne creature affected by this spell safely descends at 60 feet per round until it reaches the ground or the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":154},{"name":"Elemental Bane","source":"XGE","level":4,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Choose one creature you can see within range, and choose one of the following damage types: acid, cold, fire, lightning, or thunder. The target must succeed on a Constitution saving throw or be affected by the spell for its duration. The first time each turn the affected target takes damage of the chosen type, the target takes an extra <span class=\\"text-red-400 font-semibold\\">2d6</span> damage of that type. Moreover, the target loses any resistance to that damage type until the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th. The creatures must be within 30 feet of each other when you target them."}]}],"damageInflict":["acid","cold","fire","lightning","thunder"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":155},{"name":"Enemies Abound","source":"XGE","level":3,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You reach into the mind of one creature you can see and force it to make an Intelligence saving throw. A creature automatically succeeds if it is immune to being <i class=\\"text-dnd-gold\\">frightened</i>. On a failed save, the target loses the ability to distinguish friend from foe, regarding all creatures it can see as enemies until the spell ends. Each time the target takes damage, it can repeat the saving throw, ending the effect on itself on a success."},{"type":"text","content":"Whenever the affected creature chooses another creature as a target, it must choose the target at random from among the creatures it can see within range of the attack, spell, or other ability it's using. If an enemy provokes an opportunity attack from the affected creature, the creature must make that attack if it is able to."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":155},{"name":"Erupting Earth","source":"XGE","level":3,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a piece of obsidian"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Choose a point you can see on the ground within range. A fountain of churned earth and stone erupts in a 20-foot cube centered on that point. Each creature in that area must make a Dexterity saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">3d12</span> bludgeoning damage on a failed save, or half as much damage on a successful one. Additionally, the ground in that area becomes difficult terrain until cleared. Each 5-foot-square portion of the area requires at least 1 minute to clear by hand."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 3d12 for each slot level above 3rd."}]}],"damageInflict":["bludgeoning"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":155},{"name":"Far Step","source":"XGE","level":5,"school":"C","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You teleport up to 60 feet to an unoccupied space you can see. On each of your turns before the spell ends, you can use a bonus action to teleport in this way again."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":155},{"name":"Find Greater Steed","source":"XGE","level":4,"school":"C","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You summon a spirit that assumes the form of a loyal, majestic mount. Appearing in an unoccupied space within range, the spirit takes on a form you choose: a <b>griffon</b>, a <b>pegasus</b>, a <b>peryton</b>, a <b>dire wolf</b>, a <b>rhinoceros</b>, or a <b>saber-toothed tiger</b>. The creature has the statistics provided in the Monster Manual for the chosen form, though it is a celestial, a fey, or a fiend (your choice) instead of its normal creature type. Additionally, if it has an Intelligence score of 5 or lower, its Intelligence becomes 6, and it gains the ability to understand one language of your choice that you speak."},{"type":"text","content":"You control the mount in combat. While the mount is within 1 mile of you, you can communicate with it telepathically. While mounted on it, you can make any spell you cast that targets only you also target the mount."},{"type":"text","content":"The mount disappears temporarily when it drops to 0 hit points or when you dismiss it as an action. Casting this spell again re-summons the bonded mount, with all its hit points restored and any conditions removed."},{"type":"text","content":"You can't have more than one mount bonded by this spell or <a href=\\"/spells?search=find steed\\" class=\\"text-dnd-gold hover:underline\\">find steed</a> at the same time. As an action, you can release a mount from its bond, causing it to disappear permanently."},{"type":"text","content":"Whenever the mount disappears, it leaves behind any objects it was wearing or carrying."},{"type":"text","content":"{\\"type\\":\\"inset\\",\\"source\\":\\"FTD\\",\\"page\\":190,\\"name\\":\\"Dragonnel Steeds\\",\\"entries\\":[\\"With the DM's permission, a paladin can summon a spirit in the form of a <b>dragonnel</b> using the find greater steed spell, which appears in <i>Xanathar's Guide to Everything</i>.\\"]}"}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":156},{"name":"Flame Arrows","source":"XGE","level":3,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You touch a quiver containing arrows or bolts. When a target is hit by a ranged weapon attack using a piece of ammunition drawn from the quiver, the target takes an extra <span class=\\"text-red-400 font-semibold\\">1d6</span> fire damage. The spell's magic ends on a piece of ammunition when it hits or misses, and the spell ends when twelve pieces of ammunition have been drawn from the quiver."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, the number of pieces of ammunition you can affect with this spell increases by two for each slot level above 3rd."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":156},{"name":"Frostbite","source":"XGE","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You cause numbing frost to form on one creature that you can see within range. The target must make a Constitution saving throw. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">1d6</span> cold damage, and it has disadvantage on the next weapon attack roll it makes before the end of its next turn."},{"type":"text","content":"The spell's damage increases by <span class=\\"text-red-400 font-semibold\\">1d6</span> when you reach 5th level (<span class=\\"text-red-400 font-semibold\\">2d6</span>), 11th level (<span class=\\"text-red-400 font-semibold\\">3d6</span>), and 17th level (<span class=\\"text-red-400 font-semibold\\">4d6</span>)."}],"entriesHigherLevel":[],"damageInflict":["cold"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":156},{"name":"Guardian of Nature","source":"XGE","level":4,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A nature spirit answers your call and transforms you into a powerful guardian. The transformation lasts until the spell ends. You choose one of the following forms to assume: Primal Beast or Great Tree."},{"type":"section","name":"Primal Beast","entries":[{"type":"text","content":"Bestial fur covers your body, your facial features become feral, and you gain the following benefits:"}]},{"type":"list","items":["Your walking speed increases by 10 feet.","You gain <i>darkvision</i> with a range of 120 feet.","You make Strength-based attack rolls with advantage.","Your melee weapon attacks deal an extra <span class=\\"text-red-400 font-semibold\\">1d6</span> force damage on a hit."]},{"type":"section","name":"Great Tree","entries":[{"type":"text","content":"Your skin appears barky, leaves sprout from your hair, and you gain the following benefits:"}]},{"type":"list","items":["You gain 10 temporary hit points.","You make Constitution saving throws with advantage.","You make Dexterity- and Wisdom-based attack rolls with advantage.","While you are on the ground, the ground within 15 feet of you is difficult terrain for your enemies."]}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":157},{"name":"Gust","source":"XGE","level":0,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You seize the air and compel it to create one of the following effects at a point you can see within range:"},{"type":"list","items":["One Medium or smaller creature that you choose must succeed on a Strength saving throw or be pushed up to 5 feet away from you.","You create a small blast of air capable of moving one object that is neither held nor carried and that weighs no more than 5 pounds. The object is pushed up to 10 feet away from you. It isn't pushed with enough force to cause damage.","You create a harmless sensory effect using air, such as causing leaves to rustle, wind to slam shutters closed, or your clothing to ripple in a breeze."]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":157},{"name":"Healing Spirit","source":"XGE","level":2,"school":"C","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth a nature spirit to soothe the wounded. The intangible spirit appears in a space that is a 5-foot cube you can see within range. The spirit looks like a transparent beast or fey (your choice)."},{"type":"text","content":"Until the spell ends, whenever you or a creature you can see moves into the spirit's space for the first time on a turn or starts its turn there, you can cause the spirit to restore <span class=\\"text-green-400 font-mono\\">1d6</span> hit points to that creature (no action required). The spirit can't heal constructs or undead. The spirit can heal a number of times equal to 1 + your spellcasting ability modifier (minimum of twice). After healing that number of times, the spirit disappears."},{"type":"text","content":"As a bonus action on your turn, you can move the spirit up to 30 feet to a space you can see."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 3rd level or higher, the healing increases by 1d6 for each slot level above 2nd."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":157},{"name":"Holy Weapon","source":"XGE","level":5,"school":"V","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You imbue a weapon you touch with holy power. Until the spell ends, the weapon emits bright light in a 30-foot radius and dim light for an additional 30 feet. In addition, weapon attacks made with it deal an extra <span class=\\"text-red-400 font-semibold\\">2d8</span> radiant damage on a hit. If the weapon isn't already a magic weapon, it becomes one for the duration."},{"type":"text","content":"As a bonus action on your turn, you can dismiss this spell and cause the weapon to emit a burst of radiance. Each creature of your choice that you can see within 30 feet of the weapon must make a Constitution saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">4d8</span> radiant damage, and it is <i class=\\"text-dnd-gold\\">blinded</i> for 1 minute. On a successful save, a creature takes half as much damage and isn't <i class=\\"text-dnd-gold\\">blinded</i>. At the end of each of its turns, a <i class=\\"text-dnd-gold\\">blinded</i> creature can make a Constitution saving throw, ending the effect on itself on a success."}],"entriesHigherLevel":[],"damageInflict":["radiant"],"conditionInflict":["blinded"],"savingThrow":["constitution"],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":157},{"name":"Ice Knife","source":"XPHB","level":1,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"s":true,"m":"a drop of water or a piece of ice"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You create a shard of ice and fling it at one creature within range. Make a ranged spell attack against the target. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">1d10</span> Piercing damage. Hit or miss, the shard then explodes. The target and each creature within 5 feet of it must succeed on a Dexterity saving throw or take <span class=\\"text-red-400 font-semibold\\">2d6</span> Cold damage."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The Cold damage increases by 2d6 for each spell slot level above 1."}]}],"damageInflict":["cold","piercing"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":287},{"name":"Immolation","source":"XGE","level":5,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Flames wreathe one creature you can see within range. The target must make a Dexterity saving throw. It takes <span class=\\"text-red-400 font-semibold\\">8d6</span> fire damage on a failed save, or half as much damage on a successful one. On a failed save, the target also burns for the spell's duration. The burning target sheds bright light in a 30-foot radius and dim light for an additional 30 feet. At the end of each of its turns, the target repeats the saving throw. It takes <span class=\\"text-red-400 font-semibold\\">4d6</span> fire damage on a failed save, and the spell ends on a successful one. These magical flames can't be extinguished by nonmagical means."},{"type":"text","content":"If damage from this spell kills a target, the target is turned to ash."}],"entriesHigherLevel":[],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":158},{"name":"Infernal Calling","source":"XGE","level":5,"school":"C","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":{"text":"a ruby worth at least 999 gp","cost":99900}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Uttering a dark incantation, you summon a devil from the Nine Hells. You choose the devil's type, which must be one of <i>challenge rating 6 or lower</i>, such as a <b>barbed devil</b> or a <b>bearded devil</b>. The devil appears in an unoccupied space that you can see within range. The devil disappears when it drops to 0 hit points or when the spell ends."},{"type":"text","content":"The devil is unfriendly toward you and your companions. Roll initiative for the devil, which has its own turns. It is under the Dungeon Master's control and acts according to its nature on each of its turns, which might result in its attacking you if it thinks it can prevail, or trying to tempt you to undertake an evil act in exchange for limited service. The DM has the creature's statistics."},{"type":"text","content":"On each of your turns, you can try to issue a verbal command to the devil (no action required by you). It obeys the command if the likely outcome is in accordance with its desires, especially if the result would draw you toward evil. Otherwise, you must make a Charisma (<i>Deception</i>, <i>Intimidation</i>, or <i>Persuasion</i>) check contested by its Wisdom (<i>Insight</i>) check. You make the check with advantage if you say the devil's true name. If your check fails, the devil becomes immune to your verbal commands for the duration of the spell, though it can still carry out your commands if it chooses. If your check succeeds, the devil carries out your command—such as \\"attack my enemies,\\" \\"explore the room ahead,\\" or \\"bear this message to the queen\\"—until it completes the activity, at which point it returns to you to report having done so."},{"type":"text","content":"If your <i>concentration</i> ends before the spell reaches its full duration, the devil doesn't disappear if it has become immune to your verbal commands. Instead, it acts in whatever manner it chooses for <span class=\\"text-green-400 font-mono\\">3d6</span> minutes, and then it disappears."},{"type":"text","content":"If you possess an individual devil's talisman, you can summon that devil if it is of the appropriate challenge rating plus 1, and it obeys all your commands, with no Charisma checks required."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 6th level or higher, the challenge rating increases by 1 for each slot level above 5th."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":158},{"name":"Infestation","source":"XGE","level":0,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a living flea"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You cause a cloud of mites, fleas, and other parasites to appear momentarily on one creature you can see within range. The target must succeed on a Constitution saving throw, or it takes <span class=\\"text-red-400 font-semibold\\">1d6</span> poison damage and moves 5 feet in a random direction if it can move and its speed is at least 5 feet. Roll a <span class=\\"text-green-400 font-mono\\">d4</span> for the direction: 1, north; 2, south; 3, east; or 4, west. This movement doesn't provoke opportunity attacks, and if the direction rolled is blocked, the target doesn't move."},{"type":"text","content":"The spell's damage increases by <span class=\\"text-red-400 font-semibold\\">1d6</span> when you reach 5th level (<span class=\\"text-red-400 font-semibold\\">2d6</span>), 11th level (<span class=\\"text-red-400 font-semibold\\">3d6</span>), and 17th level (<span class=\\"text-red-400 font-semibold\\">4d6</span>)."}],"entriesHigherLevel":[],"damageInflict":["poison"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":158},{"name":"Investiture of Flame","source":"XGE","level":6,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Flames race across your body, shedding bright light in a 30-foot radius and dim light for an additional 30 feet for the spell's duration. The flames don't harm you. Until the spell ends, you gain the following benefits:"},{"type":"list","items":["You are immune to fire damage and have resistance to cold damage.","Any creature that moves within 5 feet of you for the first time on a turn or ends its turn there takes <span class=\\"text-red-400 font-semibold\\">1d10</span> fire damage.","You can use your action to create a line of fire 15 feet long and 5 feet wide extending from you in a direction you choose. Each creature in the line must make a Dexterity saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">4d8</span> fire damage on a failed save, or half as much damage on a successful one."]}],"entriesHigherLevel":[],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":159},{"name":"Investiture of Ice","source":"XGE","level":6,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Until the spell ends, ice rimes your body, and you gain the following benefits:"},{"type":"list","items":["You are immune to cold damage and have resistance to fire damage.","You can move across difficult terrain created by ice or snow without spending extra movement.","The ground in a 10-foot radius around you is icy and is difficult terrain for creatures other than you. The radius moves with you.","You can use your action to create a 15-foot cone of freezing wind extending from your outstretched hand in a direction you choose. Each creature in the cone must make a Constitution saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">4d6</span> cold damage on a failed save, or half as much damage on a successful one. A creature that fails its save against this effect has its speed halved until the start of your next turn."]}],"entriesHigherLevel":[],"damageInflict":["cold"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":159},{"name":"Investiture of Stone","source":"XGE","level":6,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Until the spell ends, bits of rock spread across your body, and you gain the following benefits:"},{"type":"list","items":["You have resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks.","You can use your action to create a small earthquake on the ground in a 15-foot radius centered on you. Other creatures on that ground must succeed on a Dexterity saving throw or be knocked <i class=\\"text-dnd-gold\\">prone</i>.","You can move across difficult terrain made of earth or stone without spending extra movement. You can move through solid earth or stone as if it was air and without destabilizing it, but you can't end your movement there. If you do so, you are ejected to the nearest unoccupied space, this spell ends, and you are <i class=\\"text-dnd-gold\\">stunned</i> until the end of your next turn."]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["prone","stunned"],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":159},{"name":"Investiture of Wind","source":"XGE","level":6,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Until the spell ends, wind whirls around you, and you gain the following benefits:"},{"type":"list","items":["Ranged weapon attacks made against you have disadvantage on the attack roll.","You gain a flying speed of 60 feet. If you are still flying when the spell ends, you fall, unless you can somehow prevent it.","You can use your action to create a 15-foot cube of swirling wind centered on a point you can see within 60 feet of you. Each creature in that area must make a Constitution saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">2d10</span> bludgeoning damage on a failed save, or half as much damage on a successful one. If a Large or smaller creature fails the save, that creature is also pushed up to 10 feet away from the center of the cube."]}],"entriesHigherLevel":[],"damageInflict":["bludgeoning"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":160},{"name":"Life Transference","source":"XGE","level":3,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You sacrifice some of your health to mend another creature's injuries. You take <span class=\\"text-red-400 font-semibold\\">4d8</span> necrotic damage, which can't be reduced in any way, and one creature of your choice that you can see within range regains a number of hit points equal to twice the necrotic damage you take."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 4d8 for each slot level above 3rd."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":160},{"name":"Maddening Darkness","source":"XGE","level":8,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"m":"a drop of pitch mixed with a drop of mercury"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Magical darkness spreads from a point you choose within range to fill a 60-foot-radius sphere until the spell ends. The darkness spreads around corners. A creature with <i>darkvision</i> can't see through this darkness. Non-magical light, as well as light created by spells of 8th level or lower, can't illuminate the area."},{"type":"text","content":"Shrieks, gibbering, and mad laughter can be heard within the sphere. Whenever a creature starts its turn in the sphere, it must make a Wisdom saving throw, taking <span class=\\"text-red-400 font-semibold\\">8d8</span> psychic damage on a failed save, or half as much damage on a successful one."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":160},{"name":"Maelstrom","source":"XGE","level":5,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"paper or leaf in the shape of a funnel"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A swirling mass of 5-foot-deep water appears in a 30-foot radius centered on a point you can see within range. The point must be on the ground or in a body of water. Until the spell ends, that area is difficult terrain, and any creature that starts its turn there must succeed on a Strength saving throw or take <span class=\\"text-red-400 font-semibold\\">6d6</span> bludgeoning damage and be pulled 10 feet toward the center."}],"entriesHigherLevel":[],"damageInflict":["bludgeoning"],"conditionInflict":[],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":160},{"name":"Magic Stone","source":"XGE","level":0,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1}}],"entries":[{"type":"text","content":"You touch one to three pebbles and imbue them with magic. You or someone else can make a ranged spell attack with one of the pebbles by throwing it or hurling it with a <b>sling</b>. If thrown, a pebble has a range of 60 feet. If someone else attacks with a pebble, that attacker adds your spellcasting ability modifier, not the attacker's, to the attack roll. On a hit, the target takes bludgeoning damage equal to <span class=\\"text-red-400 font-semibold\\">1d6</span> + your spellcasting ability modifier. Whether the attack hits or misses, the spell then ends on the stone."},{"type":"text","content":"If you cast this spell again, the spell ends on any pebbles still affected by your previous casting."}],"entriesHigherLevel":[],"damageInflict":["bludgeoning"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":160},{"name":"Mass Polymorph","source":"XGE","level":9,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a caterpillar cocoon"},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You transform up to ten creatures of your choice that you can see within range. An unwilling target must succeed on a Wisdom saving throw to resist the transformation. An unwilling shapechanger automatically succeeds on the save."},{"type":"text","content":"Each target assumes a beast form of your choice, and you can choose the same form or different ones for each target. The new form can be <i>any beast</i> you have seen whose challenge rating is equal to or less than the target's (or half the target's level, if the target doesn't have a challenge rating). The target's game statistics, including mental ability scores, are replaced by the statistics of the chosen beast, but the target retains its hit points, alignment, and personality."},{"type":"text","content":"Each target gains a number of temporary hit points equal to the hit points of its new form. These temporary hit points can't be replaced by temporary hit points from another source. A target reverts to its normal form when it has no more temporary hit points or it dies. If the spell ends before then, the creature loses all its temporary hit points and reverts to its normal form."},{"type":"text","content":"The creature is limited in the actions it can perform by the nature of its new form. It can't speak, cast spells, or do anything else that requires hands or speech."},{"type":"text","content":"The target's gear melds into the new form. The target can't activate, use, wield, or otherwise benefit from any of its equipment."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":160},{"name":"Maximilian's Earthen Grasp","source":"XGE","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a miniature hand sculpted from clay"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You choose a 5-foot-square unoccupied space on the ground that you can see within range. A Medium hand made from compacted soil rises there and reaches for one creature you can see within 5 feet of it. The target must make a Strength saving throw. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">2d6</span> bludgeoning damage and is <i class=\\"text-dnd-gold\\">restrained</i> for the spell's duration."},{"type":"text","content":"As an action, you can cause the hand to crush the <i class=\\"text-dnd-gold\\">restrained</i> target, which must make a Strength saving throw. The target takes <span class=\\"text-red-400 font-semibold\\">2d6</span> bludgeoning damage on a failed save, or half as much damage on a successful one."},{"type":"text","content":"To break out, the <i class=\\"text-dnd-gold\\">restrained</i> target can use its action to make a Strength check against your spell save DC. On a success, the target escapes and is no longer <i class=\\"text-dnd-gold\\">restrained</i> by the hand."},{"type":"text","content":"As an action, you can cause the hand to reach for a different creature or to move to a different unoccupied space within range. The hand releases a <i class=\\"text-dnd-gold\\">restrained</i> target if you do either."}],"entriesHigherLevel":[],"damageInflict":["bludgeoning"],"conditionInflict":["restrained"],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":161},{"name":"Melf's Minute Meteors","source":"XGE","level":3,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"niter, sulfur, and pine tar formed into a bead"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You create six tiny meteors in your space. They float in the air and orbit you for the spell's duration. When you cast the spell—and as a bonus action on each of your turns thereafter—you can expend one or two of the meteors, sending them streaking toward a point or points you choose within 120 feet of you. Once a meteor reaches its destination or impacts against a solid surface, the meteor explodes. Each creature within 5 feet of the point where the meteor explodes must make a Dexterity saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">2d6</span> fire damage on a failed save, or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, the number of meteors created increases by two for each slot level above 3rd."}]}],"damageInflict":["fire"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":161},{"name":"Mental Prison","source":"XGE","level":6,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You attempt to bind a creature within an illusory cell that only it perceives. One creature you can see within range must make an Intelligence saving throw. The target succeeds automatically if it is immune to being <i class=\\"text-dnd-gold\\">charmed</i>. On a successful save, the target takes <span class=\\"text-red-400 font-semibold\\">5d10</span> psychic damage, and the spell ends. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">5d10</span> psychic damage, and you make the area immediately around the target's space appear dangerous to it in some way. You might cause the target to perceive itself as being surrounded by fire, floating razors, or hideous maws filled with dripping teeth. Whatever form the illusion takes, the target can't see or hear anything beyond it and is <i class=\\"text-dnd-gold\\">restrained</i> for the spell's duration. If the target is moved out of the illusion, makes a melee attack through it, or reaches any part of its body through it, the target takes <span class=\\"text-red-400 font-semibold\\">10d10</span> psychic damage, and the spell ends."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":161},{"name":"Mighty Fortress","source":"XGE","level":8,"school":"C","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"miles","amount":1}},"components":{"v":true,"s":true,"m":{"text":"a diamond worth at least 500 gp, which the spell consumes","cost":50000,"consume":true}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A fortress of stone erupts from a square area of ground of your choice that you can see within range. The area is 120 feet on each side, and it must not have any buildings or other structures on it. Any creatures in the area are harmlessly lifted up as the fortress rises."},{"type":"text","content":"The fortress has four turrets with square bases, each one 20 feet on a side and 30 feet tall, with one turret on each corner. The turrets are connected to each other by stone walls that are each 80 feet long, creating an enclosed area. Each wall is 1 foot thick and is composed of panels that are 10 feet wide and 20 feet tall. Each panel is contiguous with two other panels or one other panel and a turret. You can place up to four stone doors in the fortress's outer wall."},{"type":"text","content":"A small keep stands inside the enclosed area. The keep has a square base that is 50 feet on each side, and it has three floors with 10-foot-high ceilings. Each of the floors can be divided into as many rooms as you like, provided each room is at least 5 feet on each side. The floors of the keep are connected by stone staircases, its walls are 6 inches thick, and interior rooms can have stone doors or open archways as you choose. The keep is furnished and decorated however you like, and it contains sufficient food to serve a nine-course banquet for up to 100 people each day. Furnishings, food, and other objects created by this spell crumble to dust if removed from the fortress."},{"type":"text","content":"A staff of one hundred invisible servants obeys any command given to them by creatures you designate when you cast the spell. Each servant functions as if created by the <a href=\\"/spells?search=unseen servant\\" class=\\"text-dnd-gold hover:underline\\">unseen servant</a> spell."},{"type":"text","content":"The walls, turrets, and keep are all made of stone that can be damaged. Each 10-foot-by-10-foot section of stone has AC 15 and 30 hit points per inch of thickness. It is immune to poison and psychic damage. Reducing a section of stone to 0 hit points destroys it and might cause connected sections to buckle and collapse at the DM's discretion."},{"type":"text","content":"After 7 days or when you cast this spell somewhere else, the fortress harmlessly crumbles and sinks back into the ground, leaving any creatures that were inside it safely on the ground."},{"type":"text","content":"Casting this spell on the same spot once every 7 days for a year makes the fortress permanent."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":161},{"name":"Mind Spike","source":"XPHB","level":2,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You drive a spike of psionic energy into the mind of one creature you can see within range. The target makes a Wisdom saving throw, taking <span class=\\"text-red-400 font-semibold\\">3d8</span> Psychic damage on a failed save or half as much damage on a successful one. On a failed save, you also always know the target's location until the spell ends, but only while the two of you are on the same plane of existence. While you have this knowledge, the target can't become hidden from you, and if it has the <i class=\\"text-dnd-gold\\">Invisible</i> condition, it gains no benefit from that condition against you."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 3d8 for each spell slot level above 2."}]}],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":298},{"name":"Mold Earth","source":"XGE","level":0,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"s":true},"duration":[{"type":"instant"},{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You choose a portion of dirt or stone that you can see within range and that fits within a 5-foot cube. You manipulate it in one of the following ways:"},{"type":"list","items":["If you target an area of loose earth, you can instantaneously excavate it, move it along the ground, and deposit it up to 5 feet away. This movement doesn't involve enough force to cause damage.","You cause shapes, colors, or both to appear on the dirt or stone, spelling out words, creating images, or shaping patterns. The changes last for 1 hour.","If the dirt or stone you target is on the ground, you cause it to become difficult terrain. Alternatively, you can cause the ground to become normal terrain if it is already difficult terrain. This change lasts for 1 hour."]},{"type":"text","content":"If you cast this spell multiple times, you can have no more than two of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":162},{"name":"Primal Savagery","source":"XGE","level":0,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You channel primal magic to cause your teeth or fingernails to sharpen, ready to deliver a corrosive attack. Make a melee spell attack against one creature within 5 feet of you. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">1d10</span> acid damage. After you make the attack, your teeth or fingernails return to normal."},{"type":"text","content":"The spell's damage increases by <span class=\\"text-red-400 font-semibold\\">1d10</span> when you reach 5th level (<span class=\\"text-red-400 font-semibold\\">2d10</span>), 11th level (<span class=\\"text-red-400 font-semibold\\">3d10</span>), and 17th level (<span class=\\"text-red-400 font-semibold\\">4d10</span>)."}],"entriesHigherLevel":[],"damageInflict":["acid"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":163},{"name":"Primordial Ward","source":"XGE","level":6,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You have resistance to acid, cold, fire, lightning, and thunder damage for the spell's duration."},{"type":"text","content":"When you take damage of one of those types, you can use your reaction to gain immunity to that type of damage, including against the triggering damage. If you do so, the resistances end, and you have the immunity until the end of your next turn, at which time the spell ends."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":163},{"name":"Psychic Scream","source":"XGE","level":9,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You unleash the power of your mind to blast the intellect of up to ten creatures of your choice that you can see within range. Creatures that have an Intelligence score of 2 or lower are unaffected."},{"type":"text","content":"Each target must make an Intelligence saving throw. On a failed save, a target takes <span class=\\"text-red-400 font-semibold\\">14d6</span> psychic damage and is <i class=\\"text-dnd-gold\\">stunned</i>. On a successful save, a target takes half as much damage and isn't <i class=\\"text-dnd-gold\\">stunned</i>. If a target is killed by this damage, its head explodes, assuming it has one."},{"type":"text","content":"A <i class=\\"text-dnd-gold\\">stunned</i> target can make an Intelligence saving throw at the end of each of its turns. On a successful save, the stunning effect ends."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":["stunned"],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":163},{"name":"Pyrotechnics","source":"XGE","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Choose an area of nonmagical flame that you can see and that fits within a 5-foot cube within range. You can extinguish the fire in that area, and you create either fireworks or smoke when you do so."},{"type":"section","name":"Fireworks","entries":[{"type":"text","content":"The target explodes with a dazzling display of colors. Each creature within 10 feet of the target must succeed on a Constitution saving throw or become <i class=\\"text-dnd-gold\\">blinded</i> until the end of your next turn."}]},{"type":"section","name":"Smoke","entries":[{"type":"text","content":"Thick black smoke spreads out from the target in a 20-foot radius, moving around corners. The area of the smoke is heavily obscured. The smoke persists for 1 minute or until a strong wind disperses it."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["blinded"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":163},{"name":"Scatter","source":"XGE","level":6,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"The air quivers around up to five creatures of your choice that you can see within range. An unwilling creature must succeed on a Wisdom saving throw to resist this spell. You teleport each affected target to an unoccupied space that you can see within 120 feet of you. That space must be on the ground or on a floor."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":164},{"name":"Shadow Blade","source":"XGE","level":2,"school":"I","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You weave together threads of shadow to create a sword of solidified gloom in your hand. This magic sword lasts until the spell ends. It counts as a simple melee weapon with which you are proficient. It deals <span class=\\"text-red-400 font-semibold\\">2d8</span> psychic damage on a hit and has the finesse, light, and thrown properties (range 20/60). In addition, when you use the sword to attack a target that is in dim light or darkness, you make the attack roll with advantage."},{"type":"text","content":"If you drop the weapon or throw it, it dissipates at the end of the turn. Thereafter, while the spell persists, you can use a bonus action to cause the sword to reappear in your hand."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a 3rd- or 4th-level spell slot, the damage increases to <span class=\\"text-red-400 font-semibold\\">3d8</span>. When you cast it using a 5th- or 6th-level spell slot, the damage increases to <span class=\\"text-red-400 font-semibold\\">4d8</span>. When you cast it using a spell slot of 7th level or higher, the damage increases to <span class=\\"text-red-400 font-semibold\\">5d8</span>."}]}],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":164},{"name":"Shadow of Moil","source":"XGE","level":4,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":{"text":"an undead eyeball encased in a gem worth at least 150 gp","cost":15000}},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Flame-like shadows wreathe your body until the spell ends, causing you to become heavily obscured to others. The shadows turn dim light within 10 feet of you into darkness, and bright light in the same area to dim light."},{"type":"text","content":"Until the spell ends, you have resistance to radiant damage. In addition, whenever a creature within 10 feet of you hits you with an attack, the shadows lash out at that creature, dealing it <span class=\\"text-red-400 font-semibold\\">2d8</span> necrotic damage."}],"entriesHigherLevel":[],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":164},{"name":"Shape Water","source":"XGE","level":0,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"s":true},"duration":[{"type":"instant"},{"type":"timed","duration":{"type":"hour","amount":1}}],"entries":[{"type":"text","content":"You choose an area of water that you can see within range and that fits within a 5-foot cube. You manipulate it in one of the following ways:"},{"type":"list","items":["You instantaneously move or otherwise change the flow of the water as you direct, up to 5 feet in any direction. This movement doesn't have enough force to cause damage.","You cause the water to form into simple shapes and animate at your direction. This change lasts for 1 hour.","You change the water's color or opacity. The water must be changed in the same way throughout. This change lasts for 1 hour.","You freeze the water, provided that there are no creatures in it. The water unfreezes in 1 hour."]},{"type":"text","content":"If you cast this spell multiple times, you can have no more than two of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":164},{"name":"Sickening Radiance","source":"XGE","level":4,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"Dim, greenish light spreads within a 30-foot-radius sphere centered on a point you choose within range. The light spreads around corners, and it lasts until the spell ends."},{"type":"text","content":"When a creature moves into the spell's area for the first time on a turn or starts its turn there, that creature must succeed on a Constitution saving throw or take <span class=\\"text-red-400 font-semibold\\">4d10</span> radiant damage, and it suffers one level of <i class=\\"text-dnd-gold\\">exhaustion</i> and emits a dim, greenish light in a 5-foot radius. This light makes it impossible for the creature to benefit from being <i class=\\"text-dnd-gold\\">invisible</i>. The light and any levels of <i class=\\"text-dnd-gold\\">exhaustion</i> caused by this spell go away when the spell ends."}],"entriesHigherLevel":[],"damageInflict":["radiant"],"conditionInflict":["exhaustion"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":164},{"name":"Skill Empowerment","source":"XGE","level":5,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"Your magic deepens a creature's understanding of its own talent. You touch one willing creature and give it expertise in one skill of your choice; until the spell ends, the creature doubles its proficiency bonus for ability checks it makes that use the chosen skill."},{"type":"text","content":"You must choose a skill in which the target is proficient and that isn't already benefiting from an effect, such as Expertise, that doubles its proficiency bonus."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":165},{"name":"Skywrite","source":"XGE","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"sight"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You cause up to ten words to form in a part of the sky you can see. The words appear to be made of cloud and remain in place for the spell's duration. The words dissipate when the spell ends. A strong wind can disperse the clouds and end the spell early."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":true,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":165},{"name":"Snare","source":"XGE","level":1,"school":"A","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"s":true,"m":{"text":"25 feet of rope, which the spell consumes","consume":true}},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"As you cast this spell, you use the rope to create a circle with a 5-foot radius on the ground or the floor. When you finish casting, the rope disappears and the circle becomes a magic trap."},{"type":"text","content":"This trap is nearly invisible, requiring a successful Intelligence (<i>Investigation</i>) check against your spell save DC to be discerned."},{"type":"text","content":"The trap triggers when a Small, Medium, or Large creature moves onto the ground or the floor in the spell's radius. That creature must succeed on a Dexterity saving throw or be magically hoisted into the air, leaving it hanging upside down 3 feet above the ground or the floor. The creature is <i class=\\"text-dnd-gold\\">restrained</i> there until the spell ends."},{"type":"text","content":"A <i class=\\"text-dnd-gold\\">restrained</i> creature can make a Dexterity saving throw at the end of each of its turns, ending the effect on itself on a success. Alternatively, the creature or someone else who can reach it can use an action to make an Intelligence (<i>Arcana</i>) check against your spell save DC. On a success, the <i class=\\"text-dnd-gold\\">restrained</i> effect ends."},{"type":"text","content":"After the trap is triggered, the spell ends when no creature is <i class=\\"text-dnd-gold\\">restrained</i> by it."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["restrained"],"savingThrow":["dexterity"],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":165},{"name":"Snilloc's Snowball Swarm","source":"XGE","level":2,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":"a piece of ice or a small white rock chip"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"A flurry of magic snowballs erupts from a point you choose within range. Each creature in a 5-foot-radius sphere centered on that point must make a Dexterity saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">3d6</span> cold damage on a failed save, or half as much damage on a successful one."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 3d6 for each slot level above 2nd."}]}],"damageInflict":["cold"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":165},{"name":"Soul Cage","source":"XGE","level":6,"school":"N","time":[{"number":1,"unit":"reaction","condition":"which you take when a humanoid you can see within 60 feet of you dies"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"a tiny silver cage worth 100 gp","cost":10000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"This spell snatches the soul of a humanoid as it dies and traps it inside the tiny cage you use for the material component. A stolen soul remains inside the cage until the spell ends or until you destroy the cage, which ends the spell. While you have a soul inside the cage, you can exploit it in any of the ways described below. You can use a trapped soul up to six times. Once you exploit a soul for the sixth time, it is released, and the spell ends. While a soul is trapped, the dead humanoid it came from can't be revived."},{"type":"section","name":"Steal Life","entries":[{"type":"text","content":"You can use a bonus action to drain vigor from the soul and regain <span class=\\"text-green-400 font-mono\\">2d8</span> hit points."}]},{"type":"section","name":"Query Soul","entries":[{"type":"text","content":"You ask the soul a question (no action required) and receive a brief telepathic answer, which you can understand regardless of the language used. The soul knows only what it knew in life, but it must answer you truthfully and to the best of its ability. The answer is no more than a sentence or two and might be cryptic."}]},{"type":"section","name":"Borrow Experience","entries":[{"type":"text","content":"You can use a bonus action to bolster yourself with the soul's life experience, making your next attack roll, ability check, or saving throw with advantage. If you don't use this benefit before the start of your next turn, it is lost."}]},{"type":"section","name":"Eyes of the Dead","entries":[{"type":"text","content":"You can use an action to name a place the humanoid saw in life, which creates an invisible sensor somewhere in that place if it is on the plane of existence you're currently on. The sensor remains for as long as you concentrate, up to 10 minutes (as if you were <i>concentration</i> on a spell). You receive visual and auditory information from the sensor as if you were in its space using your senses."}]},{"type":"text","content":"A creature that can see the sensor (such as one using <a href=\\"/spells?search=see invisibility\\" class=\\"text-dnd-gold hover:underline\\">see invisibility</a> or <i>truesight</i>) sees a translucent image of the tormented humanoid whose soul you caged."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"reaction","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":165},{"name":"Steel Wind Strike","source":"XPHB","level":5,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"s":true,"m":{"text":"a Melee weapon worth 1+ SP","cost":10}},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You flourish the weapon used in the casting and then vanish to strike like the wind. Choose up to five creatures you can see within range. Make a melee spell attack against each target. On a hit, a target takes <span class=\\"text-red-400 font-semibold\\">6d10</span> Force damage."},{"type":"text","content":"You then teleport to an unoccupied space you can see within 5 feet of one of the targets."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":320},{"name":"Storm Sphere","source":"XGE","level":4,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A 20-foot-radius sphere of whirling air springs into existence, centered on a point you choose within range. The sphere remains for the spell's duration. Each creature in the sphere when it appears or that ends its turn there must succeed on a Strength saving throw or take <span class=\\"text-red-400 font-semibold\\">2d6</span> bludgeoning damage. The sphere's space is difficult terrain."},{"type":"text","content":"Until the spell ends, you can use a bonus action on each of your turns to cause a bolt of lightning to leap from the center of the sphere toward one creature you choose within 60 feet of the center. Make a ranged spell attack. You have advantage on the attack roll if the target is in the sphere. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">4d6</span> lightning damage."},{"type":"text","content":"Creatures within 30 feet of the sphere have disadvantage on Wisdom (<i>Perception</i>) checks made to listen."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 5th level or higher, the damage for each of its effects increases by 2d6;4d6 for each slot level above 4th."}]}],"damageInflict":["bludgeoning","lightning"],"conditionInflict":[],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":166},{"name":"Summon Greater Demon","source":"XGE","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"a vial of blood from a humanoid killed within the past 24 hours","consume":"optional"}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You utter foul words, summoning one demon from the chaos of the Abyss. You choose the demon's type, which must be <i>one of challenge rating 5 or lower</i>, such as a <b>shadow demon</b> or a <b>barlgura</b>. The demon appears in an unoccupied space you can see within range, and the demon disappears when it drops to 0 hit points or when the spell ends."},{"type":"text","content":"Roll initiative for the demon, which has its own turns. When you summon it and on each of your turns thereafter, you can issue a verbal command to it (requiring no action on your part), telling it what it must do on its next turn. If you issue no command, it spends its turn attacking any creature within reach that has attacked it."},{"type":"text","content":"At the end of each of the demon's turns, it makes a Charisma saving throw. The demon has disadvantage on this saving throw if you say its true name. On a failed save, the demon continues to obey you. On a successful save, your control of the demon ends for the rest of the duration, and the demon spends its turns pursuing and attacking the nearest non-demons to the best of its ability. If you stop <i>concentration</i> on the spell before it reaches its full duration, an uncontrolled demon doesn't disappear for <span class=\\"text-green-400 font-mono\\">1d6</span> rounds if it still has hit points."},{"type":"text","content":"As part of casting the spell, you can form a circle on the ground with the blood used as a material component. The circle is large enough to encompass your space. While the spell lasts, the summoned demon can't cross the circle or harm it, and it can't target anyone within it. Using the material component in this manner consumes it when the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 5th level or higher, the challenge rating increases by 1 for each slot level above 4th."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":["charisma"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":166},{"name":"Summon Lesser Demons","source":"XGE","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"a vial of blood from a humanoid killed within the past 24 hours","consume":"optional"}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You utter foul words, summoning demons from the chaos of the Abyss. Roll on the following table to determine what appears."},{"type":"table","caption":"","colLabels":["{@dice d6}","Demons Summoned"],"rows":[["[object Object]","Two <i>demons of challenge rating 1 or lower</i>"],["[object Object]","Four <i>demons of challenge rating 1/2 or lower</i>"],["[object Object]","Eight <i>demons of challenge rating 1/4 or lower</i>"]]},{"type":"text","content":"The DM chooses the demons, such as <b>manes</b> or <b>dretch</b>, and you choose the unoccupied spaces you can see within range where they appear. A summoned demon disappears when it drops to 0 hit points or when the spell ends."},{"type":"text","content":"The demons are hostile to all creatures, including you. Roll initiative for the summoned demons as a group, which has its own turns. The demons pursue and attack the nearest non-demons to the best of their ability."},{"type":"text","content":"As part of casting the spell, you can form a circle on the ground with the blood used as a material component. The circle is large enough to encompass your space. While the spell lasts, the summoned demons can't cross the circle or harm it, and they can't target anyone within it. Using the material component in this manner consumes it when the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 6th or 7th level, you summon twice as many demons. If you cast it using a spell slot of 8th or 9th level, you summon three times as many demons."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":167},{"name":"Synaptic Static","source":"XPHB","level":5,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You cause psychic energy to erupt at a point within range. Each creature in a 20-foot-radius <i>Sphere [Area of Effect]</i> centered on that point makes an Intelligence saving throw, taking <span class=\\"text-red-400 font-semibold\\">8d6</span> Psychic damage on a failed save or half as much damage on a successful one."},{"type":"text","content":"On a failed save, a target also has muddled thoughts for 1 minute. During that time, it subtracts <span class=\\"text-green-400 font-mono\\">1d6</span> from all its attack rolls and ability checks, as well as any Constitution saving throws to maintain <i>Concentration</i>. The target makes an Intelligence saving throw at the end of each of its turns, ending the effect on itself on a success."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["intelligence","constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":330},{"name":"Temple of the Gods","source":"XGE","level":7,"school":"C","time":[{"number":1,"unit":"hour"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":{"text":"a holy symbol worth at least 5 gp","cost":500}},"duration":[{"type":"timed","duration":{"type":"hour","amount":24}}],"entries":[{"type":"text","content":"You cause a temple to shimmer into existence on ground you can see within range. The temple must fit within an unoccupied cube of space, up to 120 feet on each side. The temple remains until the spell ends. It is dedicated to whatever god, pantheon, or philosophy is represented by the holy symbol used in the casting."},{"type":"text","content":"You make all decisions about the temple's appearance. The interior is enclosed by a floor, walls, and a roof, with one door granting access to the interior and as many windows as you wish. Only you and any creatures you designate when you cast the spell can open or close the door."},{"type":"text","content":"The temple's interior is an open space with an idol or altar at one end. You decide whether the temple is illuminated and whether that illumination is bright light or dim light. The smell of burning incense fills the air within, and the temperature is mild."},{"type":"text","content":"The temple opposes types of creatures you choose when you cast this spell. Choose one or more of the following: celestials, elementals, fey, fiends, or undead. If a creature of the chosen type attempts to enter the temple, that creature must make a Charisma saving throw. On a failed save, it can't enter the temple for 24 hours. Even if the creature can enter the temple, the magic there hinders it; whenever it makes an attack roll, an ability check, or a saving throw inside the temple, it must roll a <span class=\\"text-green-400 font-mono\\">d4</span> and subtract the number rolled from the <span class=\\"text-green-400 font-mono\\">d20</span> roll."},{"type":"text","content":"In addition, the sensors created by divination spells can't appear inside the temple, and creatures within can't be targeted by divination spells."},{"type":"text","content":"Finally, whenever any creature in the temple regains hit points from a spell of 1st level or higher, the creature regains additional hit points equal to your Wisdom modifier (minimum 1 hit point)."},{"type":"text","content":"The temple is made from opaque magical force that extends into the Ethereal Plane, thus blocking ethereal travel into the temple's interior. Nothing can physically pass through the temple's exterior. It can't be dispelled by <a href=\\"/spells?search=dispel magic\\" class=\\"text-dnd-gold hover:underline\\">dispel magic</a>, and <a href=\\"/spells?search=antimagic field\\" class=\\"text-dnd-gold hover:underline\\">antimagic field</a> has no effect on it. A <a href=\\"/spells?search=disintegrate\\" class=\\"text-dnd-gold hover:underline\\">disintegrate</a> spell destroys the temple instantly."},{"type":"text","content":"Casting this spell on the same spot every day for a year makes this effect permanent."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":["charisma"],"castingTime":"hour","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":167},{"name":"Tenser's Transformation","source":"XGE","level":6,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true,"m":"a few hairs from a bull"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You endow yourself with endurance and martial prowess fueled by magic. Until the spell ends, you can't cast spells, and you gain the following benefits:"},{"type":"list","items":["You gain 50 temporary hit points. If any of these remain when the spell ends, they are lost.","You have advantage on attack rolls that you make with simple and martial weapons.","When you hit a target with a weapon attack, that target takes an extra <span class=\\"text-red-400 font-semibold\\">2d12</span> force damage.","You have proficiency with all armor, shields, simple weapons, and martial weapons.","You have proficiency in Strength and Constitution saving throws.","You can attack twice, instead of once, when you take the <b>Attack</b> action on your turn. You ignore this benefit if you already have a feature, like Extra Attack, that gives you extra attacks."]},{"type":"text","content":"Immediately after the spell ends, you must succeed on a DC 15 Constitution saving throw or suffer one level of <i class=\\"text-dnd-gold\\">exhaustion</i>."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":["exhaustion"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":168},{"name":"Thunder Step","source":"XGE","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You teleport yourself to an unoccupied space you can see within range. Immediately after you disappear, a thunderous boom sounds, and each creature within 10 feet of the space you left must make a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">3d10</span> thunder damage on a failed save, or half as much damage on a successful one. The thunder can be heard from up to 300 feet away."},{"type":"text","content":"You can bring along objects as long as their weight doesn't exceed what you can carry. You can also teleport one willing creature of your size or smaller who is carrying gear up to its carrying capacity. The creature must be within 5 feet of you when you cast this spell, and there must be an unoccupied space within 5 feet of your destination space for the creature to appear in; otherwise, the creature is left behind."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 3d10 for each slot level above 3rd."}]}],"damageInflict":["thunder"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":168},{"name":"Thunderclap","source":"XPHB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":5}},"components":{"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Each creature in a 5-foot <i>Emanation [Area of Effect]</i> originating from you must succeed on a Constitution saving throw or take <span class=\\"text-red-400 font-semibold\\">1d6</span> Thunder damage. The spell's thunderous sound can be heard up to 100 feet away."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d6</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d6</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d6</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d6</span>)."}]}],"damageInflict":["thunder"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":333},{"name":"Tidal Wave","source":"XGE","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a drop of water"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You conjure up a wave of water that crashes down on an area within range. The area can be up to 30 feet long, up to 10 feet wide, and up to 10 feet tall. Each creature in that area must make a Dexterity saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">4d8</span> bludgeoning damage and is knocked <i class=\\"text-dnd-gold\\">prone</i>. On a successful save, a creature takes half as much damage and isn't knocked <i class=\\"text-dnd-gold\\">prone</i>. The water then spreads out across the ground in all directions, extinguishing unprotected flames in its area and within 30 feet of it, and then it vanishes."}],"entriesHigherLevel":[],"damageInflict":["bludgeoning"],"conditionInflict":["prone"],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":168},{"name":"Tiny Servant","source":"XGE","level":3,"school":"T","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"touch"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"hour","amount":8}}],"entries":[{"type":"text","content":"You touch one Tiny, nonmagical object that isn't attached to another object or a surface and isn't being carried by another creature. The target animates and sprouts little arms and legs, becoming a creature under your control until the spell ends or the creature drops to 0 hit points. See the <b>tiny servant</b> for its statistics."},{"type":"text","content":"As a bonus action, you can mentally command the creature if it is within 120 feet of you. (If you control multiple creatures with this spell, you can command any or all of them at the same time, issuing the same command to each one.) You decide what action the creature will take and where it will move during its next turn, or you can issue a simple, general command, such as to fetch a key, stand watch, or stack some books. If you issue no commands, the servant does nothing other than defend itself against hostile creatures. Once given an order, the servant continues to follow that order until its task is complete."},{"type":"text","content":"When the creature drops to 0 hit points, it reverts to its original form, and any remaining damage carries over to that form."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 4th level or higher, you can animate two additional objects for each slot level above 3rd."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"minute","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":168},{"name":"Toll the Dead","source":"XPHB","level":0,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You point at one creature you can see within range, and the single chime of a dolorous bell is audible within 10 feet of the target. The target must succeed on a Wisdom saving throw or take <span class=\\"text-red-400 font-semibold\\">1d8</span> Necrotic damage. If the target is missing any of its <i>Hit Points</i>, it instead takes <span class=\\"text-red-400 font-semibold\\">1d12</span> Necrotic damage."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by one die when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d8</span> or <span class=\\"text-red-400 font-semibold\\">2d12</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d8</span> or <span class=\\"text-red-400 font-semibold\\">3d12</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d8</span> or <span class=\\"text-red-400 font-semibold\\">4d12</span>)."}]}],"damageInflict":["necrotic"],"conditionInflict":[],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":334},{"name":"Transmute Rock","source":"XGE","level":5,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"clay and water"},"duration":[{"type":"permanent","ends":["dispel"]}],"entries":[{"type":"text","content":"You choose an area of stone or mud that you can see that fits within a 40-foot cube and is within range, and choose one of the following effects."},{"type":"section","name":"Transmute Rock to Mud","entries":[{"type":"text","content":"Nonmagical rock of any sort in the area becomes an equal volume of thick, flowing mud that remains for the spell's duration."}]},{"type":"text","content":"The ground in the spell's area becomes muddy enough that creatures can sink into it. Each foot that a creature moves through the mud costs 4 feet of movement, and any creature on the ground when you cast the spell must make a Strength saving throw. A creature must also make the saving throw when it moves into the area for the first time on a turn or ends its turn there. On a failed save, a creature sinks into the mud and is <i class=\\"text-dnd-gold\\">restrained</i>, though it can use an action to end the <i class=\\"text-dnd-gold\\">restrained</i> condition on itself by pulling itself free of the mud."},{"type":"text","content":"If you cast the spell on a ceiling, the mud falls. Any creature under the mud when it falls must make a Dexterity saving throw. A creature takes <span class=\\"text-red-400 font-semibold\\">4d8</span> bludgeoning damage on a failed save, or half as much damage on a successful one."},{"type":"section","name":"Transmute Mud to Rock","entries":[{"type":"text","content":"Nonmagical mud or quicksand in the area no more than 10 feet deep transforms into soft stone for the spell's duration. Any creature in the mud when it transforms must make a Dexterity saving throw. On a successful save, a creature is shunted safely to the surface in an unoccupied space. On a failed save, a creature becomes <i class=\\"text-dnd-gold\\">restrained</i> by the rock. A <i class=\\"text-dnd-gold\\">restrained</i> creature, or another creature within reach, can use an action to try to break the rock by succeeding on a DC 20 Strength check or by dealing damage to it. The rock has AC 15 and 25 hit points, and it is immune to poison and psychic damage."}]}],"entriesHigherLevel":[],"damageInflict":["bludgeoning"],"conditionInflict":["restrained"],"savingThrow":["strength","dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":169},{"name":"Vitriolic Sphere","source":"XPHB","level":4,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":"a drop of bile"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You point at a location within range, and a glowing, 1-foot-diameter ball of acid streaks there and explodes in a 20-foot-radius <i>Sphere [Area of Effect]</i>. Each creature in that area makes a Dexterity saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">10d4</span> Acid damage and another <span class=\\"text-red-400 font-semibold\\">5d4</span> Acid damage at the end of its next turn. On a successful save, a creature takes half the initial damage only."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The initial damage increases by 10d4 for each spell slot level above 4."}]}],"damageInflict":["acid"],"conditionInflict":[],"savingThrow":["dexterity"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":337},{"name":"Wall of Light","source":"XGE","level":5,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a hand mirror"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"A shimmering wall of bright light appears at a point you choose within range. The wall appears in any orientation you choose: horizontally, vertically, or diagonally. It can be free floating, or it can rest on a solid surface. The wall can be up to 60 feet long, 10 feet high, and 5 feet thick. The wall blocks line of sight, but creatures and objects can pass through it. It emits bright light out to 120 feet and dim light for an additional 120 feet."},{"type":"text","content":"When the wall appears, each creature in its area must make a Constitution saving throw. On a failed save, a creature takes <span class=\\"text-red-400 font-semibold\\">4d8</span> radiant damage, and it is <i class=\\"text-dnd-gold\\">blinded</i> for 1 minute. On a successful save, it takes half as much damage and isn't <i class=\\"text-dnd-gold\\">blinded</i>. A <i class=\\"text-dnd-gold\\">blinded</i> creature can make a Constitution saving throw at the end of each of its turns, ending the effect on itself on a success."},{"type":"text","content":"A creature that ends its turn in the wall's area takes <span class=\\"text-red-400 font-semibold\\">4d8</span> radiant damage."},{"type":"text","content":"Until the spell ends, you can use an action to launch a beam of radiance from the wall at one creature you can see within 60 feet of it. Make a ranged spell attack. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">4d8</span> radiant damage. Whether you hit or miss, reduce the length of the wall by 10 feet. If the wall's length drops to 0 feet, the spell ends."}],"entriesHigherLevel":[{"type":"section","name":"At Higher Levels","entries":[{"type":"text","content":"When you cast this spell using a spell slot of 6th level or higher, the damage increases by 4d8 for each slot level above 5th."}]}],"damageInflict":["radiant"],"conditionInflict":["blinded"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":170},{"name":"Wall of Sand","source":"XGE","level":3,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":"a handful of sand"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You create a wall of swirling sand on the ground at a point you can see within range. You can make the wall up to 30 feet long, 10 feet high, and 10 feet thick, and it vanishes when the spell ends. It blocks line of sight but not movement. A creature is <i class=\\"text-dnd-gold\\">blinded</i> while in the wall's space and must spend 3 feet of movement for every 1 foot it moves there."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["blinded"],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":170},{"name":"Wall of Water","source":"XGE","level":3,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a drop of water"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"You create a wall of water on the ground at a point you can see within range. You can make the wall up to 30 feet long, 10 feet high, and 1 foot thick, or you can make a ringed wall up to 20 feet in diameter, 20 feet high, and 1 foot thick. The wall vanishes when the spell ends. The wall's space is difficult terrain."},{"type":"text","content":"Any ranged weapon attack that enters the wall's space has disadvantage on the attack roll, and fire damage is halved if the fire effect passes through the wall to reach its target. Spells that deal cold damage that pass through the wall cause the area of the wall they pass through to freeze solid (at least a 5-foot-square section is frozen). Each 5-foot-square frozen section has AC 5 and 15 hit points. Reducing a frozen section to 0 hit points destroys it. When a section is destroyed, the wall's water doesn't fill it."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":170},{"name":"Warding Wind","source":"XGE","level":2,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"A strong wind (20 miles per hour) blows around you in a 10-foot radius and moves with you, remaining centered on you. The wind lasts for the spell's duration."},{"type":"text","content":"The wind has the following effects:"},{"type":"list","items":["It <i class=\\"text-dnd-gold\\">deafened</i> you and other creatures in its area.","It extinguishes unprotected flames in its area that are torch-sized or smaller.","It hedges out vapor, gas, and fog that can be dispersed by strong wind.","The area is difficult terrain for creatures other than you.","The attack rolls of ranged weapon attacks have disadvantage if the attacks pass in or out of the wind."]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["deafened"],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":170},{"name":"Watery Sphere","source":"XGE","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":"a droplet of water"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You conjure up a sphere of water with a 5-foot radius at a point you can see within range. The sphere can hover but no more than 10 feet off the ground. The sphere remains for the spell's duration."},{"type":"text","content":"Any creature in the sphere's space must make a Strength saving throw. On a successful save, a creature is ejected from that space to the nearest unoccupied space of the creature's choice outside the sphere. A Huge or larger creature succeeds on the saving throw automatically, and a Large or smaller creature can choose to fail it. On a failed save, a creature is <i class=\\"text-dnd-gold\\">restrained</i> by the sphere and is engulfed by the water. At the end of each of its turns, a <i class=\\"text-dnd-gold\\">restrained</i> target can repeat the saving throw, ending the effect on itself on a success."},{"type":"text","content":"The sphere can restrain as many as four Medium or smaller creatures or one Large creature. If the sphere restrains a creature that causes it to exceed this capacity, a random creature that was already <i class=\\"text-dnd-gold\\">restrained</i> by the sphere falls out of it and lands <i class=\\"text-dnd-gold\\">prone</i> in a space within 5 feet of it."},{"type":"text","content":"As an action, you can move the sphere up to 30 feet in a straight line. If it moves over a pit, a cliff, or other drop-off, it safely descends until it is hovering 10 feet above the ground. Any creature <i class=\\"text-dnd-gold\\">restrained</i> by the sphere moves with it. You can ram the sphere into creatures, forcing them to make the saving throw."},{"type":"text","content":"When the spell ends, the sphere falls to the ground and extinguishes all normal flames within 30 feet of it. Any creature <i class=\\"text-dnd-gold\\">restrained</i> by the sphere is knocked <i class=\\"text-dnd-gold\\">prone</i> in the space where it falls. The water then vanishes."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":["prone","restrained"],"savingThrow":["strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":170},{"name":"Whirlwind","source":"XGE","level":7,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":300}},"components":{"v":true,"m":"a piece of straw"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"A whirlwind howls down to a point that you can see on the ground within range. The whirlwind is a 10-foot-radius, 30-foot-high cylinder centered on that point. Until the spell ends, you can use your action to move the whirlwind up to 30 feet in any direction along the ground. The whirlwind sucks up any Medium or smaller objects that aren't secured to anything and that aren't worn or carried by anyone."},{"type":"text","content":"A creature must make a Dexterity saving throw the first time on a turn that it enters the whirlwind or that the whirlwind enters its space, including when the whirlwind first appears. A creature takes <span class=\\"text-red-400 font-semibold\\">10d6</span> bludgeoning damage on a failed save, or half as much damage on a successful one. In addition, a Large or smaller creature that fails the save must succeed on a Strength saving throw or become <i class=\\"text-dnd-gold\\">restrained</i> in the whirlwind until the spell ends. When a creature starts its turn <i class=\\"text-dnd-gold\\">restrained</i> by the whirlwind, the creature is pulled 5 feet higher inside it, unless the creature is at the top. A <i class=\\"text-dnd-gold\\">restrained</i> creature moves with the whirlwind and falls when the spell ends, unless the creature has some means to stay aloft."},{"type":"text","content":"A <i class=\\"text-dnd-gold\\">restrained</i> creature can use an action to make a Strength or Dexterity check against your spell save DC. If successful, the creature is no longer <i class=\\"text-dnd-gold\\">restrained</i> by the whirlwind and is hurled <span class=\\"text-green-400 font-mono\\">3d6 × 10</span> feet away from it in a random direction."}],"entriesHigherLevel":[],"damageInflict":["bludgeoning"],"conditionInflict":["restrained"],"savingThrow":["dexterity","strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":171},{"name":"Word of Radiance","source":"XPHB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":5}},"components":{"v":true,"m":"a sunburst token"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"Burning radiance erupts from you in a 5-foot <i>Emanation [Area of Effect]</i>. Each creature of your choice that you can see in it must succeed on a Constitution saving throw or take <span class=\\"text-red-400 font-semibold\\">1d6</span> Radiant damage."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d6</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d6</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d6</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d6</span>)."}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":343},{"name":"Wrath of Nature","source":"XGE","level":5,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call out to the spirits of nature to rouse them against your enemies. Choose a point you can see within range. The spirits cause trees, rocks, and grasses in a 60-foot cube centered on that point to become animated until the spell ends."},{"type":"section","name":"Grasses and Undergrowth","entries":[{"type":"text","content":"Any area of ground in the cube that is covered by grass or undergrowth is difficult terrain for your enemies."}]},{"type":"section","name":"Trees","entries":[{"type":"text","content":"At the start of each of your turns, each of your enemies within 10 feet of any tree in the cube must succeed on a Dexterity saving throw or take <span class=\\"text-red-400 font-semibold\\">4d6</span> slashing damage from whipping branches."}]},{"type":"section","name":"Roots and Vines","entries":[{"type":"text","content":"At the end of each of your turns, one creature of your choice that is on the ground in the cube must succeed on a Strength saving throw or become <i class=\\"text-dnd-gold\\">restrained</i> until the spell ends. A <i class=\\"text-dnd-gold\\">restrained</i> creature can use an action to make a Strength (<i>Athletics</i>) check against your spell save DC, ending the effect on itself on a success."}]},{"type":"section","name":"Rocks","entries":[{"type":"text","content":"As a bonus action on your turn, you can cause a loose rock in the cube to launch at a creature you can see in the cube. Make a ranged spell attack against the target. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">3d8</span> nonmagical bludgeoning damage, and it must succeed on a Strength saving throw or fall <i class=\\"text-dnd-gold\\">prone</i>."}]}],"entriesHigherLevel":[],"damageInflict":["bludgeoning","slashing"],"conditionInflict":["prone","restrained"],"savingThrow":["dexterity","strength"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":171},{"name":"Zephyr Strike","source":"XGE","level":1,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You move like the wind. Until the spell ends, your movement doesn't provoke opportunity attacks."},{"type":"text","content":"Once before the spell ends, you can give yourself advantage on one weapon attack roll on your turn. That attack deals an extra <span class=\\"text-red-400 font-semibold\\">1d8</span> force damage on a hit. Whether you hit or miss, your walking speed increases by 30 feet until the end of that turn."}],"entriesHigherLevel":[],"damageInflict":["force"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":171},{"name":"Arcane Vigor","source":"XPHB","level":2,"school":"A","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You tap into your life force to heal yourself. Roll one or two of your unexpended <i>Hit Point Dice</i>, and regain a number of <i>Hit Points</i> equal to the roll's total plus your spellcasting ability modifier. Those dice are then expended."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The number of unexpended Hit Dice you can roll increases by one for each spell slot level above 2."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":242},{"name":"Befuddlement","source":"XPHB","level":8,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":150}},"components":{"v":true,"s":true,"m":"a key ring with no keys"},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You blast the mind of a creature that you can see within range. The target makes an Intelligence saving throw."},{"type":"text","content":"On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">10d12</span> Psychic damage and can't cast spells or take the <b>Magic</b> action. At the end of every 30 days, the target repeats the save, ending the effect on a success. The effect can also be ended by the <a href=\\"/spells?search=Greater Restoration\\" class=\\"text-dnd-gold hover:underline\\">Greater Restoration</a>, <a href=\\"/spells?search=Heal\\" class=\\"text-dnd-gold hover:underline\\">Heal</a>, or <a href=\\"/spells?search=Wish\\" class=\\"text-dnd-gold hover:underline\\">Wish</a> spell."},{"type":"text","content":"On a successful save, the target takes half as much damage only."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":[],"savingThrow":["intelligence"],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":245},{"name":"Divine Smite","source":"XPHB","level":1,"school":"V","time":[{"number":1,"unit":"bonus","condition":"which you take immediately after hitting a target with a Melee weapon or an {@variantrule Unarmed Strike|XPHB}"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"The target takes an extra <span class=\\"text-red-400 font-semibold\\">2d8</span> Radiant damage from the attack. The damage increases by <span class=\\"text-red-400 font-semibold\\">1d8</span> if the target is a Fiend or an Undead."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d8 for each spell slot level above 1."}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":265},{"name":"Elementalism","source":"XPHB","level":0,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You exert control over the elements, creating one of the following effects within range."},{"type":"section","name":"Beckon Air","entries":[{"type":"text","content":"You create a breeze strong enough to ripple cloth, stir dust, rustle leaves, and close open doors and shutters, all in a 5-foot <i>Cube [Area of Effect]</i>. Doors and shutters being held open by someone or something aren't affected."}]},{"type":"section","name":"Beckon Earth","entries":[{"type":"text","content":"You create a thin shroud of dust or sand that covers surfaces in a 5-foot-square area, or you cause a single word to appear in your handwriting in a patch of dirt or sand."}]},{"type":"section","name":"Beckon Fire","entries":[{"type":"text","content":"You create a thin cloud of harmless embers and colored, scented smoke in a 5-foot <i>Cube [Area of Effect]</i>. You choose the color and scent, and the embers can light candles, torches, or lamps in that area. The smoke's scent lingers for 1 minute."}]},{"type":"section","name":"Beckon Water","entries":[{"type":"text","content":"You create a spray of cool mist that lightly dampens creatures and objects in a 5-foot <i>Cube [Area of Effect]</i>. Alternatively, you create 1 cup of clean water either in an open container or on a surface, and the water evaporates in 1 minute."}]},{"type":"section","name":"Sculpt Element","entries":[{"type":"text","content":"You cause dirt, sand, fire, smoke, mist, or water that can fit in a 1-foot <i>Cube [Area of Effect]</i> to assume a crude shape (such as that of a creature) for 1 hour."}]}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":267},{"name":"Fount of Moonlight","source":"XPHB","level":4,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true,"s":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":10},"concentration":true}],"entries":[{"type":"text","content":"A cool light wreathes your body for the duration, emitting <i>Bright Light</i> in a 20-foot radius and <i>Dim Light</i> for an additional 20 feet."},{"type":"text","content":"Until the spell ends, you have <i>Resistance</i> to Radiant damage, and your melee attacks deal an extra <span class=\\"text-red-400 font-semibold\\">2d6</span> Radiant damage on a hit."},{"type":"text","content":"In addition, immediately after you take damage from a creature you can see within 60 feet of yourself, you can take a <i>Reaction</i> to force the creature to make a Constitution saving throw. On a failed save, the creature has the <i class=\\"text-dnd-gold\\">Blinded</i> condition until the end of your next turn."}],"entriesHigherLevel":[],"damageInflict":["radiant"],"conditionInflict":["blinded"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":277},{"name":"Jallarzi's Storm of Radiance","source":"XPHB","level":5,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true,"m":"a pinch of phosphorus"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You unleash a storm of flashing light and raging thunder in a 10-foot-radius, 40-foot-high <i>Cylinder [Area of Effect]</i> centered on a point you can see within range. While in this area, creatures have the <i class=\\"text-dnd-gold\\">Blinded</i> and <i class=\\"text-dnd-gold\\">Deafened</i> conditions, and they can't cast spells with a Verbal component."},{"type":"text","content":"When the storm appears, each creature in it makes a Constitution saving throw, taking <span class=\\"text-red-400 font-semibold\\">2d10</span> Radiant damage and <span class=\\"text-red-400 font-semibold\\">2d10</span> Thunder damage on a failed save or half as much damage on a successful one. A creature also makes this save when it enters the spell's area for the first time on a turn or ends its turn there. A creature makes this save only once per turn."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The Radiant and Thunder damage increase by 2d10 for each spell slot level above 5."}]}],"damageInflict":["radiant","thunder"],"conditionInflict":["blinded","deafened"],"savingThrow":["constitution"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":289},{"name":"Power Word Fortify","source":"XPHB","level":7,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You fortify up to six creatures you can see within range. The spell bestows 120 <i>Temporary Hit Points</i>, which you divide among the spell's recipients."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":306},{"name":"Shining Smite","source":"XPHB","level":2,"school":"T","time":[{"number":1,"unit":"bonus","condition":"which you take immediately after hitting a creature with a Melee weapon or an {@variantrule Unarmed Strike|XPHB}"}],"range":{"type":"point","distance":{"type":"self"}},"components":{"v":true},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"The target hit by the strike takes an extra <span class=\\"text-red-400 font-semibold\\">2d6</span> Radiant damage from the attack. Until the spell ends, the target sheds <i>Bright Light</i> in a 5-foot radius, attack rolls against it have <i>Advantage</i>, and it can't benefit from the <i class=\\"text-dnd-gold\\">Invisible</i> condition."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"The damage increases by 2d6 for each spell slot level above 2."}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":[],"castingTime":"bonus","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":316},{"name":"Sorcerous Burst","source":"XPHB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You cast sorcerous energy at one creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">1d8</span> damage of a type you choose: Acid, Cold, Fire, Lightning, Poison, Psychic, or Thunder."},{"type":"text","content":"If you roll an 8 on a <span class=\\"text-green-400 font-mono\\">d8</span> for this spell, you can roll another <span class=\\"text-green-400 font-mono\\">d8</span>, and add it to the damage. When you cast this spell, the maximum number of these d8s you can add to the spell's damage equals your spellcasting ability modifier."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d8</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d8</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d8</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d8</span>)."}]}],"damageInflict":["acid","cold","fire","lightning","poison","psychic","thunder"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":318},{"name":"Starry Wisp","source":"XPHB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"entries":[{"type":"text","content":"You launch a mote of light at one creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes <span class=\\"text-red-400 font-semibold\\">1d8</span> Radiant damage, and until the end of your next turn, it emits <i>Dim Light</i> in a 10-foot radius and can't benefit from the <i class=\\"text-dnd-gold\\">Invisible</i> condition."}],"entriesHigherLevel":[{"type":"section","name":"Cantrip Upgrade","entries":[{"type":"text","content":"The damage increases by <span class=\\"text-red-400 font-semibold\\">1d8</span> when you reach levels 5 (<span class=\\"text-red-400 font-semibold\\">2d8</span>), 11 (<span class=\\"text-red-400 font-semibold\\">3d8</span>), and 17 (<span class=\\"text-red-400 font-semibold\\">4d8</span>)."}]}],"damageInflict":["radiant"],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":320},{"name":"Summon Dragon","source":"XPHB","level":5,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":{"text":"an object with the image of a dragon engraved on it worth 500+ GP","cost":50000}},"duration":[{"type":"timed","duration":{"type":"hour","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You call forth a Dragon spirit. It manifests in an unoccupied space that you can see within range and uses the <b>Draconic Spirit</b> stat block. The creature disappears when it drops to 0 <i>Hit Points</i> or when the spell ends."},{"type":"text","content":"The creature is an ally to you and your allies. In combat, the creature shares your <i>Initiative</i> count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the <b>Dodge</b> action and uses its movement to avoid danger."}],"entriesHigherLevel":[{"type":"section","name":"Using a Higher-Level Spell Slot","entries":[{"type":"text","content":"Use the spell slot's level for the spell's level in the stat block."}]}],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":true,"basicRules":false,"basicRules2024":true,"reprintedAs":[],"page":324},{"name":"Tasha's Bubbling Cauldron","source":"XPHB","level":6,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":5}},"components":{"v":true,"s":true,"m":"a gilded ladle worth 500 + GP"},"duration":[{"type":"timed","duration":{"type":"minute","amount":10}}],"entries":[{"type":"text","content":"You conjure a claw-footed cauldron filled with bubbling liquid. The cauldron appears in an unoccupied space on the ground within 5 feet of you and lasts for the duration. The cauldron can't be moved and disappears when the spell ends, along with the bubbling liquid inside it."},{"type":"text","content":"The liquid in the cauldron duplicates the properties of a Common or an Uncommon potion of your choice (such as a <b>Potion of Healing</b>). As a <i>Bonus Action</i>, you or an ally can reach into the cauldron and withdraw one potion of that kind. The potion is contained in a vial that disappears when the potion is consumed. The cauldron can produce a number of these potions equal to your spellcasting ability modifier (minimum 1). When the last of these potions is withdrawn from the cauldron, the cauldron disappears, and the spell ends."},{"type":"text","content":"Potions obtained from the cauldron that aren't consumed disappear when you cast this spell again."}],"entriesHigherLevel":[],"damageInflict":[],"conditionInflict":[],"savingThrow":[],"castingTime":"action","ritual":false,"concentration":false,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":330},{"name":"Yolande's Regal Presence","source":"XPHB","level":5,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"emanation","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":"a miniature tiara"},"duration":[{"type":"timed","duration":{"type":"minute","amount":1},"concentration":true}],"entries":[{"type":"text","content":"You surround yourself with unearthly majesty in a 10-foot <i>Emanation [Area of Effect]</i>. Whenever the <i>Emanation [Area of Effect]</i> enters the space of a creature you can see and whenever a creature you can see enters the <i>Emanation [Area of Effect]</i> or ends its turn there, you can force that creature to make a Wisdom saving throw. On a failed save, the target takes <span class=\\"text-red-400 font-semibold\\">4d6</span> Psychic damage and has the <i class=\\"text-dnd-gold\\">Prone</i> condition, and you can push it up to 10 feet away. On a successful save, the target takes half as much damage only. A creature makes this save only once per turn."}],"entriesHigherLevel":[],"damageInflict":["psychic"],"conditionInflict":["prone"],"savingThrow":["wisdom"],"castingTime":"action","ritual":false,"concentration":true,"srd":false,"srd52":false,"basicRules":false,"basicRules2024":false,"reprintedAs":[],"page":343},{"name":"Acid Stream (UA)","source":"HB","level":1,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"self","selfType":"line","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a bit of rotten food"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } A stream of acid emanates from you in a line 30 feet long and 5 feet wide in a direction you choose. Each creature in the line must succeed on a Dexterity saving throw or be covered in acid for the spell’s duration or until a creature uses its action to scrape or wash the acid off itself or another creature. A creature covered in the acid takes 3d4 acid damage at the start of each of its turns. <i>Evocation</i> 1st 1 Action Self (30-foot line) Concentration, up to 1 minute V, S, M"}],"page":0,"homebrew":true},{"name":"Antagonize (UA)","source":"HB","level":3,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a playing card depicting a rogue"},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You whisper magical words that antagonize one creature of your choice within range. The target must make a Wisdom saving throw. On a failed save, it takes 4d4 psychic damage and must immediately use its reaction, if available, to make a melee attack against another creature of your choice that you can see. If no other creature is within range, the target has disadvantage on the next attack roll it makes before the start of your next turn. <i>Enchantment</i> 3rd 1 Action 30 feet Instantaneous V, S, M"}],"page":0,"homebrew":true},{"name":"Arcane Hacking (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"self"},"components":{"v":true,"s":true,"m":"hacking tools"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"hour"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } <i>2nd-level transmutation (technomagic)</i> You gain advantage on all Intelligence checks using hacking tools to break software encryption or online security when using a foreign system. This spell also allows you to break 2nd level and lower protective spells such as Arcane Lock or Glyph of Warding by making an Intelligence check using hacking tools against the spell save DC of the spell’s caster. <i>Transmutation ^^T^^</i> 2nd 1 Action Self Concentration, up to 1 hour V, S, M"}],"page":0,"homebrew":true},{"name":"Arcane Weapon (UA)","source":"HB","level":1,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"self"},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"hour"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You channel arcane energy into one simple or martial weapon you’re holding, and choose one damage type: acid, cold, fire, lightning, poison, or thunder. Until the spell ends, you deal an extra 1d6 damage of the chosen type to any target you hit with the weapon. If the weapon isn’t magical, it becomes a magic weapon for the spell’s duration. As a bonus action, you can change the damage type, choosing from the options above. <i>Transmutation</i> 1st 1 Bonus Action Self Concentration, up to 1 hour V, S"}],"page":0,"homebrew":true},{"name":"Commune with City (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"minute"}],"range":{"type":"self"},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"list","items":["Terrain and bodies of water","Prevalent buildings, plants, animals, or intelligent creatures","Powerful (CR 1 or higher) celestials, fey, fiends, elementals, or undead","Influences from other planes of existence","Electrical currents, wireless signals, and active transit lines and tracks"]},{"type":"text","content":".page-tags { display: none; } <i>5th-level divination (ritual) (technomagic)</i> You briefly become one with the city and gain knowledge of the surrounding area. Aboveground, this spell gives you knowledge of the area within 1 mile of you. In sewers and other underground settings, you gain knowledge of the area within 600 feet of you. You instantly gain knowledge of up to three facts of your choice about any of the following subjects as they relate to the area: For example, you could determine the location of powerful undead in the area, the location of major sources of electrical power or interference, and the location of any nearby parks. <i>Divination ^^T^^</i> 5th 1 Minute <i>^^R^^</i> Self Instantaneous V, S"}],"page":0,"homebrew":true},{"name":"Conjure Barlgura (UA)","source":"HB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":false,"duration":{"amount":10,"type":"minute"}}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You summon a barlgura that appears in an unoccupied space you can see within range. The barlgura disappears when it drops to 0 hit points or when the spell ends. The barlgura is hostile to all non-demons. Roll initiative for the barlgura, which has its own turns. At the start of its turn, it moves toward and attacks the nearest non-demon it can perceive. If two or more creatures are equally near, it picks one at random. If it cannot see any potential enemies, the barlgura moves in a random direction in search of foes. As part of casting the spell, you can scribe a circle on the ground using the blood of an intelligent humanoid slain within the past 24 hours. The circle is large enough to encompass your space. The summoned barlgura cannot cross the circle or target anyone in it while the spell lasts. <i>Conjuration</i> 4th 1 Action 60 feet Up to 10 minutes V, S"}],"page":0,"homebrew":true},{"name":"Conjure Hezrou (UA)","source":"HB","level":7,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"food worth at least 100 gp, which the spell consumes"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"hour"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You summon a hezrou that appears in an unoccupied space you can see within range. The hezrou disappears when it drops to 0 hit points or when the spell ends. The hezrou’s attitude depends on the value of the food used as a material component for this spell. Roll initiative for the hezrou, which has its own turns. At the start of the hezrou’s turn, the DM makes a secret Charisma check on your behalf, with a bonus equal to the food’s value divided by 20. The check DC starts at 10 and increases by 2 each round. You can issue orders to the hezrou and have it obey you as long as you succeed on the Charisma check. If the check fails, the spell no longer requires concentration and the demon is no longer under your control. The hezrou then focuses on devouring any corpses it can see. If there are no such meals at hand, it attacks the nearest creatures and eats anything it kills. If its hit points are reduced to below half its hit point maximum, it returns to the Abyss. As part of casting the spell, you can scribe a circle on the ground using the blood of an intelligent humanoid slain within the past 24 hours. The circle is large enough to encompass your space. The summoned hezrou cannot cross the circle or target anyone in it while the spell lasts. <i>Conjuration</i> 7th 1 Action 60 feet Concentration, up to 1 hour V, S, M"}],"page":0,"homebrew":true},{"name":"Conjure Knowbot (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"touch"},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":false,"duration":{"amount":10,"type":"minute"}}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } <i>4th-level conjuration (technomagic)</i> You touch a single computerized device or computer system to conjure a knowbot—a partially sentient piece of software imprinted with vestiges of your own skills and computer abilities. For the duration of the spell, you can use a bonus action to have the knowbot execute a computer related task that would normally require an action. The knowbot makes Intelligence ability checks using your ability score and proficiency bonuses including your proficiency with hacking tools, if applicable. You have a limited telepathic bond with the knowbot, out to a range of 500 feet from the device or system where the knowbot was conjured. If you move beyond this range, the knowbot disappears in 2d4 rounds, as if the duration of the spell had expired. Moving within range again immediately reestablishes the bond. The knowbot is bound to the system in which it was created, and it stays there until it is dismissed or the spell’s duration expires. <i><b>At Higher Levels.</b></i> When you cast this spell using a spell slot of 5th level or higher, the spell’s duration increases to 1 hour. Additionally, your telepathic bond with the knowbot is effective out to a range of 1,000 feet, and if you leave the range of the bond, the knowbot continues performing its last directed task until the spell expires. <i>Conjuration ^^T^^</i> 4th 1 Action Touch 10 minutes V, S"}],"page":0,"homebrew":true},{"name":"Conjure Lesser Demon (UA)","source":"HB","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a vial of blood from an intelligent humanoid killed within the past 24 hours"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"hour"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You summon up to a total of eight manes or dretches that appear in unoccupied spaces you can see within range. A manes or dretch disappears when it drops to 0 hit points or when the spell ends. The demons are hostile to all creatures. Roll initiative for the summoned demons as a group, which has its own turns. The demons attack the nearest non-demons to the best of their ability. As part of casting the spell, you can scribe a circle on the ground with the blood used as a material component. The circle is large enough to encompass your space. The summoned demons cannot cross the circle or target anyone in it while the spell lasts. Using the material component in this manner consumes it. <i>Conjuration</i> 3rd 1 Action 60 feet Concentration, up to 1 hour V, S, M"}],"page":0,"homebrew":true},{"name":"Conjure Shadow Demon (UA)","source":"HB","level":4,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a vial of blood from an intelligent humanoid killed within the past 24 hours"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"hour"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You summon a shadow demon that appears in an unoccupied space you can see within range. The shadow demon disappears when it drops to 0 hit points or when the spell ends. Roll initiative for the shadow demon, which has its own turns. You can issue orders to the shadow demon, and it obeys you as long as it can attack a creature on each of its turns and does not start its turn in an area of bright light. If either of these conditions is not met, the shadow demon immediately makes a Charisma check contested by your Charisma check. If you fail the check, the spell no longer requires concentration and the demon is no longer under your control. The demon automatically succeeds on the check if it is more than 100 feet away from you. As part of casting the spell, you can scribe a circle on the ground using the blood of an intelligent humanoid slain within the past 24 hours. The circle is large enough to encompass your space. The summoned shadow demon cannot cross the circle or target anyone in it while the spell lasts. <i>Conjuration</i> 4th 1 Action 60 feet Concentration, up to 1 hour V, S, M"}],"page":0,"homebrew":true},{"name":"Conjure Vrock (UA)","source":"HB","level":5,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a gem worth at least 100 gp, which the spell consumes"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"hour"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You summon a vrock that appears in an unoccupied space you can see within range. The vrock disappears when it drops to 0 hit points or when the spell ends. The vrock’s attitude depends on the value of the gem used as a material component for this spell. Roll initiative for the vrock, which has its own turns. At the start of the vrock’s turn, the DM makes a secret Charisma check on your behalf, with a bonus equal to the gem’s value divided by 20. The check DC starts at 10 and increases by 2 each round. You can issue orders to the vrock and have it obey you as long as you succeed on the Charisma check. If the check fails, the spell no longer requires concentration and the vrock is no longer under your control. The vrock takes no actions on its next turn and uses its telepathy to tell any creature it can see that it will fight in exchange for treasure. The creature that gives the vrock the most expensive gem can command it for the next 1d6 rounds. At the end of that time, it offers the bargain again. If no one offers the vrock treasure before its next turn begins, it attacks the nearest creatures for 1d6 rounds before returning to the Abyss. As part of casting the spell, you can scribe a circle on the ground using the blood of an intelligent humanoid slain within the past 24 hours. The circle is large enough to encompass your space. The summoned vrock cannot cross the circle or target anyone in it while the spell lasts. <i>Conjuration</i> 5th 1 Action 60 feet Concentration, up to 1 hour V, S, M"}],"page":0,"homebrew":true},{"name":"Digital Phantom (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"self"},"components":{"v":true,"s":true,"m":"a small piece of copper wire"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"hour"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } <i>2nd-level abjuration (technomagic)</i> This spell works to actively hide your presence within a computer system. For the spell’s duration, you and any other users you choose on your local network gain a +10 bonus to Intelligence checks to avoid detection by administrators, knowbots, tracking software, and the like. Whenever you and your chosen users leave any computer system you are working in while this spell is in effect, all trace of your previous presence in that system is erased. <i>Abjuration ^^T^^</i> 2nd 1 Action Self Concentration, up to 1 hour V, S, M"}],"page":0,"homebrew":true},{"name":"Draconic Transformation (UA)","source":"HB","level":7,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"self"},"components":{"v":true,"s":true,"m":true},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"list","items":["You have blindsight with a range of 30 feet. Within that range, you can effectively see anything that isn’t behind total cover, even if you’re blinded or in darkness. Moreover, you can see an invisible creature, unless the creature successfully hides from you.","Incorporeal wings sprout from your back, giving you a flying speed of 40 feet.","When you cast this spell, and as a bonus action on subsequent turns for the duration, you can exhale a breath of shimmering energy in a 30-foot cone. Each creature in the area must make a Dexterity saving throw, taking 3d8 force damage on a failed save or half as much damage on a successful one."]},{"type":"text","content":".page-tags { display: none; } worth at least 500 gp) With a roar, you draw on the magic of dragons to transform yourself, taking on various draconic features. You gain the following benefits until the spell ends: <i>Transmutation</i> 7th 1 Bonus Action Self Concentration, up to 1 minute V, S, M"}],"page":0,"homebrew":true},{"name":"Ego Whip (UA)","source":"HB","level":4,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You lash the mind of one creature you can see within range, filling it with despair. The target must succeed on an Intelligence saving throw or suffer disadvantage on attack rolls, ability checks, and saving throws, and it can’t cast spells. At the end of each of its turns, the target can make another Intelligence saving throw. On a success, the spell ends on the target. <i>Enchantment</i> 4th 1 Action 30 feet Concentration, up to 1 minute V"}],"page":0,"homebrew":true},{"name":"Find Vehicle (UA)","source":"HB","level":0,"school":"V","time":[{"number":10,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":false,"duration":{"amount":8,"type":"hour"}}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } <i>2nd-level conjuration (technomagic)</i> You summon a spirit that assumes the form of a nonmilitary land vehicle of your choice, appearing in an unoccupied space within range. The vehicle has the statistics of a normal vehicle of its sort, though it is celestial, fey, or fiendish (your choice in origin). The physical characteristics of the vehicle reflect its origin to some degree. For example, a fiendish SUV might be jet black in color, with tinted windows and a sinister-looking front grille. You have a supernatural bond with the conjured vehicle that allows you to drive beyond your normal ability. While driving the conjured vehicle, you are considered proficient with vehicles of its type, and you add double your proficiency bonus to ability checks related to driving the vehicle. While driving the vehicle, you can make any spell you cast that targets only you also target the vehicle. If the vehicle drops to 0 hit points, it disappears, leaving behind no physical form. You can also dismiss the vehicle at any time as an action, causing it to disappear. You can't have more than one vehicle bonded by this spell at a time. As an action, you can release the vehicle from its bond at any time, causing it to disappear. <i>Conjuration ^^T^^</i> 2nd 10 Minutes 30 feet 8 hours V, S"}],"page":0,"homebrew":true},{"name":"Fizban's Platinum Shield (UA)","source":"HB","level":6,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a platinum-plated dragon scale, worth at least 500 gp"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"list","items":["The creature has half cover.","The creature has resistance to acid, cold, fire, lightning, and poison damage.","If the creature is subjected to an effect that allows it to make a Dexterity saving throw to take only half damage, the creature instead takes no damage if it succeeds on the saving throw, and only half damage if it fails."]},{"type":"text","content":".page-tags { display: none; } You create a field of silvery light that surrounds a creature of your choice within range (you can choose yourself). The field sheds dim light out to 5 feet. As a bonus action on subsequent turns, you can move the field to another creature within 60 feet of the field. The creature protected by the field gains the following benefits: <i>Abjuration</i> 6th 1 Action 60 feet Concentration, up to 1 minute V, S, M"}],"page":0,"homebrew":true},{"name":"Flame Stride (UA)","source":"HB","level":3,"school":"T","time":[{"number":1,"unit":"bonus"}],"range":{"type":"self"},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } The billowing flames of a dragon cover your feet, granting you explosive speed. For the duration, your speed increases by 20 feet and moving doesn’t provoke opportunity attacks. When you move within 5 feet of a creature or object that isn’t being worn or carried, it takes 1d6 fire damage from your trail of heat. A creature or object can take this damage only once during a turn. <i>Transmutation</i> 3rd 1 Bonus Action Self Concentration, up to 1 minute V, S"}],"page":0,"homebrew":true},{"name":"Guiding Hand (UA)","source":"HB","level":1,"school":"D","time":[{"number":1,"unit":"minute"}],"range":{"type":"point","distance":{"type":"feet","amount":5}},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":true,"duration":{"amount":8,"type":"hour"}}],"ritual":true,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You create a Tiny incorporeal hand of shimmering light in an unoccupied space you can see within range. The hand exists for the duration, but it disappears if you teleport or you travel to a different plane of existence. When the hand appears, you name one major landmark, such as a city, mountain, castle, or battlefield on the same plane of existence as you. Someone in history must have visited the site and mapped it. If the landmark appears on no map in existence, the spell fails. Otherwise, whenever you move toward the hand, it moves away from you at the same speed you moved, and it moves in the direction of the landmark, always remaining 5 feet away from you. If you don’t move toward the hand, it remains in place until you do and beckons for you to follow once every 1d4 minutes. <i>Divination</i> 1st 1 Minute <i>^^R^^</i> 5 feet Concentration, up to 8 hours V, S"}],"page":0,"homebrew":true},{"name":"Hand of Radiance (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":5}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } <i>Evocation cantrip</i> You raise your hand, and burning radiance erupts from it. Each creature of your choice that you can see within 5 feet of you must succeed on a Constitution saving throw or take 1d6 radiant damage. <b><i>At Higher Levels:</i></b> The spell's damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6). <b><i>Spell Lists:</i></b> Cleric <i>Evocation</i> Cantrip 1 Action 5 feet Instantaneous V, S"}],"page":0,"homebrew":true},{"name":"Haywire (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } <i>3rd-level enchantment (technomagic)</i> This spell plays havoc with electronic devices, making the use of such devices all but impossible. Each electronic device in a 10-foot-radius sphere centered on a point you choose within range is subject to random behavior while it remains within the area. A device not held by a creature is automatically affected. If an electronic device is held by a creature, that creature must succeed on a Wisdom saving throw or have the device affected by the spell. At the start of each of your turns, roll a d6 for each affected device to determine its behavior. Except where otherwise indicated, that behavior lasts until the start of your next turn while this spell is in effect."},{"type":"table","colLabels":[],"rows":[["1","The device shuts down and must be restarted. Do not roll again for this device until it is restarted."]]},{"type":"table","colLabels":[],"rows":[["2-4","The device does not function."]]},{"type":"table","colLabels":[],"rows":[["5","The device experiences a power surge, causing an electric shock to the wielder (if any and one random creature within 5 feet of the device. Each affected creature must make a Dexterity saving throw against your spell save DC, taking 6d6 lightning damage on a failed save, or half as much damage on a successful one."]]},{"type":"table","colLabels":[],"rows":[["6","The device is usable as normal."]]},{"type":"text","content":"<i>Enchantment ^^T^^</i> 5th 1 Action 90 feet Concentration, up to 1 minute V, S"}],"page":0,"homebrew":true},{"name":"Healing Elixir (UA)","source":"HB","level":1,"school":"C","time":[{"number":1,"unit":"minute"}],"range":{"type":"self"},"components":{"v":true,"s":true,"m":"alchemist’s supplies"},"duration":[{"type":"timed","concentration":false,"duration":{"amount":24,"type":"hour"}}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You create a healing elixir in a simple vial that appears in your hand. The elixir retains its potency for the duration or until it’s consumed, at which point the vial vanishes. As an action, a creature can drink the elixir or administer it to another creature. The drinker regains 2d4 + 2 hit points. <i>^^HB^^This spell is massively overpowered. For example, a 1st-level wizard could use this spell to produce enough healing for an entire party without losing any spell slots. Additionally, it could be used to run a potion-selling scam in which the product vanishes a day after purchase. I would not recommend allowing it. Editor's Note: I don't have a clue as to what the first point is referring to, arcane recovery only gives 1 spell slot until 4th level, spell mastery is at 18th level, and any abusable subclass features are at 2nd level. But yes, either way, this spell is overpowered, it gives non-divine caster classes access to healing, and it can be abused in numerous ways. I'd suggest limiting the duration to an hour or less. Editor notes+: At higher levels, this allows wizards to heal creatures infinitely, and overall, wizards just shouldn't have healing spells, it goes against their design philosophy. On the warlock, its also still a confusing option, as though warlocks can gain healing spells through a celestial patron, this spell lacks any upcasting rules, which goes against the design of warlock.</i> <i>Conjuration</i> 1st 1 Minute Self 24 hours V, S, M"}],"page":0,"homebrew":true},{"name":"House of Cards (UA)","source":"HB","level":3,"school":"C","time":[{"number":1,"unit":"minute"}],"range":{"type":"touch"},"components":{"v":true,"s":true,"m":"a deck of cards"},"duration":[{"type":"timed","concentration":false,"duration":{"amount":24,"type":"hour"}}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You touch the ground and conjure forth a defensive structure made of enormous playing cards. The structure rises with you at its center, harmlessly lifting you and any creatures in the area. The house of cards has a square base that is 30 feet on each side, and it has three floors with 10-foot-high ceilings. The second floor is 20 feet on each side, and the top floor is 10 feet on each side—both centered above the bottom floor. Ramps connect the interior of each floor, and empty doorframes connect the interior and exterior of each level. Creatures inside or on top of the structure have half cover. Each card that comprises the house is 5 feet wide and 10 feet tall and is very fragile. A card has AC 10 and 1 hit point. The cards are immune to poison and psychic damage. Reducing a card to 0 hit points destroys it. Every time a card is destroyed, roll 1d6. If you roll a 5 or a 6, the house collapses, ending the spell. The house and all its cards vanish when the spell ends. <i>Conjuration</i> 3rd 1 Minute Touch 24 hours V, S, M"}],"page":0,"homebrew":true},{"name":"Icingdeath's Frost (UA)","source":"HB","level":2,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"self","selfType":"cone","distance":{"type":"feet","amount":15}},"components":{"s":true,"m":"a vial of meltwater"},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } A burst of icy cold energy emanates from you in a 30-foot cone. Each creature in that area must make a Constitution saving throw. On a failed save, a creature takes 3d8 cold damage and is covered in ice for 1 minute or until a creature uses its action to break the ice off itself or another creature. A creature covered in ice has its speed reduced to 0. On a successful save, a creature takes half as much damage with no additional effects. <i>Evocation</i> 2nd 1 Action Self (15-foot cone) Instantaneous S, M"}],"page":0,"homebrew":true},{"name":"Id Insinuation (UA)","source":"HB","level":1,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You unleash a torrent of conflicting desires in the mind of one creature you can see within range, impairing its ability to make decisions. The target must succeed on a Wisdom saving throw or be incapacitated. At the end of each of its turns, it takes 1d12 psychic damage, and it can then make another Wisdom saving throw. On a success, the spell ends on the target. <i>Enchantment</i> 1st 1 Action 60 feet Concentration, up to 1 minute V, S"}],"page":0,"homebrew":true},{"name":"Infallible Relay (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"minute"}],"range":{"type":"self"},"components":{"v":true,"s":true,"m":"a mobile phone"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":10,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } <i>1st-level divination (technomagic)</i> With this spell, you can target any creature with whom you have spoken previously, as long as the two of you are on the same plane of existence. When you cast the spell, the nearest functioning telephone or similar communications device within 100 feet of the target begins to ring. If there is no suitable device close enough to the target, the spell fails. The target must make a successful Charisma saving throw or be compelled to answer your call. Once the connection is established, the call is crystal clear and cannot be dropped until the conversation has ended or the spell’s duration ends. You can end the conversation at any time, but a target must succeed on a Charisma saving throw to end the conversation. <i>Divination ^^T^^</i> 1st 1 Minute Self Concentration, up to 10 minutes V, S, M"}],"page":0,"homebrew":true},{"name":"Invisibility To Cameras (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true,"s":true,"m":"a scrap of black paper"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } <i>3rd-level illusion (technomagic)</i> Four creatures of your choice within range become undetectable to electronic sensors and cameras for the duration of the spell. Anything a target is wearing or carrying is likewise undetectable as long as it is on the target’s person. The targets remain visible to vision. <i>Illusion ^^T^^</i> 3rd 1 Action 10 feet Concentration, up to 1 minute V, S, M"}],"page":0,"homebrew":true},{"name":"Maximillian's Earthen Grasp","source":"XGE","level":2,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":30}},"components":{"v":true,"s":true,"m":"a miniature hand sculpted from clay"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You choose a 5-foot-square unoccupied space on the ground that you can see within range. A Medium hand made from compacted soil rises there and reaches for one creature you can see within 5 feet of it. The target must make a Strength saving throw. On a failed save, the target takes 2d6 bludgeoning damage and is restrained for the spell’s duration. As an action, you can cause the hand to crush the restrained target, who must make a Strength saving throw. It takes 2d6 bludgeoning damage on a failed save, or half as much damage on a successful one. To break out, the restrained target can use its action to make a Strength check against your spell save DC. On a success, the target escapes and is no longer restrained by the hand. As an action, you can cause the hand to reach for a different creature or to move to a different unoccupied space within range. The hand releases a restrained target if you do either. <i>Transmutation</i> 2nd 1 Action 30 feet Concentration, up to 1 minute V, S, M"}],"page":0,"homebrew":true},{"name":"Mental Barrier (UA)","source":"HB","level":2,"school":"A","time":[{"number":1,"unit":"reaction"}],"range":{"type":"self"},"components":{"v":true},"duration":[{"type":"timed","concentration":false,"duration":{"amount":1,"type":"round"}}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You protect your mind with a wall of looping, repetitive thought. Until the start of your next turn, you have advantage on Intelligence, Wisdom, and Charisma saving throws, and you have resistance to psychic damage. <i>Abjuration</i> 2nd 1 Reaction Self 1 round V"}],"page":0,"homebrew":true},{"name":"Mind Thrust (UA)","source":"HB","level":2,"school":"E","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":false,"duration":{"amount":1,"type":"round"}}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You thrust a lance of psychic disruption into the mind of one creature you can see within range. The target must make an Intelligence saving throw. On a failed save, the target takes 3d6 psychic damage, and it can’t take a reaction until the end of its next turn. Moreover, on its next turn, it must choose whether it gets a move, an action, or a bonus action; it gets only one of the three. On a successful save, the target takes half as much damage and suffers none of the spell’s other effects. <i>Enchantment</i> 2nd 1 Bonus Action 60 feet 1 round V, S"}],"page":0,"homebrew":true},{"name":"Nathair's Mischief (UA)","source":"HB","level":2,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"s":true,"m":"a piece of crust from an apple pie"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You fill a 20-foot cube centered on a point you choose within range with fey and draconic magic. Roll on the Mischievous Surge table to determine the magical effect produced. At the start of each of your turns, you can move the cube up to 10 feet and reroll on the table."},{"type":"table","colLabels":[],"rows":[["1","The smell of apple pie fills the air, and each creature in the cube must succeed on a Wisdom saving throw or become charmed by you until the start of your next turn."]]},{"type":"table","colLabels":[],"rows":[["2","Bouquets of flowers appear all around, and each creature in the cube must succeed on a Dexterity saving throw or be blinded until the start of your next turn as the flowers spray water in their faces."]]},{"type":"table","colLabels":[],"rows":[["3","Each creature in the cube must succeed on a Wisdom saving throw or begin giggling until the start of your next turn. A giggling creature is incapacitated and uses all its movement to move in a random direction."]]},{"type":"table","colLabels":[],"rows":[["4","Drops of molasses appear and hover in the cube, turning it into difficult terrain until the start of your next turn."]]},{"type":"text","content":"<i>Illusion</i> 2nd 1 Action 60 feet Concentration, up to 1 minute S, M"}],"page":0,"homebrew":true},{"name":"On/Off (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } <i>Transmutation cantrip (technomagic)</i> This cantrip allows you to activate or deactivate any electronic device within range, as long as the device has a clearly defined on or off function that can be easily accessed from the outside of the device. Any device that requires a software-based shutdown sequence to activate or deactivate cannot be affected by On/Off. <i>Transmutation ^^T^^</i> Cantrip 1 Action 60 feet Instantaneous V, S"}],"page":0,"homebrew":true},{"name":"Otherworldly Form (UA)","source":"HB","level":6,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"self"},"components":{"v":true,"s":true,"m":"an object engraved with a symbol of the Outer Planes, worth at least 500 gp"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"list","items":["You are immune to fire and poison damage (Lower Planes) or radiant and necrotic damage (Upper Planes).","You are immune to the poisoned condition (Lower Planes) or the charmed condition (Upper Planes).","Spectral wings appear on your back, giving you a flying speed of 40 feet.","You have a +2 bonus to AC.","All your weapon attacks are magical, and when you make a weapon attack, you can use your spellcasting ability modifier, instead of Strength or Dexterity, for the attack and damage rolls.","You can attack twice, instead of once, when you take the Attack action on your turn. You ignore this benefit if you already have a feature, like Extra Attack, that gives you extra attacks"]},{"type":"text","content":".page-tags { display: none; } Uttering an incantation, you draw on the magic of the Lower Planes or Upper Planes (your choice) to transform yourself. You gain the following benefits until the spell ends: <i>Transmutation</i> 6th 1 Action Self Concentration, up to 1 minute V, S, M"}],"page":0,"homebrew":true},{"name":"Power Word: Heal","source":"PHB","level":9,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"touch"},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } A wave of healing energy washes over a creature you touch. The target regains all its hit points. If the creature is charmed, frightened, paralyzed, or stunned, the condition ends. If the creature is prone, it can use its reaction to stand up. This spell has no effect on undead or constructs. <i>Evocation</i> 9th 1 Action Touch Instantaneous V, S"}],"page":0,"homebrew":true},{"name":"Power Word: Kill","source":"PHB","level":9,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You utter a word of power that can compel one creature you can see within range to die instantly. If the creature you chose has 100 hit points or fewer, it dies. Otherwise, the spell has no effect. <i>Enchantment</i> 9th 1 Action 60 feet Instantaneous V"}],"page":0,"homebrew":true},{"name":"Power Word: Pain","source":"XGE","level":7,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You speak a word of power that causes waves of intense pain to assail one creature you can see within range. If the target has 100 hit points or fewer, it is subject to crippling pain. Otherwise, the spell has no effect on it. A target is also unaffected if it is immune to being charmed. While the target is affected by crippling pain, any speed it has can be no higher than 10 feet. The target also has disadvantage on attack rolls, ability checks, and saving throws, other than Constitution saving throws. Finally, if the target tries to cast a spell, it must first succeed on a Constitution saving throw, or the casting fails and the spell is wasted. A target suffering this pain can make a Constitution saving throw at the end of each of its turns. On a successful save, the pain ends. <i>Enchantment</i> 7th 1 Action 60 feet Instantaneous V"}],"page":0,"homebrew":true},{"name":"Power Word: Stun","source":"PHB","level":8,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You speak a word of power that can overwhelm the mind of one creature you can see within range, leaving it dumbfounded. If the target has 150 hit points or fewer, it is stunned. Otherwise, the spell has no effect. The stunned target must make a Constitution saving throw at the end of each of its turns. On a successful save, this stunning effect ends. <i>Enchantment</i> 8th 1 Action 60 feet Instantaneous V, S"}],"page":0,"homebrew":true},{"name":"Protection from Ballistics (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"touch"},"components":{"v":true,"s":true,"m":"a shell casing"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":10,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } <i>3rd-level abjuration (technomagic)</i> This spell enchants the flesh of the target against the impact of bullets. Until the spell ends, the target has resistance to nonmagical ballistic damage. <i>Abjuration ^^T^^</i> 3rd 1 Action Touch Concentration, up to 10 minutes V, S, M"}],"page":0,"homebrew":true},{"name":"Psionic Blast (UA)","source":"HB","level":3,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"self","selfType":"cone","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You unleash a destructive wave of mental power in a 30-foot cone. Each creature in the area must make a Dexterity saving throw. On a failed save, a target takes 5d8 force damage, is pushed 20 feet directly away from you, and is knocked prone. On a successful save, a target takes half as much damage and isn’t pushed or knocked prone. <i>Evocation</i> 3rd 1 Action Self (30-foot cone) Instantaneous V"}],"page":0,"homebrew":true},{"name":"Psychic Crush (UA)","source":"HB","level":6,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":false,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You overload the mind of one creature you can see within range, filling its psyche with discordant emotions. The target must make an Intelligence saving throw. On a failed save, the target takes 12d6 psychic damage and is stunned for 1 minute. On a successful save, the target takes half as much damage and isn’t stunned. The stunned target can make an Intelligence saving throw at the end of each of its turns. On a successful save, the spell ends on the target. <i>Enchantment</i> 6th 1 Action 60 feet 1 minute V, S"}],"page":0,"homebrew":true},{"name":"Puppet (UA)","source":"HB","level":1,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } Your gesture forces one humanoid you can see within range to make a Constitution saving throw. On a failed save, the target must move up to its speed in a direction you choose. In addition, you can cause the target to drop whatever it is holding. This spell has no effect on a humanoid that is immune to being charmed. <i>^^HB^^This spell is somewhat overpowered. Forced movement is one thing, but forced disarmament is very strong. I would recommend allowing only forced movement or forced disarmament, not both.</i> <i>Enchantment</i> 1st 1 Action 120 feet Instantaneous V"}],"page":0,"homebrew":true},{"name":"Raulothim's Psychic Lance (UA)","source":"HB","level":4,"school":"E","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You unleash a shimmering lance of psychic power from your forehead at a creature that you can see within range. Alternatively, you can utter the creature’s name. If the named target is within range, it gains no benefit from cover or invisibility as the lance homes in on it. If the named target isn’t within range, the lance dissipates, and the spell slot is not expended. The target must succeed on an Intelligence saving throw or take 10d6 psychic damage and be incapacitated until the start of your next turn. <i>Enchantment</i> 4th 1 Action 120 feet Instantaneous V"}],"page":0,"homebrew":true},{"name":"Remote Access (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":false,"duration":{"amount":10,"type":"minute"}}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } <i>1st-level transmutation (technomagic)</i> You can use any electronic device within range as if it were in your hands. This is not a telekinesis effect. Rather, this spell allows you to simulate a device's mechanical functions electronically. You are able to access only functions that a person using the device manually would be able to access. You can use remote access with only one device at a time. <i>Transmutation ^^T^^</i> 1st 1 Action 120 feet 10 minutes V, S"}],"page":0,"homebrew":true},{"name":"Sense Emotion (UA)","source":"HB","level":1,"school":"D","time":[{"number":1,"unit":"action"}],"range":{"type":"self"},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You attune your senses to pick up the emotions of others for the duration. When you cast the spell, and as your action on each turn until the spell ends, you can focus your senses on one humanoid you can see within 30 feet of you. You instantly learn the target’s prevailing emotion, whether it’s love, anger, pain, fear, calm, or something else. If the target isn’t actually humanoid or it is immune to being charmed, you sense that it is calm. <i>Divination</i> 1st Level 1 Action Self Concentration, up to 1 minute V, S"}],"page":0,"homebrew":true},{"name":"Shutdown (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } <i>5th-level transmutation (technomagic)</i> This spell shuts down all electronic devices within range that are not wielded by or under the direct control of a creature. If an electronic device within range is used by a creature, that creature must succeed on a Constitution saving throw to prevent the device from being shut down. While the spell remains active, no electronic device within range can be started or restarted. <i>Transmutation ^^T^^</i> 5th 1 Action 120 feet Concentration, up to 1 minute V, S"}],"page":0,"homebrew":true},{"name":"Spirit of Death (UA)","source":"HB","level":4,"school":"N","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"a gilded playing card depicting an avatar of death worth at least 400 gp"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You call forth a spirit that embodies death itself. Choose a creature you can see within range. The spirit manifests in an unoccupied space that you can see within 10 feet of the target, and the target becomes haunted by the spirit. The spirit uses the Reaper Spirit stat block. The spirit disappears when it or the haunted creature is reduced to 0 hit points, or when the spell ends. The reaper spirit is an ally to you and your companions. In combat, the spirit shares your initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you), but it will only attack the haunted creature. If you don’t issue the spirit any commands, it takes the Dodge action and uses its move to avoid danger"},{"type":"table","colLabels":[],"rows":[["","","","","","<i>Medium Undead</i>"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Armor Class:</b> 11 + the level of the spell (natural armor)"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Hit Points:</b> 40 + 10 for each level of the spell above 4th"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Speed:</b> 30 ft., fly 30 ft. (hover)"]]},{"type":"table","colLabels":[],"rows":[["16 (+3)","16 (+3)","16 (+3)","16 (+3)","16 (+3)","16 (+3)"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Damage Immunities:</b> necrotic, poison"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Condition Immunities:</b> charmed, frightened, paralyzed, poisoned"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Senses:</b> darkvision 60 ft., passive Perception 13"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Languages:</b> understands the languages you speak"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Challenge:</b> --"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Proficiency Bonus:</b> equals your bonus"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Incorporeal Movement.</i></b> The reaper can move through other creatures and objects as if they were difficult terrain. If it ends its turn inside an object, it is shunted to the nearest unoccupied space and takes 1d10 force damage for every 5 feet traveled."]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Haunting Tracker.</i></b> You and the reaper can sense the direction and distance to the haunted creature if it’s on the same plane of existence as you."]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Multiattack.</i></b> The reaper makes a number of attacks equal to half this spell’s level (rounded down)."]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Reaping Scythe.</i></b> <i>Melee Weapon Attack:</i> your spell attack modifier to hit (with advantage), reach 5 ft., one target. <i>Hit:</i> 1d10 + 3 + the spell’s level necrotic damage."]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Paralyzing Fear (1/Day).</i></b> The reaper attempts to instill fear into the haunted creature it can see within 60 feet of itself. The creature must succeed on a Wisdom saving throw against your spell save DC or be frightened of the reaper for 1 minute. While frightened this way, the creature’s speed is 0, and it can’t benefit from any bonus to its speed. The frightened creature can repeat the saving throw at the end of each of its turns, or immediately after it takes damage, ending the effect on itself on a success."]]},{"type":"text","content":"<i>Necromancy</i> 4th 1 Action 60 feet Concentration, up to 1 minute V, S, M"}],"page":0,"homebrew":true},{"name":"Spray of Cards (UA)","source":"HB","level":2,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":0}},"components":{"v":true,"s":true,"m":"a deck of cards"},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"list","items":["<b>Blinding Cards.</b> Each creature in a 15-foot cone must succeed on a Wisdom saving throw or be blinded until the end of their next turn.","<b>Cutting Cards.</b> Each creature in a 15-foot cone must make a Dexterity saving throw. A creature takes 2d10 force damage on a failed save or half as much damage on a successful one."]},{"type":"text","content":".page-tags { display: none; } You spray spectral cards from your hands or sleeve; the cards blind or slash at your enemies, and then vanish. Choose one of the following effects for the cards: <i>Conjuration</i> 2nd 1 Action 15-foot cone Instantaneous V, S, M"}],"page":0,"homebrew":true},{"name":"Sudden Awakening (UA)","source":"HB","level":1,"school":"E","time":[{"number":1,"unit":"bonus"}],"range":{"type":"point","distance":{"type":"feet","amount":10}},"components":{"v":true},"duration":[{"type":"instant"}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } Each sleeping creature you choose within range awakens, and then each prone creature within range can stand up without expending any movement. <i>Enchantment</i> 1st 1 Bonus Action 10 feet Instantaneous V"}],"page":0,"homebrew":true},{"name":"Summon Draconic Spirit (UA)","source":"HB","level":5,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":60}},"components":{"v":true,"s":true,"m":"an art object from a dragon's hoard, worth at least 500 gp"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"hour"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You call forth a draconic spirit. It manifests in an unoccupied space that you can see within range. This corporeal form uses the Draconic Spirit stat block. When you cast this spell, choose a family of dragon: Chromatic, Gem, or Metallic. The creature resembles a dragon of the chosen family, which determines certain traits in its stat block. The creature disappears when it drops to 0 hit points or when the spell ends. The creature is an ally to you and your companions. In combat, the creature shares your initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don’t issue any, it takes the Dodge action and uses its move to avoid danger."},{"type":"table","colLabels":[],"rows":[["","","","","","<i>Large Dragon</i>"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Armor Class:</b> 14 + the level of the spell (natural armor)"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Hit Points:</b> 50 + 10 for each level of the spell above 5th"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Speed:</b> 30 ft., fly 80 ft., swim 30 ft."]]},{"type":"table","colLabels":[],"rows":[["19 (+4)","14 (+2)","17 (+3)","10 (+0)","14 (+2)","14 (+2)"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Damage Resistances (Chromatic and Metallic only):</b> acid, cold, fire, lightning, poison"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Damage Resistances (Gem only):</b> force, necrotic, psychic, radiant, thunder"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Condition Immunities:</b> charmed, frightened, poisoned"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Senses:</b> blindsight 30 ft., darkvision 60 ft., passive Perception 12"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Languages:</b> Draconic, understands the languages you speak"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Challenge:</b> --"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Proficiency Bonus:</b> equals your bonus"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Shared Resistances.</i></b> When you summon the dragon, choose one of its damage resistances. You have resistance to the chosen damage type until the spell ends."]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Multiattack.</i></b> The dragon uses its Breath Weapon, and it makes a number of Bite and Claw attacks equal to half the spell's level (rounded down)."]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Bite and Claw.</i></b> <i>Melee Weapon Attack:</i> your spell attack modifier to hit, reach 10 ft., one target. <i>Hit:</i> 1d6 + 4 + the spell’s level piercing damage."]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Breath Weapon.</i></b> The dragon exhales a stream of multicolored energy in a 30-foot cone. Each creature in that area must make a Dexterity saving throw, taking 2d6 damage of your choice of a damage type this dragon has resistance to on a failed save, or half as much damage on a successful one."]]},{"type":"text","content":"<i>Conjuration</i> 5th 1 Action 60 feet Concentration, up to 1 hour V, S, M"}],"page":0,"homebrew":true},{"name":"Summon Warrior Spirit (UA)","source":"HB","level":3,"school":"C","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":90}},"components":{"v":true,"s":true,"m":"a gilded playing card depicting a knight worth at least 300 gp"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"hour"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } You call forth a warrior spirit from the legendary Deck of Many Things. It manifests in an unoccupied space that you can see within range. This corporeal form uses the Warrior Spirit stat block. When you cast the spell, choose a type of warrior: barbarian, fighter, or monk. The warrior resembles a humanoid armed appropriately to the chosen class, which determines certain traits in its stat block. The warrior disappears when it drops to 0 hit points or when the spell ends. The warrior is an ally to you and your companions. In combat, the warrior shares your initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don’t issue any, it takes the Dodge action and uses its move to avoid danger."},{"type":"table","colLabels":[],"rows":[["","","","","","<i>Medium Undead</i>"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Armor Class:</b> 13 + the level of the spell + 2 (Fighter only)"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Hit Points:</b> 30 (Barbarian and Fighter only) or 20 (Monk only) + 10 for each spell level above 3rd"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Speed:</b> 30 ft., 40 ft. (Monk only)"]]},{"type":"table","colLabels":[],"rows":[["16 (+3)","16 (+3)","14 (+2)","10 (+0)","16 (+3)","9 (-1)"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Saving Throws:</b> Str +3, Dex +3"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Damage Resistances:</b> poison"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Condition Immunities:</b> charmed, poisoned"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Senses:</b> passive Perception 13"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Languages:</b> Common, understands the languages you speak"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Challenge:</b> --"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b>Proficiency Bonus:</b> equals your bonus"]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Multiattack.</i></b> The warrior makes a number of attacks equal to half this spell’s level (rounded down)."]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Reckless Strike (Barbarian Only).</i></b> <i>Melee Weapon Attack:</i> your spell attack modifier to hit (with advantage), reach 5 ft., one target. <i>Hit:</i> 1d12 + 3 + the spell’s level slashing damage, and attacks made against the warrior until the start of its next turn are made with advantage."]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Rallying Strike (Fighter Only).</i></b> <i>Melee or Ranged Weapon Attack:</i> your spell attack modifier to hit, reach 5 ft., or range 20/60 ft., one target. <i>Hit:</i> 1d6 + 3 + the spell’s level piercing damage, and the warrior can choose another creature it can see within 20 feet of itself. The chosen creature gains 1d6 temporary hit points."]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Unarmed Strike (Monk Only).</i></b> <i>Melee Weapon Attack:</i> your spell attack modifier to hit, reach 5 ft., one target. <i>Hit:</i> 1d4 + 3 + the spell’s level bludgeoning damage, and the target must succeed on a Strength saving throw against your spell save DC or be knocked prone."]]},{"type":"table","colLabels":[],"rows":[["","","","","","<b><i>Flurry of Blows (Monk Only).</i></b> The monk makes one Unarmed Strike attack."]]},{"type":"text","content":"<i>Conjuration</i> 3rd 1 Action 90 feet Concentration, up to 1 hour V, S, M"}],"page":0,"homebrew":true},{"name":"Synchronicity (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"touch"},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"hour"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } <i>4th-level enchantment (technomagic)</i> The creature you touch feels reality subtly shifted to its favor while this spell is in effect. The target isn't inconvenienced by mundane delays of any sort. Traffic lights are always green, there's always a waiting elevator, and a taxi is always around the corner. The target can run at full speed through dense crowds, and attacks of opportunity provoked by the target's movement are made with disadvantage. Synchronicity grants advantage to Dexterity (Stealth) checks, since the target always finds a handy piece of cover available. Additionally, the target has advantage on all ability checks made to drive a vehicle. In the event that two or more creatures under the effect of synchronicity are attempting to avoid being inconvenienced by each other, the creatures engage in a contest of Charisma each time the effects of the spells would oppose each other. <i>Enchantment ^^T^^</i> 4th 1 Action Touch Concentration, up to 1 hour V, S"}],"page":0,"homebrew":true},{"name":"System Backdoor (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"minute"}],"range":{"type":"self"},"components":{"v":true,"s":true,"m":"hacking tools"},"duration":[{"type":"timed","concentration":true,"duration":{"amount":1,"type":"hour"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } <i>4th-level transmutation (technomagic)</i> This spell allows you to bypass system security in order to create a secure login on a foreign system. The login you create allows you administrator-level privileges in any computer system not enhanced through technomagic. The login defeats any technomagic spells of 3rd level or lower. Once the duration of the spell expires, the login and all privileges are wiped from the system. System logs still show the activity of the user, but the user identification cannot be found or traced. <i>Transmutation ^^T^^</i> 4th 1 Minute Self Concentration, up to 1 hour V, S, M"}],"page":0,"homebrew":true},{"name":"Thought Shield (UA)","source":"HB","level":2,"school":"A","time":[{"number":1,"unit":"action"}],"range":{"type":"touch"},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":false,"duration":{"amount":8,"type":"hour"}}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } You weave a clouding veil over the mind of one creature you touch. For the duration, the target’s mind can’t be read or detected, creatures can’t telepathically communicate with the target unless the target allows it, and the target has advantage on saving throws against any effect that would determine whether it is telling the truth. <i>Abjuration</i> 2nd 1 Action Touch 8 hours V, S"}],"page":0,"homebrew":true},{"name":"Unearthly Chorus (UA)","source":"HB","level":1,"school":"I","time":[{"number":1,"unit":"action"}],"range":{"type":"self","selfType":"radius","distance":{"type":"feet","amount":30}},"components":{"v":true},"duration":[{"type":"timed","concentration":true,"duration":{"amount":10,"type":"minute"}}],"ritual":false,"concentration":true,"entries":[{"type":"text","content":".page-tags { display: none; } Music of a style you choose fills the air around you in a 30-foot radius. The music spreads around corners and can be heard from up to 100 feet away. The music moves with you, centered on you for the duration. Until the spell ends, you make Charisma (Performance) checks with advantage. In addition, you can use a bonus action on each of your turns to beguile one creature you choose within 30 feet of you that can see you and hear the music. The creature must make a Charisma saving throw. If you or your companions are attacking it, the creature automatically succeeds on the saving throw. On a failure, the creature becomes friendly to you for as long as it can hear the music and for 1 hour thereafter. You make Charisma (Deception) checks and Charisma (Persuasion) checks against creatures made friendly by this spell with advantage. <i>Illusion</i> 1st 1 Action Self (30-foot radius) Concentration, up to 10 minutes V"}],"page":0,"homebrew":true},{"name":"Virtue (UA)","source":"HB","level":0,"school":"V","time":[{"number":1,"unit":"action"}],"range":{"type":"touch"},"components":{"v":true,"s":true},"duration":[{"type":"timed","concentration":false,"duration":{"amount":1,"type":"round"}}],"ritual":false,"concentration":false,"entries":[{"type":"text","content":".page-tags { display: none; } <i>Abjuration cantrip</i> You touch one creature, imbuing it with vitality. If the target has at least 1 hit point, it gains a number of temporary hit points equal to 1d4 + your spellcasting ability modifier. The temporary hit points are lost when the spell ends. <i>Abjuration</i> Cantrip 1 Action Touch 1 round V, S"}],"page":0,"homebrew":true},{"name":"Wild Cunning (UA)","source":"HB","level":1,"school":"T","time":[{"number":1,"unit":"action"}],"range":{"type":"point","distance":{"type":"feet","amount":120}},"components":{"v":true,"s":true},"duration":[{"type":"instant"}],"ritual":true,"concentration":false,"entries":[{"type":"list","items":["If there are any tracks on the ground within range, you know where they are, and you make Wisdom (Survival) checks to follow these tracks with advantage for 1 hour or until you cast this spell again.","If there is edible forage within range, you know it and where to find it.","If there is clean drinking water within range, you know it and where to find it.","If there is suitable shelter for you and your companions within range, you know it and where to find it.","Send the spirits to bring back wood for a fire and to set up a campsite in the area using your supplies. The spirits build the fire in a circle of stones, put up tents, unroll bedrolls, and put out any rations and water for consumption.","Have the spirits instantly break down a campsite, which includes putting out a fire, taking down tents, packing up bags, and burying any rubbish."]},{"type":"text","content":".page-tags { display: none; } You call out to the spirits of nature to aid you. When you cast this spell, choose one of the following effects: <i>Transmutation</i> 1st 1 Action <i>^^R^^</i> 120 feet Instantaneous V, S"}],"page":0,"homebrew":true}]`);export{e as t};